/// Clone-owned counterpart of one C++ `EffectPath`, keyed by its
/// `(StrokeEffect, ShapePaint)` identity. The optional retained value matches
/// C++ exactly: unsupported effects do not replace the incoming path, while a
/// supported effect may own an empty path.
#[derive(Debug)]
pub(crate) struct RuntimeShapeEffectPathOwner {
    dirty: Cell<bool>,
    pub(crate) retained: RefCell<Option<Option<RuntimeShapePathState>>>,
    pub(crate) backend: RuntimePathBackendSlot,
}

impl Clone for RuntimeShapeEffectPathOwner {
    fn clone(&self) -> Self {
        Self::default()
    }
}

impl Default for RuntimeShapeEffectPathOwner {
    fn default() -> Self {
        Self {
            dirty: Cell::new(true),
            retained: RefCell::new(None),
            backend: RuntimePathBackendSlot::default(),
        }
    }
}

/// Clone-owned counterpart of one C++ `ShapePaint`. Authored identity is
/// fixed at construction; mutator, feather, effect-path, and RenderPaint state
/// live directly on this occurrence and are settled by component updates.
#[derive(Debug)]
pub(crate) struct RuntimeShapePaintOwner {
    paint_index: usize,
    pub(crate) paint_local: usize,
    paint_global_id: u32,
    mutator_local: Option<usize>,
    feather_local: Option<usize>,
    pub(crate) paint_type: RuntimeShapePaintKind,
    pub(crate) authored_fill_rule: RenderFillRule,
    authored_path_kind: RuntimeShapePaintPathKind,
    authored_blend_mode_value: u32,
    container_local: usize,
    render_opacity: Cell<f32>,
    mutator_dirty: Cell<bool>,
    feather_dirty: Cell<bool>,
    backend_queued: Cell<bool>,
    effect_dirty_from: Cell<Option<usize>>,
    pub(crate) effect_paths: Vec<RuntimeShapeEffectPathOwner>,
    paint_state: RefCell<Option<RuntimeShapePaintState>>,
    pending_gradient_states: RefCell<Vec<RuntimeShapePaintState>>,
    initial_gradient_event_supplied: Cell<bool>,
    pub(crate) feather_state: RefCell<Option<RuntimeFeatherState>>,
    pub(crate) inner_feather_path: RefCell<Option<RuntimeShapePathState>>,
    pub(crate) backend: RuntimePaintBackendSlot,
    pub(crate) inner_feather_backend: RuntimePathBackendSlot,
}

impl Clone for RuntimeShapePaintOwner {
    fn clone(&self) -> Self {
        Self {
            paint_index: self.paint_index,
            paint_local: self.paint_local,
            paint_global_id: self.paint_global_id,
            mutator_local: self.mutator_local,
            feather_local: self.feather_local,
            paint_type: self.paint_type,
            authored_fill_rule: self.authored_fill_rule,
            authored_path_kind: self.authored_path_kind,
            authored_blend_mode_value: self.authored_blend_mode_value,
            container_local: self.container_local,
            // ShapePaintMutator construction starts at 1.0 and receives the
            // clone's inherited value from Shape::update(RenderOpacity).
            render_opacity: Cell::new(1.0),
            mutator_dirty: Cell::new(true),
            feather_dirty: Cell::new(self.feather_local.is_some()),
            backend_queued: Cell::new(true),
            effect_dirty_from: Cell::new(Some(0)),
            effect_paths: std::iter::repeat_with(RuntimeShapeEffectPathOwner::default)
                .take(self.effect_paths.len())
                .collect(),
            paint_state: RefCell::new(None),
            pending_gradient_states: RefCell::new(Vec::new()),
            initial_gradient_event_supplied: Cell::new(false),
            feather_state: RefCell::new(None),
            inner_feather_path: RefCell::new(None),
            backend: RuntimePaintBackendSlot::default(),
            inner_feather_backend: RuntimePathBackendSlot::default(),
        }
    }
}

impl RuntimeShapePaintOwner {
    fn new(paint_index: usize, paint: &ShapePaintNode, container_local: usize) -> Self {
        Self {
            paint_index,
            paint_local: paint.local_id,
            paint_global_id: paint.global_id,
            mutator_local: paint.mutator_local,
            feather_local: paint.feather_local,
            paint_type: runtime_shape_paint_kind(paint.paint_type),
            authored_fill_rule: runtime_fill_rule_for_value(paint.fill_rule),
            authored_path_kind: paint
                .path_kind
                .and_then(runtime_shape_paint_path_kind)
                .unwrap_or(RuntimeShapePaintPathKind::Local),
            authored_blend_mode_value: paint.blend_mode_value,
            container_local,
            // C++ ShapePaintMutator::m_renderOpacity is initialized to 1.0f
            // (`shape_paint_mutator.hpp:55`).
            render_opacity: Cell::new(1.0),
            mutator_dirty: Cell::new(true),
            feather_dirty: Cell::new(paint.feather_local.is_some()),
            backend_queued: Cell::new(true),
            effect_dirty_from: Cell::new(Some(0)),
            effect_paths: std::iter::repeat_with(RuntimeShapeEffectPathOwner::default)
                .take(paint.effects.len())
                .collect(),
            paint_state: RefCell::new(None),
            pending_gradient_states: RefCell::new(Vec::new()),
            initial_gradient_event_supplied: Cell::new(false),
            feather_state: RefCell::new(None),
            inner_feather_path: RefCell::new(None),
            backend: RuntimePaintBackendSlot::default(),
            inner_feather_backend: RuntimePathBackendSlot::default(),
        }
    }

    fn mark_mutator_dirty(&self) {
        self.mutator_dirty.set(true);
    }

    fn mark_feather_dirty(&self) {
        if self.feather_local.is_some() {
            self.feather_dirty.set(true);
        }
    }

    fn invalidate_effects_from(&self, effect_index: usize) {
        let first = crate::shapes::paint::effects_container::first_dirty_effect(
            self.effect_dirty_from.get(),
            effect_index,
        );
        self.effect_dirty_from.set(Some(first));
        crate::shapes::paint::effects_container::invalidate_suffix(
            &self.effect_paths,
            effect_index,
            |effect| effect.dirty.set(true),
        );
    }

    pub(crate) fn invalidate_all_effects(&self) {
        self.invalidate_effects_from(0);
    }

    fn record_gradient_update(&self) {
        let state = self.paint_state.borrow().clone();
        if let Some(
            state @ (RuntimeShapePaintState::LinearGradient { .. }
            | RuntimeShapePaintState::RadialGradient { .. }),
        ) = state
        {
            let mut pending = self.pending_gradient_states.borrow_mut();
            if self.initial_gradient_event_supplied.get()
                && self.backend.value.borrow().context_id.is_none()
            {
                // A mounted-layout occurrence can receive its parent-owned
                // solve after the isolated initial shader frame but before a
                // RenderFactory is attached. C++ observes only the final
                // post-frame dependency update at that boundary; replace the
                // provisional detached-child event instead of replaying both.
                pending.clear();
            }
            pending.push(state);
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct RuntimeShapePaintOwnerRef {
    shape_local: usize,
    owner_index: usize,
}

#[derive(Debug, Clone, Copy)]
struct RuntimeShapeEffectOwnerRef {
    shape_local: usize,
    owner_index: usize,
    effect_index: usize,
}

impl RuntimeShapeList {
    /// Move the renderer members owned by a pooled Artboard occurrence onto
    /// its freshly reconstructed CPU/property state.
    ///
    /// C++ `ArtboardComponentList::applyRecorders` writes authored properties
    /// back onto the same cloned objects. Rust reconstructs that authored
    /// state in a temporary occurrence, so explicitly retain the concrete
    /// `ShapePaint` and `ShapePaintPath` backend sidecars from the pooled
    /// occurrence before installing the fresh state.
    pub(crate) fn adopt_pooled_backend_owners(&mut self, pooled: &mut Self) {
        self.backend_context_id
            .set(pooled.backend_context_id.take());
        for (fresh_shape, pooled_shape) in self.by_local.iter_mut().zip(&mut pooled.by_local) {
            let (Some(fresh_shape), Some(pooled_shape)) = (fresh_shape, pooled_shape) else {
                continue;
            };
            for (fresh_path, pooled_path) in fresh_shape
                .paint_paths
                .iter_mut()
                .zip(&mut pooled_shape.paint_paths)
            {
                std::mem::swap(&mut fresh_path.backend, &mut pooled_path.backend);
            }
            for (fresh_paint, pooled_paint) in fresh_shape
                .paint_owners
                .iter_mut()
                .zip(&mut pooled_shape.paint_owners)
            {
                std::mem::swap(&mut fresh_paint.backend, &mut pooled_paint.backend);
                std::mem::swap(
                    &mut fresh_paint.inner_feather_backend,
                    &mut pooled_paint.inner_feather_backend,
                );
                for (fresh_effect, pooled_effect) in fresh_paint
                    .effect_paths
                    .iter_mut()
                    .zip(&mut pooled_paint.effect_paths)
                {
                    std::mem::swap(&mut fresh_effect.backend, &mut pooled_effect.backend);
                }
            }
        }
    }

    fn text_style_paint_owner(&self, paint_local: usize) -> Option<&RuntimeShapePaintOwner> {
        self.paint_owners_by_component_local
            .get(paint_local)?
            .iter()
            .find_map(|owner_ref| {
                let shape = self.get(owner_ref.shape_local)?;
                shape
                    .paint_container_family
                    .is_some_and(|family| family.owns_text_paint())
                    .then(|| shape.paint_owners.get(owner_ref.owner_index))
                    .flatten()
            })
    }

    pub(crate) fn text_style_paint_container_for_component(
        &self,
        local_id: usize,
    ) -> Option<usize> {
        self.paint_owners_by_component_local
            .get(local_id)?
            .iter()
            .find_map(|owner| {
                let shape = self.get(owner.shape_local)?;
                (shape.paint_container_family
                    == Some(
                        crate::shapes::shape_paint_container::RuntimeShapePaintContainerFamily::TextStylePaint,
                    ))
                .then_some(owner.shape_local)
            })
    }

    fn backend_paints_need_realization(&self, context_id: u64) -> bool {
        self.backend_context_id.get() != Some(context_id)
            || !self.pending_backend_paints.borrow().is_empty()
    }

    fn activate_backend_context(&self, context_id: u64) {
        if self.backend_context_id.replace(Some(context_id)) == Some(context_id) {
            return;
        }
        let mut pending = self.pending_backend_paints.borrow_mut();
        pending.clone_from(&self.paint_owner_refs);
        for owner_ref in &self.paint_owner_refs {
            if let Some(owner) = self
                .get(owner_ref.shape_local)
                .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
            {
                owner.backend_queued.set(true);
                let initial_event_supplied = owner.initial_gradient_event_supplied.get();
                if owner.pending_gradient_states.borrow().is_empty() && !initial_event_supplied {
                    owner.record_gradient_update();
                }
            }
        }
    }

    fn take_pending_backend_paints(&self) -> Vec<RuntimeShapePaintOwnerRef> {
        std::mem::take(&mut *self.pending_backend_paints.borrow_mut())
    }

    pub(crate) fn from_graph(graph: &ArtboardGraph) -> Self {
        let mut shapes = Self::default();
        let maximum_path_local = graph.paths.iter().map(|path| path.local_id).max();
        if let Some(maximum_path_local) = maximum_path_local {
            shapes
                .paths_by_local
                .resize_with(maximum_path_local.saturating_add(1), || None);
            for path in &graph.paths {
                shapes.paths_by_local[path.local_id] = Some(RuntimePathOwner::default());
            }
        }
        for composer in &graph.path_composers {
            shapes.slot_mut(composer.shape_local);
        }
        shapes.retain_paint_containers(&graph.shape_paint_containers);
        shapes.retain_opacity_owner_index(graph);
        shapes
            .pending_backend_paints
            .get_mut()
            .clone_from(&shapes.paint_owner_refs);
        shapes
    }

    fn retain_opacity_owner_index(&mut self, graph: &ArtboardGraph) {
        for (container_index, container) in graph.shape_paint_containers.iter().enumerate() {
            if crate::shapes::shape_paint_container::family(container.type_name).is_none() {
                continue;
            }
            let owner_local = crate::shapes::shape_paint_container::opacity_owner_local(
                graph,
                container.local_id,
            );
            self.slot_mut(container.local_id).opacity_owner_local = Some(owner_local);
            if self.opacity_paint_containers_by_owner_local.len() <= owner_local {
                self.opacity_paint_containers_by_owner_local
                    .resize_with(owner_local + 1, Vec::new);
            }
            self.opacity_paint_containers_by_owner_local[owner_local].push(container_index);
        }
    }

    fn opacity_paint_container_indices(&self, owner_local: usize) -> &[usize] {
        self.opacity_paint_containers_by_owner_local
            .get(owner_local)
            .map_or(&[], Vec::as_slice)
    }

    fn retain_paint_containers(&mut self, containers: &[ShapePaintContainerNode]) {
        for (container_index, container) in containers.iter().enumerate() {
            let Some(family) = crate::shapes::shape_paint_container::family(container.type_name)
            else {
                continue;
            };
            let shape = self.slot_mut(container.local_id);
            shape.paint_container_index = Some(container_index);
            shape.paint_container_family = Some(family);
            shape.paint_owners.clear();
            for (paint_index, paint) in container.paints.iter().enumerate() {
                crate::shapes::shape_paint_container::add_paint(
                    family,
                    &mut shape.paint_owners,
                    RuntimeShapePaintOwner::new(paint_index, paint, container.local_id),
                );
            }
            for (owner_index, paint) in container.paints.iter().enumerate() {
                let owner_ref = RuntimeShapePaintOwnerRef {
                    shape_local: container.local_id,
                    owner_index,
                };
                // ShapePaint and its TextStylePaint subclass retain the
                // common occurrence-owned RenderPaint. Geometry ownership is
                // separate: only Shape/Artboard use the paint-path slots.
                if family.owns_shape_geometry() || family.owns_text_paint() {
                    self.paint_owner_refs.push(owner_ref);
                }
                self.register_paint_component(container.local_id, owner_ref);
                self.register_paint_component(paint.local_id, owner_ref);
                if let Some(local_id) = paint.mutator_local {
                    self.register_paint_component(local_id, owner_ref);
                }
                if let Some(local_id) = paint.feather_local {
                    self.register_paint_component(local_id, owner_ref);
                }
                for stop in &paint.gradient_stops {
                    self.register_paint_component(stop.local_id, owner_ref);
                }
                for (effect_index, effect) in paint.effects.iter().enumerate() {
                    self.register_effect_components(effect, owner_ref, effect_index);
                }
            }
        }
    }

    fn invalidate_container_stroke_effects(&self, container_local: usize) {
        let Some(container) = self.get(container_local) else {
            return;
        };
        let Some(family) = container.paint_container_family else {
            return;
        };
        crate::shapes::shape_paint_container::invalidate_stroke_effects(
            family,
            &container.paint_owners,
            |paint| paint.invalidate_all_effects(),
        );
    }

    /// Rebuild the renderer-facing membership projection from the exact
    /// occurrence-owned `Shape::m_Paths` / `Path::m_Shape` handles. This is
    /// called after every dirty/clean clone lifecycle; copied local-id
    /// memberships are never runtime truth (`src/shapes/path.cpp:76-96`;
    /// `include/rive/shapes/{path,shape}.hpp`).
    pub(crate) fn rebuild_component_memberships(&mut self, objects: &InstanceObjectArena) {
        for shape in self.by_local.iter_mut().flatten() {
            shape.path_locals.clear();
        }
        self.shape_by_path_local.fill(None);

        for &shape_handle in objects.component_handles() {
            let Some(component) = objects.component(shape_handle) else {
                continue;
            };
            let Some(shape_state) = component.concrete.shape.as_ref() else {
                continue;
            };
            let shape_local = component.local_id;
            let mut path_locals = Vec::with_capacity(shape_state.paths.len());
            for &path_handle in &shape_state.paths {
                let Some(path_local) = objects.component_local_id(path_handle) else {
                    continue;
                };
                path_locals.push(path_local);
                if self.shape_by_path_local.len() <= path_local {
                    self.shape_by_path_local.resize(path_local + 1, None);
                }
                self.shape_by_path_local[path_local] = Some(shape_local);
            }
            self.slot_mut(shape_local).path_locals = path_locals;
        }
    }

    fn register_paint_component(&mut self, local_id: usize, owner: RuntimeShapePaintOwnerRef) {
        if self.paint_owners_by_component_local.len() <= local_id {
            self.paint_owners_by_component_local
                .resize_with(local_id + 1, Vec::new);
        }
        self.paint_owners_by_component_local[local_id].push(owner);
    }

    fn register_effect_components(
        &mut self,
        effect: &StrokeEffectNode,
        owner: RuntimeShapePaintOwnerRef,
        effect_index: usize,
    ) {
        self.register_effect_component(effect.local_id, owner, effect_index);
        for dash in &effect.dashes {
            self.register_effect_component(dash.local_id, owner, effect_index);
        }
        for nested in &effect.group_effects {
            self.register_effect_components(nested, owner, effect_index);
        }
    }

    fn register_effect_component(
        &mut self,
        local_id: usize,
        owner: RuntimeShapePaintOwnerRef,
        effect_index: usize,
    ) {
        self.register_paint_component(local_id, owner);
        if self.effect_owners_by_component_local.len() <= local_id {
            self.effect_owners_by_component_local
                .resize_with(local_id + 1, Vec::new);
        }
        self.effect_owners_by_component_local[local_id].push(RuntimeShapeEffectOwnerRef {
            shape_local: owner.shape_local,
            owner_index: owner.owner_index,
            effect_index,
        });
    }

    fn slot_mut(&mut self, shape_local: usize) -> &mut RuntimeShape {
        if self.by_local.len() <= shape_local {
            self.by_local.resize_with(shape_local + 1, || None);
        }
        self.by_local[shape_local].get_or_insert_with(|| RuntimeShape {
            path_locals: Vec::new(),
            paint_container_index: None,
            paint_container_family: None,
            opacity_owner_local: None,
            paint_paths: std::array::from_fn(|_| RuntimeShapePaintPathOwner::default()),
            paint_owners: Vec::new(),
            world_bounds: Cell::new(None),
            world_length: Cell::new(None),
        })
    }

    pub(crate) fn get(&self, shape_local: usize) -> Option<&RuntimeShape> {
        self.by_local.get(shape_local)?.as_ref()
    }

    /// Borrow the concrete Path owner's retained RawPath representation.
    /// FollowPath calls this only from its dependency-ordered update, after
    /// the source Path has consumed its own dirt.
    pub(crate) fn retained_follow_path_source(
        &self,
        path_local: usize,
    ) -> Option<(Arc<RawPath>, bool)> {
        let owner = self.paths_by_local.get(path_local)?.as_ref()?;
        let retained = owner.retained.borrow();
        let retained = retained.as_ref()?;
        Some((
            Arc::clone(&retained.raw_path),
            retained.has_weighted_context,
        ))
    }

    /// Snapshot the current clone-owned `Path::rawPath()` for script-facing
    /// node lookup. The retained owner is populated only after the Path's
    /// dependency update; callers preserve C++'s pre-update empty path when
    /// this returns `None` (`src/lua/lua_artboards.cpp:884-900`).
    pub(crate) fn retained_script_path(&self, path_local: usize) -> Option<Arc<RawPath>> {
        let owner = self.paths_by_local.get(path_local)?.as_ref()?;
        owner
            .retained
            .borrow()
            .as_ref()
            .map(|path| Arc::clone(&path.raw_path))
    }

    #[cfg(test)]
    pub(crate) fn seed_follow_path_source_for_test(
        &mut self,
        shape_local: usize,
        path_local: usize,
        commands: &[RuntimePathCommand],
        has_weighted_context: bool,
    ) {
        if self.paths_by_local.len() <= path_local {
            self.paths_by_local.resize_with(path_local + 1, || None);
        }
        let owner = self.paths_by_local[path_local].get_or_insert_with(Default::default);
        *owner.retained.get_mut() = Some(RuntimeOwnedPath {
            path: Arc::new(PathGeometryNode {
                local_id: path_local,
                global_id: path_local as u32,
                type_name: "PointsPath",
                is_closed: false,
                is_hole: false,
                is_clockwise: true,
                parametric: None,
                vertices: Vec::new(),
            }),
            raw_path: Arc::new(runtime_raw_path_from_commands(commands)),
            has_weighted_context,
        });
        owner.dirty.set(false);
        let shape = self.slot_mut(shape_local);
        if !shape.path_locals.contains(&path_local) {
            shape.path_locals.push(path_local);
        }
        if self.shape_by_path_local.len() <= path_local {
            self.shape_by_path_local.resize(path_local + 1, None);
        }
        self.shape_by_path_local[path_local] = Some(shape_local);
    }

    #[cfg(test)]
    pub(crate) fn retained_path_mutation_id_for_test(&self, path_local: usize) -> Option<u64> {
        self.paths_by_local
            .get(path_local)?
            .as_ref()?
            .retained
            .borrow()
            .as_ref()
            .map(|path| path.raw_path.mutation_id())
    }

    pub(crate) fn paint_path_owner(
        &self,
        shape_local: usize,
        path_kind: RuntimeShapePaintPathKind,
    ) -> Option<&RuntimeShapePaintPathOwner> {
        self.get(shape_local)?
            .paint_paths
            .get(runtime_shape_paint_path_kind_slot(path_kind))
    }

    fn mark_shape_paths_dirty(&self, shape_local: usize) {
        let Some(shape) = self.get(shape_local) else {
            return;
        };
        for path in &shape.paint_paths {
            path.mark_dirty();
        }
        shape.world_bounds.set(None);
        shape.world_length.set(None);
        crate::shapes::shape_paint_container::invalidate_stroke_effects(
            shape.paint_container_family.unwrap_or(
                crate::shapes::shape_paint_container::RuntimeShapePaintContainerFamily::Shape,
            ),
            &shape.paint_owners,
            |paint| paint.invalidate_all_effects(),
        );
        for (owner_index, paint) in shape.paint_owners.iter().enumerate() {
            paint.mark_feather_dirty();
            self.queue_backend_paint(RuntimeShapePaintOwnerRef {
                shape_local,
                owner_index,
            });
        }
    }

    /// Direct port of pinned C++ `Path::collapse` ->
    /// `Shape::pathCollapseChanged` -> `PathComposer::pathCollapseChanged`
    /// (`path.cpp:384-390`, `shape.cpp:330`,
    /// `path_composer.cpp:119-133`). Unlike ordinary dirt propagation, this
    /// must return the composer's paint dependents even when Path dirt was
    /// already present.
    pub(crate) fn path_collapse_changed(&self, path_local: usize) -> Option<usize> {
        let shape_local = self
            .shape_by_path_local
            .get(path_local)
            .and_then(|shape_local| *shape_local)?;
        self.get(shape_local)?;
        self.mark_shape_paths_dirty(shape_local);
        Some(shape_local)
    }

    fn queue_backend_paint(&self, owner: RuntimeShapePaintOwnerRef) {
        let Some(paint) = self
            .get(owner.shape_local)
            .and_then(|shape| shape.paint_owners.get(owner.owner_index))
        else {
            return;
        };
        if !paint.backend_queued.replace(true) {
            self.pending_backend_paints.borrow_mut().push(owner);
        }
    }

    pub(crate) fn on_component_dirty(&self, local_id: usize, dirt: ComponentDirt) -> Vec<usize> {
        let source_path_dirt = dirt
            & (ComponentDirt::PATH
                | ComponentDirt::VERTICES
                | ComponentDirt::WORLD_TRANSFORM
                | ComponentDirt::N_SLICER
                | ComponentDirt::LAYOUT_STYLE);
        let mut changed_shapes = Vec::new();
        if let Some(path) = self.paths_by_local.get(local_id).and_then(Option::as_ref)
            && !source_path_dirt.is_empty()
        {
            path.dirty.set(true);
        }
        if !source_path_dirt.is_empty() {
            if self.get(local_id).is_some() && dirt.contains(ComponentDirt::PATH) {
                self.mark_shape_paths_dirty(local_id);
                changed_shapes.push(local_id);
            }
            if let Some(shape_local) = self
                .shape_by_path_local
                .get(local_id)
                .and_then(|shape_local| *shape_local)
            {
                self.mark_shape_paths_dirty(shape_local);
                changed_shapes.push(shape_local);
            }
        }
        if let Some(owners) = self.paint_owners_by_component_local.get(local_id) {
            for owner in owners {
                let Some(paint) = self
                    .get(owner.shape_local)
                    .and_then(|shape| shape.paint_owners.get(owner.owner_index))
                else {
                    continue;
                };
                if paint.feather_local == Some(local_id) {
                    paint.mark_feather_dirty();
                } else {
                    paint.mark_mutator_dirty();
                }
                self.queue_backend_paint(*owner);
                if dirt.contains(ComponentDirt::PATH)
                    && self
                        .effect_owners_by_component_local
                        .get(local_id)
                        .is_none_or(Vec::is_empty)
                    && paint.effect_dirty_from.get().is_none()
                {
                    paint.invalidate_all_effects();
                    paint.mark_feather_dirty();
                }
            }
        }
        changed_shapes.sort_unstable();
        changed_shapes.dedup();
        changed_shapes
    }

    pub(crate) fn mark_property_changed(&self, local_id: usize) {
        if let Some(owners) = self.paint_owners_by_component_local.get(local_id) {
            for owner in owners {
                if let Some(paint) = self
                    .get(owner.shape_local)
                    .and_then(|shape| shape.paint_owners.get(owner.owner_index))
                {
                    if paint.feather_local == Some(local_id) {
                        // Feather's generated bool/uint callbacks are no-ops;
                        // strength/offset callbacks reach this owner through
                        // Component dirt instead (`feather.cpp:103-110`).
                        continue;
                    }
                    paint.mark_mutator_dirty();
                    self.queue_backend_paint(*owner);
                }
            }
        }
    }

    pub(crate) fn invalidate_effect_from_local(&self, local_id: usize) -> Vec<usize> {
        let mut paint_locals = Vec::new();
        if let Some(effects) = self.effect_owners_by_component_local.get(local_id) {
            for effect in effects {
                if let Some(paint) = self
                    .get(effect.shape_local)
                    .and_then(|shape| shape.paint_owners.get(effect.owner_index))
                {
                    paint.invalidate_effects_from(effect.effect_index);
                    paint_locals.push(paint.paint_local);
                }
            }
        }
        paint_locals.sort_unstable();
        paint_locals.dedup();
        paint_locals
    }
}

/// Clone-owned counterpart of C++ `ClippingShape::{m_Shapes,m_path,m_clipPath}`.
/// Source membership is fixed by `onAddedClean`; the CPU path and backend
/// RenderPath remain on the concrete occurrence and start cold on clone.
#[derive(Debug, Default)]
pub(crate) struct RuntimeClippingShapeList {
    by_local: Vec<Option<RuntimeClippingShapeOwner>>,
}

impl Clone for RuntimeClippingShapeList {
    fn clone(&self) -> Self {
        Self {
            by_local: self
                .by_local
                .iter()
                .map(|owner| owner.as_ref().map(RuntimeClippingShapeOwner::clone_cold))
                .collect(),
        }
    }
}

impl RuntimeClippingShapeList {
    pub(crate) fn from_graph(graph: &ArtboardGraph) -> Self {
        let mut owners = Self::default();
        if let Some(maximum) = graph
            .clipping_shapes
            .iter()
            .map(|shape| shape.local_id)
            .max()
        {
            owners
                .by_local
                .resize_with(maximum.saturating_add(1), || None);
            for shape in &graph.clipping_shapes {
                owners.by_local[shape.local_id] = Some(RuntimeClippingShapeOwner::new(shape));
            }
        }
        owners
    }

    pub(crate) fn get(&self, local_id: usize) -> Option<&RuntimeClippingShapeOwner> {
        self.by_local.get(local_id)?.as_ref()
    }
}

#[derive(Debug)]
pub(crate) struct RuntimeClippingShapeOwner {
    pub(crate) shape_locals: Vec<usize>,
    pub(crate) authored_fill_rule: u64,
    authored_is_visible: bool,
    pub(crate) path: RefCell<RawPath>,
    pub(crate) has_path: Cell<bool>,
    pub(crate) fill_rule: Cell<RenderFillRule>,
    backend: RuntimePathBackendSlot,
}

impl RuntimeClippingShapeOwner {
    fn new(shape: &ClippingShapeNode) -> Self {
        Self {
            shape_locals: shape.shape_locals.clone(),
            authored_fill_rule: shape.fill_rule,
            authored_is_visible: shape.is_visible,
            path: RefCell::new(RawPath::new()),
            has_path: Cell::new(false),
            fill_rule: Cell::new(runtime_fill_rule_for_value(shape.fill_rule)),
            backend: RuntimePathBackendSlot::default(),
        }
    }

    fn clone_cold(&self) -> Self {
        Self {
            shape_locals: self.shape_locals.clone(),
            authored_fill_rule: self.authored_fill_rule,
            authored_is_visible: self.authored_is_visible,
            path: RefCell::new(RawPath::new()),
            has_path: Cell::new(false),
            fill_rule: Cell::new(runtime_fill_rule_for_value(self.authored_fill_rule)),
            backend: RuntimePathBackendSlot::default(),
        }
    }
}

/// One clone-owned runtime drawable. This is the direct Rust counterpart of
/// C++ `Drawable`: mutable draw-order links and save intent live on the object,
/// while immutable import topology only seeds construction.
#[derive(Debug)]
struct RuntimeTextDrawOwner {
    dirty: Cell<bool>,
    pending_update_dirt: Cell<ComponentDirt>,
    render_styles_dirty: Cell<bool>,
    retain_paths_on_rebuild: Cell<bool>,
    /// C++ `Text::{m_allRuns,m_textStylePaints,m_modifierGroups}`: immutable
    /// imported topology retained by this concrete Text occurrence.
    topology: RefCell<Option<Arc<StaticTextSlice>>>,
    /// C++ `Text::{m_shape,m_lines}`. The outer Cell distinguishes a retained
    /// empty shape from a shape that has not been built or was invalidated.
    shaped_topology_valid: Cell<bool>,
    shaped_topology: RefCell<Option<Arc<StaticShapedTextTopology>>>,
    retained: RefCell<Option<RuntimeCachedTextShapePaints>>,
    backend: RefCell<RuntimeTextBackendResources>,
}

impl Clone for RuntimeTextDrawOwner {
    fn clone(&self) -> Self {
        // Generated Text/TextInputDrawable clones copy generated properties
        // into fresh concrete objects. Text's custom m_drawCommands,
        // m_clipPath, TextStylePaint opacity paths/paint pools, and backend
        // resources are rebuilt during clone initialization
        // (`src/generated/text/text_base.cpp:6-10`,
        // `include/rive/generated/text/text_base.hpp:244-262`,
        // `src/text/text_style_paint.cpp:13-19,125-134`).
        let cloned = Self::default();
        *cloned.topology.borrow_mut() = self.topology.borrow().clone();
        cloned
    }
}

impl Default for RuntimeTextDrawOwner {
    fn default() -> Self {
        Self {
            dirty: Cell::new(true),
            pending_update_dirt: Cell::new(ComponentDirt::PATH),
            render_styles_dirty: Cell::new(true),
            retain_paths_on_rebuild: Cell::new(false),
            topology: RefCell::new(None),
            shaped_topology_valid: Cell::new(false),
            shaped_topology: RefCell::new(None),
            retained: RefCell::new(None),
            backend: RefCell::new(RuntimeTextBackendResources::default()),
        }
    }
}

impl RuntimeTextDrawOwner {
    fn topology_or_build(
        &self,
        build: impl FnOnce() -> Result<StaticTextSlice>,
    ) -> Result<Arc<StaticTextSlice>> {
        if self.topology.borrow().is_none() {
            *self.topology.borrow_mut() = Some(Arc::new(build()?));
        }
        self.topology
            .borrow()
            .as_ref()
            .cloned()
            .context("Text occurrence did not retain its imported topology")
    }

    fn is_dirty(&self) -> bool {
        self.dirty.get() || self.retained.borrow().is_none()
    }

    fn mark_dirty(&self) {
        self.dirty.set(true);
        self.pending_update_dirt
            .set(self.pending_update_dirt.get() | ComponentDirt::PATH);
    }

    fn mark_paths_retained_dirty(&self) {
        self.dirty.set(true);
        self.pending_update_dirt
            .set(self.pending_update_dirt.get() | ComponentDirt::PATH);
        if !self.render_styles_dirty.get() {
            self.retain_paths_on_rebuild.set(true);
        }
    }

    fn mark_paint_paths_retained_dirty(&self) {
        self.dirty.set(true);
        self.pending_update_dirt
            .set(self.pending_update_dirt.get() | ComponentDirt::PAINT);
        if !self.render_styles_dirty.get() {
            self.retain_paths_on_rebuild.set(true);
        }
    }

    fn mark_render_styles_dirty(&self) {
        self.dirty.set(true);
        self.pending_update_dirt
            .set(self.pending_update_dirt.get() | ComponentDirt::PAINT);
        self.render_styles_dirty.set(true);
        self.retain_paths_on_rebuild.set(false);
    }

    fn mark_shape_dirty_unless_paths_retained(&self) {
        self.shaped_topology_valid.set(false);
        self.shaped_topology.borrow_mut().take();
        self.mark_render_styles_dirty_unless_paths_retained();
    }

    fn mark_external_font_shape_dirty(&self) {
        self.dirty.set(true);
        self.pending_update_dirt
            .set(self.pending_update_dirt.get() | ComponentDirt::PATH);
        self.shaped_topology_valid.set(false);
        self.shaped_topology.borrow_mut().take();
        self.render_styles_dirty.set(true);
        self.retain_paths_on_rebuild.set(false);
    }

    fn shaped_topology_or_build(
        &self,
        build: impl FnOnce() -> Result<Option<StaticShapedTextTopology>>,
    ) -> Result<Option<Arc<StaticShapedTextTopology>>> {
        if !self.shaped_topology_valid.get() {
            *self.shaped_topology.borrow_mut() = build()?.map(Arc::new);
            self.shaped_topology_valid.set(true);
        }
        Ok(self.shaped_topology.borrow().clone())
    }

    fn mark_render_styles_dirty_unless_paths_retained(&self) {
        self.dirty.set(true);
        if !self.retain_paths_on_rebuild.get() {
            self.render_styles_dirty.set(true);
        }
    }

    fn propagate_render_opacity(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        opacity_owner_local: usize,
    ) -> bool {
        let render_opacity = instance
            .component(opacity_owner_local)
            .map_or(1.0, |component| component.transform.render_opacity);
        let mut retained = self.retained.borrow_mut();
        let Some(frame) = retained.as_mut() else {
            return false;
        };
        for command in Arc::make_mut(&mut frame.commands) {
            let effective_opacity =
                render_opacity * command.text_path_bucket_opacity.unwrap_or(1.0);
            command.render_opacity = effective_opacity;
            if let Some(paint) =
                command
                    .text_paint_ref
                    .and_then(|(container_index, paint_index)| {
                        graph
                            .shape_paint_containers
                            .get(container_index)
                            .and_then(|container| container.paints.get(paint_index))
                    })
            {
                command.paint_state = runtime_shape_paint_state(instance, paint, effective_opacity);
            }
        }
        true
    }

    fn propagate_world_transform(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        text_local: usize,
        layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    ) -> bool {
        let text_world = instance.runtime_component_world_transform_with_bounds(
            text_local,
            graph,
            layout_bounds,
        );
        let mut retained = self.retained.borrow_mut();
        let Some(frame) = retained.as_mut() else {
            return false;
        };
        let shape_world = text_world.multiply(frame.shape_local_transform);
        let commands = Arc::make_mut(&mut frame.commands);
        let mut world_geometry_changed = false;
        for command in commands.iter_mut() {
            let previous_shape_world = command.shape_world_override.unwrap_or(shape_world);
            if let Some(paint) =
                command
                    .text_paint_ref
                    .and_then(|(container_index, paint_index)| {
                        graph
                            .shape_paint_containers
                            .get(container_index)
                            .and_then(|container| container.paints.get(paint_index))
                    })
            {
                let path_kind = runtime_live_shape_paint_path_kind(instance, paint)
                    .unwrap_or(command.path_kind);
                command.paint_space_transform =
                    runtime_shape_paint_space_transform(path_kind, shape_world);
                if path_kind == RuntimeShapePaintPathKind::World {
                    let delta = shape_world.multiply(previous_shape_world.invert_or_identity());
                    transform_path_commands(&mut command.path_commands, delta);
                    transform_path_commands(&mut command.effect_path_commands, delta);
                    if let Some(feather) = command.feather_state.as_mut() {
                        transform_path_commands(&mut feather.inner_path_commands, delta);
                    }
                    world_geometry_changed = true;
                }
            }
            command.shape_world_override = Some(shape_world);
        }
        if world_geometry_changed {
            frame.paths = Arc::new(runtime_text_owned_raw_paths(commands));
        }
        if let Some(color) = frame.color.as_mut() {
            Arc::make_mut(color).shape_world = shape_world;
        }
        frame.clip_path = frame.clip_bounds.map(|bounds| {
            Arc::new(runtime_raw_path_from_commands(
                &runtime_text_clip_path_commands(bounds, text_world),
            ))
        });
        true
    }

    fn retained_or_build(
        &self,
        build: impl FnOnce() -> Result<RuntimeCachedTextShapePaints>,
    ) -> Result<RuntimeCachedTextShapePaints> {
        if self.dirty.get() || self.retained.borrow().is_none() {
            let retained = build()?;
            if self.retained.borrow().is_some() && self.render_styles_dirty.get() {
                // `Text::buildRenderStyles()` begins with
                // `clearRenderStyles()`, whose
                // `TextStylePaint::rewindPath()` clears `m_opacityPaths`.
                // Render-style dirt therefore creates fresh
                // ShapePaintPath/RenderPath objects; only
                // TextStylePaint::m_path and Text::m_clipPath rewind in place
                // (`text.cpp:534-543`, `text_style_paint.cpp:15-43`).
                //
                // World-transform and render-opacity dirt take C++'s separate
                // update branches and must not clear these paths merely
                // because Rust refreshes its immutable retained draw frame
                // (`text.cpp:1209-1230`).
                // Direct opacity buckets carry their TextStylePaint owner and
                // are replaced by `clearRenderStyles`. Effect and feather
                // outputs carry their concrete ShapePaint owner and rewind in
                // place when that retained paint invalidates them.
                self.backend
                    .borrow_mut()
                    .paths
                    .retain(|key, _| !key.replace_on_render_style_rebuild);
            }
            *self.retained.borrow_mut() = Some(retained);
            self.dirty.set(false);
            self.pending_update_dirt.set(ComponentDirt::NONE);
            self.render_styles_dirty.set(false);
            self.retain_paths_on_rebuild.set(false);
        }
        Ok(self
            .retained
            .borrow()
            .as_ref()
            .expect("text owner was just populated")
            .clone())
    }

    fn rebuild(
        &self,
        build: impl FnOnce() -> Result<RuntimeCachedTextShapePaints>,
    ) -> Result<bool> {
        if !self.dirty.get() && self.retained.borrow().is_some() {
            return Ok(false);
        }
        self.retained_or_build(build)?;
        Ok(true)
    }

    fn retained_frame(&self) -> Result<RuntimeCachedTextShapePaints> {
        // Pending dirt is legal here: setters running between the last
        // advance and this draw (state-machine pointer listeners, data-bind
        // writes) only publish dirt in C++ (`TextValueRun::textChanged` ->
        // `Text::markShapeDirty` -> `addDirt`, `text_value_run.cpp:11-14`,
        // `text.cpp:951-971`); `Text::buildRenderStyles` runs solely in the
        // next update pass, and `Text::draw` renders whatever
        // `m_drawCommands` the previous update built (`text.cpp:845-875`).
        // Draw therefore consumes the stale retained frame and the dirt
        // survives for the next component update.
        self.retained
            .borrow()
            .as_ref()
            .cloned()
            .context("Text update did not retain render styles")
    }
}

#[derive(Default)]
struct RuntimeTextBackendResources {
    context_id: Option<u64>,
    pooled_paints: BTreeMap<(usize, usize), RuntimeTextPooledPaintBackend>,
    paths: BTreeMap<RuntimeTextPathOwnerKey, RuntimeTextPathBackend>,
    clip_path: Option<RuntimeTextPathBackend>,
    color_paths: BTreeMap<(usize, usize), RuntimeTextPathBackend>,
    emoji_images: BTreeMap<(usize, u32), Option<Box<dyn RenderImage>>>,
}

impl std::fmt::Debug for RuntimeTextBackendResources {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("RuntimeTextBackendResources")
            .field("context_id", &self.context_id)
            .field("pooled_paints", &self.pooled_paints.len())
            .field("paths", &self.paths.len())
            .field("clip_path", &self.clip_path.is_some())
            .field("color_paths", &self.color_paths.len())
            .field("emoji_images", &self.emoji_images.len())
            .finish()
    }
}

struct RuntimeTextPooledPaintBackend {
    paint: Box<dyn RenderPaint>,
    configuration: Option<RuntimeCachedRenderPaintConfiguration>,
}

struct RuntimeTextPathBackend {
    path: Box<dyn RenderPath>,
    raw_mutation_id: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct RuntimeTextPathOwnerKey {
    owner_local: usize,
    replace_on_render_style_rebuild: bool,
    slot: usize,
}

/// Concrete virtual draw family retained with each cloned Drawable. Pinned
/// C++ pays one vtable dispatch from `Artboard::drawInternal`; it does not
/// rediscover the subclass through strings on every frame
/// (`src/artboard.cpp:1652-1698`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RuntimeDrawableFamily {
    Shape,
    Image,
    Text,
    TextInputConcrete,
    TextInputContainer,
    LayoutComponent,
    ForegroundLayoutDrawable,
    NestedArtboard,
    ArtboardComponentList,
    ScriptedDrawable,
    ClipProxy,
    Other,
}

impl RuntimeDrawableFamily {
    fn from_type_name(type_name: &str) -> Self {
        match type_name {
            "Shape" => Self::Shape,
            "Image" => Self::Image,
            "Text" => Self::Text,
            "TextInputCursor"
            | "TextInputSelectedText"
            | "TextInputSelection"
            | "TextInputText" => Self::TextInputConcrete,
            "TextInput" | "TextInputDrawable" => Self::TextInputContainer,
            "LayoutComponent" => Self::LayoutComponent,
            "ForegroundLayoutDrawable" => Self::ForegroundLayoutDrawable,
            "NestedArtboard" | "NestedArtboardLeaf" | "NestedArtboardLayout" => {
                Self::NestedArtboard
            }
            "ArtboardComponentList" => Self::ArtboardComponentList,
            "ScriptedDrawable" | "ScriptedLayout" => Self::ScriptedDrawable,
            "ClippingShapeProxyDrawable" => Self::ClipProxy,
            _ => Self::Other,
        }
    }

    fn uses_render_opacity(self) -> bool {
        matches!(self, Self::Shape | Self::TextInputContainer)
    }
}

/// Clone-owned counterpart of `LayoutComponent::m_backgroundRawPath`,
/// `m_localPath`, and `m_worldPath`.
#[derive(Debug, Clone)]
struct RuntimeLayoutDrawPaths {
    _background: Arc<RawPath>,
    paint: Arc<Vec<RuntimePathCommand>>,
    clip: Arc<Vec<RuntimePathCommand>>,
}

#[derive(Default)]
struct RuntimeLayoutBackendResources {
    context_id: Option<u64>,
    clip_path: Option<RuntimeRetainedRenderPath>,
    draw_paths: RuntimeDrawPathSlots,
}

impl std::fmt::Debug for RuntimeLayoutBackendResources {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("RuntimeLayoutBackendResources")
            .field("context_id", &self.context_id)
            .field("clip_path", &self.clip_path.is_some())
            .finish_non_exhaustive()
    }
}

#[derive(Debug)]
struct RuntimeLayoutDrawOwner {
    dirty: Cell<bool>,
    revision: Cell<u64>,
    retained: RefCell<Option<RuntimeLayoutDrawPaths>>,
    retained_paint_commands:
        RefCell<[Option<(RuntimeLayoutPaintCommandKey, Vec<RuntimeShapePaintCommand>)>; 2]>,
    backend: RefCell<RuntimeLayoutBackendResources>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RuntimeLayoutPaintCommandKey {
    cache_epoch: u64,
    prepared_epoch: u64,
    layout_revision: u64,
    path_revision: u64,
}

impl Clone for RuntimeLayoutDrawOwner {
    fn clone(&self) -> Self {
        // Generated Core clones rebuild LayoutComponent's custom path members;
        // renderer resources never cross an occurrence boundary.
        Self::default()
    }
}

impl Default for RuntimeLayoutDrawOwner {
    fn default() -> Self {
        Self {
            dirty: Cell::new(true),
            revision: Cell::new(0),
            retained: RefCell::new(None),
            retained_paint_commands: RefCell::new([None, None]),
            backend: RefCell::new(RuntimeLayoutBackendResources::default()),
        }
    }
}

impl RuntimeLayoutDrawOwner {
    fn mark_dirty(&self) {
        self.dirty.set(true);
        self.revision.set(self.revision.get().wrapping_add(1));
    }

    fn backend(&self, context_id: u64) -> std::cell::RefMut<'_, RuntimeLayoutBackendResources> {
        let mut backend = self.backend.borrow_mut();
        if backend.context_id != Some(context_id) {
            *backend = RuntimeLayoutBackendResources {
                context_id: Some(context_id),
                ..RuntimeLayoutBackendResources::default()
            };
        }
        backend
    }

    fn retained_or_build(
        &self,
        build: impl FnOnce() -> RuntimeLayoutDrawPaths,
    ) -> RuntimeLayoutDrawPaths {
        if self.dirty.get() || self.retained.borrow().is_none() {
            *self.retained.borrow_mut() = Some(build());
            self.dirty.set(false);
        }
        self.retained
            .borrow()
            .as_ref()
            .expect("layout owner was just populated")
            .clone()
    }

    fn retained_paint_commands(
        &self,
        slot: usize,
        key: RuntimeLayoutPaintCommandKey,
        build: impl FnOnce() -> Vec<RuntimeShapePaintCommand>,
    ) -> std::cell::Ref<'_, [RuntimeShapePaintCommand]> {
        let needs_rebuild = self
            .retained_paint_commands
            .borrow()
            .get(slot)
            .and_then(Option::as_ref)
            .is_none_or(|(cached_key, _)| *cached_key != key);
        if needs_rebuild {
            self.retained_paint_commands.borrow_mut()[slot] = Some((key, build()));
        }
        std::cell::Ref::map(self.retained_paint_commands.borrow(), |retained| {
            retained
                .get(slot)
                .and_then(Option::as_ref)
                .expect("layout paint commands were just populated")
                .1
                .as_slice()
        })
    }
}

#[derive(Debug, Clone)]
pub(crate) struct RuntimeDrawable {
    kind: DrawableOrderKind,
    local_id: Option<usize>,
    /// C++ `Drawable` inherits `Component`, so draw traversal reads collapse,
    /// opacity, and world transform on the same concrete object. This stable
    /// handle is the Rust non-owning pointer counterpart.
    component_handle: Option<ComponentHandle>,
    global_id: Option<u32>,
    type_name: &'static str,
    family: RuntimeDrawableFamily,
    resolved_image_asset_global: Option<u32>,
    referenced_artboard_global: Option<u32>,
    layout_local: Option<usize>,
    flattened_draw_rules_local: Option<usize>,
    flattened_draw_rules_index: Option<usize>,
    draw_target_local: Option<usize>,
    clipping_shape_local: Option<usize>,
    /// C++ `Text::m_drawCommands` / TextInputDrawable's parent-owned paths.
    /// This CPU-side retained frame is clone-owned with the concrete drawable
    /// and is dirtied by object changes, never by a scene epoch.
    text_draw_owner: Option<RuntimeTextDrawOwner>,
    needs_save_operation: bool,
    /// C++ `Drawable::prev`; `Artboard::drawInternal` follows this link.
    prev: Option<usize>,
    /// C++ `Drawable::next`; maintained for target/proxy splicing.
    next: Option<usize>,
}

impl RuntimeDrawable {
    fn from_imported(drawable: &DrawableOrderNode, objects: &InstanceObjectArena) -> Self {
        let component_local = match drawable.kind {
            DrawableOrderKind::LayoutProxy => drawable.layout_local,
            _ => drawable.local_id,
        };
        Self {
            kind: drawable.kind,
            local_id: drawable.local_id,
            component_handle: component_local
                .and_then(|component_local| objects.component_handle(component_local)),
            global_id: drawable.global_id,
            type_name: drawable.type_name,
            family: RuntimeDrawableFamily::from_type_name(drawable.type_name),
            resolved_image_asset_global: drawable.resolved_image_asset_global,
            referenced_artboard_global: drawable.referenced_artboard_global,
            layout_local: drawable.layout_local,
            flattened_draw_rules_local: drawable.flattened_draw_rules_local,
            flattened_draw_rules_index: None,
            draw_target_local: None,
            clipping_shape_local: None,
            text_draw_owner: (drawable.type_name == "Text"
                || is_text_input_drawable_type(drawable.type_name))
            .then(RuntimeTextDrawOwner::default),
            needs_save_operation: true,
            prev: None,
            next: None,
        }
    }

    fn clipping_proxy(clipping_shape_local: usize, kind: DrawableOrderKind) -> Self {
        debug_assert!(matches!(
            kind,
            DrawableOrderKind::ClipStartProxy | DrawableOrderKind::ClipEndProxy
        ));
        Self {
            kind,
            local_id: None,
            component_handle: None,
            global_id: None,
            type_name: "ClippingShapeProxyDrawable",
            family: RuntimeDrawableFamily::ClipProxy,
            resolved_image_asset_global: None,
            referenced_artboard_global: None,
            layout_local: None,
            flattened_draw_rules_local: None,
            flattened_draw_rules_index: None,
            draw_target_local: None,
            clipping_shape_local: Some(clipping_shape_local),
            text_draw_owner: None,
            needs_save_operation: true,
            prev: None,
            next: None,
        }
    }

    /// C++ `Drawable::hittableComponent` returns the Drawable itself, while
    /// `DrawableProxy` returns its `LayoutComponent` ProxyDrawing owner and a
    /// clipping proxy returns no hittable component
    /// (`src/drawable.cpp:62-88`;
    /// `include/rive/shapes/clipping_shape.hpp:64-66`).
    fn hittable_component(&self) -> Option<ComponentHandle> {
        match self.kind {
            DrawableOrderKind::ClipStartProxy | DrawableOrderKind::ClipEndProxy => None,
            DrawableOrderKind::Drawable | DrawableOrderKind::LayoutProxy => self.component_handle,
        }
    }
}

/// Clone-owned counterpart of C++ `Artboard::m_Drawables`, `m_DrawTargets`,
/// and `m_FirstDrawable`. Clip proxies are pooled by their owning clipping
/// shape, matching `ClippingShape::resetDrawables/createProxyDrawable`.
#[derive(Debug, Clone, Default)]
pub(crate) struct RuntimeDrawableList {
    drawables: Vec<Box<RuntimeDrawable>>,
    imported_count: usize,
    layout_draw_owners: Vec<Option<RuntimeLayoutDrawOwner>>,
    first_drawable: Option<usize>,
    drawable_by_local: BTreeMap<usize, usize>,
    draw_rules: Vec<crate::draw_rules::RuntimeDrawRules>,
    draw_rules_index_by_local: BTreeMap<usize, usize>,
    draw_targets: Vec<crate::draw_target::RuntimeDrawTarget>,
    draw_target_index_by_local: BTreeMap<usize, usize>,
    draw_target_order: Vec<usize>,
    active_proxies: Vec<usize>,
    pooled_proxies: BTreeMap<usize, Vec<usize>>,
    #[cfg(test)]
    sort_draw_order_call_count: Cell<usize>,
    #[cfg(test)]
    clear_redundant_operations_call_count: Cell<usize>,
}

impl RuntimeDrawableList {
    /// Preserve backend sidecars when a virtualized component-list row is
    /// restored from a fresh authored-property snapshot. The drawable CPU
    /// state comes from the snapshot; the RenderPath/RenderPaint objects stay
    /// with the pooled occurrence, matching C++ property-recorder replay.
    pub(crate) fn adopt_pooled_backend_owners(&mut self, pooled: &mut Self) {
        for (fresh_drawable, pooled_drawable) in
            self.drawables.iter_mut().zip(&mut pooled.drawables)
        {
            if fresh_drawable.local_id != pooled_drawable.local_id
                || fresh_drawable.type_name != pooled_drawable.type_name
            {
                continue;
            }
            if let (Some(fresh_owner), Some(pooled_owner)) = (
                fresh_drawable.text_draw_owner.as_mut(),
                pooled_drawable.text_draw_owner.as_mut(),
            ) {
                std::mem::swap(&mut fresh_owner.backend, &mut pooled_owner.backend);
                // The pooled C++ Text keeps its concrete TextStylePaint
                // opacity paths while property recorders and the new row
                // context rebuild CPU draw commands. Mark this as the
                // layout/property refresh branch so the next Text update
                // rewinds those paths instead of treating the fresh snapshot
                // as `clearRenderStyles` ownership replacement.
                fresh_owner.mark_paths_retained_dirty();
            }
        }
        for (fresh_owner, pooled_owner) in self
            .layout_draw_owners
            .iter_mut()
            .zip(&mut pooled.layout_draw_owners)
        {
            if let (Some(fresh_owner), Some(pooled_owner)) = (fresh_owner, pooled_owner) {
                std::mem::swap(&mut fresh_owner.backend, &mut pooled_owner.backend);
            }
        }
    }

    pub(crate) fn from_graph(graph: &ArtboardGraph, objects: &InstanceObjectArena) -> Self {
        let mut drawables = graph
            .drawable_order
            .iter()
            .map(|drawable| Box::new(RuntimeDrawable::from_imported(drawable, objects)))
            .collect::<Vec<_>>();
        let imported_count = drawables.len();
        let mut layout_draw_owners = Vec::new();
        for component in graph
            .components
            .iter()
            .filter(|component| component.type_name == "LayoutComponent")
        {
            if layout_draw_owners.len() <= component.local_id {
                layout_draw_owners.resize_with(component.local_id + 1, || None);
            }
            layout_draw_owners[component.local_id] = Some(RuntimeLayoutDrawOwner::default());
        }
        let drawable_by_local: BTreeMap<usize, usize> = drawables
            .iter()
            .enumerate()
            .filter_map(|(index, drawable)| drawable.local_id.map(|local| (local, index)))
            .collect();
        let draw_targets = graph
            .draw_targets
            .iter()
            .map(|target| crate::draw_target::RuntimeDrawTarget {
                local_id: target.local_id,
                drawable_index: target
                    .drawable_local
                    .and_then(|local| drawable_by_local.get(&local).copied()),
                placement_value: target.placement_value,
                first: None,
                last: None,
            })
            .collect::<Vec<_>>();
        let draw_target_index_by_local: BTreeMap<usize, usize> = draw_targets
            .iter()
            .enumerate()
            .map(|(index, target)| (target.local_id, index))
            .collect();
        let draw_rules = graph
            .draw_rules
            .iter()
            .map(|rules| {
                crate::draw_rules::RuntimeDrawRules::new(
                    rules
                        .active_target_local
                        .and_then(|target| draw_target_index_by_local.get(&target).copied()),
                )
            })
            .collect::<Vec<_>>();
        let draw_rules_index_by_local = graph
            .draw_rules
            .iter()
            .enumerate()
            .map(|(index, rules)| (rules.local_id, index))
            .collect::<BTreeMap<_, _>>();
        for drawable in &mut drawables {
            drawable.flattened_draw_rules_index = drawable
                .flattened_draw_rules_local
                .and_then(|local| draw_rules_index_by_local.get(&local).copied());
        }
        let draw_target_order = graph
            .draw_target_order
            .iter()
            .filter_map(|local| draw_target_index_by_local.get(local).copied())
            .collect();
        let initial_clipping_visibility = graph
            .clipping_shapes
            .iter()
            .map(|shape| (shape.local_id, shape.is_visible))
            .collect::<BTreeMap<_, _>>();
        let mut result = Self {
            drawables,
            imported_count,
            layout_draw_owners,
            first_drawable: None,
            drawable_by_local,
            draw_rules,
            draw_rules_index_by_local,
            draw_targets,
            draw_target_index_by_local,
            draw_target_order,
            active_proxies: Vec::new(),
            pooled_proxies: BTreeMap::new(),
            #[cfg(test)]
            sort_draw_order_call_count: Cell::new(0),
            #[cfg(test)]
            clear_redundant_operations_call_count: Cell::new(0),
        };
        result.sort_draw_order(
            Some(objects),
            runtime_draw_property_key_for_name("ClippingShape", "isVisible"),
            Some(&initial_clipping_visibility),
        );
        result
    }

    fn hit_component_order(&self) -> Vec<ComponentHandle> {
        let mut result = Vec::new();
        self.visit_hit_component_order(|handle| {
            if !result.contains(&handle) {
                result.push(handle);
            }
            true
        });
        result
    }

    fn visit_hit_component_order(&self, mut visit: impl FnMut(ComponentHandle) -> bool) {
        // `StateMachineInstance::sortHitComponents` starts at
        // `firstDrawable`, walks `prev` to the back, then visits `next` so hit
        // targets are processed front-to-back (`state_machine_instance.cpp:
        // 2255-2297`). Read the live relinked list, never copied graph order.
        let mut first = self.first_drawable;
        while let Some(index) = first {
            let Some(previous) = self.drawables[index].prev else {
                break;
            };
            first = Some(previous);
        }
        let mut current = first;
        while let Some(index) = current {
            let drawable = self.drawables[index].as_ref();
            if let Some(handle) = drawable.hittable_component()
                && !visit(handle)
            {
                break;
            }
            current = drawable.next;
        }
    }

    pub(crate) fn mark_text_resources_dirty(&self) {
        for drawable in self.drawables.iter().take(self.imported_count) {
            if let Some(owner) = drawable.text_draw_owner.as_ref() {
                // A font-resource replacement is C++ FontAsset::fontChanged
                // -> TextShape dirt, so every affected Text executes
                // buildRenderStyles and clears its opacity paths.
                owner.mark_external_font_shape_dirty();
            }
        }
    }

    pub(crate) fn dirty_text_locals(&self) -> Vec<(usize, ComponentDirt)> {
        self.drawables
            .iter()
            .take(self.imported_count)
            .filter(|drawable| drawable.type_name == "Text")
            .filter_map(|drawable| {
                let owner = drawable.text_draw_owner.as_ref()?;
                if !owner.is_dirty() {
                    return None;
                }
                let pending = owner.pending_update_dirt.get();
                Some((
                    drawable.local_id?,
                    if pending.is_empty() {
                        ComponentDirt::PATH
                    } else {
                        pending
                    },
                ))
            })
            .collect()
    }

    pub(crate) fn mark_text_paint_dirty_for_local(&self, local_id: usize) {
        let Some(drawable_index) = self.drawable_by_local.get(&local_id).copied() else {
            return;
        };
        if let Some(owner) = self.drawables[drawable_index].text_draw_owner.as_ref() {
            owner.mark_paint_paths_retained_dirty();
        }
    }

    pub(crate) fn mark_text_shape_paths_retained_for_local(&self, local_id: usize) {
        let Some(drawable_index) = self.drawable_by_local.get(&local_id).copied() else {
            return;
        };
        if let Some(owner) = self.drawables[drawable_index].text_draw_owner.as_ref() {
            owner.mark_paths_retained_dirty();
        }
    }

    pub(crate) fn mark_text_render_styles_dirty_for_local(&self, local_id: usize) {
        let Some(drawable_index) = self.drawable_by_local.get(&local_id).copied() else {
            return;
        };
        if let Some(owner) = self.drawables[drawable_index].text_draw_owner.as_ref() {
            owner.mark_render_styles_dirty();
        }
    }

    pub(crate) fn mark_layout_resource_dirty_for_local(&self, local_id: usize) -> bool {
        if let Some(owner) = self
            .layout_draw_owners
            .get(local_id)
            .and_then(Option::as_ref)
        {
            owner.mark_dirty();
            true
        } else {
            false
        }
    }

    fn layout_draw_paths(
        &self,
        layout_local: usize,
        build: impl FnOnce() -> RuntimeLayoutDrawPaths,
    ) -> Option<RuntimeLayoutDrawPaths> {
        Some(
            self.layout_draw_owners
                .get(layout_local)?
                .as_ref()?
                .retained_or_build(build),
        )
    }

    fn layout_draw_owner(&self, layout_local: usize) -> Option<&RuntimeLayoutDrawOwner> {
        self.layout_draw_owners.get(layout_local)?.as_ref()
    }

    fn sort_draw_order(
        &mut self,
        objects: Option<&InstanceObjectArena>,
        is_visible_key: Option<u16>,
        initial_clipping_visibility: Option<&BTreeMap<usize, bool>>,
    ) {
        #[cfg(test)]
        self.sort_draw_order_call_count
            .set(self.sort_draw_order_call_count.get() + 1);
        // Ported from C++ `Artboard::sortDrawOrder` (artboard.cpp:574-746).
        self.reset_proxy_drawables();
        for drawable in &mut self.drawables[..self.imported_count] {
            drawable.prev = None;
            drawable.next = None;
            drawable.draw_target_local = None;
            drawable.needs_save_operation = true;
        }
        for target in &mut self.draw_targets {
            target.first = None;
            target.last = None;
        }

        let mut last_main = None;
        for drawable_index in 0..self.imported_count {
            let active_target_index = self.drawables[drawable_index]
                .flattened_draw_rules_index
                .and_then(|rules_index| self.draw_rules.get(rules_index))
                .and_then(|rules| rules.active_target_index)
                .filter(|target_index| {
                    self.draw_targets
                        .get(*target_index)
                        .is_some_and(|target| target.drawable_index.is_some())
                });
            self.drawables[drawable_index].draw_target_local = active_target_index
                .and_then(|target_index| self.draw_targets.get(target_index))
                .map(|target| target.local_id);
            if let Some(target_index) = active_target_index {
                let previous = self.draw_targets[target_index].last;
                self.drawables[drawable_index].prev = previous;
                if let Some(previous) = previous {
                    self.drawables[previous].next = Some(drawable_index);
                } else {
                    self.draw_targets[target_index].first = Some(drawable_index);
                }
                self.draw_targets[target_index].last = Some(drawable_index);
                continue;
            }

            self.drawables[drawable_index].prev = last_main;
            if let Some(previous) = last_main {
                self.drawables[previous].next = Some(drawable_index);
            }
            last_main = Some(drawable_index);
        }

        for order_index in 0..self.draw_target_order.len() {
            let target_index = self.draw_target_order[order_index];
            let Some(group_first) = self.draw_targets[target_index].first else {
                continue;
            };
            let Some(group_last) = self.draw_targets[target_index].last else {
                continue;
            };
            let Some(target_drawable) = self.draw_targets[target_index].drawable_index else {
                continue;
            };
            let placement = self.draw_targets[target_index].placement_value;
            match placement {
                0 => {
                    let target_prev = self.drawables[target_drawable].prev;
                    if let Some(target_prev) = target_prev {
                        self.drawables[target_prev].next = Some(group_first);
                        self.drawables[group_first].prev = Some(target_prev);
                    }
                    self.drawables[target_drawable].prev = Some(group_last);
                    self.drawables[group_last].next = Some(target_drawable);
                }
                1 => {
                    let target_next = self.drawables[target_drawable].next;
                    if let Some(target_next) = target_next {
                        self.drawables[target_next].prev = Some(group_last);
                        self.drawables[group_last].next = Some(target_next);
                    }
                    if last_main == Some(target_drawable) {
                        last_main = Some(group_last);
                    }
                    self.drawables[target_drawable].next = Some(group_first);
                    self.drawables[group_first].prev = Some(target_drawable);
                }
                _ => {}
            }
        }

        self.first_drawable = last_main;
        self.interleave_clipping_proxies(objects);
        self.clear_redundant_operations(objects, is_visible_key, initial_clipping_visibility);
    }

    pub(crate) fn set_draw_rules_active_target(
        &mut self,
        rules_local: usize,
        active_target_local: Option<usize>,
    ) {
        let active_target_index = active_target_local
            .and_then(|target| self.draw_target_index_by_local.get(&target).copied());
        if let Some(rules) = self
            .draw_rules_index_by_local
            .get(&rules_local)
            .and_then(|index| self.draw_rules.get_mut(*index))
        {
            rules.active_target_index = active_target_index;
        }
    }

    pub(crate) fn set_draw_target_placement(&mut self, target_local: usize, placement_value: u64) {
        let Some(target_index) = self.draw_target_index_by_local.get(&target_local).copied() else {
            return;
        };
        self.draw_targets[target_index].placement_value = placement_value;
    }

    fn reset_proxy_drawables(&mut self) {
        for proxy in self.active_proxies.drain(..) {
            let clipping_local = self.drawables[proxy]
                .clipping_shape_local
                .expect("active clipping proxy has an owner");
            self.drawables[proxy].prev = None;
            self.drawables[proxy].next = None;
            self.pooled_proxies
                .entry(clipping_local)
                .or_default()
                .push(proxy);
        }
    }

    fn create_proxy(&mut self, clipping_local: usize, kind: DrawableOrderKind) -> usize {
        let proxy = self
            .pooled_proxies
            .get_mut(&clipping_local)
            .and_then(Vec::pop)
            .unwrap_or_else(|| {
                self.drawables
                    .push(Box::new(RuntimeDrawable::clipping_proxy(
                        clipping_local,
                        kind,
                    )));
                self.drawables.len() - 1
            });
        let drawable = &mut self.drawables[proxy];
        drawable.kind = kind;
        drawable.prev = None;
        drawable.next = None;
        drawable.needs_save_operation = true;
        self.active_proxies.push(proxy);
        proxy
    }

    fn interleave_clipping_proxies(&mut self, objects: Option<&InstanceObjectArena>) {
        let mut current = self.first_drawable;
        let mut next_drawable = None;
        let mut clipping_stack = Vec::<usize>::new();
        while let Some(current_index) = current {
            let drawable_clips = self.drawables[current_index]
                .component_handle
                .and_then(|component| objects?.component(component))
                .and_then(|component| component.concrete.drawable.as_ref())
                .map(|drawable| {
                    drawable
                        .clipping_shapes
                        .iter()
                        .filter_map(|shape| objects?.component_local_id(*shape))
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            let removing_index = clipping_stack
                .iter()
                .position(|clipping| !drawable_clips.contains(clipping))
                .unwrap_or(clipping_stack.len());
            for stack_index in (removing_index..clipping_stack.len()).rev() {
                let proxy =
                    self.create_proxy(clipping_stack[stack_index], DrawableOrderKind::ClipEndProxy);
                self.insert_proxy_after(current_index, next_drawable, proxy);
                next_drawable = Some(proxy);
            }
            clipping_stack.truncate(removing_index);

            for clipping_local in drawable_clips {
                if !clipping_stack.contains(&clipping_local) {
                    let proxy =
                        self.create_proxy(clipping_local, DrawableOrderKind::ClipStartProxy);
                    self.insert_proxy_after(current_index, next_drawable, proxy);
                    if next_drawable.is_none() {
                        self.first_drawable = Some(proxy);
                    }
                    next_drawable = Some(proxy);
                    clipping_stack.push(clipping_local);
                }
            }
            next_drawable = Some(current_index);
            current = self.drawables[current_index].prev;
        }

        for clipping_local in clipping_stack.into_iter().rev() {
            let proxy = self.create_proxy(clipping_local, DrawableOrderKind::ClipEndProxy);
            if let Some(next) = next_drawable {
                self.drawables[next].prev = Some(proxy);
                self.drawables[proxy].next = Some(next);
            }
            self.drawables[proxy].prev = None;
            next_drawable = Some(proxy);
        }
    }

    fn insert_proxy_after(&mut self, current: usize, next_drawable: Option<usize>, proxy: usize) {
        if let Some(next) = next_drawable {
            self.drawables[proxy].next = Some(next);
            self.drawables[next].prev = Some(proxy);
        }
        self.drawables[proxy].prev = Some(current);
        self.drawables[current].next = Some(proxy);
    }

    fn clear_redundant_operations(
        &mut self,
        objects: Option<&InstanceObjectArena>,
        is_visible_key: Option<u16>,
        initial_clipping_visibility: Option<&BTreeMap<usize, bool>>,
    ) {
        #[cfg(test)]
        self.clear_redundant_operations_call_count
            .set(self.clear_redundant_operations_call_count.get() + 1);
        // Ported from C++ `Artboard::clearRedundantOperations`
        // (artboard.cpp:750-804).
        let mut current = self.first_drawable;
        let mut previous_applied_save = false;
        let mut applied_clipping_saves = Vec::<bool>::new();
        while let Some(index) = current {
            self.drawables[index].needs_save_operation = true;
            if previous_applied_save {
                if self.drawables[index].kind == DrawableOrderKind::ClipStartProxy {
                    applied_clipping_saves.push(false);
                    self.drawables[index].needs_save_operation = false;
                } else if self.drawables[index].kind == DrawableOrderKind::ClipEndProxy {
                    let applied = applied_clipping_saves.pop().unwrap_or(true);
                    self.drawables[index].needs_save_operation = applied;
                } else if self.drawables[index].prev.is_some_and(|prev| {
                    self.drawables[prev].kind == DrawableOrderKind::ClipEndProxy
                }) {
                    self.drawables[index].needs_save_operation = false;
                }
            } else if self.drawables[index].kind == DrawableOrderKind::ClipStartProxy {
                applied_clipping_saves.push(true);
            } else if self.drawables[index].kind == DrawableOrderKind::ClipEndProxy {
                let applied = applied_clipping_saves.pop().unwrap_or(true);
                self.drawables[index].needs_save_operation = applied;
            }
            let will_clip = self.drawables[index]
                .clipping_shape_local
                .is_some_and(|local| {
                    objects
                        .zip(is_visible_key)
                        .and_then(|(objects, key)| objects.bool_property(local, key))
                        .or_else(|| initial_clipping_visibility?.get(&local).copied())
                        .unwrap_or(false)
                });
            previous_applied_save = self.drawables[index].kind == DrawableOrderKind::ClipStartProxy
                && (will_clip || previous_applied_save);
            current = self.drawables[index].prev;
        }
        debug_assert!(applied_clipping_saves.is_empty());
    }

    #[cfg(test)]
    pub(crate) fn reset_artboard_maintenance_call_counts(&self) {
        self.sort_draw_order_call_count.set(0);
        self.clear_redundant_operations_call_count.set(0);
    }

    #[cfg(test)]
    pub(crate) fn artboard_maintenance_call_counts(&self) -> (usize, usize) {
        (
            self.sort_draw_order_call_count.get(),
            self.clear_redundant_operations_call_count.get(),
        )
    }

    pub(crate) fn iter(&self) -> RuntimeDrawableIter<'_> {
        RuntimeDrawableIter {
            list: self,
            current: self.first_drawable,
        }
    }
}

/// Retain `Drawable::m_ClippingShapes` on the concrete occurrence in C++
/// registration order (`drawable.cpp:42-45`; `clipping_shape.cpp:84-101`).
pub(crate) fn retain_runtime_drawable_component_topology(
    graph: &ArtboardGraph,
    objects: &mut InstanceObjectArena,
) {
    for clipping_shape in &graph.clipping_shapes {
        let Some(shape) = objects.component_handle(clipping_shape.local_id) else {
            continue;
        };
        for drawable_local in &clipping_shape.clipped_drawable_locals {
            let Some(drawable) = objects.component_handle(*drawable_local) else {
                continue;
            };
            let Some(state) = objects
                .component_mut(drawable)
                .and_then(|component| component.concrete.drawable.as_mut())
            else {
                continue;
            };
            state.clipping_shapes.push(shape);
        }
    }
}

pub(crate) struct RuntimeDrawableIter<'a> {
    list: &'a RuntimeDrawableList,
    current: Option<usize>,
}

impl<'a> Iterator for RuntimeDrawableIter<'a> {
    type Item = &'a RuntimeDrawable;

    fn next(&mut self) -> Option<Self::Item> {
        let index = self.current?;
        let drawable = self.list.drawables.get(index)?.as_ref();
        self.current = drawable.prev;
        Some(drawable)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuntimeDrawableDispatchKind {
    Draw,
    ClipStart,
    ClipEnd,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuntimeDrawableDispatchObjectKind {
    ArtboardComponentList,
    DrawableProxy,
    ForegroundLayoutDrawable,
    Image,
    LayoutComponent,
    NestedArtboard,
    NestedArtboardLeaf,
    NestedArtboardLayout,
    ScriptedDrawable,
    Text,
    Other,
}

impl RuntimeDrawableDispatchObjectKind {
    fn from_type_name(type_name: &str) -> Self {
        match type_name {
            "ArtboardComponentList" => Self::ArtboardComponentList,
            "DrawableProxy" => Self::DrawableProxy,
            "ForegroundLayoutDrawable" => Self::ForegroundLayoutDrawable,
            "Image" => Self::Image,
            "LayoutComponent" => Self::LayoutComponent,
            "NestedArtboard" => Self::NestedArtboard,
            "NestedArtboardLeaf" => Self::NestedArtboardLeaf,
            "NestedArtboardLayout" => Self::NestedArtboardLayout,
            "ScriptedDrawable" | "ScriptedLayout" => Self::ScriptedDrawable,
            "Text" => Self::Text,
            _ => Self::Other,
        }
    }

    fn is_nested_artboard(self) -> bool {
        matches!(
            self,
            Self::NestedArtboard | Self::NestedArtboardLeaf | Self::NestedArtboardLayout
        )
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct RuntimeDrawableDispatch {
    pub kind: RuntimeDrawableDispatchKind,
    pub object_kind: RuntimeDrawableDispatchObjectKind,
    pub local_id: Option<usize>,
    pub global_id: Option<u32>,
    pub type_name: &'static str,
    pub world_transform: Option<Mat2D>,
    pub render_opacity: f32,
    pub referenced_artboard_global: Option<u32>,
    pub resolved_image_asset_global: Option<u32>,
    pub clipping_shape_local: Option<usize>,
    pub needs_save_operation: bool,
    pub shape_paints: Vec<RuntimeShapePaintCommand>,
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq)]
pub struct RuntimeLayoutBoundsReport {
    pub local_id: usize,
    pub global_id: u32,
    pub type_name: &'static str,
    pub name: Option<String>,
    pub parent_local: Option<usize>,
    pub collapsed: bool,
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
    pub world_transform: [f32; 6],
}

/// Solved border box retained by one runtime `LayoutComponent` occurrence.
///
/// Coordinates are artboard-local. Width and height are the solved dimensions
/// exposed by pinned C++
/// `LayoutComponent::layoutBounds/layoutWidth/layoutHeight`
/// (`include/rive/layout_component.hpp:190-217`).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RuntimeLayoutBounds {
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
}

trait RuntimeLayoutEngine {
    fn compute_bounds(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
    ) -> Option<BTreeMap<usize, RuntimeLayoutBounds>>;
}

struct TaffyRuntimeLayoutEngine;

#[cfg(test)]
thread_local! {
    static TAFFY_LAYOUT_SOLVE_ENTRIES: Cell<usize> = const { Cell::new(0) };
}

#[cfg(test)]
pub(crate) fn reset_taffy_layout_solve_entries() {
    TAFFY_LAYOUT_SOLVE_ENTRIES.with(|count| count.set(0));
}

#[cfg(test)]
pub(crate) fn taffy_layout_solve_entries() -> usize {
    TAFFY_LAYOUT_SOLVE_ENTRIES.with(Cell::get)
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum TaffyMeasureContext {
    LayoutComponentMeasure {
        local: usize,
    },
    LayoutParticipantMeasure {
        local: usize,
    },
    ComponentListItem {
        list_local: usize,
        item_index: usize,
        intrinsic_size: Size<f32>,
    },
}

#[derive(Default)]
struct RuntimeComputedLayout {
    bounds: BTreeMap<usize, RuntimeLayoutBounds>,
    component_list_item_bounds: BTreeMap<usize, Vec<RuntimeLayoutBounds>>,
}

pub(crate) fn runtime_component_list_item_layout_size(
    item: &crate::artboard::RuntimeComponentListItemInstance,
) -> (f32, f32) {
    if let Some(size) = item.settled_layout_size.get() {
        // Once `ArtboardComponentList::layoutNode` transfers the mounted root
        // to its hosting layout, C++ reads `Artboard::layoutWidth/Height`
        // directly from that retained Yoga result. A fresh standalone child
        // solve would also overwrite `layoutX/layoutY`, which the virtualizer
        // owns on the cross axis (`artboard.cpp:1099-1138`;
        // `scroll_virtualizer.cpp:269-291`).
        return size;
    }
    item.child
        .retained_layout_bounds()
        .and_then(|bounds| bounds.get(&0).copied())
        .map(|bounds| (bounds.width, bounds.height))
        .unwrap_or((item.child.width, item.child.height))
}

fn runtime_mounted_component_list_revisions(instance: &ArtboardInstance) -> (u64, u64) {
    // The overwhelmingly common case has no mounted component list. Avoid
    // allocating the cycle guard merely to reproduce the two seed hashes.
    let list_locals = instance.component_list_locals();
    if list_locals.clone().all(|local_id| {
        instance
            .component_list_items(local_id)
            .is_none_or(|items| items.is_empty())
    }) {
        return (0xcbf29ce484222325, 0xcbf29ce484222325);
    }

    fn mix(epoch: &mut u64, value: u64) {
        *epoch = epoch.wrapping_mul(0x100000001b3) ^ value;
    }

    fn visit(
        instance: &ArtboardInstance,
        layout_revision: &mut u64,
        prepared_epoch: &mut u64,
        visited: &mut BTreeSet<u64>,
    ) {
        if !visited.insert(instance.instance_identity()) {
            return;
        }
        for list_local in instance.component_list_locals() {
            let Some(items) = instance.component_list_items(list_local) else {
                continue;
            };
            mix(layout_revision, list_local as u64);
            mix(layout_revision, items.len() as u64);
            mix(prepared_epoch, list_local as u64);
            mix(prepared_epoch, items.len() as u64);
            for item in items {
                for epoch in [&mut *layout_revision, &mut *prepared_epoch] {
                    mix(epoch, item.context.borrow().instance_identity());
                    mix(epoch, item.occurrence_identity);
                    mix(epoch, item.logical_index as u64);
                    mix(epoch, item.render_cache_revision);
                    mix(epoch, u64::from(item.child.graph_global_id));
                    mix(epoch, item.child.instance_identity());
                }
                for epoch in [&mut *layout_revision, &mut *prepared_epoch] {
                    for value in item.transform.0 {
                        mix(epoch, u64::from(value.to_bits()));
                    }
                }
                mix(layout_revision, item.child.layout_revision());
                mix(layout_revision, u64::from(item.child.width.to_bits()));
                mix(layout_revision, u64::from(item.child.height.to_bits()));
                // The prepared frame owns a transient clone of each mounted
                // child, so it must track all live instance-property writes,
                // not only prepared-topology changes. For example SolidColor
                // mutations intentionally bump `cache_epoch` without bumping
                // `prepared_epoch`; omitting this would keep drawing the
                // clone's stale paint value.
                mix(prepared_epoch, item.child.cache_epoch());
                mix(prepared_epoch, item.child.prepared_epoch());
                visit(&item.child, layout_revision, prepared_epoch, visited);
            }
        }
    }

    let mut layout_revision = 0xcbf29ce484222325;
    let mut prepared_epoch = 0xcbf29ce484222325;
    visit(
        instance,
        &mut layout_revision,
        &mut prepared_epoch,
        &mut BTreeSet::new(),
    );
    (layout_revision, prepared_epoch)
}

#[derive(Default)]
struct TaffyLayoutBuild {
    nodes_by_local: BTreeMap<usize, NodeId>,
    children_by_local: BTreeMap<usize, Vec<usize>>,
    component_list_item_nodes: BTreeMap<usize, Vec<NodeId>>,
}

fn definite_available_space(space: AvailableSpace) -> Option<f32> {
    match space {
        AvailableSpace::Definite(value) => Some(value),
        AvailableSpace::MinContent | AvailableSpace::MaxContent => None,
    }
}

impl RuntimeLayoutEngine for TaffyRuntimeLayoutEngine {
    fn compute_bounds(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
    ) -> Option<BTreeMap<usize, RuntimeLayoutBounds>> {
        self.compute_bounds_with_root_hug(
            instance,
            graph,
            runtime,
            Size {
                width: false,
                height: false,
            },
        )
    }
}

impl TaffyRuntimeLayoutEngine {
    fn compute_bounds_with_root_hug(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
        root_hug: Size<bool>,
    ) -> Option<BTreeMap<usize, RuntimeLayoutBounds>> {
        self.compute_layout_with_root_hug(instance, graph, runtime, root_hug)
            .map(|layout| layout.bounds)
    }

    fn compute_layout(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
    ) -> Option<RuntimeComputedLayout> {
        self.compute_layout_with_root_hug(
            instance,
            graph,
            runtime,
            Size {
                width: false,
                height: false,
            },
        )
    }

    fn compute_layout_with_root_hug(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
        root_hug: Size<bool>,
    ) -> Option<RuntimeComputedLayout> {
        // Ported from C++ `src/layout_component.cpp`
        // `syncStyle`/`syncLayoutChildren`/`calculateLayoutInternal`: translate
        // Rive layout style into the delegated layout engine, then expose the
        // settled layout boxes back to draw/world/computed-value code.
        let root = graph
            .components
            .iter()
            .find(|component| component.local_id == 0)?;
        if root.type_name != "Artboard" {
            return None;
        }
        #[cfg(test)]
        TAFFY_LAYOUT_SOLVE_ENTRIES.with(|count| count.set(count.get() + 1));
        let mut taffy = TaffyTree::<TaffyMeasureContext>::new();
        taffy.disable_rounding();
        let mut build = TaffyLayoutBuild::default();
        let root_node =
            self.build_node(instance, graph, runtime, 0, true, &mut taffy, &mut build)?;
        if root_hug.width || root_hug.height {
            let mut style = taffy.style(root_node).ok()?.clone();
            if root_hug.width {
                style.size.width = Dimension::auto();
            }
            if root_hug.height {
                style.size.height = Dimension::auto();
            }
            taffy.set_style(root_node, style).ok()?;
        }
        let mut available_space = self.root_available_space(instance)?;
        if root_hug.width {
            available_space.width = AvailableSpace::MaxContent;
        }
        if root_hug.height {
            available_space.height = AvailableSpace::MaxContent;
        }
        taffy
            .compute_layout_with_measure(
                root_node,
                available_space,
                |known_dimensions, available_space, _node_id, node_context, _style| {
                    match node_context {
                        Some(TaffyMeasureContext::LayoutComponentMeasure { local }) => runtime
                            .and_then(|runtime| {
                                self.measure_layout_component(
                                    runtime,
                                    instance,
                                    graph,
                                    *local,
                                    known_dimensions,
                                    available_space,
                                )
                            })
                            .unwrap_or(Size::ZERO),
                        Some(TaffyMeasureContext::LayoutParticipantMeasure { local }) => runtime
                            .and_then(|runtime| {
                                self.measure_layout_participant(
                                    runtime,
                                    instance,
                                    graph,
                                    *local,
                                    known_dimensions,
                                    available_space,
                                )
                            })
                            .unwrap_or(Size::ZERO),
                        Some(TaffyMeasureContext::ComponentListItem {
                            list_local: _,
                            item_index: _,
                            intrinsic_size,
                        }) => Size {
                            width: known_dimensions.width.unwrap_or(intrinsic_size.width),
                            height: known_dimensions.height.unwrap_or(intrinsic_size.height),
                        },
                        None => Size::ZERO,
                    }
                },
            )
            .ok()?;

        let mut bounds = BTreeMap::new();
        self.collect_bounds(0, 0.0, 0.0, &taffy, &build, &mut bounds)?;
        let mut component_list_item_bounds = BTreeMap::new();
        for (list_local, nodes) in &build.component_list_item_nodes {
            let mut item_bounds = Vec::with_capacity(nodes.len());
            for node in nodes {
                let layout = taffy.layout(*node).ok()?;
                item_bounds.push(RuntimeLayoutBounds {
                    x: layout.location.x,
                    y: layout.location.y,
                    width: layout.size.width,
                    height: layout.size.height,
                });
            }
            component_list_item_bounds.insert(*list_local, item_bounds);
        }
        Some(RuntimeComputedLayout {
            bounds,
            component_list_item_bounds,
        })
    }

    fn build_node(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
        local: usize,
        parent_is_row: bool,
        taffy: &mut TaffyTree<TaffyMeasureContext>,
        build: &mut TaffyLayoutBuild,
    ) -> Option<NodeId> {
        // Cycle guard: a malformed-but-accepted file can make the layout child
        // graph cyclic, which would recurse forever here (the node map is only
        // populated after the child recursion below). The nodes-by-local map
        // doubles as the visited set, mirroring C++'s visited-set cycle-guard
        // idiom (DependencySorter::visit, src/dependency_sorter.cpp): each local
        // is built exactly once on any valid tree, so returning the existing
        // node is identical behavior there and terminates cycles gracefully.
        if let Some(node) = build.nodes_by_local.get(&local) {
            return Some(*node);
        }
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == local)?;
        let is_participant = instance.runtime_layout_participant_local(local).is_some();
        if !matches!(
            component.type_name,
            "Artboard" | "LayoutComponent" | "NestedArtboardLayout"
        ) && !is_participant
        {
            return None;
        }
        if !is_participant && self.needs_unimplemented_measure(instance, graph, runtime, local)? {
            return None;
        }

        let style = if component.type_name == "NestedArtboardLayout" {
            self.nested_artboard_layout_style(instance, local, parent_is_row)?
        } else {
            self.style_for_node(instance, graph, local, parent_is_row)?
        };
        if component.type_name == "NestedArtboardLayout" {
            let node = taffy.new_leaf(style).ok()?;
            build.nodes_by_local.insert(local, node);
            build.children_by_local.insert(local, Vec::new());
            return Some(node);
        }
        let is_row = instance
            .runtime_layout_node_style_local(local)
            .is_none_or(|style_local| instance.runtime_layout_style_is_row(style_local));
        let mut child_nodes = Vec::new();
        let mut child_locals = Vec::new();
        for child_local in self.layout_provider_children(instance, local)? {
            // C++ inserts layout-provider children into Yoga even when runtime
            // collapse later suppresses drawing; display:none is represented
            // by the child node's style.
            let Some(child) = graph
                .components
                .iter()
                .find(|component| component.local_id == child_local)
            else {
                continue;
            };
            match child.type_name {
                "LayoutComponent" => {
                    let child_node = self.build_node(
                        instance,
                        graph,
                        runtime,
                        child_local,
                        is_row,
                        taffy,
                        build,
                    )?;
                    child_nodes.push(child_node);
                    child_locals.push(child_local);
                }
                "ArtboardComponentList" => {
                    if !self.zero_sized_component_list_supported(graph, child_local)? {
                        return None;
                    }
                    if let Some(items) = instance.component_list_items(child_local) {
                        for (item_index, item) in items.iter().enumerate() {
                            let intrinsic_size = runtime_component_list_item_layout_size(item);
                            let item_style = self.component_list_item_style(
                                instance,
                                graph,
                                child_local,
                                item,
                                is_row,
                            )?;
                            let item_node = taffy
                                .new_leaf_with_context(
                                    item_style,
                                    TaffyMeasureContext::ComponentListItem {
                                        list_local: child_local,
                                        item_index,
                                        intrinsic_size: Size {
                                            width: intrinsic_size.0,
                                            height: intrinsic_size.1,
                                        },
                                    },
                                )
                                .ok()?;
                            child_nodes.push(item_node);
                            build
                                .component_list_item_nodes
                                .entry(child_local)
                                .or_default()
                                .push(item_node);
                        }
                    }
                }
                "NestedArtboardLayout" => {
                    let child_node = self.build_node(
                        instance,
                        graph,
                        runtime,
                        child_local,
                        is_row,
                        taffy,
                        build,
                    )?;
                    child_nodes.push(child_node);
                    child_locals.push(child_local);
                }
                _ if instance
                    .runtime_layout_participant_local(child_local)
                    .is_some() =>
                {
                    let child_node = self.build_node(
                        instance,
                        graph,
                        runtime,
                        child_local,
                        is_row,
                        taffy,
                        build,
                    )?;
                    child_nodes.push(child_node);
                    child_locals.push(child_local);
                }
                _ => {}
            }
        }

        let node = if child_nodes.is_empty() {
            if is_participant && runtime.is_some() {
                taffy
                    .new_leaf_with_context(
                        style,
                        TaffyMeasureContext::LayoutParticipantMeasure { local },
                    )
                    .ok()?
            } else if runtime.is_some()
                && self.layout_component_registers_measure_func(instance, local)?
            {
                taffy
                    .new_leaf_with_context(
                        style,
                        TaffyMeasureContext::LayoutComponentMeasure { local },
                    )
                    .ok()?
            } else {
                taffy.new_leaf(style).ok()?
            }
        } else {
            taffy.new_with_children(style, &child_nodes).ok()?
        };
        build.nodes_by_local.insert(local, node);
        build.children_by_local.insert(local, child_locals);
        Some(node)
    }

    /// C++ contributes the mounted artboard's root Yoga node directly to the
    /// hosting layout. Before insertion, `ArtboardComponentListOverride`
    /// rewrites that root node's width/height scale contract. Keep the
    /// override on the provider node (rather than on the authored child
    /// instance) so list lifecycle remains persistent and reversible.
    fn component_list_item_style(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        list_local: usize,
        item: &crate::artboard::RuntimeComponentListItemInstance,
        parent_is_row: bool,
    ) -> Option<Style> {
        let item_graph = item.child.runtime_graph()?;
        let mut style = self.style_for_node(&item.child, item_graph, 0, parent_is_row)?;
        // `style_for_node` fixes a standalone root to the current artboard
        // dimensions because those dimensions are the root's available
        // space. A component list instead transfers that root node into the
        // hosting layout. Restore the authored unit/scale contract here so a
        // fill root is `auto` and can stretch/shrink to the parent's assigned
        // row width, exactly as C++ `Artboard::takeLayoutData()` does.
        if let Some(style_local) = item.child.runtime_layout_component_style_local(0) {
            style.size = Size {
                width: self.axis_dimension(&item.child, 0, style_local, true)?,
                height: self.axis_dimension(&item.child, 0, style_local, false)?,
            };
        }
        let Some(override_local) =
            self.component_list_item_override_local(instance, graph, list_local, item)
        else {
            return Some(style);
        };

        let width_scale = self.component_list_override_axis_scale(instance, override_local, true);
        let height_scale = self.component_list_override_axis_scale(instance, override_local, false);
        self.apply_component_list_item_axis_override(
            instance,
            override_local,
            item,
            parent_is_row,
            true,
            width_scale,
            &mut style,
        )?;

        // Match `StyleOverrider::updateHeightOverride` literally. Upstream's
        // hug branch currently checks `instanceWidthScaleType`; fixed/fill use
        // the height scale as expected. Keeping this quirk is required for
        // byte-exact behavior with the pinned C++ runtime.
        let effective_height_scale = match height_scale {
            0 | 1 => Some(height_scale),
            _ if width_scale == 2 => Some(2),
            _ => None,
        };
        if let Some(height_scale) = effective_height_scale {
            self.apply_component_list_item_axis_override(
                instance,
                override_local,
                item,
                parent_is_row,
                false,
                height_scale,
                &mut style,
            )?;
        }
        Some(style)
    }

    fn component_list_item_override_local(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        list_local: usize,
        item: &crate::artboard::RuntimeComponentListItemInstance,
    ) -> Option<usize> {
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == list_local)?;
        let item_artboard_index = item
            .child
            .runtime_file()
            .zip(item.child.runtime_graph())
            .and_then(|(file, item_graph)| artboard_index_for_graph(file, item_graph));
        let artboard_id_key = runtime_component_list_override_property_key_for_name("artboardId")?;
        let mut default_override = None;
        for child_local in &component.children {
            if graph
                .components
                .iter()
                .find(|candidate| candidate.local_id == *child_local)
                .is_none_or(|candidate| candidate.type_name != "ArtboardComponentListOverride")
            {
                continue;
            }
            let artboard_id = instance
                .uint_property(*child_local, artboard_id_key)
                .unwrap_or(u64::from(u32::MAX));
            if artboard_id == u64::from(u32::MAX) {
                default_override = Some(*child_local);
            } else if usize::try_from(artboard_id).ok() == item_artboard_index {
                return Some(*child_local);
            }
        }
        default_override
    }

    fn component_list_override_axis_scale(
        &self,
        instance: &ArtboardInstance,
        override_local: usize,
        width_axis: bool,
    ) -> u64 {
        runtime_component_list_override_property_key_for_name(if width_axis {
            "instanceWidthScaleType"
        } else {
            "instanceHeightScaleType"
        })
        .and_then(|key| instance.uint_property(override_local, key))
        .unwrap_or(0)
    }

    #[allow(clippy::too_many_arguments)]
    fn apply_component_list_item_axis_override(
        &self,
        instance: &ArtboardInstance,
        override_local: usize,
        item: &crate::artboard::RuntimeComponentListItemInstance,
        parent_is_row: bool,
        width_axis: bool,
        scale: u64,
        style: &mut Style,
    ) -> Option<()> {
        if !matches!(scale, 0 | 1 | 2) {
            return None;
        }
        let value_key = runtime_component_list_override_property_key_for_name(if width_axis {
            "instanceWidth"
        } else {
            "instanceHeight"
        })?;
        let units_key = runtime_component_list_override_property_key_for_name(if width_axis {
            "instanceWidthUnitsValue"
        } else {
            "instanceHeightUnitsValue"
        })?;
        let configured_value = instance
            .double_property(override_local, value_key)
            .unwrap_or(-1.0);
        let original_value = item
            .child
            .runtime_file()
            .and_then(|file| file.object(item.child.graph_global_id as usize))
            .and_then(|artboard| {
                artboard.double_property(if width_axis { "width" } else { "height" })
            })
            .unwrap_or(if width_axis {
                item.child.width
            } else {
                item.child.height
            });
        let value = if configured_value == -1.0 {
            original_value
        } else {
            configured_value
        };
        let units = instance
            .uint_property(override_local, units_key)
            .unwrap_or(1);
        let dimension = match scale {
            0 => self.dimension_from_unit(value.max(0.0), units)?,
            1 | 2 => Dimension::auto(),
            _ => return None,
        };
        if width_axis {
            style.size.width = dimension;
        } else {
            style.size.height = dimension;
        }

        if width_axis == parent_is_row {
            match scale {
                0 | 2 => {
                    style.flex_grow = 0.0;
                    style.flex_shrink = 0.0;
                    style.flex_basis = Dimension::auto();
                }
                1 => {
                    style.flex_grow = item.child.runtime_layout_axis_fraction(0, width_axis);
                    style.flex_shrink = style.flex_grow;
                    style.flex_basis = item
                        .child
                        .runtime_layout_component_style_local(0)
                        .and_then(|style_local| {
                            let basis = item
                                .child
                                .runtime_layout_style_double(
                                    style_local,
                                    RuntimeLayoutStyleProperty::FlexBasis,
                                )
                                .unwrap_or(0.0);
                            let basis_units = item.child.runtime_layout_style_uint_default(
                                style_local,
                                RuntimeLayoutStyleProperty::FlexBasisUnitsValue,
                                3,
                            );
                            self.dimension_from_unit(basis, basis_units)
                        })
                        .unwrap_or_else(Dimension::auto);
                }
                _ => return None,
            }
        } else {
            style.align_self = match scale {
                1 => Some(AlignSelf::STRETCH),
                0 | 2 => None,
                _ => return None,
            };
        }
        Some(())
    }

    fn zero_sized_component_list_supported(
        &self,
        graph: &ArtboardGraph,
        local: usize,
    ) -> Option<bool> {
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == local)?;
        graph
            .component_lists
            .iter()
            .find(|list| list.local_id == local)?;
        Some(component.children.iter().all(|child_local| {
            graph
                .components
                .iter()
                .find(|component| component.local_id == *child_local)
                .is_some_and(|component| {
                    matches!(
                        component.type_name,
                        "ArtboardListMapRule"
                            | "ArtboardComponentListOverride"
                            | "ListFollowPathConstraint"
                            | "ClippingShape"
                    )
                })
        }))
    }

    fn collect_bounds(
        &self,
        local: usize,
        parent_x: f32,
        parent_y: f32,
        taffy: &TaffyTree<TaffyMeasureContext>,
        build: &TaffyLayoutBuild,
        bounds: &mut BTreeMap<usize, RuntimeLayoutBounds>,
    ) -> Option<()> {
        // Cycle guard: a malformed-but-accepted file can make the layout child
        // graph cyclic, turning this walk into unbounded recursion. The bounds
        // map doubles as the visited set (each local is laid out exactly once on
        // any valid tree), mirroring C++'s visited-set cycle-guard idiom
        // (DependencySorter::visit, src/dependency_sorter.cpp); on revisit,
        // terminate gracefully with the already-computed bounds.
        if bounds.contains_key(&local) {
            return Some(());
        }
        let node = *build.nodes_by_local.get(&local)?;
        let layout = taffy.layout(node).ok()?;
        let x = parent_x + layout.location.x;
        let y = parent_y + layout.location.y;
        bounds.insert(
            local,
            RuntimeLayoutBounds {
                x,
                y,
                width: layout.size.width,
                height: layout.size.height,
            },
        );
        for child_local in build.children_by_local.get(&local)? {
            self.collect_bounds(*child_local, x, y, taffy, build, bounds)?;
        }
        Some(())
    }

    fn style_for_node(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        local: usize,
        parent_is_row: bool,
    ) -> Option<Style> {
        let is_root = local == 0;
        let style_local = instance.runtime_layout_node_style_local(local);
        if style_local.is_none() && !is_root {
            return None;
        }

        let layout_type = instance
            .runtime_layout_component_style_local(local)
            .map(|style_local| {
                instance.runtime_layout_style_uint_default(
                    style_local,
                    RuntimeLayoutStyleProperty::LayoutTypeValue,
                    0,
                )
            })
            .unwrap_or(0);

        let mut style = Style {
            display: if style_local.is_some_and(|style_local| {
                instance.runtime_layout_style_uint_default(
                    style_local,
                    RuntimeLayoutStyleProperty::DisplayValue,
                    0,
                ) == 1
            }) {
                TaffyDisplay::None
            } else if matches!(layout_type, 1 | 2) {
                TaffyDisplay::Grid
            } else {
                TaffyDisplay::Flex
            },
            size: if is_root {
                if let Some(style_local) = style_local {
                    Size {
                        width: self.root_axis_dimension(instance, style_local, true)?,
                        height: self.root_axis_dimension(instance, style_local, false)?,
                    }
                } else {
                    Size::from_lengths(instance.width, instance.height)
                }
            } else {
                let style_local = style_local?;
                Size {
                    width: self.axis_dimension(instance, local, style_local, true)?,
                    height: self.axis_dimension(instance, local, style_local, false)?,
                }
            },
            ..Default::default()
        };

        let Some(style_local) = style_local else {
            // C++ `LayoutComponent::syncStyle` returns before touching the
            // Yoga node when `m_style == nullptr`
            // (src/layout_component.cpp:478-483), so a style-less root keeps
            // Yoga's zero-initialized flex direction: Column
            // (yoga/YGStyle.h `flags = 0`, `YGFlexDirectionColumn`). Taffy's
            // `Style::default()` is Row, so pin the pinned-C++ default
            // explicitly. The null-style `mainAxisIsRow()` accessor still
            // reports row — that mismatch is upstream's own
            // (src/layout_component.cpp:436-444) and both sides are ported
            // as-is.
            style.flex_direction = FlexDirection::Column;
            return Some(style);
        };

        style.position = if instance.runtime_layout_style_uint_default(
            style_local,
            RuntimeLayoutStyleProperty::PositionTypeValue,
            1,
        ) == 2
        {
            Position::Absolute
        } else {
            Position::Relative
        };
        style.direction = match instance.runtime_layout_style_uint_default(
            style_local,
            RuntimeLayoutStyleProperty::DirectionValue,
            0,
        ) {
            2 => TaffyDirection::Rtl,
            _ => TaffyDirection::Ltr,
        };
        style.flex_direction = match instance.runtime_layout_style_uint_default(
            style_local,
            RuntimeLayoutStyleProperty::FlexDirectionValue,
            2,
        ) {
            0 => FlexDirection::Column,
            1 => FlexDirection::ColumnReverse,
            3 => FlexDirection::RowReverse,
            _ => FlexDirection::Row,
        };
        style.flex_wrap = match instance.runtime_layout_style_uint_default(
            style_local,
            RuntimeLayoutStyleProperty::FlexWrapValue,
            0,
        ) {
            1 => FlexWrap::Wrap,
            2 => FlexWrap::WrapReverse,
            _ => FlexWrap::NoWrap,
        };
        style.gap = Size {
            width: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::GapHorizontal,
                RuntimeLayoutStyleProperty::GapHorizontalUnitsValue,
            )?,
            height: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::GapVertical,
                RuntimeLayoutStyleProperty::GapVerticalUnitsValue,
            )?,
        };
        style.padding = Rect {
            left: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PaddingLeft,
                RuntimeLayoutStyleProperty::PaddingLeftUnitsValue,
            )?,
            right: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PaddingRight,
                RuntimeLayoutStyleProperty::PaddingRightUnitsValue,
            )?,
            top: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PaddingTop,
                RuntimeLayoutStyleProperty::PaddingTopUnitsValue,
            )?,
            bottom: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PaddingBottom,
                RuntimeLayoutStyleProperty::PaddingBottomUnitsValue,
            )?,
        };
        style.border = Rect {
            left: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::BorderLeft,
                RuntimeLayoutStyleProperty::BorderLeftUnitsValue,
            )?,
            right: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::BorderRight,
                RuntimeLayoutStyleProperty::BorderRightUnitsValue,
            )?,
            top: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::BorderTop,
                RuntimeLayoutStyleProperty::BorderTopUnitsValue,
            )?,
            bottom: self.length_percentage_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::BorderBottom,
                RuntimeLayoutStyleProperty::BorderBottomUnitsValue,
            )?,
        };
        style.margin = Rect {
            left: self.length_percentage_auto_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MarginLeft,
                RuntimeLayoutStyleProperty::MarginLeftUnitsValue,
            )?,
            right: self.length_percentage_auto_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MarginRight,
                RuntimeLayoutStyleProperty::MarginRightUnitsValue,
            )?,
            top: self.length_percentage_auto_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MarginTop,
                RuntimeLayoutStyleProperty::MarginTopUnitsValue,
            )?,
            bottom: self.length_percentage_auto_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MarginBottom,
                RuntimeLayoutStyleProperty::MarginBottomUnitsValue,
            )?,
        };
        style.inset = Rect {
            left: self.position_inset_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PositionLeft,
                RuntimeLayoutStyleProperty::PositionLeftUnitsValue,
            )?,
            right: self.position_inset_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PositionRight,
                RuntimeLayoutStyleProperty::PositionRightUnitsValue,
            )?,
            top: self.position_inset_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PositionTop,
                RuntimeLayoutStyleProperty::PositionTopUnitsValue,
            )?,
            bottom: self.position_inset_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::PositionBottom,
                RuntimeLayoutStyleProperty::PositionBottomUnitsValue,
            )?,
        };
        style.min_size = Size {
            width: self.dimension_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MinWidth,
                RuntimeLayoutStyleProperty::MinWidthUnitsValue,
                false,
                false,
            )?,
            height: self.dimension_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MinHeight,
                RuntimeLayoutStyleProperty::MinHeightUnitsValue,
                false,
                false,
            )?,
        };
        // The top-level Artboard adapter preserves its historical
        // undefined-unit minimum as an external host constraint. Ordinary
        // Yoga LayoutComponents do not: YGUnitUndefined means no min bound.
        if !is_root {
            if instance.runtime_layout_style_uint_default(
                style_local,
                RuntimeLayoutStyleProperty::MinWidthUnitsValue,
                0,
            ) == 0
                && instance
                    .runtime_layout_style_double(style_local, RuntimeLayoutStyleProperty::MinWidth)
                    .unwrap_or(0.0)
                    .abs()
                    > f32::EPSILON
            {
                style.min_size.width = Dimension::auto();
            }
            if instance.runtime_layout_style_uint_default(
                style_local,
                RuntimeLayoutStyleProperty::MinHeightUnitsValue,
                0,
            ) == 0
                && instance
                    .runtime_layout_style_double(style_local, RuntimeLayoutStyleProperty::MinHeight)
                    .unwrap_or(0.0)
                    .abs()
                    > f32::EPSILON
            {
                style.min_size.height = Dimension::auto();
            }
        }
        style.max_size = Size {
            width: self.dimension_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MaxWidth,
                RuntimeLayoutStyleProperty::MaxWidthUnitsValue,
                true,
                false,
            )?,
            height: self.dimension_style(
                instance,
                style_local,
                RuntimeLayoutStyleProperty::MaxHeight,
                RuntimeLayoutStyleProperty::MaxHeightUnitsValue,
                true,
                false,
            )?,
        };
        let aspect_ratio = instance
            .runtime_layout_style_double(style_local, RuntimeLayoutStyleProperty::AspectRatio)
            .unwrap_or(0.0);
        if aspect_ratio > 0.0 {
            style.aspect_ratio = Some(aspect_ratio);
        }

        if layout_type == 2 {
            self.apply_stack_alignment(instance, style_local, &mut style);
            let single = GridTemplateComponent::Single(TrackSizingFunction {
                min: MinTrackSizingFunction::auto(),
                max: MaxTrackSizingFunction::fr(1.0),
            });
            style.grid_template_columns = vec![single.clone()];
            style.grid_template_rows = vec![single];
        } else {
            self.apply_alignment(instance, style_local, &mut style);
            if layout_type == 1 {
                self.apply_grid_container_style(instance, graph, local, style_local, &mut style)?;
            }
        }

        let parent_layout_type = self.parent_layout_type(instance, graph, local);
        if matches!(parent_layout_type, 1 | 2) {
            self.apply_grid_item_style(
                instance,
                graph,
                local,
                style_local,
                parent_layout_type == 2,
                &mut style,
            )?;
        } else {
            self.apply_flex_item_style(instance, local, style_local, parent_is_row, &mut style)?;
        }
        Some(style)
    }

    fn root_available_space(&self, instance: &ArtboardInstance) -> Option<Size<AvailableSpace>> {
        let style_local = instance.runtime_layout_component_style_local(0);
        Some(Size {
            width: self.root_axis_available_space(instance, style_local, true)?,
            height: self.root_axis_available_space(instance, style_local, false)?,
        })
    }

    fn root_axis_available_space(
        &self,
        instance: &ArtboardInstance,
        style_local: Option<usize>,
        width_axis: bool,
    ) -> Option<AvailableSpace> {
        if instance.layout_node_owned_by_host {
            return Some(AvailableSpace::Definite(if width_axis {
                instance.width
            } else {
                instance.height
            }));
        }
        if let Some(style_local) = style_local {
            const LAYOUT_SCALE_TYPE_HUG: u64 = 2;
            if instance.runtime_layout_axis_scale(style_local, width_axis) == LAYOUT_SCALE_TYPE_HUG
            {
                return Some(AvailableSpace::MaxContent);
            }
        }
        Some(AvailableSpace::Definite(if width_axis {
            instance.width
        } else {
            instance.height
        }))
    }

    fn root_axis_dimension(
        &self,
        instance: &ArtboardInstance,
        style_local: usize,
        width_axis: bool,
    ) -> Option<Dimension> {
        if instance.layout_node_owned_by_host {
            return Some(Dimension::length(if width_axis {
                instance.width
            } else {
                instance.height
            }));
        }
        const LAYOUT_SCALE_TYPE_HUG: u64 = 2;
        if instance.runtime_layout_axis_scale(style_local, width_axis) == LAYOUT_SCALE_TYPE_HUG {
            return Some(Dimension::auto());
        }
        Some(Dimension::length(if width_axis {
            instance.width
        } else {
            instance.height
        }))
    }

    fn nested_artboard_layout_style(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        parent_is_row: bool,
    ) -> Option<Style> {
        // Ported from C++ `src/nested_artboard_layout.cpp` and
        // `include/rive/layout/style_overrider.hpp`: the layout-backed host
        // contributes the referenced artboard instance's layout node to its
        // parent.
        let width_scale = self.nested_artboard_layout_axis_scale(instance, local, true);
        let height_scale = self.nested_artboard_layout_axis_scale(instance, local, false);
        if !matches!(width_scale, 0 | 1 | 2) || !matches!(height_scale, 0 | 1 | 2) {
            return None;
        }

        let mut style = Style {
            display: TaffyDisplay::Flex,
            size: Size {
                width: self.nested_artboard_layout_axis_dimension(instance, local, true)?,
                height: self.nested_artboard_layout_axis_dimension(instance, local, false)?,
            },
            ..Default::default()
        };

        let main_scale = if parent_is_row {
            width_scale
        } else {
            height_scale
        };
        let cross_scale = if parent_is_row {
            height_scale
        } else {
            width_scale
        };
        if matches!(width_scale, 0 | 2) {
            style.min_size.width = style.size.width;
        }
        if matches!(height_scale, 0 | 2) {
            style.min_size.height = style.size.height;
        }
        if width_scale == 2 {
            style.max_size.width = style.size.width;
        }
        if height_scale == 2 {
            style.max_size.height = style.size.height;
        }
        match main_scale {
            0 => {
                style.flex_grow = 0.0;
                style.flex_shrink = 0.0;
                // Yoga's fixed-scale LayoutComponent uses its authored main
                // size as the flex basis. Leaving Taffy's basis at `auto`
                // lets intrinsic Text content replace that fixed width.
                style.flex_basis = if parent_is_row {
                    style.size.width
                } else {
                    style.size.height
                };
            }
            2 => {
                style.flex_grow = 0.0;
                style.flex_shrink = 0.0;
                style.flex_basis = Dimension::auto();
            }
            1 => {
                style.flex_grow = 1.0;
                style.flex_shrink = 1.0;
                // C++ contributes the referenced artboard's layout node, so
                // fill distribution starts from its intrinsic content size.
                style.flex_basis = self
                    .nested_artboard_layout_axis_hug_size(instance, local, parent_is_row)
                    .filter(|value| value.is_finite() && *value >= 0.0)
                    .map(Dimension::length)
                    .unwrap_or_else(Dimension::auto);
            }
            _ => return None,
        }
        style.align_self = match cross_scale {
            1 => Some(AlignSelf::STRETCH),
            0 | 2 => None,
            _ => return None,
        };
        Some(style)
    }

    fn nested_artboard_layout_axis_dimension(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> Option<Dimension> {
        match self.nested_artboard_layout_axis_scale(instance, local, width_axis) {
            0 => {
                let value = self.nested_artboard_layout_axis_length(instance, local, width_axis);
                let units = self.nested_artboard_layout_axis_units(instance, local, width_axis);
                if value < 0.0 {
                    Some(
                        self.nested_artboard_layout_axis_retained_or_hug_size(
                            instance, local, width_axis,
                        )
                        .filter(|value| value.is_finite() && *value >= 0.0)
                        .map(Dimension::length)
                        .unwrap_or_else(Dimension::auto),
                    )
                } else {
                    self.dimension_from_unit(value, units)
                }
            }
            1 => Some(Dimension::auto()),
            2 => self
                .nested_artboard_layout_axis_retained_or_hug_size(instance, local, width_axis)
                .filter(|value| value.is_finite() && *value >= 0.0)
                .map(Dimension::length)
                .or_else(|| Some(Dimension::auto())),
            _ => None,
        }
    }

    fn nested_artboard_layout_axis_retained_or_hug_size(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> Option<f32> {
        let nested = instance.nested_artboards.get(&local)?;
        if nested.layout_data_transferred {
            let child_layout_generation = nested.child.runtime_transferred_layout_generation();
            if nested.transferred_hug_layout_generation.get() != child_layout_generation {
                let (retained_hug_size, _) =
                    nested.child.transferred_hug_size_after_child_layout_change(
                        nested.transferred_hug_size.get(),
                    );
                nested.transferred_hug_size.set(retained_hug_size);
                nested
                    .transferred_hug_layout_generation
                    .set(child_layout_generation);
            }
            // `takeLayoutData()` has transferred this root node into the
            // parent. Its assigned Artboard dimensions are the retained Yoga
            // node size; the child's local root bounds can additionally carry
            // padding and must not replace that parent-owned measurement.
            let transferred = nested.transferred_hug_size.get();
            let retained = if width_axis {
                transferred.0
            } else {
                transferred.1
            };
            if self.nested_artboard_layout_axis_scale(instance, local, width_axis) == 2 {
                retained.or_else(|| {
                    self.nested_artboard_layout_axis_hug_size(instance, local, width_axis)
                })
            } else {
                retained.or_else(|| {
                    self.nested_artboard_layout_axis_intrinsic_size(instance, local, width_axis)
                })
            }
        } else {
            let value = self
                .nested_artboard_layout_axis_intrinsic_size(instance, local, width_axis)
                .or_else(|| self.nested_artboard_layout_axis_hug_size(instance, local, width_axis));
            if let Some(value) = value.filter(|value| value.is_finite() && *value >= 0.0) {
                let (mut width, mut height) = nested.transferred_hug_size.get();
                if width_axis {
                    width = Some(value);
                } else {
                    height = Some(value);
                }
                nested.transferred_hug_size.set((width, height));
            }
            value
        }
    }

    fn nested_artboard_layout_axis_intrinsic_dimension(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> Option<Dimension> {
        let value = self.nested_artboard_layout_axis_intrinsic_size(instance, local, width_axis)?;
        if value.is_finite() && value >= 0.0 {
            Some(Dimension::length(value))
        } else {
            None
        }
    }

    fn nested_artboard_layout_axis_intrinsic_size(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> Option<f32> {
        let nested = instance.nested_artboards.get(&local)?;
        // `NestedArtboardLayout::layoutNode` transfers the mounted artboard's
        // exact root Yoga node to its host, and `Artboard::takeLayoutData`
        // disables standalone child solves. Measure that retained node here:
        // re-solving the detached child skips its interpolation and shrinks
        // independently positioned siblings (`nested_artboard_layout.cpp:24-42`;
        // `artboard.cpp:1245-1253`).
        if nested.child.layout_node_owned_by_host
            && (instance.mounted_layout_host_is_fenced(local)
                || !nested.child.suppress_mounted_component_list_layout_updates)
            && let Some(layout) = nested
                .child
                .component(0)
                .and_then(|component| component.concrete.layout.as_ref())
        {
            let (_, _, width, height) = layout.current_bounds();
            return Some(if width_axis { width } else { height });
        }
        let layout_size = if nested.child.layout_node_owned_by_host {
            nested
                .child
                .retained_layout_bounds()
                .and_then(|bounds| bounds.get(&0).copied())
        } else {
            nested
                .child
                .runtime_file()
                .zip(nested.child.runtime_graph())
                .and_then(|(runtime, graph)| {
                    nested
                        .child
                        .runtime_taffy_layout_bounds(graph, Some(runtime))
                        .and_then(|bounds| bounds.get(&0).copied())
                })
        }
        .map(|bounds| {
            if width_axis {
                bounds.width
            } else {
                bounds.height
            }
        });

        layout_size.or_else(|| {
            Some(if width_axis {
                nested.child.width
            } else {
                nested.child.height
            })
        })
    }

    fn nested_artboard_layout_axis_hug_size(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> Option<f32> {
        let nested = instance.nested_artboards.get(&local)?;
        let value = nested
            .child
            .runtime_file()
            .zip(nested.child.runtime_graph())
            .and_then(|(runtime, graph)| {
                self.compute_bounds_with_root_hug(
                    &nested.child,
                    graph,
                    Some(runtime),
                    Size {
                        width: width_axis,
                        height: !width_axis,
                    },
                )
            })
            .and_then(|bounds| bounds.get(&0).copied())
            .map(|bounds| {
                if width_axis {
                    bounds.width
                } else {
                    bounds.height
                }
            });
        if let Some(value) = value.filter(|value| value.is_finite() && *value >= 0.0) {
            let (mut width, mut height) = nested.transferred_hug_size.get();
            if width_axis {
                width = Some(value);
            } else {
                height = Some(value);
            }
            nested.transferred_hug_size.set((width, height));
        }
        value
    }

    fn nested_artboard_layout_axis_scale(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> u64 {
        runtime_nested_artboard_layout_property_key_for_name(if width_axis {
            "instanceWidthScaleType"
        } else {
            "instanceHeightScaleType"
        })
        .and_then(|key| instance.uint_property(local, key))
        .unwrap_or(0)
    }

    fn nested_artboard_layout_axis_units(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> u64 {
        runtime_nested_artboard_layout_property_key_for_name(if width_axis {
            "instanceWidthUnitsValue"
        } else {
            "instanceHeightUnitsValue"
        })
        .and_then(|key| instance.uint_property(local, key))
        .unwrap_or(1)
    }

    fn nested_artboard_layout_axis_length(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        width_axis: bool,
    ) -> f32 {
        runtime_nested_artboard_layout_property_key_for_name(if width_axis {
            "instanceWidth"
        } else {
            "instanceHeight"
        })
        .and_then(|key| instance.double_property(local, key))
        .unwrap_or(-1.0)
    }

    fn axis_dimension(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
        style_local: usize,
        width_axis: bool,
    ) -> Option<Dimension> {
        let value = instance.runtime_layout_component_dimension(
            layout_local,
            if width_axis { "width" } else { "height" },
        );
        let units = self.effective_units(instance, layout_local, style_local, width_axis)?;
        self.dimension_from_unit(value.max(0.0), units)
    }

    fn effective_units(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
        style_local: usize,
        width_axis: bool,
    ) -> Option<u64> {
        let scale = instance.runtime_layout_axis_scale(style_local, width_axis);
        let stored = instance.runtime_layout_axis_units(style_local, width_axis);
        let absolute = instance.runtime_layout_component_is_absolute(layout_local);
        if absolute && scale != 2 {
            return Some(stored);
        }
        if scale != 0 {
            return Some(3);
        }
        if matches!(stored, 1 | 2) {
            return Some(stored);
        }
        if self.is_legacy_hug_encoding(instance, layout_local, style_local)? {
            Some(3)
        } else {
            Some(1)
        }
    }

    fn is_legacy_hug_encoding(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
        style_local: usize,
    ) -> Option<bool> {
        let width_fixed = instance.runtime_layout_axis_scale(style_local, true) == 0;
        let height_fixed = instance.runtime_layout_axis_scale(style_local, false) == 0;
        let intrinsic = instance
            .runtime_layout_style_bool(
                style_local,
                RuntimeLayoutStyleProperty::IntrinsicallySizedValue,
            )
            .unwrap_or(false);
        Some(
            width_fixed
                && height_fixed
                && intrinsic
                && self
                    .layout_provider_children(instance, layout_local)?
                    .is_empty(),
        )
    }

    fn apply_flex_item_style(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
        style_local: usize,
        parent_is_row: bool,
        style: &mut Style,
    ) -> Option<()> {
        let width_scale = instance.runtime_layout_axis_scale(style_local, true);
        let height_scale = instance.runtime_layout_axis_scale(style_local, false);
        let main_scale = if parent_is_row {
            width_scale
        } else {
            height_scale
        };
        let cross_scale = if parent_is_row {
            height_scale
        } else {
            width_scale
        };

        match main_scale {
            0 => {
                style.flex_grow = 0.0;
                style.flex_shrink = 0.0;
                // Yoga preserves the authored main-axis size for fixed
                // LayoutComponents (`flexBasis = YGUnitAuto`,
                // src/layout_component.cpp:626-630, resolved by Yoga against
                // the container's real direction). Taffy's `auto` basis would
                // instead let intrinsic Text content widen the fixed child,
                // so pin the point value — picked along the container's
                // ACTUAL main axis. That axis diverges from the
                // `parent_is_row` gating quirk only under a style-less
                // container: C++ `mainAxisIsRow()` reports row there while
                // the zero-initialized Yoga node settles as a column.
                style.flex_basis =
                    if self.parent_actual_main_axis_is_row(instance, layout_local, parent_is_row) {
                        style.size.width
                    } else {
                        style.size.height
                    };
            }
            2 => {
                style.flex_grow = 0.0;
                style.flex_shrink = 0.0;
                style.flex_basis = Dimension::auto();
            }
            1 => {
                style.flex_grow =
                    instance.runtime_layout_axis_fraction(layout_local, parent_is_row);
                style.flex_shrink = style.flex_grow;
                let basis = instance
                    .runtime_layout_style_double(style_local, RuntimeLayoutStyleProperty::FlexBasis)
                    .unwrap_or(0.0);
                let units = instance.runtime_layout_style_uint_default(
                    style_local,
                    RuntimeLayoutStyleProperty::FlexBasisUnitsValue,
                    3,
                );
                style.flex_basis = self.dimension_from_unit(basis, units)?;
            }
            _ => return None,
        }
        style.align_self = match cross_scale {
            1 => Some(AlignSelf::STRETCH),
            0 | 2 => None,
            _ => return None,
        };
        Some(())
    }

    /// The solved main axis of this node's layout container, as the layout
    /// engine will actually flow it. This differs from the C++
    /// `mainAxisIsRow()` gating value only for a style-less container:
    /// upstream's accessor reports row on a null style
    /// (src/layout_component.cpp:436-444) while the zero-initialized Yoga
    /// node settles as a column (yoga/YGStyle.h `flags = 0`,
    /// `YGFlexDirectionColumn`) — only the style-less Artboard root reaches
    /// the layout tree in that state. Falls back to the gating value when the
    /// container cannot be resolved from this instance (a component-list item
    /// child whose container lives in the host artboard).
    fn parent_actual_main_axis_is_row(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        quirk_parent_is_row: bool,
    ) -> bool {
        let mut current = instance.component_parent_local(local);
        let mut visited = BTreeSet::new();
        while let Some(parent) = current {
            if !visited.insert(parent) {
                break;
            }
            if let Some(style_local) = instance.runtime_layout_node_style_local(parent) {
                return instance.runtime_layout_style_is_row(style_local);
            }
            if parent == 0 {
                // Style-less Artboard root: Yoga's zero-initialized default
                // flows children as a column.
                return false;
            }
            current = instance.component_parent_local(parent);
        }
        quirk_parent_is_row
    }

    fn parent_layout_type(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        local: usize,
    ) -> u64 {
        let mut current = graph
            .components
            .iter()
            .find(|component| component.local_id == local)
            .and_then(|_| instance.component_parent_local(local));
        let mut visited = BTreeSet::new();
        while let Some(parent) = current {
            if !visited.insert(parent) {
                break;
            }
            if let Some(style_local) = instance.runtime_layout_component_style_local(parent) {
                return instance.runtime_layout_style_uint_default(
                    style_local,
                    RuntimeLayoutStyleProperty::LayoutTypeValue,
                    0,
                );
            }
            current = instance.component_parent_local(parent);
        }
        0
    }

    fn apply_grid_container_style(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        local: usize,
        style_local: usize,
        style: &mut Style,
    ) -> Option<()> {
        style.justify_items = self.grid_align_items(instance.runtime_layout_style_uint_default(
            style_local,
            RuntimeLayoutStyleProperty::JustifyItemsValue,
            7,
        ));
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == local)?;
        for child_local in &component.children {
            let child = graph
                .components
                .iter()
                .find(|component| component.local_id == *child_local)?;
            if child.type_name != "GridTrack" {
                continue;
            }
            let collection = property_key_for_name("GridTrack", "collection")
                .and_then(|key| instance.uint_property(*child_local, key))
                .unwrap_or(0);
            let track = self.grid_track(instance, *child_local)?;
            match collection {
                0 => style
                    .grid_template_columns
                    .push(GridTemplateComponent::Single(track)),
                1 => style
                    .grid_template_rows
                    .push(GridTemplateComponent::Single(track)),
                2 => style.grid_auto_columns.push(track),
                3 => style.grid_auto_rows.push(track),
                _ => {}
            }
        }
        Some(())
    }

    fn grid_track(&self, instance: &ArtboardInstance, local: usize) -> Option<TrackSizingFunction> {
        let uint = |name| {
            property_key_for_name("GridTrack", name)
                .and_then(|key| instance.uint_property(local, key))
        };
        let number = |name| {
            property_key_for_name("GridTrack", name)
                .and_then(|key| instance.double_property(local, key))
                .unwrap_or(0.0)
        };
        let track_type = uint("trackType").unwrap_or(0);
        let value = number("trackValue").max(0.0);
        let min = match track_type {
            1 => MinTrackSizingFunction::length(value),
            2 => MinTrackSizingFunction::percent(value / 100.0),
            3 => MinTrackSizingFunction::auto(),
            _ => MinTrackSizingFunction::auto(),
        };
        let default_max = match track_type {
            1 => MaxTrackSizingFunction::length(value),
            2 => MaxTrackSizingFunction::percent(value / 100.0),
            3 => MaxTrackSizingFunction::fr(value),
            _ => MaxTrackSizingFunction::auto(),
        };
        let max_type = uint("trackMaxType").unwrap_or(0);
        let max_value = number("trackMaxValue").max(0.0);
        let max = match max_type {
            0 => default_max,
            1 => MaxTrackSizingFunction::auto(),
            2 => MaxTrackSizingFunction::length(max_value),
            3 => MaxTrackSizingFunction::percent(max_value / 100.0),
            4 => MaxTrackSizingFunction::fr(max_value),
            _ => default_max,
        };
        Some(TrackSizingFunction { min, max })
    }

    fn apply_grid_item_style(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        local: usize,
        style_local: usize,
        stack: bool,
        style: &mut Style,
    ) -> Option<()> {
        let width_hugs = instance.runtime_layout_axis_scale(style_local, true) == 2;
        let justify_self = instance.runtime_layout_style_uint_default(
            style_local,
            RuntimeLayoutStyleProperty::JustifySelfValue,
            6,
        );
        let container_justify_items = instance
            .runtime_owning_layout_local(local)
            .and_then(|parent| instance.runtime_layout_component_style_local(parent))
            .map(|parent_style| {
                instance.runtime_layout_style_uint_default(
                    parent_style,
                    RuntimeLayoutStyleProperty::JustifyItemsValue,
                    7,
                )
            })
            .unwrap_or(7);
        let resolved_justify_self = if !stack
            && width_hugs
            && (justify_self == 7 || (justify_self == 6 && container_justify_items == 7))
        {
            0
        } else {
            justify_self
        };
        style.justify_self = if instance.runtime_layout_axis_scale(style_local, true) == 1 {
            Some(AlignSelf::STRETCH)
        } else {
            self.grid_align_self(resolved_justify_self)
        };
        if instance.runtime_layout_axis_scale(style_local, false) == 1 {
            style.align_self = Some(AlignSelf::STRETCH);
        }
        if stack {
            style.grid_column = Line {
                start: GridPlacement::Line(1.into()),
                end: GridPlacement::Auto,
            };
            style.grid_row = Line {
                start: GridPlacement::Line(1.into()),
                end: GridPlacement::Auto,
            };
            return Some(());
        }
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == local)?;
        let placement_local = component.children.iter().find_map(|child_local| {
            graph
                .components
                .iter()
                .find(|component| component.local_id == *child_local)
                .filter(|component| component.type_name == "GridItemPlacement")
                .map(|_| *child_local)
        });
        let Some(placement_local) = placement_local else {
            return Some(());
        };
        style.grid_column =
            self.grid_item_line(instance, placement_local, "gridColumn", "gridColumnSpan")?;
        style.grid_row =
            self.grid_item_line(instance, placement_local, "gridRow", "gridRowSpan")?;
        Some(())
    }

    fn grid_item_line(
        &self,
        instance: &ArtboardInstance,
        local: usize,
        cell_name: &str,
        span_name: &str,
    ) -> Option<Line<GridPlacement>> {
        let cell = property_key_for_name("GridItemPlacement", cell_name)
            .and_then(|key| instance.objects.int_property(local, key))
            .unwrap_or(0);
        let span = property_key_for_name("GridItemPlacement", span_name)
            .and_then(|key| instance.uint_property(local, key))
            .and_then(|value| u16::try_from(value).ok())
            .unwrap_or(1);
        let start = if cell == 0 {
            GridPlacement::Auto
        } else {
            let line = if cell < 0 { cell - 1 } else { cell };
            GridPlacement::Line(i16::try_from(line).ok()?.into())
        };
        let end = if span > 1 {
            GridPlacement::Span(span)
        } else {
            GridPlacement::Auto
        };
        Some(Line { start, end })
    }

    fn grid_align_items(&self, value: u64) -> Option<AlignItems> {
        Some(match value {
            1 => AlignItems::CENTER,
            2 | 9 => AlignItems::FLEX_END,
            7 => AlignItems::STRETCH,
            _ => AlignItems::FLEX_START,
        })
    }

    fn grid_align_self(&self, value: u64) -> Option<AlignSelf> {
        match value {
            6 => None,
            1 => Some(AlignSelf::CENTER),
            2 | 9 => Some(AlignSelf::FLEX_END),
            7 => Some(AlignSelf::STRETCH),
            _ => Some(AlignSelf::FLEX_START),
        }
    }

    fn apply_stack_alignment(
        &self,
        instance: &ArtboardInstance,
        style_local: usize,
        style: &mut Style,
    ) {
        let alignment = instance.runtime_layout_alignment_type(style_local);
        style.justify_items = Some(match alignment {
            1 | 4 | 7 | 10 => AlignItems::CENTER,
            2 | 5 | 8 | 11 => AlignItems::FLEX_END,
            _ => AlignItems::FLEX_START,
        });
        style.align_items = Some(match alignment {
            3..=5 => AlignItems::CENTER,
            6..=8 => AlignItems::FLEX_END,
            _ => AlignItems::FLEX_START,
        });
    }

    fn apply_alignment(&self, instance: &ArtboardInstance, style_local: usize, style: &mut Style) {
        let alignment = instance.runtime_layout_alignment_type(style_local);
        let is_row = instance.runtime_layout_style_is_row(style_local);

        match alignment {
            0 | 1 | 2 => {
                if is_row {
                    style.align_items = Some(AlignItems::FLEX_START);
                    style.align_content = Some(AlignContent::FLEX_START);
                } else {
                    style.justify_content = Some(JustifyContent::FLEX_START);
                }
            }
            3 | 4 | 5 => {
                if is_row {
                    style.align_items = Some(AlignItems::CENTER);
                    style.align_content = Some(AlignContent::CENTER);
                } else {
                    style.justify_content = Some(JustifyContent::CENTER);
                }
            }
            6 | 7 | 8 => {
                if is_row {
                    style.align_items = Some(AlignItems::FLEX_END);
                    style.align_content = Some(AlignContent::FLEX_END);
                } else {
                    style.justify_content = Some(JustifyContent::FLEX_END);
                }
            }
            _ => {}
        }

        match alignment {
            0 | 3 | 6 => {
                if is_row {
                    style.justify_content = Some(JustifyContent::FLEX_START);
                } else {
                    style.align_items = Some(AlignItems::FLEX_START);
                    style.align_content = Some(AlignContent::FLEX_START);
                }
            }
            1 | 4 | 7 => {
                if is_row {
                    style.justify_content = Some(JustifyContent::CENTER);
                } else {
                    style.align_items = Some(AlignItems::CENTER);
                    style.align_content = Some(AlignContent::CENTER);
                }
            }
            2 | 5 | 8 => {
                if is_row {
                    style.justify_content = Some(JustifyContent::FLEX_END);
                } else {
                    style.align_items = Some(AlignItems::FLEX_END);
                    style.align_content = Some(AlignContent::FLEX_END);
                }
            }
            9 => {
                style.align_items = Some(AlignItems::FLEX_START);
                style.align_content = Some(AlignContent::FLEX_START);
                style.justify_content = Some(JustifyContent::SPACE_BETWEEN);
            }
            10 => {
                style.align_items = Some(AlignItems::CENTER);
                style.align_content = Some(AlignContent::CENTER);
                style.justify_content = Some(JustifyContent::SPACE_BETWEEN);
            }
            11 => {
                style.align_items = Some(AlignItems::FLEX_END);
                style.align_content = Some(AlignContent::FLEX_END);
                style.justify_content = Some(JustifyContent::SPACE_BETWEEN);
            }
            _ => {}
        }
    }

    fn needs_unimplemented_measure(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        runtime: Option<&RuntimeFile>,
        layout_local: usize,
    ) -> Option<bool> {
        let Some(style_local) = instance.runtime_layout_component_style_local(layout_local) else {
            return Some(false);
        };
        if !self
            .layout_provider_children(instance, layout_local)?
            .is_empty()
        {
            return Some(false);
        }
        let intrinsic = instance
            .runtime_layout_style_bool(
                style_local,
                RuntimeLayoutStyleProperty::IntrinsicallySizedValue,
            )
            .unwrap_or(false);
        let hugs_content = instance.runtime_layout_axis_scale(style_local, true) == 2
            || instance.runtime_layout_axis_scale(style_local, false) == 2;
        if !intrinsic && !hugs_content {
            return Some(false);
        }
        if runtime.is_some()
            && self.layout_component_registers_measure_func(instance, layout_local)?
        {
            return Some(false);
        }
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == layout_local)?;
        Some(component.children.iter().any(|child_local| {
            let child_type = graph
                .components
                .iter()
                .find(|component| component.local_id == *child_local)
                .map(|child| child.type_name);
            let measured_child = runtime.is_some()
                && matches!(
                    child_type,
                    Some("Shape" | "Text" | "TextInput" | "Joystick" | "ScriptedLayout")
                );
            let zero_sized_component_list = matches!(child_type, Some("ArtboardComponentList"))
                && self
                    .zero_sized_component_list_supported(graph, *child_local)
                    .unwrap_or(false);
            !measured_child
                && !zero_sized_component_list
                && !matches!(
                    child_type,
                    Some(
                        "LayoutComponent"
                            | "Fill"
                            | "LinearGradient"
                            | "NestedArtboardLeaf"
                            | "NestedArtboardLayout"
                            | "RadialGradient"
                            | "SolidColor"
                            | "Stroke"
                            | "LayoutComponentStyle"
                    )
                )
        }))
    }

    /// Mirrors `LayoutComponent::syncStyle`: an intrinsically-sized Yoga leaf
    /// owns a measure function even when its measured children contribute
    /// zero. The callback itself performs the `IntrinsicallySizeable` dispatch.
    fn layout_component_registers_measure_func(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
    ) -> Option<bool> {
        let style_local = instance.runtime_layout_component_style_local(layout_local)?;
        if !instance
            .runtime_layout_style_bool(
                style_local,
                RuntimeLayoutStyleProperty::IntrinsicallySizedValue,
            )
            .unwrap_or(false)
        {
            return Some(false);
        }
        Some(
            self.layout_provider_children(instance, layout_local)?
                .is_empty(),
        )
    }

    fn measure_layout_component(
        &self,
        runtime: &RuntimeFile,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        layout_local: usize,
        known_dimensions: Size<Option<f32>>,
        available_space: Size<AvailableSpace>,
    ) -> Option<Size<f32>> {
        // Ported from C++ `src/layout_component.cpp`
        // `LayoutComponent::measureLayout`: measure intrinsically sizeable
        // non-layout children and take the max size for the static runtime
        // subsets the Taffy adapter can currently model.
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == layout_local)?;
        let style_local = instance.runtime_layout_component_style_local(layout_local);
        let fixed_width = style_local.and_then(|style_local| {
            self.fixed_layout_measure_dimension(
                instance,
                layout_local,
                style_local,
                true,
                available_space.width,
            )
        });
        let fixed_height = style_local.and_then(|style_local| {
            self.fixed_layout_measure_dimension(
                instance,
                layout_local,
                style_local,
                false,
                available_space.height,
            )
        });
        let constrained_dimensions = Size {
            // Yoga's fixed-axis style is authoritative even when the layout
            // engine offers an intrinsic known dimension to the callback.
            width: fixed_width.or(known_dimensions.width),
            height: fixed_height.or(known_dimensions.height),
        };
        let mut measured = Size::ZERO;
        for child_local in &component.children {
            // Mirrors C++ `LayoutComponent::measureLayout`: hidden/collapsed
            // intrinsically sizeable children still participate in layout
            // measurement; draw filtering happens later.
            let Some(child) = graph
                .components
                .iter()
                .find(|component| component.local_id == *child_local)
            else {
                continue;
            };
            let Some(child_handle) = instance.component_handle(child.local_id) else {
                continue;
            };
            if crate::intrinsically_sizeable::RuntimeIntrinsicallySizeable::from_component(
                instance,
                child_handle,
            )
            .is_none()
            {
                continue;
            }
            match child.type_name {
                "Shape" => {
                    let Some((width, height)) = self.measure_shape_layout_child(
                        instance,
                        graph,
                        child.local_id,
                        known_dimensions,
                        available_space,
                    ) else {
                        continue;
                    };
                    measured.width = measured.width.max(width);
                    measured.height = measured.height.max(height);
                }
                "Text" => {
                    let measured_bounds = instance
                        .runtime_layout_component_style_local(layout_local)
                        .and_then(|style_local| {
                            let layout_constraint = RuntimeTextLayoutConstraint {
                                width: constrained_dimensions
                                    .width
                                    .or_else(|| definite_available_space(available_space.width))
                                    .unwrap_or(f32::MAX),
                                height: constrained_dimensions
                                    .height
                                    .or_else(|| definite_available_space(available_space.height))
                                    .unwrap_or(f32::MAX),
                                width_scale_type: instance
                                    .runtime_layout_axis_scale(style_local, true),
                                height_scale_type: instance
                                    .runtime_layout_axis_scale(style_local, false),
                                layout_direction: instance
                                    .debug_layout_actual_direction(layout_local)
                                    .unwrap_or(0),
                            };
                            static_text_layout_measure_bounds(
                                runtime,
                                graph,
                                instance,
                                child.local_id,
                                layout_constraint,
                            )
                        });
                    let Some((_x, _y, width, height)) = measured_bounds else {
                        continue;
                    };
                    measured.width = measured.width.max(width);
                    measured.height = measured.height.max(height);
                }
                "TextInput" => {
                    let measured_bounds = instance
                        .runtime_layout_component_style_local(layout_local)
                        .and_then(|style_local| {
                            let layout_constraint = RuntimeTextLayoutConstraint {
                                width: constrained_dimensions
                                    .width
                                    .or_else(|| definite_available_space(available_space.width))
                                    .unwrap_or(f32::MAX),
                                height: constrained_dimensions
                                    .height
                                    .or_else(|| definite_available_space(available_space.height))
                                    .unwrap_or(f32::MAX),
                                width_scale_type: instance
                                    .runtime_layout_axis_scale(style_local, true),
                                height_scale_type: instance
                                    .runtime_layout_axis_scale(style_local, false),
                                layout_direction: instance
                                    .debug_layout_actual_direction(layout_local)
                                    .unwrap_or(0),
                            };
                            text_input_layout_measure_bounds(
                                runtime,
                                graph,
                                instance,
                                child.local_id,
                                layout_constraint,
                            )
                        });
                    let Some((_x, _y, width, height)) = measured_bounds else {
                        continue;
                    };
                    measured.width = measured.width.max(width);
                    measured.height = measured.height.max(height);
                }
                "ArtboardComponentList" => {
                    let Some((width, height)) = self.measure_component_list_layout_child(
                        instance,
                        layout_local,
                        child.local_id,
                    ) else {
                        continue;
                    };
                    measured.width = measured.width.max(width);
                    measured.height = measured.height.max(height);
                }
                "Joystick" => {
                    let maximum_width = known_dimensions
                        .width
                        .or_else(|| definite_available_space(available_space.width))
                        .unwrap_or(f32::MAX);
                    let maximum_height = known_dimensions
                        .height
                        .or_else(|| definite_available_space(available_space.height))
                        .unwrap_or(f32::MAX);
                    let Some((width, height)) = crate::joystick::measure_joystick_layout(
                        instance,
                        child_handle,
                        maximum_width,
                        maximum_height,
                    ) else {
                        continue;
                    };
                    measured.width = measured.width.max(width);
                    measured.height = measured.height.max(height);
                }
                "ScriptedLayout" => {
                    let maximum_width = constrained_dimensions
                        .width
                        .or_else(|| definite_available_space(available_space.width));
                    let maximum_height = constrained_dimensions
                        .height
                        .or_else(|| definite_available_space(available_space.height));
                    let (width, height) = instance.measure_scripted_layout(
                        child.local_id,
                        maximum_width,
                        maximum_height,
                    );
                    measured.width = measured.width.max(width);
                    measured.height = measured.height.max(height);
                }
                _ => {}
            }
        }
        Some(Size {
            width: constrained_dimensions.width.unwrap_or(measured.width),
            height: constrained_dimensions.height.unwrap_or(measured.height),
        })
    }

    fn measure_layout_participant(
        &self,
        runtime: &RuntimeFile,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        local: usize,
        known_dimensions: Size<Option<f32>>,
        available_space: Size<AvailableSpace>,
    ) -> Option<Size<f32>> {
        let component = graph
            .components
            .iter()
            .find(|component| component.local_id == local)?;
        let style_local = instance.runtime_layout_participant_local(local)?;
        let fixed_width = self.fixed_layout_measure_dimension(
            instance,
            local,
            style_local,
            true,
            available_space.width,
        );
        let fixed_height = self.fixed_layout_measure_dimension(
            instance,
            local,
            style_local,
            false,
            available_space.height,
        );
        let constrained = Size {
            width: fixed_width.or(known_dimensions.width),
            height: fixed_height.or(known_dimensions.height),
        };
        let measured = match component.type_name {
            "Shape" => self
                .measure_shape_layout_child(instance, graph, local, constrained, available_space)
                .map(|(width, height)| Size { width, height })
                .unwrap_or(Size::ZERO),
            "Text" => {
                let constraint = RuntimeTextLayoutConstraint {
                    width: constrained
                        .width
                        .or_else(|| definite_available_space(available_space.width))
                        .unwrap_or(f32::MAX),
                    height: constrained
                        .height
                        .or_else(|| definite_available_space(available_space.height))
                        .unwrap_or(f32::MAX),
                    width_scale_type: instance.runtime_layout_axis_scale(style_local, true),
                    height_scale_type: instance.runtime_layout_axis_scale(style_local, false),
                    layout_direction: instance.debug_layout_actual_direction(local).unwrap_or(0),
                };
                static_text_layout_measure_bounds(runtime, graph, instance, local, constraint)
                    .map(|(_, _, width, height)| Size { width, height })
                    .unwrap_or(Size::ZERO)
            }
            "TextInput" => {
                let constraint = RuntimeTextLayoutConstraint {
                    width: constrained
                        .width
                        .or_else(|| definite_available_space(available_space.width))
                        .unwrap_or(f32::MAX),
                    height: constrained
                        .height
                        .or_else(|| definite_available_space(available_space.height))
                        .unwrap_or(f32::MAX),
                    width_scale_type: instance.runtime_layout_axis_scale(style_local, true),
                    height_scale_type: instance.runtime_layout_axis_scale(style_local, false),
                    layout_direction: instance.debug_layout_actual_direction(local).unwrap_or(0),
                };
                text_input_layout_measure_bounds(runtime, graph, instance, local, constraint)
                    .map(|(_, _, width, height)| Size { width, height })
                    .unwrap_or(Size::ZERO)
            }
            _ => Size::ZERO,
        };
        Some(Size {
            width: constrained.width.unwrap_or(measured.width),
            height: constrained.height.unwrap_or(measured.height),
        })
    }

    fn fixed_layout_measure_dimension(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
        style_local: usize,
        width_axis: bool,
        available_space: AvailableSpace,
    ) -> Option<f32> {
        if instance.runtime_layout_axis_scale(style_local, width_axis) != 0 {
            return None;
        }
        let value = instance
            .runtime_layout_component_dimension(
                layout_local,
                if width_axis { "width" } else { "height" },
            )
            .max(0.0);
        match self.effective_units(instance, layout_local, style_local, width_axis)? {
            0 | 1 => Some(value),
            2 => {
                definite_available_space(available_space).map(|available| available * value / 100.0)
            }
            _ => None,
        }
    }

    /// C++ exposes each `ArtboardComponentList` row as a layout-provider node
    /// of the hosting `LayoutComponent`. The current Taffy adapter represents
    /// intrinsically measured non-layout children through one leaf callback,
    /// so collapse those repeated nodes to their equivalent no-wrap intrinsic
    /// extent. Parent padding is deliberately excluded: Taffy applies it from
    /// the hosting component's style around this measured content box.
    fn measure_component_list_layout_child(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
        list_local: usize,
    ) -> Option<(f32, f32)> {
        let items = instance.component_list_items(list_local)?;
        if items.is_empty() {
            return Some((0.0, 0.0));
        }
        let style_local = instance.runtime_layout_component_style_local(layout_local)?;
        let is_row = instance.runtime_layout_style_is_row(style_local);
        let gap = if is_row {
            instance
                .runtime_layout_style_double(style_local, RuntimeLayoutStyleProperty::GapHorizontal)
        } else {
            instance
                .runtime_layout_style_double(style_local, RuntimeLayoutStyleProperty::GapVertical)
        }
        .unwrap_or(0.0);
        let mut width: f32 = 0.0;
        let mut height: f32 = 0.0;
        for item in items {
            let (item_width, item_height) = runtime_component_list_item_layout_size(item);
            if is_row {
                width += item_width;
                height = height.max(item_height);
            } else {
                width = width.max(item_width);
                height += item_height;
            }
        }
        let total_gap = gap * items.len().saturating_sub(1) as f32;
        if is_row {
            width += total_gap;
        } else {
            height += total_gap;
        }
        Some((width, height))
    }

    fn measure_shape_layout_child(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        shape_local: usize,
        known_dimensions: Size<Option<f32>>,
        available_space: Size<AvailableSpace>,
    ) -> Option<(f32, f32)> {
        // Ported from C++ `src/shapes/shape.cpp` and
        // `src/shapes/parametric_path.cpp`: `Shape::measureLayout` takes the max
        // measured size of its intrinsically sizeable paths; parametric paths
        // clamp their authored size to the provided measure constraints.
        let composer = graph
            .path_composers
            .iter()
            .find(|composer| composer.shape_local == shape_local)?;
        let max_width = known_dimensions
            .width
            .or_else(|| definite_available_space(available_space.width))
            .unwrap_or(f32::MAX);
        let max_height = known_dimensions
            .height
            .or_else(|| definite_available_space(available_space.height))
            .unwrap_or(f32::MAX);
        let mut measured = Size::ZERO;
        for path_ref in &composer.paths {
            let Some(path) = graph
                .paths
                .iter()
                .find(|path| path.local_id == path_ref.local_id)
            else {
                continue;
            };
            let runtime_path = runtime_path_geometry(instance, path);
            let Some((width, height)) =
                measure_parametric_path_layout(&runtime_path, max_width, max_height)
            else {
                continue;
            };
            measured.width = measured.width.max(width);
            measured.height = measured.height.max(height);
        }
        Some((measured.width, measured.height))
    }

    /// Mirrors pinned C++ `forEachLayoutProvider`: walk the occurrence-owned
    /// `ContainerComponent::children()` hierarchy directly. Keeping
    /// `ArtboardGraph` out of this interface prevents provider discovery from
    /// falling back to local-id scans over the static component vector.
    fn layout_provider_children(
        &self,
        instance: &ArtboardInstance,
        layout_local: usize,
    ) -> Option<Vec<usize>> {
        fn visit(
            instance: &ArtboardInstance,
            from: usize,
            nested: bool,
            out: &mut Vec<usize>,
            visiting: &mut BTreeSet<usize>,
        ) -> Option<()> {
            if !visiting.insert(from) {
                return Some(());
            }
            let component_handle = instance.component_handle(from)?;
            let component = instance.component(from)?;
            for child_handle in &component.children {
                let child_local = instance.component_local_id(*child_handle)?;
                if component.type_name == "Solo"
                    && instance
                        .component(child_local)
                        .is_some_and(RuntimeComponent::is_collapsed)
                {
                    continue;
                }
                let child = instance.component(child_local)?;
                if child.parent != Some(component_handle) {
                    continue;
                }
                let provider = matches!(
                    child.type_name,
                    "LayoutComponent" | "NestedArtboardLayout" | "ArtboardComponentList"
                ) || instance
                    .runtime_layout_participant_local(child_local)
                    .is_some();
                if provider {
                    // S4-38 keeps an ArtboardComponentList behind a transparent
                    // Group/Solo out of layout unless DrawableFlag bit 8 opts
                    // it in. Existing files leave the bit unset so their
                    // free-form x/y or follow-path placement is unchanged.
                    let joins_through_container = child.type_name != "ArtboardComponentList"
                        || !nested
                        || property_key_for_name("Drawable", "drawableFlags")
                            .and_then(|key| instance.uint_property(child_local, key))
                            .is_some_and(|flags| flags & (1 << 8) != 0);
                    if joins_through_container {
                        out.push(child_local);
                    }
                } else if matches!(child.type_name, "Node" | "Group" | "Solo") {
                    visit(instance, child_local, true, out, visiting)?;
                }
            }
            visiting.remove(&from);
            Some(())
        }

        let mut providers = Vec::new();
        visit(
            instance,
            layout_local,
            false,
            &mut providers,
            &mut BTreeSet::new(),
        )?;
        Some(providers)
    }

    fn dimension_style(
        &self,
        instance: &ArtboardInstance,
        style_local: usize,
        value_property: RuntimeLayoutStyleProperty,
        unit_property: RuntimeLayoutStyleProperty,
        zero_undefined_is_auto: bool,
        _nonzero_undefined_is_auto: bool,
    ) -> Option<Dimension> {
        let value = instance
            .runtime_layout_style_double(style_local, value_property)
            .unwrap_or(0.0);
        let units = instance.runtime_layout_style_uint_default(style_local, unit_property, 0);
        if _nonzero_undefined_is_auto
            && units == 0
            && value.abs() > f32::EPSILON
            && matches!(
                value_property,
                RuntimeLayoutStyleProperty::MinWidth | RuntimeLayoutStyleProperty::MinHeight
            )
        {
            return Some(Dimension::auto());
        }
        if zero_undefined_is_auto && units == 0 && value.abs() <= f32::EPSILON {
            return Some(Dimension::auto());
        }
        self.dimension_from_unit(value.max(0.0), units)
    }

    fn length_percentage_style(
        &self,
        instance: &ArtboardInstance,
        style_local: usize,
        value_property: RuntimeLayoutStyleProperty,
        unit_property: RuntimeLayoutStyleProperty,
    ) -> Option<LengthPercentage> {
        let value = instance
            .runtime_layout_style_double(style_local, value_property)
            .unwrap_or(0.0);
        let units = instance.runtime_layout_style_uint_default(style_local, unit_property, 0);
        self.length_percentage_from_unit(value, units)
    }

    fn length_percentage_auto_style(
        &self,
        instance: &ArtboardInstance,
        style_local: usize,
        value_property: RuntimeLayoutStyleProperty,
        unit_property: RuntimeLayoutStyleProperty,
    ) -> Option<LengthPercentageAuto> {
        let value = instance
            .runtime_layout_style_double(style_local, value_property)
            .unwrap_or(0.0);
        let units = instance.runtime_layout_style_uint_default(style_local, unit_property, 0);
        self.length_percentage_auto_from_unit(value, units)
    }

    fn position_inset_style(
        &self,
        instance: &ArtboardInstance,
        style_local: usize,
        value_property: RuntimeLayoutStyleProperty,
        unit_property: RuntimeLayoutStyleProperty,
    ) -> Option<LengthPercentageAuto> {
        let value = instance
            .runtime_layout_style_double(style_local, value_property)
            .unwrap_or(0.0);
        let units = instance.runtime_layout_style_uint_default(style_local, unit_property, 0);
        self.position_inset_from_unit(value, units)
    }

    fn dimension_from_unit(&self, value: f32, units: u64) -> Option<Dimension> {
        match units {
            2 => Some(Dimension::percent(value / 100.0)),
            3 => Some(Dimension::auto()),
            0 | 1 => Some(Dimension::length(value)),
            _ => None,
        }
    }

    fn length_percentage_from_unit(&self, value: f32, units: u64) -> Option<LengthPercentage> {
        match units {
            2 => Some(LengthPercentage::percent(value / 100.0)),
            0 | 1 | 3 => Some(LengthPercentage::length(value)),
            _ => None,
        }
    }

    fn position_inset_from_unit(&self, value: f32, units: u64) -> Option<LengthPercentageAuto> {
        // C++ `src/layout_component.cpp::positionTypeChanged` leaves
        // non-explicit position edges as Yoga undefined, which maps to Taffy
        // auto rather than a zero/nonzero length.
        match units {
            1 => Some(LengthPercentageAuto::length(value)),
            2 => Some(LengthPercentageAuto::percent(value / 100.0)),
            0 | 3 => Some(LengthPercentageAuto::auto()),
            _ => None,
        }
    }

    fn length_percentage_auto_from_unit(
        &self,
        value: f32,
        units: u64,
    ) -> Option<LengthPercentageAuto> {
        match units {
            2 => Some(LengthPercentageAuto::percent(value / 100.0)),
            3 => Some(LengthPercentageAuto::auto()),
            0 | 1 => Some(LengthPercentageAuto::length(value)),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq)]
struct RuntimeLayoutCorners {
    top_left: f32,
    top_right: f32,
    bottom_right: f32,
    bottom_left: f32,
}

fn runtime_layout_rect_path_commands(
    bounds: RuntimeLayoutBounds,
    corners: RuntimeLayoutCorners,
) -> Vec<RuntimePathCommand> {
    let raw_path = runtime_layout_rect_raw_path(bounds, corners);
    let mut commands = runtime_path_commands_from_raw_path(&raw_path);
    prune_empty_path_segments(&mut commands);
    commands
}

/// Taffy-backed counterpart of C++ `Path::addRoundedRect`. Layout owns this
/// small RawPath directly; it must not acquire a Rectangle/vertex dependency.
fn runtime_layout_rect_raw_path(
    bounds: RuntimeLayoutBounds,
    corners: RuntimeLayoutCorners,
) -> RawPath {
    #[derive(Clone, Copy)]
    struct Corner {
        position: (f32, f32),
        to_prev: (f32, f32),
        to_next: (f32, f32),
        radius: f32,
    }

    let corners = [
        Corner {
            position: (0.0, 0.0),
            to_prev: (0.0, 1.0),
            to_next: (1.0, 0.0),
            radius: corners.top_left,
        },
        Corner {
            position: (bounds.width, 0.0),
            to_prev: (-1.0, 0.0),
            to_next: (0.0, 1.0),
            radius: corners.top_right,
        },
        Corner {
            position: (bounds.width, bounds.height),
            to_prev: (0.0, -1.0),
            to_next: (-1.0, 0.0),
            radius: corners.bottom_right,
        },
        Corner {
            position: (0.0, bounds.height),
            to_prev: (1.0, 0.0),
            to_next: (0.0, -1.0),
            radius: corners.bottom_left,
        },
    ];
    let max_radius = bounds.width.min(bounds.height) * 0.5;
    let mut raw_path = RawPath::new();
    raw_path.rebuild(10, 17, |path| {
        let mut start = (0.0, 0.0);
        for (index, corner) in corners.into_iter().enumerate() {
            if corner.radius != 0.0 {
                let radius = corner.radius.abs().min(max_radius);
                let ideal_distance =
                    compute_ideal_control_point_distance(corner.to_prev, corner.to_next, radius);
                let enter = scale_and_add_point(corner.position, corner.to_prev, radius);
                if index == 0 {
                    start = enter;
                    path.move_to(enter.0, enter.1);
                } else {
                    path.line_to(enter.0, enter.1);
                }
                let mut out_point =
                    scale_and_add_point(corner.position, corner.to_prev, radius - ideal_distance);
                let mut in_point =
                    scale_and_add_point(corner.position, corner.to_next, radius - ideal_distance);
                let exit = scale_and_add_point(corner.position, corner.to_next, radius);
                if corner.radius < 0.0 {
                    rotate_rounded_points(
                        exit,
                        enter,
                        corner.position,
                        &mut out_point,
                        &mut in_point,
                    );
                }
                path.cubic_to(
                    out_point.0,
                    out_point.1,
                    in_point.0,
                    in_point.1,
                    exit.0,
                    exit.1,
                );
            } else if index == 0 {
                start = corner.position;
                path.move_to(corner.position.0, corner.position.1);
            } else {
                path.line_to(corner.position.0, corner.position.1);
            }
        }
        path.line_to(start.0, start.1);
        path.close();
    });
    raw_path
}

#[cfg(test)]
fn runtime_layout_rect_path_commands_via_vertices(
    bounds: RuntimeLayoutBounds,
    corners: RuntimeLayoutCorners,
) -> Vec<RuntimePathCommand> {
    let virtual_path = PathGeometryNode {
        local_id: 0,
        global_id: 0,
        type_name: "PointsPath",
        is_closed: true,
        is_hole: false,
        is_clockwise: true,
        parametric: None,
        vertices: vec![
            virtual_straight_vertex(0.0, 0.0, corners.top_left),
            virtual_straight_vertex(bounds.width, 0.0, corners.top_right),
            virtual_straight_vertex(bounds.width, bounds.height, corners.bottom_right),
            virtual_straight_vertex(0.0, bounds.height, corners.bottom_left),
        ],
    };
    let mut commands = points_path_commands(
        &virtual_path,
        ShapePaintPathKind::Local,
        Mat2D::IDENTITY,
        None,
    );
    prune_empty_path_segments(&mut commands);
    commands
}

fn runtime_layout_hug_size(
    child_sizes: &[(f32, f32)],
    gap: f32,
    is_row: bool,
    width_axis: bool,
) -> f32 {
    if child_sizes.is_empty() {
        return 0.0;
    }
    let gap_total = gap * child_sizes.len().saturating_sub(1) as f32;
    match (is_row, width_axis) {
        (true, true) => child_sizes.iter().map(|(width, _)| *width).sum::<f32>() + gap_total,
        (true, false) => child_sizes
            .iter()
            .map(|(_, height)| *height)
            .fold(0.0, f32::max),
        (false, true) => child_sizes
            .iter()
            .map(|(width, _)| *width)
            .fold(0.0, f32::max),
        (false, false) => child_sizes.iter().map(|(_, height)| *height).sum::<f32>() + gap_total,
    }
}

fn runtime_layout_alignment_is_space_between(alignment: u64) -> bool {
    matches!(alignment, 9..=11)
}

fn runtime_layout_main_alignment_offset(
    alignment: u64,
    is_row: bool,
    available: f32,
    occupied: f32,
) -> f32 {
    if runtime_layout_alignment_is_space_between(alignment) {
        return 0.0;
    }
    let remaining = (available - occupied).max(0.0);
    if is_row {
        match alignment {
            1 | 4 | 7 => remaining / 2.0,
            2 | 5 | 8 => remaining,
            _ => 0.0,
        }
    } else {
        match alignment {
            3..=5 => remaining / 2.0,
            6..=8 => remaining,
            _ => 0.0,
        }
    }
}

fn runtime_layout_cross_alignment_offset(
    alignment: u64,
    is_row: bool,
    available: f32,
    size: f32,
) -> f32 {
    let remaining = (available - size).max(0.0);
    if is_row {
        match alignment {
            3..=5 | 10 => remaining / 2.0,
            6..=8 | 11 => remaining,
            _ => 0.0,
        }
    } else {
        match alignment {
            1 | 4 | 7 | 10 => remaining / 2.0,
            2 | 5 | 8 | 11 => remaining,
            _ => 0.0,
        }
    }
}

