#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct RuntimeNestedRenderCacheKey {
    host: u32,
    referenced_artboard_global: u32,
    instance_revision: u64,
}

type RuntimeNestedPaintCaches =
    BTreeMap<RuntimeNestedRenderCacheKey, RuntimeArtboardResourceBundle>;
type RuntimeOptionalPaintPreparation = Option<RuntimeArtboardPaintDirtState>;

const RUNTIME_COMPONENT_LIST_CACHE_NAMESPACE: u64 = 1_u64 << 63;

/// Renderer resources follow a mounted nested-artboard tree, where each
/// parent normally owns only a handful of direct children. C++ reaches those
/// resources through the already-mounted `NestedArtboard::m_Instance`
/// directly; using a tree map here added a logarithmic lookup and node walk to
/// every retained draw. Keep the external renderer-resource ownership needed
/// by Rust, but use the same small, parent-local shape as the mounted tree.
enum RuntimeNestedRenderCaches<T> {
    Flat(Vec<(RuntimeNestedRenderCacheKey, T)>),
    Ordered(BTreeMap<RuntimeNestedRenderCacheKey, T>),
}

impl<T> Default for RuntimeNestedRenderCaches<T> {
    fn default() -> Self {
        Self::Flat(Vec::new())
    }
}

impl<T> RuntimeNestedRenderCaches<T> {
    // Authored nesting can be wider than the usual handful of direct children:
    // ai_assitant has 16 under one artboard. C++ still reaches each child
    // through direct NestedArtboard ownership, so keep that real-world width
    // in the parent-local flat tier instead of spilling every draw to a map.
    const FLAT_CAPACITY: usize = 32;

    #[inline]
    fn get_or_insert_with(
        &mut self,
        key: RuntimeNestedRenderCacheKey,
        make: impl FnOnce() -> T,
    ) -> &mut T {
        if matches!(self, Self::Ordered(_)) {
            let Self::Ordered(entries) = self else {
                unreachable!();
            };
            return entries.entry(key).or_insert_with(make);
        }

        let existing = match self {
            Self::Flat(entries) => entries.iter().position(|(candidate, _)| *candidate == key),
            Self::Ordered(_) => unreachable!(),
        };
        if let Some(index) = existing {
            let Self::Flat(entries) = self else {
                unreachable!();
            };
            return &mut entries[index].1;
        }

        let should_spill = key.instance_revision & RUNTIME_COMPONENT_LIST_CACHE_NAMESPACE != 0
            || matches!(self, Self::Flat(entries) if entries.len() == Self::FLAT_CAPACITY);
        if should_spill {
            // Component-list rows are a potentially large collection, unlike
            // the mounted direct-child set. Preserve logarithmic lookup for
            // that explicit cache-key namespace, and for unusually broad
            // ordinary nesting trees.
            let Self::Flat(entries) = std::mem::replace(self, Self::Ordered(BTreeMap::new()))
            else {
                unreachable!();
            };
            let Self::Ordered(ordered) = self else {
                unreachable!();
            };
            ordered.extend(entries);
            return ordered.entry(key).or_insert_with(make);
        }

        let Self::Flat(entries) = self else {
            unreachable!();
        };
        entries.push((key, make()));
        &mut entries.last_mut().expect("just inserted").1
    }

    #[inline]
    fn get_or_insert_default(&mut self, key: RuntimeNestedRenderCacheKey) -> &mut T
    where
        T: Default,
    {
        self.get_or_insert_with(key, T::default)
    }
}

#[derive(Default)]
pub(crate) struct RuntimeArtboardResourceBundle {
    paints: RuntimeRenderPaints,
    paint_configurations: RuntimePaintOwnerSlots,
    preparation_without_nested_layout: Option<RuntimeArtboardPaintDirtState>,
    preparation: RuntimeOptionalPaintPreparation,
    image_assets: Arc<RuntimeImageAssetOwners>,
    nested_artboards: RuntimeNestedPaintCaches,
    // Nested layout hosts require C++'s deferred-gradient preparation pass.
    // This is a conservative file-level fact, so compute it once while the
    // instance paint cache is built instead of walking the retained tree on
    // every frame.
    requires_nested_layout_prepass: bool,
    // A flat artboard containing only solid paints has no paint work to do
    // between advance and draw. Keep this conservative: nested/component-list
    // hosts can materialize child caches during preparation, even when neither
    // the parent nor child contains a gradient.
    paint_preparation_is_noop: bool,
    // A file containing no gradient paints only needs the recursive paint
    // preparation walk when its mounted instance tree changes. SolidColor
    // updates are applied to retained paints during draw, just as C++ mutates
    // its attached RenderPaint directly in SolidColor::colorValueChanged.
    paint_preparation_is_solid_only_tree: bool,
    solid_only_tree_structure_epoch: Option<u64>,
    image_decode_error: Option<ImageDecodeError>,
}

/// Backend state for one mounted child Artboard occurrence. C++
/// `NestedArtboard::m_Instance` and `ArtboardComponentList` rows own complete
/// ArtboardInstances, so their renderer resources follow that occurrence
/// instead of a host/facade cache key.
#[derive(Default)]
pub(crate) struct RuntimeOccurrenceRenderResources {
    parent_backend_context_id: Option<u64>,
    initialized: bool,
    /// `None` means the late backend has not attached this occurrence tree;
    /// `Some(epoch)` records the exact mounted structure already attached.
    /// The nested option preserves graph-less synthetic occurrences, whose
    /// stable epoch is itself `None`.
    image_tree_structure_epoch: Option<Option<u64>>,
    opacity_tree_structure_epoch: Option<Option<u64>>,
    paints: RuntimeRenderPaints,
    paint_configurations: RuntimePaintOwnerSlots,
    preparation_without_nested_layout: RuntimeOptionalPaintPreparation,
    preparation: RuntimeOptionalPaintPreparation,
    nested_artboards: RuntimeNestedPaintCaches,
    path_cache: RuntimeArtboardPathState,
    image_assets: Arc<RuntimeImageAssetOwners>,
    requires_nested_layout_prepass: bool,
    paint_preparation_is_noop: bool,
    paint_preparation_is_solid_only_tree: bool,
    solid_only_tree_structure_epoch: Option<u64>,
}

impl Clone for RuntimeOccurrenceRenderResources {
    fn clone(&self) -> Self {
        // Artboard clones rebuild every concrete object's derived/backend
        // members; never copy renderer handles across occurrences.
        Self::default()
    }
}

impl std::fmt::Debug for RuntimeOccurrenceRenderResources {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("RuntimeOccurrenceRenderResources")
            .field("initialized", &self.initialized)
            .finish_non_exhaustive()
    }
}

impl RuntimeOccurrenceRenderResources {
    fn install_root_cache(
        &mut self,
        cache: RuntimeArtboardResourceBundle,
    ) -> std::result::Result<(), ImageDecodeError> {
        if let Some(error) = cache.image_decode_error() {
            return Err(error);
        }
        self.parent_backend_context_id = Some(cache.paints.backend_context_id);
        self.paints = cache.paints;
        self.paint_configurations = cache.paint_configurations;
        self.preparation_without_nested_layout = cache.preparation_without_nested_layout;
        self.preparation = cache.preparation;
        self.nested_artboards = cache.nested_artboards;
        self.image_assets = cache.image_assets;
        self.requires_nested_layout_prepass = cache.requires_nested_layout_prepass;
        self.paint_preparation_is_noop = cache.paint_preparation_is_noop;
        self.paint_preparation_is_solid_only_tree = cache.paint_preparation_is_solid_only_tree;
        self.solid_only_tree_structure_epoch = cache.solid_only_tree_structure_epoch;
        self.initialized = true;
        Ok(())
    }

    fn reset_for_parent_backend_context(&mut self, parent_backend_context_id: u64) {
        if self.parent_backend_context_id == Some(parent_backend_context_id) {
            return;
        }
        *self = Self {
            parent_backend_context_id: Some(parent_backend_context_id),
            ..Self::default()
        };
    }

    fn initialize(
        &mut self,
        parent_backend_context_id: u64,
        runtime: &RuntimeFile,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        artboards: &[ArtboardGraph],
        factory: &mut dyn RenderFactory,
    ) {
        self.reset_for_parent_backend_context(parent_backend_context_id);
        if self.initialized {
            return;
        }
        let cache = preallocate_render_paint_cache_for_artboard_instance(
            runtime, instance, graph, artboards, factory,
        );
        self.paints = cache.paints;
        self.paint_configurations = cache.paint_configurations;
        self.preparation_without_nested_layout = cache.preparation_without_nested_layout;
        self.preparation = cache.preparation;
        self.nested_artboards = cache.nested_artboards;
        self.image_assets = cache.image_assets;
        self.requires_nested_layout_prepass = cache.requires_nested_layout_prepass;
        self.paint_preparation_is_noop = cache.paint_preparation_is_noop;
        self.paint_preparation_is_solid_only_tree = cache.paint_preparation_is_solid_only_tree;
        self.solid_only_tree_structure_epoch = cache.solid_only_tree_structure_epoch;
        self.initialized = true;
    }

    fn initialize_root(
        &mut self,
        runtime: &RuntimeFile,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        artboards: &[ArtboardGraph],
        external_images: &BTreeMap<u32, Arc<[u8]>>,
        factory: &mut dyn RenderFactory,
        max_retained_decoded_image_bytes: Option<usize>,
    ) -> std::result::Result<(), ImageDecodeError> {
        if self.initialized {
            return Ok(());
        }
        let cache =
            RuntimeArtboardResourceBundle::preallocate_for_artboard_tree_with_external_images(
                runtime,
                instance,
                graph,
                artboards,
                external_images,
                factory,
                max_retained_decoded_image_bytes,
            );
        self.install_root_cache(cache)
    }

    fn initialize_root_after_source_resources(
        &mut self,
        runtime: &RuntimeFile,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        artboards: &[ArtboardGraph],
        external_images: &BTreeMap<u32, Arc<[u8]>>,
        factory: &mut dyn RenderFactory,
        max_retained_decoded_image_bytes: Option<usize>,
    ) -> std::result::Result<(), ImageDecodeError> {
        if self.initialized {
            return Ok(());
        }
        let cache = preallocate_render_paint_cache_for_artboard_tree_internal(
            runtime,
            instance,
            graph,
            artboards,
            Some(external_images),
            factory,
            false,
            false,
            true,
            None,
            max_retained_decoded_image_bytes,
        );
        self.install_root_cache(cache)
    }

    fn needs_paint_preparation(&self, instance: &ArtboardInstance, graph: &ArtboardGraph) -> bool {
        if !graph.n_slicer_details.is_empty() {
            return true;
        }
        if self.paint_preparation_is_noop {
            return false;
        }
        if self.paint_preparation_is_solid_only_tree {
            let nested_structure_epoch = instance.nested_structure_epoch();
            return nested_structure_epoch.is_none()
                || self.solid_only_tree_structure_epoch != nested_structure_epoch;
        }
        if instance
            .runtime_shapes
            .backend_paints_need_realization(self.paints.backend_context_id)
        {
            return true;
        }
        let Some(preparation) = self.preparation.as_ref() else {
            return true;
        };
        // `update_artboard_backend_tree_internal` records this exact key only
        // after it has realized pending paints and completed the occurrence
        // traversal. Reuse that retained clean boundary so an explicit
        // prepare followed by draw does not enter synchronization twice.
        let Some(gradient_frame) = self
            .path_cache
            .gradient_preparation
            .as_ref()
            .filter(|frame| {
                frame.key.graph_global_id == graph.global_id
                    && frame.key.graph_identity == graph as *const ArtboardGraph as usize
            })
        else {
            return true;
        };
        let world_epoch = if gradient_frame.has_world_space_gradient_paints {
            instance.prepared_epoch()
        } else {
            0
        };
        !preparation.can_skip_prepared_frame(
            graph.global_id,
            instance.cache_epoch(),
            world_epoch,
            instance.tree_paint_preparation_epoch(),
        )
    }
}

pub struct RuntimeRenderPaints {
    // One renderer-resource context per public paint cache. ShapePaint and
    // ShapePaintPath remain occurrence-owned; this token only scopes the
    // backend realization of those C++-shaped slots.
    backend_context_id: u64,
    paints_by_global: Vec<Option<Box<dyn RenderPaint>>>,
}

static NEXT_RENDER_BACKEND_CONTEXT_ID: AtomicU64 = AtomicU64::new(1);

pub(crate) fn next_render_backend_context_id() -> u64 {
    let id = NEXT_RENDER_BACKEND_CONTEXT_ID.fetch_add(1, Ordering::Relaxed);
    if id == u64::MAX {
        std::process::abort();
    }
    id
}

impl Default for RuntimeRenderPaints {
    fn default() -> Self {
        Self {
            backend_context_id: next_render_backend_context_id(),
            paints_by_global: Vec::new(),
        }
    }
}

impl RuntimeRenderPaints {
    fn contains(&self, global_id: u32) -> bool {
        self.paints_by_global
            .get(global_id as usize)
            .is_some_and(Option::is_some)
    }

    fn insert(&mut self, global_id: u32, paint: Box<dyn RenderPaint>) {
        let slot = global_id as usize;
        if self.paints_by_global.len() <= slot {
            self.paints_by_global.resize_with(slot + 1, || None);
        }
        self.paints_by_global[slot] = Some(paint);
    }

    fn paint(&self, global_id: u32) -> Option<&Box<dyn RenderPaint>> {
        self.paints_by_global
            .get(global_id as usize)
            .and_then(|paint| paint.as_ref())
    }

    fn paint_mut(&mut self, global_id: u32) -> Option<&mut Box<dyn RenderPaint>> {
        self.paints_by_global.get_mut(global_id as usize)?.as_mut()
    }

    fn take_paint(&mut self, global_id: u32) -> Option<Box<dyn RenderPaint>> {
        self.paints_by_global
            .get_mut(global_id as usize)
            .and_then(Option::take)
    }
}

impl RuntimeArtboardResourceBundle {
    /// Returns whether this retained cache has paint or slice resources that
    /// must be refreshed before its next draw.
    ///
    /// Solid colors update their retained render paints during draw, matching
    /// C++ `SolidColor::colorValueChanged`. A solid-only tree therefore only
    /// needs the recursive preparation pass on its first mounted structure and
    /// after that structure changes. Gradients stay conservative, and authored
    /// NSlicers always run their mesh preparation work.
    #[inline]
    #[cfg(test)]
    pub(crate) fn needs_paint_preparation(
        &self,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
    ) -> bool {
        if !graph.n_slicer_details.is_empty() {
            return true;
        }
        if self.paint_preparation_is_noop {
            return false;
        }
        if self.paint_preparation_is_solid_only_tree {
            let nested_structure_epoch = instance.nested_structure_epoch();
            return nested_structure_epoch.is_none()
                || self.solid_only_tree_structure_epoch != nested_structure_epoch;
        }
        true
    }

    /// Allocate one artboard-tree cache using host-provided bytes for image
    /// assets whose serialized file contents are absent.
    ///
    /// External bytes are keyed by the semantic `FileAsset.assetId`. They are
    /// decoded here, at cache allocation time, so callers can discard a failed
    /// candidate cache and retry. Serialized `FileAssetContents` always wins.
    pub(crate) fn preallocate_for_artboard_tree_with_external_images(
        runtime: &RuntimeFile,
        instance: &ArtboardInstance,
        graph: &ArtboardGraph,
        artboards: &[ArtboardGraph],
        external_images: &BTreeMap<u32, Arc<[u8]>>,
        factory: &mut dyn RenderFactory,
        max_retained_decoded_image_bytes: Option<usize>,
    ) -> Self {
        preallocate_render_paint_cache_for_artboard_tree_internal(
            runtime,
            instance,
            graph,
            artboards,
            Some(external_images),
            factory,
            false,
            true,
            false,
            None,
            max_retained_decoded_image_bytes,
        )
    }

    #[cfg(test)]
    pub(crate) fn root_paints_mut(&mut self) -> &mut RuntimeRenderPaints {
        &mut self.paints
    }

    #[cfg(test)]
    pub(crate) fn root_image_assets(&self) -> &RuntimeImageAssetOwners {
        self.image_assets.as_ref()
    }

    pub(crate) fn image_decode_error(&self) -> Option<ImageDecodeError> {
        self.image_decode_error
    }
}

#[derive(Debug, Clone, PartialEq)]
struct RuntimeCachedRenderPaintConfiguration {
    instance_epoch: u128,
    configuration: RuntimeRenderPaintConfiguration,
}

#[derive(Default)]
struct RuntimePaintOwnerSlots {
    by_global: Vec<Option<RuntimeCachedRenderPaintConfiguration>>,
}

impl RuntimePaintOwnerSlots {
    fn get(&self, paint_global_id: u32) -> Option<&RuntimeCachedRenderPaintConfiguration> {
        self.by_global
            .get(paint_global_id as usize)
            .and_then(|configuration| configuration.as_ref())
    }

    fn is_current(&self, paint_global_id: u32, instance_epoch: u128) -> bool {
        self.get(paint_global_id)
            .is_some_and(|configuration| configuration.instance_epoch == instance_epoch)
    }

    fn get_mut(
        &mut self,
        paint_global_id: u32,
    ) -> Option<&mut RuntimeCachedRenderPaintConfiguration> {
        self.by_global.get_mut(paint_global_id as usize)?.as_mut()
    }

    fn insert(
        &mut self,
        paint_global_id: u32,
        configuration: RuntimeCachedRenderPaintConfiguration,
    ) {
        let slot = paint_global_id as usize;
        if self.by_global.len() <= slot {
            self.by_global.resize_with(slot + 1, || None);
        }
        self.by_global[slot] = Some(configuration);
    }

    fn remove(&mut self, paint_global_id: u32) {
        if let Some(configuration) = self.by_global.get_mut(paint_global_id as usize) {
            *configuration = None;
        }
    }
}

