fn preallocate_render_paint_cache_for_artboard_tree_internal(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    external_images: Option<&BTreeMap<u32, Arc<[u8]>>>,
    factory: &mut dyn RenderFactory,
    include_script_input_artboards: bool,
    allocate_source_paints: bool,
    scripting_file_assets: bool,
    file_registration: Option<&mut dyn FnMut(&mut dyn RenderFactory)>,
    max_retained_decoded_image_bytes: Option<usize>,
) -> RuntimeArtboardResourceBundle {
    // Import FileAssetContents once for the whole cache build. Looking up the
    // embedded payload independently for every image rescans the complete
    // object stream for each asset and turns a large valid file quadratic.
    let image_assets = RuntimeImageAssetCatalog::from_runtime(runtime);
    let pre_source_image_assets = pre_source_image_asset_globals(
        runtime,
        graph,
        artboards,
        &image_assets,
        scripting_file_assets,
    );
    let images = instance
        .runtime_image_assets
        .borrow()
        .as_ref()
        .map(Arc::clone)
        .unwrap_or_else(|| {
            Arc::new(RuntimeImageAssetOwners::with_max_retained_decoded_bytes(
                max_retained_decoded_image_bytes,
            ))
        });
    let mut image_decode_error = None;
    for asset_global in image_assets
        .globals
        .iter()
        .copied()
        .filter(|asset_global| pre_source_image_assets.contains(asset_global))
    {
        if image_decode_error.is_none() {
            image_decode_error = predecode_render_image(
                runtime,
                &image_assets,
                asset_global,
                external_images,
                factory,
                images.as_ref(),
            )
            .err();
        }
    }
    let _source_artboard_paints =
        allocate_source_paints.then(|| preallocate_render_paint_batch(runtime, factory));
    for asset_global in image_assets
        .globals
        .iter()
        .copied()
        .filter(|asset_global| !pre_source_image_assets.contains(asset_global))
    {
        if image_decode_error.is_none() {
            image_decode_error = predecode_render_image(
                runtime,
                &image_assets,
                asset_global,
                external_images,
                factory,
                images.as_ref(),
            )
            .err();
        }
    }
    // C++ resolves every source-artboard Mesh against the file-owned
    // ImageAsset before registering scripts or cloning an artboard
    // (`Mesh::onAssetLoaded`, src/shapes/mesh.cpp:101-150).
    mesh::preallocate_file_source_mesh_owners(
        runtime,
        artboards,
        factory,
        images.as_ref(),
        images.backend_context_id(),
    );
    if let Some(register_file_scripts) = file_registration {
        register_file_scripts(factory);
    }
    let mut cache = RuntimeArtboardResourceBundle::default();
    cache.image_assets = Arc::clone(&images);
    instance.attach_runtime_image_assets_tree(Arc::clone(&images));
    cache.requires_nested_layout_prepass =
        runtime_artboard_set_contains_nested_layout(graph, artboards);
    cache.paint_preparation_is_noop = runtime_artboard_paint_preparation_is_noop(graph);
    cache.paint_preparation_is_solid_only_tree =
        runtime_artboard_set_paint_preparation_is_solid_only(artboards);
    preallocate_artboard_instance_mesh_owner_tree(
        runtime,
        instance,
        graph,
        artboards,
        factory,
        &images,
        &mut BTreeSet::new(),
        include_script_input_artboards,
    );
    preallocate_artboard_render_paint_tree_batch_into(
        runtime,
        instance,
        graph,
        artboards,
        factory,
        &mut cache.paints,
        &mut BTreeSet::new(),
        include_script_input_artboards,
    );
    cache.image_decode_error = image_decode_error;
    cache
}

/// Allocates the render paints owned by a newly cloned artboard instance.
///
/// C++ `Artboard::instance()` clones each `ShapePaint` and initializes its
/// render paint from the file's existing factory. File-level source paints and
/// decoded assets are not recreated for every clone.
pub(crate) fn preallocate_render_paint_cache_for_artboard_instance(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    factory: &mut dyn RenderFactory,
) -> RuntimeArtboardResourceBundle {
    let mut cache = RuntimeArtboardResourceBundle::default();
    let image_assets = instance
        .runtime_image_assets
        .borrow()
        .as_ref()
        .map(Arc::clone)
        .unwrap_or_else(|| Arc::new(RuntimeImageAssetOwners::default()));
    cache.image_assets = Arc::clone(&image_assets);
    instance.attach_runtime_image_assets_tree(Arc::clone(&image_assets));
    cache.requires_nested_layout_prepass =
        runtime_artboard_set_contains_nested_layout(graph, artboards);
    cache.paint_preparation_is_noop = runtime_artboard_paint_preparation_is_noop(graph);
    cache.paint_preparation_is_solid_only_tree =
        runtime_artboard_set_paint_preparation_is_solid_only(artboards);
    preallocate_artboard_instance_mesh_owner_tree(
        runtime,
        instance,
        graph,
        artboards,
        factory,
        &image_assets,
        &mut BTreeSet::new(),
        true,
    );
    preallocate_artboard_render_paint_tree_batch_into(
        runtime,
        instance,
        graph,
        artboards,
        factory,
        &mut cache.paints,
        &mut BTreeSet::new(),
        true,
    );
    cache
}

/// Paint-only fallback for a graph reference that has no mounted artboard
/// occurrence. C++ cannot clone Mesh members without an Artboard instance
/// either; the mounted paths always use
/// `preallocate_render_paint_cache_for_artboard_instance`.
pub(crate) fn preallocate_render_paint_cache_for_unmounted_artboard(
    runtime: &RuntimeFile,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    factory: &mut dyn RenderFactory,
) -> RuntimeArtboardResourceBundle {
    let mut cache = RuntimeArtboardResourceBundle::default();
    cache.requires_nested_layout_prepass =
        runtime_artboard_set_contains_nested_layout(graph, artboards);
    cache.paint_preparation_is_noop = runtime_artboard_paint_preparation_is_noop(graph);
    cache.paint_preparation_is_solid_only_tree =
        runtime_artboard_set_paint_preparation_is_solid_only(artboards);
    preallocate_unmounted_artboard_render_paint_tree_batch_into(
        runtime,
        graph,
        artboards,
        factory,
        &mut cache,
        &mut BTreeSet::new(),
        true,
    );
    cache
}

fn runtime_artboard_set_contains_nested_layout(
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
) -> bool {
    graph
        .nested_artboards
        .iter()
        .chain(
            artboards
                .iter()
                .flat_map(|candidate| candidate.nested_artboards.iter()),
        )
        .any(|host| host.type_name == "NestedArtboardLayout")
}

fn runtime_artboard_paint_preparation_is_noop(graph: &ArtboardGraph) -> bool {
    graph.nested_artboards.is_empty()
        && graph.component_lists.is_empty()
        && graph
            .shape_paint_containers
            .iter()
            .flat_map(|container| container.paints.iter())
            .all(|paint| {
                !matches!(
                    paint.paint_state,
                    Some(
                        ShapePaintStateNode::LinearGradient { .. }
                            | ShapePaintStateNode::RadialGradient { .. }
                    )
                )
            })
}

fn runtime_artboard_set_paint_preparation_is_solid_only(artboards: &[ArtboardGraph]) -> bool {
    artboards.iter().all(|graph| {
        graph
            .shape_paint_containers
            .iter()
            .flat_map(|container| container.paints.iter())
            .all(|paint| {
                !matches!(
                    paint.paint_state,
                    Some(
                        ShapePaintStateNode::LinearGradient { .. }
                            | ShapePaintStateNode::RadialGradient { .. }
                    )
                )
            })
    })
}

fn pre_source_image_asset_globals(
    runtime: &RuntimeFile,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    image_assets: &RuntimeImageAssetCatalog<'_>,
    scripting_file_assets: bool,
) -> BTreeSet<u32> {
    let mut pre_source_assets =
        import_stack_pre_source_image_asset_globals(runtime, image_assets, scripting_file_assets)
            .into_iter()
            .collect::<BTreeSet<_>>();
    let heuristic_count =
        heuristic_pre_source_image_decode_count(graph, artboards, image_assets.globals.len());
    pre_source_assets.extend(image_assets.globals.iter().copied().take(heuristic_count));
    pre_source_assets
}

fn import_stack_pre_source_image_asset_globals(
    runtime: &RuntimeFile,
    image_assets: &RuntimeImageAssetCatalog<'_>,
    scripting_file_assets: bool,
) -> Vec<u32> {
    let mut pre_source_assets = Vec::new();
    let mut latest_image_asset = None;

    for object in runtime.objects.iter().flatten() {
        if object.type_name == "Artboard" {
            break;
        }
        if !runtime_object_uses_golden_file_asset_stack(object, scripting_file_assets) {
            continue;
        }

        if let Some(asset_global) = latest_image_asset.take()
            && image_assets.embedded_bytes(asset_global).is_some()
        {
            pre_source_assets.push(asset_global);
        }
        if object.type_name == "ImageAsset" {
            latest_image_asset = Some(object.id);
        }
    }

    pre_source_assets
}

fn runtime_object_uses_golden_file_asset_stack(
    object: &RuntimeObject,
    scripting_file_assets: bool,
) -> bool {
    matches!(
        object.type_name,
        "ImageAsset" | "FontAsset" | "AudioAsset" | "BlobAsset" | "ManifestAsset"
    ) || scripting_file_assets && matches!(object.type_name, "ScriptAsset" | "ShaderAsset")
}

fn heuristic_pre_source_image_decode_count(
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    image_asset_count: usize,
) -> usize {
    if image_asset_count == 0 {
        return 0;
    }

    if image_asset_count == 1 {
        // Mirrors the focused C++ ordering observed in spotify_kids_demo:
        // a text-bearing selected root with one image only in a sibling
        // artboard decodes before source paints, while feather_render_test
        // remains source-paint-first.
        let selected_has_direct_image = graph
            .sorted_drawable_order
            .iter()
            .any(|drawable| drawable.type_name == "Image");
        let selected_has_text = graph
            .local_objects
            .iter()
            .any(|object| object.type_name == Some("Text"));
        let image_is_only_in_non_selected_artboard = !selected_has_direct_image
            && selected_has_text
            && artboards.iter().any(|artboard| {
                artboard.global_id != graph.global_id
                    && artboard
                        .sorted_drawable_order
                        .iter()
                        .any(|drawable| drawable.type_name == "Image")
            });
        return usize::from(image_is_only_in_non_selected_artboard);
    }

    let has_asset_image_bind = artboards.iter().any(|artboard| {
        artboard.data_binds.iter().any(|data_bind| {
            data_bind.target_type_name == Some("Image")
                && runtime_draw_property_key_for_name("Image", "assetId")
                    .is_some_and(|key| data_bind.property_key == u64::from(key))
        })
    });
    let has_layout_component = artboards.iter().any(|artboard| {
        artboard
            .components
            .iter()
            .any(|component| component.type_name == "LayoutComponent")
    });
    if has_asset_image_bind && !has_layout_component {
        // Mirrors the C++ `FileAssetImporter` ordering for no-layout
        // asset-image data-context files: most embedded images resolve before
        // source paint allocation, while the final generated/private asset
        // resolution happens after source paints. The current corpus exposes
        // both plain scripted-property and nested-artboard variants.
        return image_asset_count.saturating_sub(1);
    }

    // Mirrors the C++ `src/importers/file_asset_importer.cpp` resolution
    // surface observed in asset-image-bound image/layout fixtures.
    let has_asset_image_layout = artboards.iter().any(|artboard| {
        let has_artboard_layout_component = artboard
            .components
            .iter()
            .any(|component| component.type_name == "LayoutComponent");
        if !has_artboard_layout_component {
            return false;
        }

        artboard.data_binds.iter().any(|data_bind| {
            data_bind.target_type_name == Some("Image")
                && runtime_draw_property_key_for_name("Image", "assetId")
                    .is_some_and(|key| data_bind.property_key == u64::from(key))
        })
    });
    if has_asset_image_layout {
        return image_asset_count.min(2);
    }

    // Ported from C++ `src/importers/file_asset_importer.cpp`: consecutive
    // embedded file assets resolve as each importer is displaced, while the
    // final file-asset importer resolves later when the import stack unwinds.
    image_asset_count.saturating_sub(1)
}

fn write_render_buffer_bytes(buffer: &mut dyn RenderBuffer, bytes: &[u8]) {
    let target = buffer.map_mut();
    debug_assert_eq!(target.len(), bytes.len());
    target.copy_from_slice(bytes);
    buffer.unmap();
}

fn push_f32_pair_bytes(bytes: &mut Vec<u8>, x: f32, y: f32) {
    bytes.extend_from_slice(&x.to_le_bytes());
    bytes.extend_from_slice(&y.to_le_bytes());
}

#[allow(clippy::too_many_arguments)]
fn preallocate_artboard_instance_mesh_owner_tree(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    factory: &mut dyn RenderFactory,
    image_assets: &Arc<RuntimeImageAssetOwners>,
    visiting: &mut BTreeSet<u32>,
    include_script_input_artboards: bool,
) {
    if !visiting.insert(graph.global_id) {
        return;
    }
    for mesh in &graph.meshes {
        let Some(owner) = instance.runtime_meshes.mesh(mesh.local_id) else {
            continue;
        };
        let Some(source) = image_assets.source_mesh(graph.global_id, mesh.local_id) else {
            continue;
        };
        *owner.shared.borrow_mut() = source;
        let backend_context_id = image_assets.backend_context_id();
        let vertex_byte_length = mesh.vertices.len().saturating_mul(8);
        let mut vertices = owner.vertices.borrow_mut();
        let must_allocate = vertices.as_ref().is_none_or(|(context_id, buffer)| {
            *context_id != backend_context_id || buffer.size_in_bytes() != vertex_byte_length
        });
        if must_allocate {
            *vertices = Some((
                backend_context_id,
                factory.make_render_buffer(
                    RenderBufferType::Vertex,
                    RenderBufferFlags::None,
                    vertex_byte_length,
                ),
            ));
            owner.vertex_render_buffer_dirty.set(true);
        }
    }

    for local_object in &graph.local_objects {
        if !include_script_input_artboards && local_object.type_name == Some("ScriptInputArtboard")
        {
            continue;
        }
        let Some(nested) = instance.nested_artboards.get(&local_object.local_id) else {
            continue;
        };
        let Some(child_graph) = nested.child.runtime_graph().or_else(|| {
            artboards
                .iter()
                .find(|candidate| candidate.global_id == nested.child.graph_global_id)
        }) else {
            continue;
        };
        preallocate_artboard_instance_mesh_owner_tree(
            runtime,
            nested.child.as_ref(),
            child_graph,
            artboards,
            factory,
            image_assets,
            visiting,
            include_script_input_artboards,
        );
    }

    visiting.remove(&graph.global_id);
}

fn preallocate_render_paint_batch(
    runtime: &RuntimeFile,
    factory: &mut dyn RenderFactory,
) -> RuntimeRenderPaints {
    let mut paints = RuntimeRenderPaints::default();
    let mut allocated = BTreeSet::new();
    for artboard_index in 0..runtime.artboards().len() {
        let Some(local_objects) = runtime.artboard_local_object_slots(artboard_index) else {
            continue;
        };
        for object in local_objects.iter().flatten() {
            if !matches!(
                object.type_name,
                "SolidColor" | "LinearGradient" | "RadialGradient"
            ) {
                continue;
            }
            let Some(paint_object) = object
                .uint_property("parentId")
                .and_then(|parent_local_id| usize::try_from(parent_local_id).ok())
                .and_then(|parent_local_id| local_objects.get(parent_local_id))
                .copied()
                .flatten()
            else {
                continue;
            };
            if !matches!(paint_object.type_name, "Fill" | "Stroke")
                || !allocated.insert(paint_object.id)
            {
                continue;
            }

            // Direct port of the source Artboard's onAddedDirty traversal. The
            // concrete mutator initializes its parent ShapePaint in object order:
            // ShapePaint allocates, Fill/Stroke applies constructor fields, and
            // SolidColor immediately applies color
            // (`artboard.cpp:264-288`, `shape_paint_mutator.cpp:7-25`,
            // `shape_paint.cpp:50-57`, `fill.cpp:13-17`,
            // `stroke.cpp:12-19`, `solid_color.cpp:9-21`).
            let mut render_paint = factory.make_render_paint();
            initialize_authored_shape_render_paint(
                render_paint.as_mut(),
                paint_object,
                Some(object),
            );
            paints.insert(paint_object.id, render_paint);
        }
    }
    paints
}

fn initialize_authored_shape_render_paint(
    render_paint: &mut dyn RenderPaint,
    paint_object: &RuntimeObject,
    mutator_object: Option<&RuntimeObject>,
) {
    match paint_object.type_name {
        "Fill" => render_paint.style(RenderPaintStyle::Fill),
        "Stroke" => {
            render_paint.style(RenderPaintStyle::Stroke);
            render_paint.thickness(paint_object.double_property("thickness").unwrap_or(1.0));
            render_paint.cap(
                runtime_stroke_cap(paint_object.uint_property("cap").unwrap_or(0))
                    .unwrap_or_default(),
            );
            render_paint.join(
                runtime_stroke_join(paint_object.uint_property("join").unwrap_or(0))
                    .unwrap_or_default(),
            );
        }
        _ => return,
    }
    if let Some(mutator) = mutator_object.filter(|mutator| mutator.type_name == "SolidColor") {
        render_paint.color(mutator.color_property("colorValue").unwrap_or(0xff00_0000));
    }
}

#[cfg(test)]
fn preallocate_artboard_render_paint_batch(
    runtime: &RuntimeFile,
    graph: &ArtboardGraph,
    factory: &mut dyn RenderFactory,
) -> RuntimeRenderPaints {
    let mut paints = RuntimeRenderPaints::default();
    let mut allocated = BTreeSet::new();
    let paint_by_mutator = graph
        .shape_paint_containers
        .iter()
        .flat_map(|container| container.paints.iter())
        .map(|paint| (paint.mutator_global, paint.global_id))
        .collect::<BTreeMap<_, _>>();

    for local_object in &graph.local_objects {
        if let Some(paint_global_id) = paint_by_mutator.get(&Some(local_object.global_id)) {
            preallocate_render_paint(*paint_global_id, factory, &mut paints, &mut allocated);
        }
    }

    for local_object in &graph.local_objects {
        let Some(object) = runtime.object(local_object.global_id as usize) else {
            continue;
        };
        if matches!(object.type_name, "Fill" | "Stroke") {
            preallocate_render_paint(object.id, factory, &mut paints, &mut allocated);
        }
    }
    paints
}

fn preallocate_artboard_render_paint_tree_batch_into(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    factory: &mut dyn RenderFactory,
    paints: &mut RuntimeRenderPaints,
    visiting: &mut BTreeSet<u32>,
    include_script_input_artboards: bool,
) {
    if !visiting.insert(graph.global_id) {
        return;
    }

    let mut allocated_for_instance = BTreeSet::new();
    let paint_by_mutator = graph
        .shape_paint_containers
        .iter()
        .flat_map(|container| container.paints.iter())
        .map(|paint| (paint.mutator_global, paint.global_id))
        .collect::<BTreeMap<_, _>>();

    for local_object in &graph.local_objects {
        if !include_script_input_artboards && local_object.type_name == Some("ScriptInputArtboard")
        {
            continue;
        }
        let Some(nested) = instance.nested_artboards.get(&local_object.local_id) else {
            continue;
        };
        let Some(child_graph) = nested.child.runtime_graph().or_else(|| {
            artboards
                .iter()
                .find(|candidate| candidate.global_id == nested.child.graph_global_id)
        }) else {
            continue;
        };
        // An artboard-valued bind can replace the authored child during the
        // clone's initial update. C++ has already constructed (and therefore
        // allocated backend members for) that authored occurrence before
        // `NestedArtboard::updateArtboard` drops it and mounts the live child
        // (`nested_artboard.cpp:88-135,228-373`). Our public factory arrives
        // later, at render-cache creation, so replay that retired construction
        // before materializing the authoritative mounted occurrence.
        if let Some(authored_graph) =
            referenced_artboard_graph_for_local_object(runtime, artboards, local_object.global_id)
            && authored_graph.global_id != child_graph.global_id
        {
            let mut retired_cache = Default::default();
            preallocate_unmounted_artboard_render_paint_tree_batch_into(
                runtime,
                authored_graph,
                artboards,
                factory,
                &mut retired_cache,
                visiting,
                include_script_input_artboards,
            );
        }
        let mut resources = nested.child.render_resources.borrow_mut();
        resources.reset_for_parent_backend_context(paints.backend_context_id);
        preallocate_artboard_render_paint_tree_batch_into(
            runtime,
            nested.child.as_ref(),
            child_graph,
            artboards,
            factory,
            &mut resources.paints,
            visiting,
            include_script_input_artboards,
        );
        resources.initialized = true;
    }

    for local_object in &graph.local_objects {
        if let Some(paint_global_id) = paint_by_mutator.get(&Some(local_object.global_id)) {
            preallocate_render_paint_for_mounted_instance(
                runtime,
                instance,
                graph,
                *paint_global_id,
                Some(local_object.global_id),
                factory,
                paints,
                &mut allocated_for_instance,
            );
        }
    }

    for local_object in &graph.local_objects {
        let Some(object) = runtime.object(local_object.global_id as usize) else {
            continue;
        };
        if matches!(object.type_name, "Fill" | "Stroke") {
            preallocate_render_paint_for_mounted_instance(
                runtime,
                instance,
                graph,
                object.id,
                None,
                factory,
                paints,
                &mut allocated_for_instance,
            );
        }
    }

    visiting.remove(&graph.global_id);
}

fn preallocate_unmounted_artboard_render_paint_tree_batch_into(
    runtime: &RuntimeFile,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    factory: &mut dyn RenderFactory,
    cache: &mut RuntimeArtboardResourceBundle,
    visiting: &mut BTreeSet<u32>,
    include_script_input_artboards: bool,
) {
    if !visiting.insert(graph.global_id) {
        return;
    }

    let mut allocated_for_instance = BTreeSet::new();
    let paint_by_mutator = graph
        .shape_paint_containers
        .iter()
        .flat_map(|container| container.paints.iter())
        .map(|paint| (paint.mutator_global, paint.global_id))
        .collect::<BTreeMap<_, _>>();

    for local_object in &graph.local_objects {
        if !include_script_input_artboards && local_object.type_name == Some("ScriptInputArtboard")
        {
            continue;
        }
        if let Some(child_graph) =
            referenced_artboard_graph_for_local_object(runtime, artboards, local_object.global_id)
        {
            let cache_key = nested_render_cache_key(
                Some(local_object.global_id),
                Some(local_object.local_id),
                child_graph.global_id,
                0,
            );
            let child_cache = cache.nested_artboards.entry(cache_key).or_default();
            preallocate_unmounted_artboard_render_paint_tree_batch_into(
                runtime,
                child_graph,
                artboards,
                factory,
                child_cache,
                visiting,
                include_script_input_artboards,
            );
        }
    }

    for local_object in &graph.local_objects {
        if let Some(paint_global_id) = paint_by_mutator.get(&Some(local_object.global_id)) {
            preallocate_render_paint_for_instance(
                runtime,
                *paint_global_id,
                Some(local_object.global_id),
                factory,
                &mut cache.paints,
                &mut allocated_for_instance,
            );
        }
    }
    for local_object in &graph.local_objects {
        let Some(object) = runtime.object(local_object.global_id as usize) else {
            continue;
        };
        if matches!(object.type_name, "Fill" | "Stroke") {
            preallocate_render_paint_for_instance(
                runtime,
                object.id,
                None,
                factory,
                &mut cache.paints,
                &mut allocated_for_instance,
            );
        }
    }
    visiting.remove(&graph.global_id);
}

fn referenced_artboard_graph_for_local_object<'a>(
    runtime: &RuntimeFile,
    artboards: &'a [ArtboardGraph],
    global_id: u32,
) -> Option<&'a ArtboardGraph> {
    let object = runtime.object(global_id as usize)?;
    let referenced = runtime.resolved_artboard_for_referencer_object(object)?;
    artboards
        .iter()
        .find(|graph| graph.global_id == referenced.id)
}

fn nested_render_cache_key(
    global_id: Option<u32>,
    local_id: Option<usize>,
    referenced_artboard_global: u32,
    instance_revision: u64,
) -> RuntimeNestedRenderCacheKey {
    let host = global_id
        .or_else(|| local_id.and_then(|local_id| u32::try_from(local_id).ok()))
        .unwrap_or(referenced_artboard_global);
    RuntimeNestedRenderCacheKey {
        host,
        referenced_artboard_global,
        instance_revision,
    }
}

fn component_list_render_cache_key(
    global_id: Option<u32>,
    local_id: Option<usize>,
    referenced_artboard_global: u32,
    _item_index: usize,
    instance_revision: u64,
) -> RuntimeNestedRenderCacheKey {
    let mut key = nested_render_cache_key(
        global_id,
        local_id,
        referenced_artboard_global,
        instance_revision,
    );
    // C++ retains an artboard (and therefore its render resources) by the
    // ViewModelInstanceListItem wrapper identity. A logical index is mutable:
    // removing or reordering a preceding row must not make every surviving
    // occurrence look like a fresh artboard. `instance_revision` is the
    // wrapper occurrence identity and is already unique for duplicate VMI
    // entries, so keep the component-list namespace bit but not the index.
    key.instance_revision = RUNTIME_COMPONENT_LIST_CACHE_NAMESPACE | instance_revision;
    key
}

#[cfg(test)]
fn preallocate_render_paint(
    global_id: u32,
    factory: &mut dyn RenderFactory,
    paints: &mut RuntimeRenderPaints,
    allocated: &mut BTreeSet<u32>,
) {
    if allocated.insert(global_id) {
        paints.insert(global_id, factory.make_render_paint());
    }
}

fn preallocate_render_paint_for_instance(
    runtime: &RuntimeFile,
    global_id: u32,
    mutator_global_id: Option<u32>,
    factory: &mut dyn RenderFactory,
    paints: &mut RuntimeRenderPaints,
    allocated_for_instance: &mut BTreeSet<u32>,
) {
    if !allocated_for_instance.insert(global_id) {
        return;
    }

    let mut render_paint = factory.make_render_paint();
    if let Some(paint_object) = runtime.object(global_id as usize) {
        let mutator_object =
            mutator_global_id.and_then(|mutator_global| runtime.object(mutator_global as usize));
        // Artboard::instance() re-runs the same onAddedDirty traversal over the
        // clone. Initialize this concrete occurrence before the next mutator
        // allocates its paint; later owner realization only settles live values
        // onto this retained backend object.
        initialize_authored_shape_render_paint(render_paint.as_mut(), paint_object, mutator_object);
    }
    if !paints.contains(global_id) {
        paints.insert(global_id, render_paint);
    }
}

/// Allocate the cloned ShapePaint backend directly into its live occurrence.
/// TextStylePaint inherits ShapePaint's one `m_renderPaint`; it must never
/// enter the parallel global paint cache and later be rediscovered by id
/// (`shape_paint.cpp:50-57`, `text_style_paint.cpp:13-19`).
#[allow(clippy::too_many_arguments)]
fn preallocate_render_paint_for_mounted_instance(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    global_id: u32,
    mutator_global_id: Option<u32>,
    factory: &mut dyn RenderFactory,
    paints: &mut RuntimeRenderPaints,
    allocated_for_instance: &mut BTreeSet<u32>,
) {
    if !allocated_for_instance.insert(global_id) {
        return;
    }

    let mut render_paint = factory.make_render_paint();
    if let Some(paint_object) = runtime.object(global_id as usize) {
        let mutator_object =
            mutator_global_id.and_then(|mutator_global| runtime.object(mutator_global as usize));
        initialize_authored_shape_render_paint(render_paint.as_mut(), paint_object, mutator_object);
    }

    let text_owner = graph
        .shape_paint_containers
        .iter()
        .filter(|container| {
            crate::shapes::shape_paint_container::family(container.type_name)
                .is_some_and(|family| family.owns_text_paint())
        })
        .find_map(|container| {
            let owner_index = container
                .paints
                .iter()
                .position(|paint| paint.global_id == global_id)?;
            instance
                .runtime_shapes
                .get(container.local_id)?
                .paint_owners
                .get(owner_index)
        });
    if let Some(owner) = text_owner {
        let mut backend = owner.backend.value.borrow_mut();
        if backend.context_id != Some(paints.backend_context_id) {
            *backend = RuntimePaintBackendState {
                context_id: Some(paints.backend_context_id),
                ..RuntimePaintBackendState::default()
            };
        }
        backend.paint = Some(render_paint);
        return;
    }

    if !paints.contains(global_id) {
        paints.insert(global_id, render_paint);
    }
}

/// Direct port of the Artboard ShapePaint loop in
/// `Artboard::drawInternal` (`src/artboard.cpp:1630-1650`). The Artboard owns
/// both its ordered paints and the paths selected by each paint. Clean draws
/// only read those retained owners.
fn runtime_draw_live_owned_artboard_paints(
    instance: &ArtboardInstance,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    backend_context_id: u64,
) -> Result<()> {
    let artboard_local = 0;
    let Some(artboard) = instance.runtime_shapes.get(artboard_local) else {
        return Ok(());
    };
    let shape_world = instance
        .component(artboard_local)
        .map_or(Mat2D::IDENTITY, |component| {
            component.transform.world_transform
        });
    for owner in &artboard.paint_owners {
        if !runtime_owned_shape_paint_is_visible(instance, owner)
            || !runtime_shape_paint_state_is_visible(&owner.paint_state.borrow())
        {
            continue;
        }
        let path_kind = runtime_live_owned_shape_paint_path_kind(instance, owner);
        // LayoutComponent::localClockwisePath returns the exact same
        // ShapePaintPath owner as localPath; Artboard inherits that contract
        // (`layout_component.cpp:1569-1571`). Keep the shared backend owner,
        // not merely shared geometry, so an even-odd/background fill followed
        // by a clockwise inner-feather clip reuses the same RenderPath just
        // like C++ (RF-2/RF-5/RF-17).
        let owner_path_kind = if path_kind == RuntimeShapePaintPathKind::LocalClockwise {
            RuntimeShapePaintPathKind::Local
        } else {
            path_kind
        };
        let Some(path) = instance
            .runtime_shapes
            .paint_path_owner(artboard_local, owner_path_kind)
        else {
            continue;
        };
        crate::shapes::paint::shape_paint::runtime_draw_live_owned_shape_paint(
            instance,
            shape_world,
            owner,
            path,
            path_kind,
            true,
            backend_context_id,
            factory,
            renderer,
        )?;
    }
    Ok(())
}

fn runtime_prepare_gradient_paint_command(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    render_opacity: f32,
    container: &ShapePaintContainerNode,
    paint: &ShapePaintNode,
    shape_world: Mat2D,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
) -> RuntimeShapePaintCommand {
    let path_kind = runtime_live_shape_paint_path_kind(instance, paint)
        .unwrap_or(RuntimeShapePaintPathKind::Local);
    let paint_state = runtime_deform_gradient_paint_state_with_nsliced_node(
        instance,
        graph,
        container,
        layout_bounds,
        shape_world,
        runtime_shape_paint_state(instance, paint, render_opacity),
    );
    RuntimeShapePaintCommand {
        paint_local: paint.local_id,
        paint_global_id: paint.global_id,
        mutator_local: paint.mutator_local,
        paint_type: runtime_shape_paint_kind(paint.paint_type),
        fill_rule: runtime_live_shape_paint_fill_rule(instance, paint),
        path_kind,
        path_slot_index: 0,
        clip_path_slot_index: 0,
        blend_mode_value: paint.blend_mode_value,
        render_blend_mode_value: runtime_shape_paint_blend_mode_value(
            paint.blend_mode_value,
            container.blend_mode_value,
        ),
        render_opacity,
        paint_state,
        feather_state: None,
        paint_space_transform: runtime_shape_paint_space_transform(path_kind, shape_world),
        path_commands: Vec::new(),
        effect_path_commands: Vec::new(),
        has_effect_path: false,
        needs_save_operation: false,
        shape_world_override: None,
        aliases_local_clockwise_path: false,
        uses_temporary_paint: false,
        text_path_bucket_slot: None,
        text_path_bucket_opacity: None,
        text_paint_ref: None,
        text_paint_pool: None,
        ensure_text_paint_pool_after_draw: None,
    }
}

fn runtime_shape_paint_container_world_transform(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    container: &ShapePaintContainerNode,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    path_cache: &mut RuntimeArtboardPathState,
) -> Mat2D {
    match container.type_name {
        "LayoutComponent" => path_cache.component_world_transform_with_bounds(
            instance,
            graph,
            container.local_id,
            layout_bounds,
        ),
        "ForegroundLayoutDrawable" => {
            let layout_local = instance
                .component_parent_local(container.local_id)
                .filter(|parent_local| {
                    instance
                        .component(*parent_local)
                        .is_some_and(|component| component.type_name == "LayoutComponent")
                })
                .unwrap_or(container.local_id);
            path_cache.component_world_transform_with_bounds(
                instance,
                graph,
                layout_local,
                layout_bounds,
            )
        }
        _ => path_cache.component_world_transform_with_bounds(
            instance,
            graph,
            container.local_id,
            layout_bounds,
        ),
    }
}

#[inline]
fn runtime_text_paint_shape_world(
    draws_text: bool,
    shape_world_override: Option<Mat2D>,
    live_shape_world: Mat2D,
) -> Option<Mat2D> {
    draws_text.then(|| shape_world_override.unwrap_or(live_shape_world))
}

fn runtime_text_style_path_owner_local(paint: &RuntimeShapePaintCommand) -> Option<usize> {
    paint
        .text_paint_pool
        .map(|pool| pool.spec.style_local)
        .or_else(|| {
            paint
                .ensure_text_paint_pool_after_draw
                .map(|pool| pool.style_local)
        })
}

fn runtime_retained_text_draw_frame(
    _runtime: &RuntimeFile,
    _instance: &ArtboardInstance,
    _graph: &ArtboardGraph,
    drawable: &RuntimeDrawable,
    _layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
) -> Result<RuntimeCachedTextShapePaints> {
    let owner = drawable
        .text_draw_owner
        .as_ref()
        .context("live text drawable is missing its retained owner")?;
    owner.retained_frame().with_context(|| {
        format!(
            "{} local {} retained owner",
            drawable.type_name,
            drawable.local_id.unwrap_or(usize::MAX)
        )
    })
}

fn runtime_build_text_draw_frame(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    drawable: &RuntimeDrawable,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
) -> Result<RuntimeCachedTextShapePaints> {
    let drawable_local = drawable
        .local_id
        .context("live text drawable is missing its local id")?;
    if drawable.type_name == "Text" {
        let has_authored_run = graph
            .components
            .iter()
            .find(|component| component.local_id == drawable_local)
            .is_some_and(|text| {
                text.children.iter().any(|child_local| {
                    graph.local_objects.iter().any(|object| {
                        object.local_id == *child_local && object.type_name == Some("TextValueRun")
                    })
                })
            });
        let text_run_list_source_key = property_key_for_name("Text", "textRunListSource");
        let has_run_list_source = graph.data_binds.iter().any(|data_bind| {
            data_bind.target_local == Some(drawable_local)
                && data_bind.target_type_name == Some("Text")
                && u16::try_from(data_bind.property_key).ok() == text_run_list_source_key
        });
        if !has_authored_run && !has_run_list_source {
            // C++ `Text::buildRenderStyles` clears its retained styles and
            // publishes zero bounds when shaping has no runs. This is still a
            // successful update-phase rebuild, not an owner left dirty for a
            // later draw (`text.cpp:534-543`).
            if let Some(text) = instance
                .component(drawable_local)
                .and_then(|component| component.concrete.text.as_ref())
            {
                text.retain_bounds(
                    static_fixed_text_constraint_bounds(
                        runtime,
                        graph,
                        instance,
                        drawable_local,
                        instance.runtime_text_layout_constraint(drawable_local, layout_bounds),
                    )
                    .unwrap_or((0.0, 0.0, 0.0, 0.0)),
                );
            }
            return Ok(RuntimeCachedTextShapePaints {
                commands: Arc::new(Vec::new()),
                replay: Arc::new(Vec::new()),
                paths: Arc::new(BTreeMap::new()),
                clip_path: None,
                clip_bounds: None,
                color: None,
                shape_local_transform: Mat2D::IDENTITY,
                publishes_layout_dirty: false,
            });
        }
    }
    let topology = if drawable.type_name == "Text" {
        Some(
            drawable
                .text_draw_owner
                .as_ref()
                .context("live Text is missing its retained owner")?
                .topology_or_build(|| {
                    StaticTextSlice::from_graph(runtime, graph, drawable_local)
                })?,
        )
    } else {
        None
    };
    let (mut commands, clip_bounds, color, shape_local_transform) = if drawable.type_name == "Text"
    {
        let layout_constraint =
            instance.runtime_text_layout_constraint(drawable_local, layout_bounds);
        let topology = topology
            .as_deref()
            .context("live Text did not retain its imported topology")?;
        let owner = drawable
            .text_draw_owner
            .as_ref()
            .context("live Text is missing its retained owner")?;
        let text_world = instance.runtime_component_world_transform_with_bounds(
            drawable_local,
            graph,
            layout_bounds,
        );
        let shaped_topology = owner.shaped_topology_or_build(|| {
            topology.render_topology(runtime, instance, layout_constraint, text_world)
        })?;
        let draw_data = runtime_text_draw_data_from_retained_topology(
            topology,
            runtime,
            instance,
            graph,
            drawable_local,
            layout_bounds,
            layout_constraint,
            shaped_topology.as_deref(),
        )?;
        let shape_local_transform = draw_data.local_transform;
        (
            draw_data.commands,
            topology.clip_bounds(runtime, instance, layout_constraint)?,
            (!draw_data.color_glyphs.is_empty()).then(|| {
                Arc::new(RuntimeRetainedColorGlyphs {
                    glyphs: draw_data.color_glyphs,
                    order: draw_data.order,
                    shape_world: draw_data.shape_world,
                })
            }),
            shape_local_transform,
        )
    } else {
        (
            runtime_text_input_shape_paint_commands(
                runtime,
                instance,
                graph,
                drawable_local,
                layout_bounds,
            )?,
            None,
            None,
            Mat2D::IDENTITY,
        )
    };
    assign_shape_paint_path_slot_indices(&mut commands);
    let replay = runtime_text_replay_order(&commands, color.as_deref());
    let paths = Arc::new(runtime_text_owned_raw_paths(&commands));
    let clip_path = clip_bounds
        // C++ `Text::buildRenderStyles` returns before rebuilding
        // `m_clipRect` when shaping produced no renderable frame
        // (`src/text/text.cpp:534-543`).
        .filter(|_| !commands.is_empty() || color.is_some())
        .map(|bounds| {
            let world = instance.runtime_component_world_transform_with_bounds(
                drawable_local,
                graph,
                layout_bounds,
            );
            Arc::new(runtime_raw_path_from_commands(
                &runtime_text_clip_path_commands(bounds, world),
            ))
        });
    if drawable.type_name == "Text"
        && let Some(bounds) = build_static_text_constraint_bounds_from_slice(
            topology
                .as_deref()
                .expect("Text topology is retained before bounds publication"),
            runtime,
            graph,
            instance,
            drawable_local,
            instance.runtime_text_layout_constraint(drawable_local, layout_bounds),
        )
        && let Some(text) = instance
            .component(drawable_local)
            .and_then(|component| component.concrete.text.as_ref())
    {
        text.retain_bounds(bounds);
    }
    Ok(RuntimeCachedTextShapePaints {
        commands: Arc::new(commands),
        replay: Arc::new(replay),
        paths,
        clip_path,
        clip_bounds,
        color,
        shape_local_transform,
        publishes_layout_dirty: true,
    })
}

fn runtime_text_replay_order(
    commands: &[RuntimeShapePaintCommand],
    color: Option<&RuntimeRetainedColorGlyphs>,
) -> Vec<RuntimeTextReplay> {
    let Some(color) = color else {
        return (0..commands.len()).map(RuntimeTextReplay::Paint).collect();
    };
    let mut replay = Vec::with_capacity(commands.len() + color.glyphs.len());
    let mut ordered_styles = BTreeSet::new();
    for item in &color.order {
        match *item {
            RuntimeTextDrawOrder::Style(style_local) => {
                ordered_styles.insert(style_local);
                replay.extend(
                    commands
                        .iter()
                        .enumerate()
                        .filter(|(_, paint)| {
                            runtime_text_style_path_owner_local(paint) == Some(style_local)
                        })
                        .map(|(index, _)| RuntimeTextReplay::Paint(index)),
                );
            }
            RuntimeTextDrawOrder::ColorGlyph(index) => {
                if color.glyphs.get(index).is_some() {
                    replay.push(RuntimeTextReplay::ColorGlyph(index));
                }
            }
        }
    }
    replay.extend(
        commands
            .iter()
            .enumerate()
            .filter(|(_, paint)| {
                runtime_text_style_path_owner_local(paint)
                    .is_none_or(|style| !ordered_styles.contains(&style))
            })
            .map(|(index, _)| RuntimeTextReplay::Paint(index)),
    );
    replay
}

impl ArtboardInstance {
    /// Build the live current-frame box observed by C++ `Node::localBounds`.
    ///
    /// D3 Taffy adapter: Rust's horizontal fill result excludes the layout
    /// component's own padding, while Rive's Yoga-backed
    /// `LayoutComponent::layoutWidth` includes it. Reinsert that horizontal
    /// padding to reconstruct the box passed to the otherwise literal
    /// `SemanticProvider::semanticBounds` port.
    pub(crate) fn semantic_layout_world_bounds(
        &self,
        local_id: usize,
    ) -> Option<(f32, f32, f32, f32)> {
        const LAYOUT_SCALE_TYPE_FILL: u64 = 1;

        let component = self.component(local_id)?;
        if component.type_name != "LayoutComponent" {
            return None;
        }
        let (_, _, width, height) = component.concrete.layout.as_ref()?.current_bounds();
        let style_local = self.runtime_layout_component_style_local(local_id)?;
        let mut min_x = 0.0;
        let mut max_x = width;
        if self.runtime_layout_axis_scale(style_local, true) == LAYOUT_SCALE_TYPE_FILL {
            let padding_left = self.runtime_layout_style_length(
                style_local,
                RuntimeLayoutStyleProperty::PaddingLeft,
                RuntimeLayoutStyleProperty::PaddingLeftUnitsValue,
                width,
            )?;
            let padding_right = self.runtime_layout_style_length(
                style_local,
                RuntimeLayoutStyleProperty::PaddingRight,
                RuntimeLayoutStyleProperty::PaddingRightUnitsValue,
                width,
            )?;
            min_x -= padding_left;
            max_x += padding_left + padding_right;
        }
        let bounds = runtime_transformed_rect_bounds(
            (min_x, 0.0, max_x, height),
            component.transform.world_transform,
        );
        Some((bounds.min_x, bounds.min_y, bounds.max_x, bounds.max_y))
    }

    /// Direct update-phase counterpart of C++ `Text::buildRenderStyles`.
    /// Drawing only consumes this retained result.
    pub(crate) fn update_runtime_text_render_styles(
        &self,
        local_id: usize,
        dirt: ComponentDirt,
        graph: &ArtboardGraph,
        layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    ) -> bool {
        if (dirt
            & (ComponentDirt::TEXT_SHAPE
                | ComponentDirt::PAINT
                | ComponentDirt::WORLD_TRANSFORM
                | ComponentDirt::RENDER_OPACITY))
            .is_empty()
        {
            return false;
        }
        let Some(type_name) = self
            .component(local_id)
            .map(|component| component.type_name)
        else {
            return false;
        };
        let target_locals = if type_name == "TextInput" {
            graph
                .components
                .iter()
                .filter(|component| component.parent_local == Some(local_id))
                .filter(|component| is_text_input_drawable_type(component.type_name))
                .map(|component| component.local_id)
                .collect::<Vec<_>>()
        } else if type_name == "Text" || is_text_input_drawable_type(type_name) {
            vec![local_id]
        } else {
            return false;
        };
        let Some(runtime) = self.runtime_file() else {
            return false;
        };
        let mut publishes_layout_dirty = false;
        for target_local in target_locals {
            let Some(drawable_index) = self
                .runtime_drawables
                .drawable_by_local
                .get(&target_local)
                .copied()
            else {
                continue;
            };
            let drawable = self.runtime_drawables.drawables[drawable_index].as_ref();
            let Some(owner) = drawable.text_draw_owner.as_ref() else {
                continue;
            };
            let rebuild_dirt = dirt & (ComponentDirt::TEXT_SHAPE | ComponentDirt::PAINT);
            if rebuild_dirt.is_empty() && dirt.contains(ComponentDirt::RENDER_OPACITY) {
                // C++ `Text::update(RenderOpacity)` only calls
                // `TextStylePaint::propagateOpacity`; shaped paragraphs,
                // lines, draw commands, and render paths remain retained.
                // Refresh the command-side opacity used by Rust's pooled
                // paints without reconstructing glyph topology or geometry.
                owner.propagate_render_opacity(self, graph, target_local);
            }
            if rebuild_dirt.is_empty()
                && dirt.contains(ComponentDirt::WORLD_TRANSFORM)
                && drawable.type_name == "Text"
            {
                // C++ updates m_shapeWorldTransform and m_clipPath after the
                // shape/paint branch. Preserve shaped glyph topology and the
                // retained backend objects while refreshing world-space
                // command and clip data.
                owner.propagate_world_transform(self, graph, target_local, layout_bounds);
            }
            if rebuild_dirt.is_empty()
                && (!dirt.contains(ComponentDirt::WORLD_TRANSFORM) || drawable.type_name == "Text")
            {
                continue;
            }
            if dirt.contains(ComponentDirt::TEXT_SHAPE) {
                // C++ Path dirt replaces `m_shape`/`m_lines`, then rebuilds
                // render styles from the new shaped topology.
                owner.mark_shape_dirty_unless_paths_retained();
            } else if dirt.contains(ComponentDirt::PAINT) {
                // C++ Paint dirt rebuilds positioning, modifiers, transforms,
                // and style paths from retained `m_shape`/`m_lines`.
                owner.mark_render_styles_dirty_unless_paths_retained();
            } else {
                owner.mark_dirty();
            }
            let rebuilt = owner
                .rebuild(|| {
                    runtime_build_text_draw_frame(runtime, self, graph, drawable, layout_bounds)
                })
                .unwrap_or(false);
            publishes_layout_dirty |= rebuilt
                && owner
                    .retained
                    .borrow()
                    .as_ref()
                    .is_some_and(|frame| frame.publishes_layout_dirty);
        }
        publishes_layout_dirty
    }

    /// Borrow the immutable topology retained by this concrete Text
    /// occurrence, materializing it once from the imported graph if needed.
    ///
    /// C++ `Text::measure` reads `m_allRuns`, `m_textStylePaints`, and
    /// `m_modifierGroups` from the cloned Text object. Yoga may invoke measure
    /// repeatedly while settling nested hug layouts; rebuilding those imported
    /// collections for every callback is not part of the upstream lifecycle.
    pub(crate) fn retained_static_text_topology(
        &self,
        runtime: &RuntimeFile,
        graph: &ArtboardGraph,
        text_local: usize,
    ) -> Option<Arc<StaticTextSlice>> {
        let drawable_index = self
            .runtime_drawables
            .drawable_by_local
            .get(&text_local)
            .copied()?;
        let owner = self.runtime_drawables.drawables[drawable_index]
            .text_draw_owner
            .as_ref()?;
        owner
            .topology_or_build(|| StaticTextSlice::from_graph(runtime, graph, text_local))
            .ok()
    }
}

fn runtime_text_backend_path<'a>(
    slot: &'a mut Option<RuntimeTextPathBackend>,
    factory: &mut dyn RenderFactory,
    raw_path: &RawPath,
    fill_rule: RenderFillRule,
) -> &'a dyn RenderPath {
    let backend = slot.get_or_insert_with(|| RuntimeTextPathBackend {
        path: runtime_make_path_from_raw_path(factory, raw_path, fill_rule),
        raw_mutation_id: raw_path.mutation_id(),
    });
    if backend.raw_mutation_id != raw_path.mutation_id() {
        runtime_rebuild_path_from_raw_path(backend.path.as_mut(), raw_path, fill_rule);
        backend.raw_mutation_id = raw_path.mutation_id();
    } else {
        backend.path.fill_rule(fill_rule);
    }
    backend.path.as_ref()
}

fn runtime_configure_text_pooled_paint(
    backend: &mut RuntimeTextPooledPaintBackend,
    authored_shader: Option<&dyn RenderShader>,
    instance: &ArtboardInstance,
    object: &RuntimeObject,
    paint: &RuntimeShapePaintCommand,
) -> Result<()> {
    let instance_epoch = runtime_paint_configuration_epoch(instance, paint);
    if backend
        .configuration
        .as_ref()
        .is_some_and(|cached| cached.instance_epoch == instance_epoch)
    {
        return Ok(());
    }
    let configuration = runtime_render_paint_configuration(instance, object, paint)?;
    if backend
        .configuration
        .as_ref()
        .is_none_or(|cached| cached.configuration != configuration)
    {
        runtime_configure_paint(backend.paint.as_mut(), instance, object, paint, None)?;
    }
    backend.paint.shader(authored_shader);
    backend.configuration = Some(RuntimeCachedRenderPaintConfiguration {
        instance_epoch,
        configuration,
    });
    Ok(())
}

/// Direct port of C++ `Text::draw`, `TextStylePaint::draw`, and
/// `TextInputDrawable::draw` (`src/text/text.cpp:845-875`,
/// `src/text/text_style_paint.cpp:42-127`,
/// `src/text/text_input_drawable.cpp:24-41`). Each drawable owns its retained
/// CPU draw frame; this path never constructs a `RuntimeDrawableDispatch`.
fn runtime_draw_integrated_color_glyph(
    glyph_index: usize,
    command: &RuntimeIntegratedColorGlyphCommand,
    shape_world: Mat2D,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    color_paths: &mut BTreeMap<(usize, usize), RuntimeTextPathBackend>,
    emoji_images: &mut BTreeMap<(usize, u32), Option<Box<dyn RenderImage>>>,
) {
    renderer.save();
    renderer.transform(runtime_render_mat(shape_world.multiply(command.transform)));
    for (layer_index, layer) in command.layers.iter().enumerate() {
        match &layer.paint {
            crate::text::RuntimeColorGlyphPaint::Image {
                bytes,
                width,
                height,
                bearing_x,
                bearing_y,
                extent_x,
                extent_y,
            } => {
                let image = emoji_images
                    .entry((command.font_identity, command.glyph_id))
                    .or_insert_with(|| factory.decode_image(bytes).ok());
                if let Some(image) = image.as_deref() {
                    renderer.save();
                    renderer.transform(runtime_render_mat(Mat2D([
                        *extent_x / *width as f32,
                        0.0,
                        0.0,
                        *extent_y / *height as f32,
                        *bearing_x,
                        *bearing_y,
                    ])));
                    renderer.draw_image(
                        Some(image),
                        RenderImageSampler::LINEAR_CLAMP,
                        RenderBlendMode::SrcOver,
                        command.opacity,
                    );
                    renderer.restore();
                }
            }
            paint_kind @ (crate::text::RuntimeColorGlyphPaint::Solid { .. }
            | crate::text::RuntimeColorGlyphPaint::LinearGradient { .. }
            | crate::text::RuntimeColorGlyphPaint::RadialGradient { .. }
            | crate::text::RuntimeColorGlyphPaint::SweepGradient { .. }) => {
                if layer.path.verbs().is_empty() {
                    continue;
                }
                let color = match paint_kind {
                    crate::text::RuntimeColorGlyphPaint::Solid { color } => *color,
                    _ => 0xff00_0000,
                };
                let path_backend = color_paths
                    .entry((glyph_index, layer_index))
                    .or_insert_with(|| RuntimeTextPathBackend {
                        path: runtime_make_path_from_raw_path(
                            factory,
                            &layer.path,
                            RenderFillRule::NonZero,
                        ),
                        raw_mutation_id: layer.path.mutation_id(),
                    });
                if path_backend.raw_mutation_id != layer.path.mutation_id() {
                    runtime_rebuild_path_from_raw_path(
                        path_backend.path.as_mut(),
                        &layer.path,
                        RenderFillRule::NonZero,
                    );
                    path_backend.raw_mutation_id = layer.path.mutation_id();
                }
                let mut paint = factory.make_render_paint();
                paint.style(RenderPaintStyle::Fill);
                paint.color(color_modulate_opacity(color, command.opacity));
                renderer.draw_path(path_backend.path.as_ref(), paint.as_ref());
            }
        }
    }
    renderer.restore();
}

#[allow(clippy::too_many_arguments)]
fn runtime_draw_live_text_family(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    drawable: &RuntimeDrawable,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    path_cache: &mut RuntimeArtboardPathState,
    _paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
) -> Result<()> {
    let drawable_local = drawable
        .local_id
        .context("live text drawable is missing its local id")?;
    let retained =
        runtime_retained_text_draw_frame(runtime, instance, graph, drawable, layout_bounds)?;

    let is_text = drawable.type_name == "Text";
    let live_world = path_cache.component_world_transform_with_bounds(
        instance,
        graph,
        drawable_local,
        layout_bounds,
    );
    let needs_outer_save =
        is_text && (drawable.needs_save_operation || retained.clip_path.is_some());
    if needs_outer_save {
        renderer.save();
    }
    let owner = drawable
        .text_draw_owner
        .as_ref()
        .context("live text drawable is missing its retained owner")?;
    let backend_context_id = paint_by_global.backend_context_id;
    let mut backend = owner.backend.borrow_mut();
    if backend.context_id != Some(backend_context_id) {
        *backend = RuntimeTextBackendResources {
            context_id: Some(backend_context_id),
            ..RuntimeTextBackendResources::default()
        };
    }
    if let Some(raw_path) = retained.clip_path.as_deref() {
        let path = runtime_text_backend_path(
            &mut backend.clip_path,
            factory,
            raw_path,
            RenderFillRule::Clockwise,
        );
        renderer.clip_path(path);
    }

    for item in retained.replay.iter().copied() {
        let paint = match item {
            RuntimeTextReplay::Paint(index) => retained
                .commands
                .get(index)
                .context("retained Text replay references a missing paint")?,
            RuntimeTextReplay::ColorGlyph(index) => {
                let color = retained
                    .color
                    .as_deref()
                    .context("retained Text replay references missing color data")?;
                let glyph = color
                    .glyphs
                    .get(index)
                    .context("retained Text replay references a missing color glyph")?;
                let RuntimeTextBackendResources {
                    color_paths,
                    emoji_images,
                    ..
                } = &mut *backend;
                runtime_draw_integrated_color_glyph(
                    index,
                    glyph,
                    color.shape_world,
                    factory,
                    renderer,
                    color_paths,
                    emoji_images,
                );
                continue;
            }
        };
        // C++ `TextStylePaint::draw` gates each ShapePaint on
        // `shouldDraw()` — `isVisible() && m_PaintMutator->isVisible()` —
        // every draw, ahead of growing `m_paintPool`
        // (`src/text/text_style_paint.cpp:53-58,69-77`,
        // `include/rive/shapes/paint/shape_paint.hpp:71-74`). The
        // `ShapePaint::isVisible()` half is Paint-dirty driven and stays
        // baked into command construction; the mutator half depends on the
        // live render opacity, so it must be re-tested here. Testing it at
        // build time instead would let a Text shaped while its ancestor
        // opacity is 0 retain an empty command set that a later
        // RenderOpacity-only propagation can never repopulate.
        //
        // TextInput drawables keep their own construction-time predicate
        // (`StaticTextSlice::text_input_paint_commands` already builds every
        // command) and are not routed through `TextStylePaint::draw`.
        if is_text && !runtime_shape_paint_state_is_effectively_visible(&paint.paint_state) {
            continue;
        }
        let global_id = paint.paint_global_id;
        let object = runtime
            .object(global_id as usize)
            .with_context(|| format!("missing occurrence-owned text paint global {global_id}"))?;
        let paint_owner = instance
            .runtime_shapes
            .text_style_paint_owner(paint.paint_local)
            .with_context(|| {
                format!(
                    "missing occurrence-owned TextStylePaint for local {}",
                    paint.paint_local
                )
            })?;
        let paint_backend = paint_owner.backend.value.borrow();
        if paint_backend.context_id != Some(backend_context_id) {
            anyhow::bail!(
                "TextStylePaint local {} was not realized for backend context {}",
                paint.paint_local,
                backend_context_id
            );
        }
        let authored_paint = paint_backend.paint.as_deref().with_context(|| {
            format!(
                "TextStylePaint local {} has no occurrence-owned RenderPaint",
                paint.paint_local
            )
        })?;

        if let Some(pool_use) = paint.text_paint_pool {
            let key = (pool_use.spec.style_local, pool_use.paint_index);
            let RuntimeTextBackendResources { pooled_paints, .. } = &mut *backend;
            // C++ grows the complete TextStylePaint::m_paintPool before it
            // iterates the non-opaque opacity buckets
            // (`src/text/text_style_paint.cpp:68-81`).
            for paint_index in 0..pool_use.spec.paint_count {
                pooled_paints
                    .entry((pool_use.spec.style_local, paint_index))
                    .or_insert_with(|| RuntimeTextPooledPaintBackend {
                        paint: factory.make_render_paint(),
                        configuration: None,
                    });
            }
            let authored_shader = paint_backend.shader.as_deref();
            let pooled = pooled_paints
                .get_mut(&key)
                .context("TextStylePaint pool allocation did not retain its paint")?;
            runtime_configure_text_pooled_paint(pooled, authored_shader, instance, object, paint)?;
        }

        let paint_world =
            runtime_text_paint_shape_world(true, paint.shape_world_override, live_world)
                .context("live Text paint is missing its shape-world transform")?;

        let mut saved = !paint.needs_save_operation;
        if let Some(feather) = paint.feather_state.as_ref()
            && runtime_feather_uses_world_space(feather)
            && !feather.inner
            && runtime_feather_has_offset(feather)
        {
            if !saved {
                saved = true;
                renderer.save();
            }
            renderer.transform(runtime_translation(feather.offset_x, feather.offset_y));
        }
        if matches!(
            paint.path_kind,
            RuntimeShapePaintPathKind::Local | RuntimeShapePaintPathKind::LocalClockwise
        ) {
            if !saved {
                saved = true;
                renderer.save();
            }
            renderer.transform(runtime_render_mat(paint_world));
        }
        if let Some(feather) = paint.feather_state.as_ref() {
            if feather.inner {
                if feather.inner_path_commands.is_empty() {
                    continue;
                }
                if !saved {
                    saved = true;
                    renderer.save();
                }
                let path_key = RuntimeTextPathOwnerKey {
                    // Without an effect C++ clips against the replaceable
                    // TextStylePaint opacity bucket. With an effect it clips
                    // against the retained EffectPath (`shape_paint.cpp:
                    // 115-143`).
                    owner_local: if paint.has_effect_path {
                        paint.paint_local
                    } else {
                        runtime_text_style_path_owner_local(paint).unwrap_or(paint.paint_local)
                    },
                    replace_on_render_style_rebuild: !paint.has_effect_path
                        && runtime_text_style_path_owner_local(paint).is_some(),
                    slot: paint.clip_path_slot_index,
                };
                let raw_path = retained
                    .paths
                    .get(&path_key)
                    .context("missing TextStylePaint clip path owner")?;
                let clip_path =
                    backend
                        .paths
                        .entry(path_key)
                        .or_insert_with(|| RuntimeTextPathBackend {
                            path: runtime_make_path_from_raw_path(
                                factory,
                                raw_path.as_ref(),
                                RenderFillRule::Clockwise,
                            ),
                            raw_mutation_id: raw_path.mutation_id(),
                        });
                if clip_path.raw_mutation_id != raw_path.mutation_id() {
                    runtime_rebuild_path_from_raw_path(
                        clip_path.path.as_mut(),
                        raw_path.as_ref(),
                        RenderFillRule::Clockwise,
                    );
                    clip_path.raw_mutation_id = raw_path.mutation_id();
                } else {
                    clip_path.path.fill_rule(RenderFillRule::Clockwise);
                }
                renderer.clip_path(clip_path.path.as_ref());
            } else if !runtime_feather_uses_world_space(feather)
                && runtime_feather_has_offset(feather)
            {
                if !saved {
                    saved = true;
                    renderer.save();
                }
                renderer.transform(runtime_translation(feather.offset_x, feather.offset_y));
            }
        }

        let path_key = RuntimeTextPathOwnerKey {
            // Direct text drawing consumes TextStylePaint's opacity bucket,
            // which clearRenderStyles replaces. StrokeEffect and inner
            // Feather commands consume their concrete retained output paths.
            owner_local: if paint.has_effect_path
                || paint
                    .feather_state
                    .as_ref()
                    .is_some_and(|feather| feather.inner)
            {
                paint.paint_local
            } else {
                runtime_text_style_path_owner_local(paint).unwrap_or(paint.paint_local)
            },
            replace_on_render_style_rebuild: paint
                .feather_state
                .as_ref()
                .is_none_or(|feather| !feather.inner)
                && !paint.has_effect_path
                && runtime_text_style_path_owner_local(paint).is_some(),
            slot: paint.path_slot_index,
        };
        let raw_path = retained
            .paths
            .get(&path_key)
            .context("missing TextStylePaint draw path owner")?;
        let fill_rule = if !is_text && paint.paint_type == RuntimeShapePaintKind::Fill {
            paint.fill_rule
        } else {
            RenderFillRule::Clockwise
        };
        let RuntimeTextBackendResources {
            pooled_paints,
            paths,
            ..
        } = &mut *backend;
        let path = paths
            .entry(path_key)
            .or_insert_with(|| RuntimeTextPathBackend {
                path: runtime_make_path_from_raw_path(factory, raw_path.as_ref(), fill_rule),
                raw_mutation_id: raw_path.mutation_id(),
            });
        if path.raw_mutation_id != raw_path.mutation_id() {
            runtime_rebuild_path_from_raw_path(path.path.as_mut(), raw_path.as_ref(), fill_rule);
            path.raw_mutation_id = raw_path.mutation_id();
        } else {
            path.path.fill_rule(fill_rule);
        }
        let render_paint = if let Some(pool_use) = paint.text_paint_pool {
            pooled_paints
                .get(&(pool_use.spec.style_local, pool_use.paint_index))
                .context("missing occurrence-owned TextStylePaint pooled paint")?
                .paint
                .as_ref()
        } else {
            authored_paint
        };
        renderer.draw_path(path.path.as_ref(), render_paint);
        if saved && paint.needs_save_operation {
            renderer.restore();
        }
        if let Some(spec) = paint.ensure_text_paint_pool_after_draw {
            for paint_index in 0..spec.paint_count {
                backend
                    .pooled_paints
                    .entry((spec.style_local, paint_index))
                    .or_insert_with(|| RuntimeTextPooledPaintBackend {
                        paint: factory.make_render_paint(),
                        configuration: None,
                    });
            }
        }
    }

    if needs_outer_save {
        renderer.restore();
    }
    Ok(())
}

/// Direct port of `LayoutComponent::drawProxy/draw` and
/// `ForegroundLayoutDrawable::draw` (`src/layout_component.cpp:317-374`,
/// `src/foreground_layout_drawable.cpp`). The retained layout object supplies
/// its paths and live world transform; no `RuntimeDrawableDispatch` is built.
#[allow(clippy::too_many_arguments)]
fn runtime_draw_live_layout_family(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    drawable: &RuntimeDrawable,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    path_cache: &mut RuntimeArtboardPathState,
    paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
) -> Result<()> {
    if drawable.kind == DrawableOrderKind::Drawable && drawable.type_name == "LayoutComponent" {
        let layout_local = drawable
            .local_id
            .context("live layout component is missing its local id")?;
        if instance.runtime_layout_component_clip_enabled(layout_local) {
            // C++ restores the clip before the foreground stroke drawable.
            renderer.restore();
        }
        return Ok(());
    }

    let layout_local = match drawable.kind {
        DrawableOrderKind::LayoutProxy => drawable.layout_local,
        DrawableOrderKind::Drawable if drawable.type_name == "ForegroundLayoutDrawable" => {
            drawable.local_id.and_then(|local_id| {
                crate::foreground_layout_drawable::parent_layout_local(instance, local_id)
            })
        }
        _ => None,
    }
    .context("live layout drawable is missing its owning LayoutComponent")?;
    let owner = instance
        .runtime_drawables
        .layout_draw_owner(layout_local)
        .context("live layout drawable is missing its retained path owner")?;
    let mut backend = owner.backend(paint_by_global.backend_context_id);

    if drawable.kind == DrawableOrderKind::LayoutProxy
        && instance.runtime_layout_component_clip_enabled(layout_local)
    {
        renderer.save();
        if let Some(paths) =
            instance.runtime_layout_component_draw_paths(layout_local, graph, layout_bounds)
            && !paths.clip.is_empty()
        {
            // LayoutComponent owns an independent retained clip path. Key it
            // by that concrete owner's Path revision; the artboard-root
            // revision only governs Artboard::m_clipPath and left resized
            // layout clips backed by stale renderer resources.
            let key = path_cache.retained_render_path_key(
                instance,
                graph,
                layout_local,
                RenderFillRule::Clockwise,
            );
            let path = runtime_cached_retained_render_path(
                &mut backend.clip_path,
                key,
                factory,
                paths.clip.as_slice(),
            );
            renderer.clip_path(path.as_ref());
        }
    }

    let shape_paints = owner.retained_paint_commands(
        usize::from(drawable.kind != DrawableOrderKind::LayoutProxy),
        RuntimeLayoutPaintCommandKey {
            cache_epoch: instance.cache_epoch(),
            prepared_epoch: instance.prepared_epoch(),
            layout_revision: instance.layout_revision(),
            path_revision: owner.revision.get(),
        },
        || instance.runtime_shape_paint_commands(drawable, graph, layout_bounds, path_cache),
    );
    runtime_draw_layout_owner_paints(
        runtime,
        instance,
        graph,
        layout_local,
        shape_paints.as_ref(),
        layout_bounds,
        factory,
        renderer,
        paint_by_global,
        &mut backend.draw_paths,
        path_cache,
        paint_configurations,
    )
}

/// Direct port of `NestedArtboard::draw/willDraw`
/// (`src/nested_artboard.cpp:491-508`) plus the live transforms established by
/// `NestedArtboardLeaf::update` and `NestedArtboardLayout::update`. Recursion
/// always uses the mounted child occurrence; layout drawing never clones it.
#[allow(clippy::too_many_arguments)]
fn runtime_draw_live_nested_artboard(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    drawable: &RuntimeDrawable,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    path_cache: &mut RuntimeArtboardPathState,
    _paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
    _nested_paint_caches: Option<
        &mut BTreeMap<RuntimeNestedRenderCacheKey, RuntimeArtboardResourceBundle>,
    >,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    nested_ancestors: &[u32],
) -> Result<()> {
    let host_local = drawable
        .local_id
        .context("live nested artboard is missing its host local id")?;
    let nested = instance
        .nested_artboards
        .get(&host_local)
        .context("live nested artboard is missing its mounted child")?;
    let child = nested.child.as_ref();
    let child_graph = child
        .runtime_graph()
        .or_else(|| {
            artboards
                .iter()
                .find(|candidate| candidate.global_id == child.graph_global_id)
        })
        .context("mounted nested artboard graph is missing")?;

    let host_world = match drawable.type_name {
        "NestedArtboardLayout" => runtime_nested_artboard_layout_world_transform(
            instance,
            graph,
            host_local,
            child,
            layout_bounds,
            path_cache,
        ),
        "NestedArtboardLeaf" => runtime_nested_artboard_leaf_world_transform(
            instance,
            graph,
            host_local,
            child_graph,
            Some(child),
            layout_bounds,
            path_cache,
        )?,
        _ => path_cache.component_world_transform_with_bounds(
            instance,
            graph,
            host_local,
            layout_bounds,
        ),
    };
    let needs_save = drawable.needs_save_operation;
    if needs_save {
        renderer.save();
    }
    renderer.transform(runtime_render_mat(host_world));

    let draw_result = (|| {
        let mut resources = nested.child.render_resources.borrow_mut();
        resources.initialize(
            paint_by_global.backend_context_id,
            runtime,
            child,
            child_graph,
            artboards,
            factory,
        );
        let RuntimeOccurrenceRenderResources {
            initialized: _,
            paints: child_paints,
            paint_configurations: child_configurations,
            preparation: child_preparation,
            nested_artboards: child_nested_artboards,
            path_cache: child_cache,
            ..
        } = &mut *resources;
        if child_preparation.is_none() {
            child.update_artboard_backend_tree_internal(
                runtime,
                child_graph,
                artboards,
                factory,
                child_paints,
                Some(child_configurations),
                Some(child_preparation),
                Some(child_nested_artboards),
                child_cache,
                false,
                true,
                nested_ancestors,
            )?;
        }
        child.prepare_static_artboard_slice_meshes(runtime, child_graph, factory, child_cache)?;
        child.draw_artboard_internal_internal_with_path_cache(
            runtime,
            child_graph,
            artboards,
            factory,
            renderer,
            child_paints,
            child_cache,
            Some(child_configurations),
            Some(child_nested_artboards),
            nested_ancestors,
        )
    })();

    if needs_save {
        renderer.restore();
    }
    draw_result
}

fn runtime_realize_owned_shape_paints(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    factory: &mut dyn RenderFactory,
    paint_by_global: &mut RuntimeRenderPaints,
) -> Result<()> {
    let backend_context_id = paint_by_global.backend_context_id;
    // C++ `ShapePaint::draw` reads the already-owned RenderPaint directly;
    // construction/configuration happens only in `onAdded` or a property
    // callback (`shape_paint.cpp:50-74`, `solid_color.cpp:23-54`). Keep the
    // Rust backend-context seam behind the same owner dirt gate so a clean
    // draw does not even enter realization work (RF-2/RF-5/RF-17).
    if !instance
        .runtime_shapes
        .backend_paints_need_realization(backend_context_id)
    {
        return Ok(());
    }
    instance
        .runtime_shapes
        .activate_backend_context(backend_context_id);
    // Validate the whole queue before consuming it. If provenance is corrupt,
    // no owner is left permanently marked queued after an early error.
    for owner_ref in instance
        .runtime_shapes
        .pending_backend_paints
        .borrow()
        .iter()
        .copied()
    {
        let Some(owner) = instance
            .runtime_shapes
            .get(owner_ref.shape_local)
            .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
        else {
            continue;
        };
        runtime
            .object(owner.paint_global_id as usize)
            .with_context(|| {
                format!(
                    "missing occurrence-owned ShapePaint global {}",
                    owner.paint_global_id
                )
            })?;
    }
    let pending = instance.runtime_shapes.take_pending_backend_paints();
    for owner_ref in pending {
        let Some(owner) = instance
            .runtime_shapes
            .get(owner_ref.shape_local)
            .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
        else {
            continue;
        };
        let object = runtime
            .object(owner.paint_global_id as usize)
            .with_context(|| {
                format!(
                    "missing occurrence-owned ShapePaint global {}",
                    owner.paint_global_id
                )
            })?;
        let mut backend = owner.backend.value.borrow_mut();
        if backend.context_id != Some(backend_context_id) {
            *backend = RuntimePaintBackendState {
                context_id: Some(backend_context_id),
                ..RuntimePaintBackendState::default()
            };
        }
        let mut render_paint = backend
            .paint
            .take()
            .or_else(|| paint_by_global.take_paint(owner.paint_global_id))
            .unwrap_or_else(|| factory.make_render_paint());
        runtime_configure_owned_shape_paint(render_paint.as_mut(), instance, object, owner)?;

        let paint_state = owner.paint_state.borrow();
        match paint_state.as_ref() {
            Some(
                RuntimeShapePaintState::LinearGradient { .. }
                | RuntimeShapePaintState::RadialGradient { .. },
            ) => {
                // C++ creates/configures the shader from the gradient
                // component's dependency update, not from ShapePaint
                // construction (`linear_gradient.cpp:86-126`). Preserve an
                // already-current shader here; the dependency-ordered
                // preparation pass realizes a changed one.
                //
                // An initial nested-layout frame configures the same
                // occurrence-owned RenderPaint before ownership transfers
                // here. Its shader is already correct and must survive this
                // construction step; a queued post-frame update, if any, will
                // replace it in dependency order below.
                if !owner.initial_gradient_event_supplied.get() {
                    render_paint.shader(backend.shader.as_deref());
                }
            }
            Some(RuntimeShapePaintState::SolidColor { .. }) | None => {
                backend.shader = None;
                backend.shader_state = None;
                // `runtime_configure_owned_shape_paint` has already detached
                // the shader before setting the solid color. Exact-source
                // paints interpret another `shader(None)` as solid black.
            }
        }
        backend.paint = Some(render_paint);
        // The late-factory realization above configures the concrete paint
        // from the occurrence's already-settled state. C++ has already
        // delivered that same inherited opacity through
        // `ShapePaintMutator::renderOpacity` before the retained RenderPaint
        // becomes observable. Seed the Rust callback guard at this seam so
        // the next component update does not replay an unchanged opacity.
        let opacity_local = instance
            .runtime_graph()
            .map_or(owner_ref.shape_local, |graph| {
                crate::shapes::shape_paint_container::opacity_owner_local(
                    graph,
                    owner_ref.shape_local,
                )
            });
        if let Some(render_opacity) = instance
            .component(opacity_local)
            .map(|component| component.transform.render_opacity)
        {
            owner.render_opacity.set(render_opacity);
        }
        owner.initial_gradient_event_supplied.set(false);
        owner.backend_queued.set(false);
    }
    Ok(())
}

/// Realize one occurrence-owned Shape gradient at its mutator's exact place
/// in the global component dependency order. C++ runs Shape, layout, text, and
/// artboard gradients through the same `LinearGradient::update` traversal
/// (`linear_gradient.cpp:86-126`); Shape paint membership order is draw order,
/// not shader-creation order.
fn runtime_initial_root_gradient_state_before_data_bind_source_writes(
    graph: &ArtboardGraph,
    owner: &RuntimeShapePaintOwner,
    state: &RuntimeShapePaintState,
) -> RuntimeShapePaintState {
    let Some(mutator_local) = owner.mutator_local else {
        return state.clone();
    };
    let mut state = state.clone();
    let type_name = match state {
        RuntimeShapePaintState::LinearGradient { .. } => "LinearGradient",
        RuntimeShapePaintState::RadialGradient { .. } => "RadialGradient",
        RuntimeShapePaintState::SolidColor { .. } => return state,
    };
    for data_bind in graph.data_binds.iter().filter(|data_bind| {
        data_bind.target_local == Some(mutator_local)
            && crate::data_bind_flags_apply_source_to_target(data_bind.flags)
    }) {
        let bound = |property_name| {
            runtime_draw_property_key_for_name(type_name, property_name)
                .is_some_and(|key| u64::from(key) == data_bind.property_key)
        };
        match &mut state {
            RuntimeShapePaintState::LinearGradient {
                start_x,
                start_y,
                end_x,
                end_y,
                ..
            }
            | RuntimeShapePaintState::RadialGradient {
                start_x,
                start_y,
                end_x,
                end_y,
                ..
            } => {
                // A C++ root Artboard owns its RenderPaint while the default
                // view-model context is being attached. The first gradient
                // update therefore observes the numeric ContextValue default;
                // a target-to-source sibling write is queued for the next
                // DataBindContainer turn and does not rewrite that retained
                // shader (`artboard.cpp:1195-1203`,
                // `data_bind_container.cpp:156-203`). Rust attaches the
                // renderer later, so preserve that one-time resource state
                // instead of sampling the already-reconciled property.
                if bound("startX") {
                    *start_x = 0.0;
                } else if bound("startY") {
                    *start_y = 0.0;
                } else if bound("endX") {
                    *end_x = 0.0;
                } else if bound("endY") {
                    *end_y = 0.0;
                }
            }
            RuntimeShapePaintState::SolidColor { .. } => {}
        }
    }
    state
}

fn runtime_realize_owned_shape_gradient(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    container: &ShapePaintContainerNode,
    paint_index: usize,
    state: &RuntimeShapePaintState,
    factory: &mut dyn RenderFactory,
    paint_by_global: &mut RuntimeRenderPaints,
) -> Result<()> {
    let owner = instance
        .runtime_shapes
        .get(container.local_id)
        .and_then(|shape| shape.paint_owners.get(paint_index))
        .with_context(|| {
            format!(
                "missing occurrence-owned ShapePaint {}:{}",
                container.local_id, paint_index
            )
        })?;
    let backend_context_id = paint_by_global.backend_context_id;
    let mut backend = owner.backend.value.borrow_mut();
    if backend.context_id != Some(backend_context_id) {
        anyhow::bail!(
            "ShapePaint global {} was not realized for backend context {}",
            owner.paint_global_id,
            backend_context_id
        );
    }
    let mut render_paint = backend.paint.take().with_context(|| {
        format!(
            "ShapePaint global {} has no occurrence-owned RenderPaint",
            owner.paint_global_id
        )
    })?;
    let initial_state;
    let state = if backend.shader_state.is_none() && container.type_name == "Artboard" {
        initial_state =
            runtime_initial_root_gradient_state_before_data_bind_source_writes(graph, owner, state);
        &initial_state
    } else {
        state
    };
    match state {
        state @ RuntimeShapePaintState::LinearGradient {
            start_x,
            start_y,
            end_x,
            end_y,
            stops,
            ..
        } => {
            let colors = stops
                .iter()
                .map(|stop| stop.render_color)
                .collect::<Vec<_>>();
            let positions = stops.iter().map(|stop| stop.position).collect::<Vec<_>>();
            backend.shader = Some(
                factory
                    .make_linear_gradient(*start_x, *start_y, *end_x, *end_y, &colors, &positions),
            );
            backend.shader_state = Some(state.clone());
            render_paint.shader(backend.shader.as_deref());
        }
        state @ RuntimeShapePaintState::RadialGradient {
            start_x,
            start_y,
            end_x,
            end_y,
            stops,
            ..
        } => {
            let colors = stops
                .iter()
                .map(|stop| stop.render_color)
                .collect::<Vec<_>>();
            let positions = stops.iter().map(|stop| stop.position).collect::<Vec<_>>();
            let dx = *end_x - *start_x;
            let dy = *end_y - *start_y;
            backend.shader = Some(factory.make_radial_gradient(
                *start_x,
                *start_y,
                dx.mul_add(dx, dy * dy).sqrt(),
                &colors,
                &positions,
            ));
            backend.shader_state = Some(state.clone());
            render_paint.shader(backend.shader.as_deref());
        }
        RuntimeShapePaintState::SolidColor { .. } => {}
    }
    backend.paint = Some(render_paint);
    Ok(())
}

fn runtime_realize_next_owned_shape_gradient(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    container: &ShapePaintContainerNode,
    paint_index: usize,
    factory: &mut dyn RenderFactory,
    paint_by_global: &mut RuntimeRenderPaints,
) -> Result<()> {
    let owner = instance
        .runtime_shapes
        .get(container.local_id)
        .and_then(|shape| shape.paint_owners.get(paint_index))
        .with_context(|| {
            format!(
                "missing occurrence-owned ShapePaint {}:{}",
                container.local_id, paint_index
            )
        })?;
    let state = owner.pending_gradient_states.borrow().first().cloned();
    let Some(state) = state else {
        return Ok(());
    };
    runtime_realize_owned_shape_gradient(
        instance,
        graph,
        container,
        paint_index,
        &state,
        factory,
        paint_by_global,
    )?;
    owner.pending_gradient_states.borrow_mut().remove(0);
    Ok(())
}

fn runtime_realize_owned_shape_gradients_in_dependency_order(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    factory: &mut dyn RenderFactory,
    paint_by_global: &mut RuntimeRenderPaints,
    render_cache: &mut RuntimeArtboardPathState,
) -> Result<()> {
    let gradient_preparation = render_cache.gradient_preparation_frame(graph);
    let mut prepared = Vec::new();
    let mut ordered = Vec::new();
    for local_id in gradient_preparation.dependency_order.iter().copied() {
        let Some(paints) = gradient_preparation.paints_by_mutator.get(&local_id) else {
            continue;
        };
        for paint_ref in paints {
            let Some(container) = graph.shape_paint_containers.get(paint_ref.container_index)
            else {
                continue;
            };
            if !runtime_shape_paint_container_is_occurrence_owned(container) {
                continue;
            }
            let Some(paint) = container.paints.get(paint_ref.paint_index) else {
                continue;
            };
            if runtime_owned_shape_gradient_is_collapsed(instance, container, paint)
                || !runtime_mark_seen_u32(&mut prepared, paint.global_id)
            {
                continue;
            }
            ordered.push((container, paint_ref.paint_index));
        }
    }
    let event_count = ordered
        .iter()
        .filter_map(|(container, paint_index)| {
            instance
                .runtime_shapes
                .get(container.local_id)
                .and_then(|shape| shape.paint_owners.get(*paint_index))
                .map(|owner| owner.pending_gradient_states.borrow().len())
        })
        .max()
        .unwrap_or(0);
    for event_index in 0..event_count {
        for (container, paint_index) in &ordered {
            let state = instance
                .runtime_shapes
                .get(container.local_id)
                .and_then(|shape| shape.paint_owners.get(*paint_index))
                .and_then(|owner| {
                    owner
                        .pending_gradient_states
                        .borrow()
                        .get(event_index)
                        .cloned()
                });
            if let Some(state) = state {
                runtime_realize_owned_shape_gradient(
                    instance,
                    graph,
                    container,
                    *paint_index,
                    &state,
                    factory,
                    paint_by_global,
                )?;
            }
        }
    }
    for (container, paint_index) in ordered {
        if let Some(owner) = instance
            .runtime_shapes
            .get(container.local_id)
            .and_then(|shape| shape.paint_owners.get(paint_index))
        {
            owner.pending_gradient_states.borrow_mut().clear();
        }
    }
    Ok(())
}

fn runtime_owned_shape_gradient_is_collapsed(
    instance: &ArtboardInstance,
    container: &ShapePaintContainerNode,
    paint: &ShapePaintNode,
) -> bool {
    // C++'s component walker skips a component carrying its own Collapsed
    // dirt; it does not suppress every descendant gradient merely because a
    // mounted host is effectively hidden. Those retained child gradients are
    // still constructed and updated before their first draw.
    [
        Some(container.local_id),
        Some(paint.local_id),
        paint.mutator_local,
    ]
    .into_iter()
    .flatten()
    .any(|local_id| {
        instance
            .component(local_id)
            .is_some_and(|component| component.is_collapsed())
    })
}

#[allow(clippy::too_many_arguments)]
fn runtime_draw_layout_owner_paints(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    shape_local: usize,
    shape_paints: &[RuntimeShapePaintCommand],
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    draw_paths: &mut RuntimeDrawPathSlots,
    path_cache: &mut RuntimeArtboardPathState,
    mut paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
) -> Result<()> {
    let shape_world = path_cache.component_world_transform_with_bounds(
        instance,
        graph,
        shape_local,
        layout_bounds,
    );
    for paint in shape_paints {
        runtime_draw_live_shape_paint(
            runtime,
            instance,
            shape_local,
            shape_world,
            paint,
            factory,
            renderer,
            paint_by_global,
            draw_paths,
            paint_configurations.as_deref_mut(),
            true,
            paint.needs_save_operation,
        )?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn runtime_draw_live_shape_paint(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    shape_local: usize,
    shape_world: Mat2D,
    paint: &RuntimeShapePaintCommand,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    draw_paths: &mut RuntimeDrawPathSlots,
    mut paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
    configure_paint_if_stale: bool,
    needs_save_operation: bool,
) -> Result<()> {
    let global_id = paint.paint_global_id;
    let paint_configuration_is_current = !configure_paint_if_stale
        || paint_configurations
            .as_deref()
            .is_some_and(|configurations| {
                configurations.is_current(
                    global_id,
                    runtime_paint_configuration_epoch(instance, paint),
                )
            });
    if !paint_configuration_is_current {
        let object = runtime
            .object(global_id as usize)
            .with_context(|| format!("missing paint global {global_id}"))?;
        let render_paint = paint_by_global
            .paint_mut(global_id)
            .with_context(|| format!("missing render paint for global {global_id}"))?
            .as_mut();
        if let Some(configurations) = paint_configurations.as_mut() {
            runtime_configure_paint_with_cache(
                render_paint,
                configurations,
                global_id,
                instance,
                object,
                paint,
            )?;
        } else {
            runtime_configure_paint(render_paint, instance, object, paint, None)?;
        }
    }

    let draw_path_revision = runtime_draw_path_revision(instance, shape_local, paint);
    let effect_or_shape_path_commands = if paint.has_effect_path {
        paint.effect_path_commands.as_slice()
    } else {
        paint.path_commands.as_slice()
    };
    let draw_path_commands = paint
        .feather_state
        .as_ref()
        .filter(|feather| feather.inner)
        .map(|feather| feather.inner_path_commands.as_slice())
        .unwrap_or(effect_or_shape_path_commands);
    let draw_path_cache_local = if paint.has_effect_path {
        Some(paint.paint_local)
    } else {
        Some(shape_local)
    };
    let inner_feather_path_cache_local = if paint
        .feather_state
        .as_ref()
        .is_some_and(|feather| feather.inner)
    {
        Some(paint.paint_local)
    } else {
        draw_path_cache_local
    };

    let mut saved = !needs_save_operation;
    if let Some(feather) = paint.feather_state.as_ref()
        && runtime_feather_uses_world_space(feather)
        && !feather.inner
        && runtime_feather_has_offset(feather)
    {
        if !saved {
            saved = true;
            renderer.save();
        }
        renderer.transform(runtime_translation(feather.offset_x, feather.offset_y));
    }
    if matches!(
        paint.path_kind,
        RuntimeShapePaintPathKind::Local | RuntimeShapePaintPathKind::LocalClockwise
    ) {
        if !saved {
            saved = true;
            renderer.save();
        }
        renderer.transform(runtime_render_mat(shape_world));
    }
    if let Some(feather) = paint.feather_state.as_ref() {
        if feather.inner {
            // C++ returns from ShapePaint::draw here. The Shape loop then
            // continues to its next retained paint.
            if feather.inner_path_commands.is_empty() {
                return Ok(());
            }
            if !saved {
                saved = true;
                renderer.save();
            }
            let clip_path = draw_paths.draw_path(
                RuntimeDrawPathCacheKey {
                    kind: RuntimeDrawPathCacheKind::Draw,
                    path_kind: runtime_draw_path_cache_path_kind(paint),
                    local_id: draw_path_cache_local,
                    path_index: paint.clip_path_slot_index,
                },
                draw_path_revision,
                factory,
                effect_or_shape_path_commands,
                RenderFillRule::Clockwise,
            );
            renderer.clip_path(clip_path.as_ref());
        } else if !runtime_feather_uses_world_space(feather) && runtime_feather_has_offset(feather)
        {
            if !saved {
                saved = true;
                renderer.save();
            }
            renderer.transform(runtime_translation(feather.offset_x, feather.offset_y));
        }
    }

    let replay_fill_rule =
        (paint.paint_type == RuntimeShapePaintKind::Fill).then_some(paint.fill_rule);
    let path = draw_paths.draw_path_with_optional_fill_rule(
        RuntimeDrawPathCacheKey {
            kind: RuntimeDrawPathCacheKind::Draw,
            path_kind: runtime_draw_path_cache_path_kind(paint),
            local_id: inner_feather_path_cache_local,
            path_index: paint.path_slot_index,
        },
        draw_path_revision,
        factory,
        draw_path_commands,
        RenderFillRule::Clockwise,
        replay_fill_rule,
    );
    let render_paint = paint_by_global
        .paint(global_id)
        .with_context(|| format!("missing render paint for global {global_id}"))?
        .as_ref();
    renderer.draw_path(path.as_ref(), render_paint);
    if saved && needs_save_operation {
        renderer.restore();
    }
    Ok(())
}

fn runtime_draw_live_scripted_drawable(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    drawable: &RuntimeDrawable,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    path_cache: &mut RuntimeArtboardPathState,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
) -> Result<()> {
    let Some(global_id) = drawable.global_id else {
        return Ok(());
    };
    let Some(script_instance) = instance.script_instance_for_global(global_id) else {
        return Ok(());
    };
    let Some(local_id) = drawable.local_id else {
        return Ok(());
    };
    let render_opacity = instance
        .component(local_id)
        .map(|component| component.transform.render_opacity)
        .unwrap_or(1.0);
    let needs_opacity_save = render_opacity != 1.0;
    let needs_save = drawable.needs_save_operation || needs_opacity_save;
    if needs_save {
        renderer.save();
    }
    if needs_opacity_save {
        renderer.modulate_opacity(render_opacity);
    }
    let world_transform =
        path_cache.component_world_transform_with_bounds(instance, graph, local_id, layout_bounds);
    renderer.transform(runtime_render_mat(world_transform));

    let mut host = crate::NoopScriptHost;
    let draw_result = script_instance
        .borrow_mut()
        .call_draw(factory, renderer, &mut host)
        .map_err(|error| anyhow::anyhow!("scripted drawable {global_id} draw failed: {error}"));

    if needs_save {
        renderer.restore();
    }
    draw_result
}

fn runtime_draw_path_cache_path_kind(
    paint: &RuntimeShapePaintCommand,
) -> RuntimeShapePaintPathKind {
    if paint.aliases_local_clockwise_path
        && paint.path_kind == RuntimeShapePaintPathKind::LocalClockwise
    {
        RuntimeShapePaintPathKind::Local
    } else {
        paint.path_kind
    }
}

fn runtime_draw_path_revision(
    instance: &ArtboardInstance,
    local_id: usize,
    paint: &RuntimeShapePaintCommand,
) -> RuntimeDrawPathRevision {
    let component_path_revision = instance
        .component(local_id)
        .map_or(0, |component| component.path_revision());
    RuntimeDrawPathRevision {
        path_epoch: component_path_revision,
        world_epoch: if paint.path_kind == RuntimeShapePaintPathKind::World {
            instance.prepared_epoch()
        } else {
            0
        },
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn runtime_component_list_item_base_transforms(
    instance: &ArtboardInstance,
    local_id: usize,
) -> Vec<Mat2D> {
    let Some(items) = instance.component_list_items(local_id) else {
        return Vec::new();
    };
    let uses_hosted_layout = instance
        .component_parent_local(local_id)
        .and_then(|parent_local| instance.component(parent_local))
        .is_some_and(|parent| matches!(parent.type_name, "Artboard" | "LayoutComponent"));
    let node_x_key = runtime_draw_property_key_for_name("Node", "x");
    let node_y_key = runtime_draw_property_key_for_name("Node", "y");
    let mut item_transforms = Vec::with_capacity(items.len());
    for item in items {
        // C++ derives the mounted origin and row advance from the mounted
        // Artboard's own `layoutWidth/layoutHeight`, not a stretched hosting
        // Yoga leaf size (`artboard_component_list.cpp:1307-1330`;
        // `artboard.cpp:1729-1734`).
        let item_size = runtime_component_list_item_layout_size(item);
        if crate::constraints::scrolling::scroll_virtualizer::component_list_virtualization(
            instance, local_id,
        )
        .is_some()
        {
            // `ScrollVirtualizer` writes the retained
            // ArtboardComponentList transform directly through
            // `setVirtualizablePosition`; draw performs no second window or
            // position reconstruction (`artboard_component_list.cpp:1728-1740`).
            item_transforms.push(item.transform);
            continue;
        }
        let (item_x, item_y) = if !uses_hosted_layout {
            // C++ reads the mounted Artboard's live `worldBounds()`. Its
            // authored canvas placement was cleared by `onAddedClean`, while
            // later animation/data-bind writes to root x/y remain visible
            // (`artboard.cpp:1080-1092,1807-1814`;
            // `artboard_component_list.cpp:1306-1329`).
            (
                node_x_key
                    .and_then(|key| item.child.double_property(0, key))
                    .unwrap_or(0.0),
                node_y_key
                    .and_then(|key| item.child.double_property(0, key))
                    .unwrap_or(0.0),
            )
        } else {
            // `ArtboardComponentList::layoutNode` transfers the mounted
            // Artboard root into the host Yoga tree. The non-virtualized
            // transform reads that retained root `layoutBounds()` verbatim,
            // including wrap and cross-axis placement
            // (`artboard_component_list.cpp:220-229,1307-1330`).
            item.child
                .component(0)
                .and_then(|component| component.concrete.layout.as_ref())
                .map(|layout| layout.position())
                .unwrap_or((0.0, 0.0))
        };
        item_transforms.push(Mat2D([
            1.0,
            0.0,
            0.0,
            1.0,
            item_x
                + if uses_hosted_layout {
                    item_size.0 * item.child.origin_x
                } else {
                    0.0
                },
            item_y
                + if uses_hosted_layout {
                    item_size.1 * item.child.origin_y
                } else {
                    0.0
                },
        ]));
    }
    item_transforms
}

#[allow(clippy::too_many_arguments)]
fn runtime_component_list_host_world_transform(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    local_id: usize,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    path_cache: &mut RuntimeArtboardPathState,
) -> Mat2D {
    if crate::constraints::scrolling::scroll_virtualizer::component_list_virtualization(
        instance, local_id,
    )
    .is_some()
    {
        let parent_local = instance
            .component_parent_local(local_id)
            .unwrap_or(local_id);
        return path_cache.component_world_transform_with_bounds(
            instance,
            graph,
            parent_local,
            layout_bounds,
        );
    }
    let base =
        path_cache.component_world_transform_with_bounds(instance, graph, local_id, layout_bounds);
    instance
        .component_handle(local_id)
        .map(|list| {
            crate::constraints::constrain_component_list_world_transform(instance, list, base)
        })
        .unwrap_or(base)
}

fn runtime_draw_live_component_list(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    drawable: &RuntimeDrawable,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    path_cache: &mut RuntimeArtboardPathState,
    paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
    nested_paint_caches: Option<
        &mut BTreeMap<RuntimeNestedRenderCacheKey, RuntimeArtboardResourceBundle>,
    >,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    nested_ancestors: &[u32],
) -> Result<()> {
    let local_id = drawable
        .local_id
        .context("live component list is missing its local id")?;
    runtime_draw_component_list_with_state(
        runtime,
        instance,
        graph,
        artboards,
        local_id,
        drawable.global_id,
        drawable.needs_save_operation,
        factory,
        renderer,
        paint_by_global,
        path_cache,
        paint_configurations,
        nested_paint_caches,
        layout_bounds,
        nested_ancestors,
    )
}

#[allow(clippy::too_many_arguments)]
fn runtime_draw_component_list_with_state(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    artboards: &[ArtboardGraph],
    local_id: usize,
    _global_id: Option<u32>,
    needs_save_operation: bool,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
    paint_by_global: &mut RuntimeRenderPaints,
    path_cache: &mut RuntimeArtboardPathState,
    _paint_configurations: Option<&mut RuntimePaintOwnerSlots>,
    _nested_paint_caches: Option<
        &mut BTreeMap<RuntimeNestedRenderCacheKey, RuntimeArtboardResourceBundle>,
    >,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    nested_ancestors: &[u32],
) -> Result<()> {
    let Some(list_state) = instance.component_list_state(local_id) else {
        return Ok(());
    };
    let items = &list_state.items;
    // A virtualized list's row positions already include the scroll window.
    // C++ therefore draws it in its parent's world space; non-virtualized
    // lists continue to use their own world transform.
    let host_world = runtime_component_list_host_world_transform(
        instance,
        graph,
        local_id,
        layout_bounds,
        path_cache,
    );
    if needs_save_operation {
        renderer.save();
    }
    renderer.transform(runtime_render_mat(host_world));

    let item_transforms = &list_state.item_transforms;
    let order_cache =
        crate::artboard_component_list_order::runtime_component_list_order(runtime, list_state);

    for &item_index in &order_cache.indices {
        let item = &items[item_index];
        if nested_ancestors.contains(&item.child.graph_global_id) {
            continue;
        }
        let Some(child_graph) = item.child.runtime_graph().or_else(|| {
            artboards
                .iter()
                .find(|graph| graph.global_id == item.child.graph_global_id)
        }) else {
            continue;
        };
        let child = item.child.as_ref();

        renderer.save();
        renderer.transform(runtime_render_mat(item_transforms[item_index]));
        let mut resources = item.render_resources.borrow_mut();
        resources.initialize(
            paint_by_global.backend_context_id,
            runtime,
            child,
            child_graph,
            artboards,
            factory,
        );
        let RuntimeOccurrenceRenderResources {
            initialized: _,
            paints: child_paints,
            paint_configurations: child_configurations,
            preparation: child_preparation,
            nested_artboards: child_nested_artboards,
            path_cache: child_cache,
            ..
        } = &mut *resources;
        if child_preparation.is_none() {
            child.update_artboard_backend_tree_internal(
                runtime,
                child_graph,
                artboards,
                factory,
                child_paints,
                Some(child_configurations),
                Some(child_preparation),
                Some(child_nested_artboards),
                child_cache,
                false,
                true,
                nested_ancestors,
            )?;
        }
        child.prepare_static_artboard_slice_meshes(runtime, child_graph, factory, child_cache)?;
        child.draw_artboard_internal_internal_with_path_cache(
            runtime,
            child_graph,
            artboards,
            factory,
            renderer,
            child_paints,
            child_cache,
            Some(child_configurations),
            Some(child_nested_artboards),
            nested_ancestors,
        )?;
        renderer.restore();
    }

    if needs_save_operation {
        renderer.restore();
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct RuntimeAabb {
    left: f32,
    top: f32,
    width: f32,
    height: f32,
}

impl RuntimeAabb {
    fn from_artboard(instance: &ArtboardInstance) -> Self {
        Self {
            left: -instance.width * instance.origin_x,
            top: -instance.height * instance.origin_y,
            width: instance.width,
            height: instance.height,
        }
    }

    fn from_artboard_with_layout(instance: &ArtboardInstance, graph: &ArtboardGraph) -> Self {
        instance
            .retained_layout_bounds()
            .and_then(|bounds| bounds.get(&0).copied())
            .or_else(|| instance.runtime_root_artboard_layout_bounds(graph))
            .map(|bounds| Self {
                left: 0.0,
                top: 0.0,
                width: bounds.width,
                height: bounds.height,
            })
            .unwrap_or_else(|| Self::from_artboard(instance))
    }

    fn from_local_layout_bounds(bounds: RuntimeLayoutBounds) -> Self {
        Self {
            left: 0.0,
            top: 0.0,
            width: bounds.width,
            height: bounds.height,
        }
    }
}

/// Port the translation owner used by `NestedArtboardLayout::update`.
///
/// The parent solve supplies size/target bounds, but the mounted child
/// Artboard retains the current interpolated Yoga left/top. Start with the
/// ordinary host transform and replace only the solved parent-local
/// translation with that retained position, preserving authored linear
/// transforms and parent affine composition
/// (`nested_artboard_layout.cpp:53-78`; `artboard.cpp:1120-1137`).
fn runtime_nested_artboard_layout_world_transform(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    local_id: usize,
    child: &ArtboardInstance,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    path_cache: &mut RuntimeArtboardPathState,
) -> Mat2D {
    let mut world =
        path_cache.component_world_transform_with_bounds(instance, graph, local_id, layout_bounds);
    let Some((retained_x, retained_y)) = child
        .component(0)
        .and_then(|component| component.concrete.layout.as_ref())
        .map(|layout| layout.position())
    else {
        return world;
    };
    let Some(solved) = layout_bounds.and_then(|bounds| bounds.get(&local_id).copied()) else {
        return world;
    };
    let parent_local = instance.component_parent_local(local_id);
    let solved_parent_local = parent_local
        .and_then(|parent_local| {
            layout_bounds
                .and_then(|bounds| bounds.get(&parent_local).copied())
                .map(|parent| (solved.x - parent.x, solved.y - parent.y))
        })
        .unwrap_or((solved.x, solved.y));
    let parent_world = parent_local.map_or(Mat2D::IDENTITY, |parent_local| {
        path_cache.component_world_transform_with_bounds(
            instance,
            graph,
            parent_local,
            layout_bounds,
        )
    });
    let delta_x = retained_x - solved_parent_local.0;
    let delta_y = retained_y - solved_parent_local.1;
    world.0[4] += parent_world.0[0] * delta_x + parent_world.0[2] * delta_y;
    world.0[5] += parent_world.0[1] * delta_x + parent_world.0[3] * delta_y;
    world
}

fn runtime_nested_artboard_leaf_world_transform(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    local_id: usize,
    child_graph: &ArtboardGraph,
    child: Option<&ArtboardInstance>,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    path_cache: &mut RuntimeArtboardPathState,
) -> Result<Mat2D> {
    let host_world =
        path_cache.component_world_transform_with_bounds(instance, graph, local_id, layout_bounds);
    let Some(child) = child else {
        return Ok(host_world);
    };

    let frame =
        runtime_nested_artboard_leaf_frame_bounds(instance, graph, local_id, child, layout_bounds)?;
    let content = RuntimeAabb::from_artboard_with_layout(child, child_graph);
    let fit_key = runtime_draw_property_key_for_name("NestedArtboardLeaf", "fit")
        .context("missing NestedArtboardLeaf.fit")?;
    let alignment_x_key = runtime_draw_property_key_for_name("NestedArtboardLeaf", "alignmentX")
        .context("missing NestedArtboardLeaf.alignmentX")?;
    let alignment_y_key = runtime_draw_property_key_for_name("NestedArtboardLeaf", "alignmentY")
        .context("missing NestedArtboardLeaf.alignmentY")?;
    let fit = instance.uint_property(local_id, fit_key).unwrap_or(0);
    let alignment_x = instance
        .double_property(local_id, alignment_x_key)
        .unwrap_or(0.0);
    let alignment_y = instance
        .double_property(local_id, alignment_y_key)
        .unwrap_or(0.0);

    Ok(
        host_world.multiply(crate::artboard::runtime_nested_artboard_leaf_alignment(
            fit,
            alignment_x,
            alignment_y,
            (frame.left, frame.top, frame.width, frame.height),
            (content.left, content.top, content.width, content.height),
        )),
    )
}

fn runtime_nested_artboard_leaf_frame_bounds(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    local_id: usize,
    child: &ArtboardInstance,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
) -> Result<RuntimeAabb> {
    instance
        .component(local_id)
        .context("nested artboard leaf component is missing")?;
    if let Some(parent_local) = instance.component_parent_local(local_id)
        && instance
            .component(parent_local)
            .is_some_and(|parent| parent.type_name == "LayoutComponent")
    {
        let bounds = layout_bounds
            .and_then(|bounds| bounds.get(&parent_local).copied())
            .with_context(|| {
                let global = graph
                    .components
                    .iter()
                    .find(|component| component.local_id == parent_local)
                    .map(|component| component.global_id)
                    .unwrap_or_default();
                format!(
                    "nested artboard leaf local {local_id} missing parent layout bounds local {parent_local} global {global}"
                )
            })?;
        return Ok(RuntimeAabb::from_local_layout_bounds(bounds));
    }

    Ok(RuntimeAabb::from_artboard(child))
}

fn runtime_apply_nested_artboard_layout_child_bounds(
    child: &mut ArtboardInstance,
    command: &RuntimeDrawableDispatch,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
) -> Result<()> {
    if command.object_kind != RuntimeDrawableDispatchObjectKind::NestedArtboardLayout {
        return Ok(());
    }
    let local_id = command
        .local_id
        .context("nested artboard layout command missing local id")?;
    let bounds = layout_bounds
        .and_then(|bounds| bounds.get(&local_id).copied())
        .context("nested artboard layout missing Taffy bounds")?;
    let assigned_size_changed = child.set_artboard_dimensions(bounds.width, bounds.height);
    let width_changed = runtime_layout_component_property_key_for_name("width")
        .is_some_and(|key| child.set_double_property(0, key, bounds.width));
    let height_changed = runtime_layout_component_property_key_for_name("height")
        .is_some_and(|key| child.set_double_property(0, key, bounds.height));
    if assigned_size_changed
        || width_changed
        || height_changed
        || !child.layout_constraint_bounds_enabled
    {
        child.refresh_layout_constraint_bounds();
    }
    Ok(())
}

pub(crate) fn runtime_apply_component_list_item_layout_bounds(
    child: &mut ArtboardInstance,
    bounds: RuntimeLayoutBounds,
) -> bool {
    // `ArtboardComponentList::layoutNode` transfers the mounted artboard's
    // root Yoga node to the parent. The resulting width/height are therefore
    // the child's own layout constraints, not merely a draw-time frame.
    let assigned_size_changed = child.set_artboard_dimensions(bounds.width, bounds.height);
    let mut changed = assigned_size_changed || !child.layout_constraint_bounds_enabled;
    if let Some(width_key) = runtime_layout_component_property_key_for_name("width") {
        changed |= child.set_double_property(0, width_key, bounds.width);
    }
    if let Some(height_key) = runtime_layout_component_property_key_for_name("height") {
        changed |= child.set_double_property(0, height_key, bounds.height);
    }
    if changed {
        // The hosted root is still the child's LayoutComponent owner. Apply
        // the assigned root properties before the one retained constraint
        // solve so descendants observe the new row size immediately
        // (`artboard_component_list.cpp:220-260`;
        // `artboard.cpp:1138-1157`).
        child.refresh_layout_constraint_bounds();
    }
    changed
}

fn runtime_settle_nested_artboard_layout_child(child: &mut ArtboardInstance) {
    for _ in 0..100 {
        child.update_pass();
        if !child.has_dirt(ComponentDirt::COMPONENTS) {
            break;
        }
    }
}

fn runtime_draw_live_clip_start(
    instance: &ArtboardInstance,
    drawable: &RuntimeDrawable,
    backend_context_id: u64,
    factory: &mut dyn RenderFactory,
    renderer: &mut dyn Renderer,
) {
    let Some(local_id) = drawable.clipping_shape_local else {
        return;
    };
    let Some(clipping_shape) = instance.runtime_clipping_shapes.get(local_id) else {
        return;
    };
    if !instance.runtime_clipping_shape_is_visible_local(local_id) || !clipping_shape.has_path.get()
    {
        return;
    }
    if drawable.needs_save_operation {
        renderer.save();
    }
    let path = clipping_shape.path.borrow();
    clipping_shape.backend.with_path(
        backend_context_id,
        factory,
        &path,
        clipping_shape.fill_rule.get(),
        None,
        |path| renderer.clip_path(path),
    );
}

fn runtime_draw_live_clip_end(
    instance: &ArtboardInstance,
    drawable: &RuntimeDrawable,
    renderer: &mut dyn Renderer,
) {
    let Some(local_id) = drawable.clipping_shape_local else {
        return;
    };
    if instance.runtime_clipping_shape_is_visible_local(local_id) && drawable.needs_save_operation {
        renderer.restore();
    }
}

fn assign_shape_paint_path_slot_indices(commands: &mut [RuntimeShapePaintCommand]) {
    let explicit_slot_count = commands
        .iter()
        .filter_map(|command| command.text_path_bucket_slot)
        .max()
        .map_or(0, |slot| slot + 1);
    let mut path_slots = Vec::<&[RuntimePathCommand]>::new();
    for command in commands {
        let effect_or_shape_path_commands = if command.has_effect_path {
            command.effect_path_commands.as_slice()
        } else {
            command.path_commands.as_slice()
        };
        if let Some(feather) = command
            .feather_state
            .as_ref()
            .filter(|feather| feather.inner)
        {
            command.clip_path_slot_index = explicit_slot_count
                + runtime_cached_path_slot_index(&mut path_slots, effect_or_shape_path_commands);
            command.path_slot_index = explicit_slot_count
                + runtime_cached_path_slot_index(
                    &mut path_slots,
                    feather.inner_path_commands.as_slice(),
                );
        } else if let Some(slot) = command.text_path_bucket_slot {
            command.path_slot_index = slot;
            command.clip_path_slot_index = slot;
        } else {
            command.path_slot_index = explicit_slot_count
                + runtime_cached_path_slot_index(&mut path_slots, effect_or_shape_path_commands);
            command.clip_path_slot_index = command.path_slot_index;
        }
    }
}

fn runtime_text_owned_raw_paths(
    commands: &[RuntimeShapePaintCommand],
) -> BTreeMap<RuntimeTextPathOwnerKey, Arc<RawPath>> {
    let mut paths = BTreeMap::new();

    let mut retain = |key: RuntimeTextPathOwnerKey, commands: &[RuntimePathCommand]| {
        paths
            .entry(key)
            .or_insert_with(|| Arc::new(runtime_raw_path_from_commands(commands)));
    };
    for command in commands {
        let source = if command.has_effect_path {
            command.effect_path_commands.as_slice()
        } else {
            command.path_commands.as_slice()
        };
        if let Some(feather) = command
            .feather_state
            .as_ref()
            .filter(|feather| feather.inner)
        {
            retain(
                RuntimeTextPathOwnerKey {
                    // The no-effect clip is TextStylePaint's replaceable
                    // opacity bucket; an active effect supplies its retained
                    // EffectPath instead. Feather's inner draw path below is
                    // always retained (`text_style_paint.cpp:15-43`,
                    // `shape_paint.cpp:115-145`).
                    owner_local: if command.has_effect_path {
                        command.paint_local
                    } else {
                        runtime_text_style_path_owner_local(command).unwrap_or(command.paint_local)
                    },
                    replace_on_render_style_rebuild: !command.has_effect_path
                        && runtime_text_style_path_owner_local(command).is_some(),
                    slot: command.clip_path_slot_index,
                },
                source,
            );
            retain(
                RuntimeTextPathOwnerKey {
                    owner_local: command.paint_local,
                    replace_on_render_style_rebuild: false,
                    slot: command.path_slot_index,
                },
                feather.inner_path_commands.as_slice(),
            );
        } else {
            retain(
                RuntimeTextPathOwnerKey {
                    // A direct text path is TextStylePaint::m_opacityPaths and
                    // is replaced by clearRenderStyles. Effect outputs are
                    // retained by their StrokeEffect owner and rewind.
                    owner_local: if command.has_effect_path {
                        command.paint_local
                    } else {
                        runtime_text_style_path_owner_local(command).unwrap_or(command.paint_local)
                    },
                    replace_on_render_style_rebuild: !command.has_effect_path
                        && runtime_text_style_path_owner_local(command).is_some(),
                    slot: command.path_slot_index,
                },
                source,
            );
        }
    }
    paths
}

fn runtime_cached_path_slot_index<'a>(
    cache: &mut Vec<&'a [RuntimePathCommand]>,
    commands: &'a [RuntimePathCommand],
) -> usize {
    if let Some(index) = cache.iter().position(|candidate| *candidate == commands) {
        return index;
    }
    cache.push(commands);
    cache.len() - 1
}

fn runtime_render_paint_configuration(
    instance: &ArtboardInstance,
    object: &RuntimeObject,
    paint: &RuntimeShapePaintCommand,
) -> Result<RuntimeRenderPaintConfiguration> {
    let (stroke_thickness, stroke_cap, stroke_join) = match paint.paint_type {
        RuntimeShapePaintKind::Fill => (None, None, None),
        RuntimeShapePaintKind::Stroke => (
            Some(runtime_stroke_thickness(
                instance,
                object,
                paint.paint_local,
            )),
            Some(runtime_stroke_cap(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "cap",
                0,
            ))?),
            Some(runtime_stroke_join(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "join",
                0,
            ))?),
        ),
        RuntimeShapePaintKind::Unknown => anyhow::bail!("unsupported: unknown shape paint"),
    };
    let shader = if let Some(render_color) = runtime_current_solid_render_color(instance, paint) {
        RuntimeRenderPaintShaderConfiguration::SolidColor(render_color)
    } else {
        match paint.paint_state.as_ref() {
            Some(RuntimeShapePaintState::SolidColor { render_color, .. }) => {
                RuntimeRenderPaintShaderConfiguration::SolidColor(*render_color)
            }
            Some(
                RuntimeShapePaintState::LinearGradient { .. }
                | RuntimeShapePaintState::RadialGradient { .. },
            ) => RuntimeRenderPaintShaderConfiguration::PreserveGradientShader,
            None => RuntimeRenderPaintShaderConfiguration::None,
        }
    };

    Ok(RuntimeRenderPaintConfiguration {
        paint_type: paint.paint_type,
        stroke_thickness,
        stroke_cap,
        stroke_join,
        blend_mode: runtime_blend_mode(paint.render_blend_mode_value)?,
        shader,
        feather: paint
            .feather_state
            .as_ref()
            .map(|feather| feather.strength)
            .unwrap_or(0.0),
    })
}

// The paint-configuration cache epoch for a shape paint command. World-space
// paints (paint_space_transform set) bake shape world transforms into their
// shader endpoints, and keyed transform writes only bump prepared_epoch, so
// their configuration must also be keyed on it. Mirrors C++
// linear_gradient.cpp:98-106 (PathFlags::world && WorldTransform dirt).
fn runtime_paint_configuration_epoch(
    instance: &ArtboardInstance,
    paint: &RuntimeShapePaintCommand,
) -> u128 {
    if paint.paint_type == RuntimeShapePaintKind::Fill
        && paint.feather_state.is_none()
        && matches!(
            paint.paint_state,
            Some(RuntimeShapePaintState::SolidColor { .. })
        )
    {
        // C++ SolidColor dirties only its attached ShapePaint. A transform on
        // an unrelated component must not make every solid fill reconfigure.
        // Retain the same per-mutator dirt revision and combine it with the
        // command-local opacity/blend values that complete the fill state.
        let revision = paint
            .mutator_local
            .map(|local_id| instance.solid_color_paint_revision(local_id))
            .unwrap_or_default();
        return (1_u128 << 127)
            | (u128::from(revision & 0x7fff_ffff_ffff_ffff) << 64)
            | (u128::from(paint.render_blend_mode_value) << 32)
            | u128::from(paint.render_opacity.to_bits());
    }
    let cache_epoch = instance.cache_epoch();
    if paint.paint_space_transform.is_some() {
        u128::from(runtime_world_paint_configuration_epoch(instance))
    } else {
        u128::from(cache_epoch)
    }
}

fn runtime_world_paint_configuration_epoch(instance: &ArtboardInstance) -> u64 {
    (0xcbf29ce484222325u64 ^ instance.cache_epoch())
        .wrapping_mul(0x100000001b3)
        .wrapping_add(instance.prepared_epoch())
}

fn runtime_configure_paint_with_cache(
    render_paint: &mut dyn RenderPaint,
    configurations: &mut RuntimePaintOwnerSlots,
    paint_global_id: u32,
    instance: &ArtboardInstance,
    object: &RuntimeObject,
    paint: &RuntimeShapePaintCommand,
) -> Result<()> {
    let instance_epoch = runtime_paint_configuration_epoch(instance, paint);
    if configurations
        .get(paint_global_id)
        .is_some_and(|cached| cached.instance_epoch == instance_epoch)
    {
        return Ok(());
    }

    let configuration = runtime_render_paint_configuration(instance, object, paint)?;
    if let Some(cached) = configurations.get_mut(paint_global_id)
        && cached.configuration == configuration
    {
        cached.instance_epoch = instance_epoch;
        return Ok(());
    }

    runtime_configure_paint(render_paint, instance, object, paint, None)?;
    configurations.insert(
        paint_global_id,
        RuntimeCachedRenderPaintConfiguration {
            instance_epoch,
            configuration,
        },
    );
    Ok(())
}

/// Direct clone-owner translation of the ShapePaint mutator update path.
/// C++ mutates the ShapePaint-owned RenderPaint when its component dirt is
/// processed; the Rust arena keeps that backend object in a one-to-one
/// sidecar and applies the same live fields when the owner is dirty.
fn runtime_configure_owned_shape_paint(
    render_paint: &mut dyn RenderPaint,
    instance: &ArtboardInstance,
    object: &RuntimeObject,
    paint: &RuntimeShapePaintOwner,
) -> Result<()> {
    match paint.paint_type {
        RuntimeShapePaintKind::Fill => {
            render_paint.style(RenderPaintStyle::Fill);
        }
        RuntimeShapePaintKind::Stroke => {
            render_paint.style(RenderPaintStyle::Stroke);
            render_paint.thickness(runtime_stroke_thickness(
                instance,
                object,
                paint.paint_local,
            ));
            render_paint.cap(runtime_stroke_cap(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "cap",
                0,
            ))?);
            render_paint.join(runtime_stroke_join(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "join",
                0,
            ))?);
        }
        RuntimeShapePaintKind::Unknown => anyhow::bail!("unsupported: unknown shape paint"),
    }
    render_paint.blend_mode(runtime_blend_mode(
        runtime_live_owned_shape_paint_blend_mode_value(instance, paint),
    )?);
    let paint_state = paint.paint_state.borrow();
    match paint_state.as_ref() {
        Some(RuntimeShapePaintState::SolidColor { render_color, .. }) => {
            render_paint.shader(None);
            render_paint.color(*render_color);
        }
        // LinearGradient/RadialGradient own shader mutation in their
        // dependency-ordered update pass. ShapePaint only retains and draws
        // the already-attached shader.
        Some(
            RuntimeShapePaintState::LinearGradient { .. }
            | RuntimeShapePaintState::RadialGradient { .. },
        ) => {}
        None => {
            render_paint.shader(None);
        }
    }
    render_paint.feather(runtime_live_owned_shape_paint_feather_strength(
        instance, paint,
    ));
    Ok(())
}

fn runtime_configure_paint(
    render_paint: &mut dyn RenderPaint,
    instance: &ArtboardInstance,
    object: &RuntimeObject,
    paint: &RuntimeShapePaintCommand,
    gradient_resources: Option<&mut RuntimeGradientShaderResources<'_>>,
) -> Result<()> {
    match paint.paint_type {
        RuntimeShapePaintKind::Fill => {
            render_paint.style(RenderPaintStyle::Fill);
        }
        RuntimeShapePaintKind::Stroke => {
            render_paint.style(RenderPaintStyle::Stroke);
            render_paint.thickness(runtime_stroke_thickness(
                instance,
                object,
                paint.paint_local,
            ));
            render_paint.cap(runtime_stroke_cap(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "cap",
                0,
            ))?);
            render_paint.join(runtime_stroke_join(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "join",
                0,
            ))?);
        }
        RuntimeShapePaintKind::Unknown => anyhow::bail!("unsupported: unknown shape paint"),
    }
    render_paint.blend_mode(runtime_blend_mode(paint.render_blend_mode_value)?);
    if let Some(render_color) = runtime_current_solid_render_color(instance, paint) {
        render_paint.shader(None);
        render_paint.color(render_color);
    } else {
        match paint.paint_state.as_ref() {
            Some(RuntimeShapePaintState::SolidColor { render_color, .. }) => {
                render_paint.shader(None);
                render_paint.color(*render_color);
            }
            Some(
                state @ RuntimeShapePaintState::LinearGradient {
                    start_x,
                    start_y,
                    end_x,
                    end_y,
                    stops,
                    ..
                },
            ) => {
                if let Some(resources) = gradient_resources {
                    let (start_x, start_y, end_x, end_y) = runtime_gradient_space_endpoints(
                        paint.paint_space_transform,
                        *start_x,
                        *start_y,
                        *end_x,
                        *end_y,
                    );
                    let state = runtime_shape_paint_state_with_endpoints(
                        state.clone(),
                        start_x,
                        start_y,
                        end_x,
                        end_y,
                    );
                    runtime_configure_linear_gradient(
                        render_paint,
                        resources,
                        object.id,
                        state,
                        start_x,
                        start_y,
                        end_x,
                        end_y,
                        stops,
                    );
                }
            }
            Some(
                state @ RuntimeShapePaintState::RadialGradient {
                    start_x,
                    start_y,
                    end_x,
                    end_y,
                    stops,
                    ..
                },
            ) => {
                if let Some(resources) = gradient_resources {
                    let (start_x, start_y, end_x, end_y) = runtime_gradient_space_endpoints(
                        paint.paint_space_transform,
                        *start_x,
                        *start_y,
                        *end_x,
                        *end_y,
                    );
                    let state = runtime_shape_paint_state_with_endpoints(
                        state.clone(),
                        start_x,
                        start_y,
                        end_x,
                        end_y,
                    );
                    runtime_configure_radial_gradient(
                        render_paint,
                        resources,
                        object.id,
                        state,
                        start_x,
                        start_y,
                        end_x,
                        end_y,
                        stops,
                    );
                }
            }
            None => {
                render_paint.shader(None);
            }
        }
    }
    render_paint.feather(
        paint
            .feather_state
            .as_ref()
            .map(|feather| feather.strength)
            .unwrap_or(0.0),
    );
    Ok(())
}

fn runtime_configure_initial_nested_layout_paint_frame(
    frame: RuntimeInitialNestedLayoutPaintFrame,
    factory: &mut dyn RenderFactory,
    paints: &mut RuntimeRenderPaints,
    mut configurations: Option<&mut RuntimePaintOwnerSlots>,
    render_cache: &mut RuntimeArtboardPathState,
) -> Result<()> {
    for gradient in frame.gradients {
        let object_id = gradient.paint_global_id;
        let (start_x, start_y, end_x, end_y, state_opacity, stops) = match &gradient.paint_state {
            RuntimeShapePaintState::LinearGradient {
                start_x,
                start_y,
                end_x,
                end_y,
                render_opacity,
                stops,
                ..
            }
            | RuntimeShapePaintState::RadialGradient {
                start_x,
                start_y,
                end_x,
                end_y,
                render_opacity,
                stops,
                ..
            } => (
                *start_x,
                *start_y,
                *end_x,
                *end_y,
                *render_opacity,
                stops.clone(),
            ),
            RuntimeShapePaintState::SolidColor { .. } => continue,
        };
        debug_assert_eq!(state_opacity, gradient.inherited_opacity);
        let (start_x, start_y, end_x, end_y) = runtime_gradient_space_endpoints(
            gradient.paint_space_transform,
            start_x,
            start_y,
            end_x,
            end_y,
        );
        let paint_state = runtime_shape_paint_state_with_endpoints(
            gradient.paint_state,
            start_x,
            start_y,
            end_x,
            end_y,
        );
        let mut resources = RuntimeGradientShaderResources {
            factory,
            shaders: &mut render_cache.gradient_shaders,
        };
        let render_paint = paints
            .paint_mut(gradient.paint_global_id)
            .with_context(|| {
                format!(
                    "missing render paint for initial nested layout gradient {}",
                    gradient.paint_global_id
                )
            })?
            .as_mut();
        if let Some(configurations) = configurations.as_deref_mut() {
            configurations.remove(gradient.paint_global_id);
        }
        match paint_state {
            state @ RuntimeShapePaintState::LinearGradient { .. } => {
                runtime_configure_linear_gradient(
                    render_paint,
                    &mut resources,
                    object_id,
                    state,
                    start_x,
                    start_y,
                    end_x,
                    end_y,
                    &stops,
                );
            }
            state @ RuntimeShapePaintState::RadialGradient { .. } => {
                runtime_configure_radial_gradient(
                    render_paint,
                    &mut resources,
                    object_id,
                    state,
                    start_x,
                    start_y,
                    end_x,
                    end_y,
                    &stops,
                );
            }
            RuntimeShapePaintState::SolidColor { .. } => {}
        }
    }
    Ok(())
}

fn runtime_current_solid_render_color(
    instance: &ArtboardInstance,
    paint: &RuntimeShapePaintCommand,
) -> Option<u32> {
    match paint.paint_state.as_ref()? {
        RuntimeShapePaintState::SolidColor { color, .. } => {
            let color = paint
                .mutator_local
                .and_then(|local_id| instance.solid_color_value(local_id))
                .unwrap_or(*color);
            Some(color_modulate_opacity(color, paint.render_opacity))
        }
        RuntimeShapePaintState::LinearGradient { .. }
        | RuntimeShapePaintState::RadialGradient { .. } => None,
    }
}

// Ported from src/shapes/paint/linear_gradient.cpp and radial_gradient.cpp.
fn runtime_configure_linear_gradient(
    render_paint: &mut dyn RenderPaint,
    resources: &mut RuntimeGradientShaderResources<'_>,
    paint_global_id: u32,
    state: RuntimeShapePaintState,
    start_x: f32,
    start_y: f32,
    end_x: f32,
    end_y: f32,
    stops: &[RuntimeGradientStop],
) {
    let shader = runtime_cached_gradient_shader(resources, paint_global_id, state, |factory| {
        let colors = stops
            .iter()
            .map(|stop| stop.render_color)
            .collect::<Vec<_>>();
        let positions = stops.iter().map(|stop| stop.position).collect::<Vec<_>>();
        factory.make_linear_gradient(start_x, start_y, end_x, end_y, &colors, &positions)
    });
    render_paint.shader(Some(shader));
}

fn runtime_configure_radial_gradient(
    render_paint: &mut dyn RenderPaint,
    resources: &mut RuntimeGradientShaderResources<'_>,
    paint_global_id: u32,
    state: RuntimeShapePaintState,
    start_x: f32,
    start_y: f32,
    end_x: f32,
    end_y: f32,
    stops: &[RuntimeGradientStop],
) {
    let radius = crate::shapes::paint::radial_gradient::radius(start_x, start_y, end_x, end_y);
    let shader = runtime_cached_gradient_shader(resources, paint_global_id, state, |factory| {
        let colors = stops
            .iter()
            .map(|stop| stop.render_color)
            .collect::<Vec<_>>();
        let positions = stops.iter().map(|stop| stop.position).collect::<Vec<_>>();
        factory.make_radial_gradient(start_x, start_y, radius, &colors, &positions)
    });
    render_paint.shader(Some(shader));
}

fn runtime_shape_paint_state_with_endpoints(
    mut state: RuntimeShapePaintState,
    start_x: f32,
    start_y: f32,
    end_x: f32,
    end_y: f32,
) -> RuntimeShapePaintState {
    match &mut state {
        RuntimeShapePaintState::LinearGradient {
            start_x: state_start_x,
            start_y: state_start_y,
            end_x: state_end_x,
            end_y: state_end_y,
            ..
        }
        | RuntimeShapePaintState::RadialGradient {
            start_x: state_start_x,
            start_y: state_start_y,
            end_x: state_end_x,
            end_y: state_end_y,
            ..
        } => {
            *state_start_x = start_x;
            *state_start_y = start_y;
            *state_end_x = end_x;
            *state_end_y = end_y;
        }
        RuntimeShapePaintState::SolidColor { .. } => {}
    }
    state
}

fn runtime_deform_gradient_paint_state_with_nsliced_node(
    instance: &ArtboardInstance,
    graph: &ArtboardGraph,
    container: &ShapePaintContainerNode,
    layout_bounds: Option<&BTreeMap<usize, RuntimeLayoutBounds>>,
    shape_world: Mat2D,
    state: Option<RuntimeShapePaintState>,
) -> Option<RuntimeShapePaintState> {
    let state = state?;
    let Some(context) = n_sliced_node::runtime_nsliced_node_context_for_shape(
        instance,
        graph,
        container.local_id,
        layout_bounds,
    ) else {
        return Some(state);
    };
    let Some(inverse_shape_world) = runtime_mat2d_invert(shape_world) else {
        return Some(state);
    };

    let (start_x, start_y, end_x, end_y) = match &state {
        RuntimeShapePaintState::LinearGradient {
            start_x,
            start_y,
            end_x,
            end_y,
            ..
        }
        | RuntimeShapePaintState::RadialGradient {
            start_x,
            start_y,
            end_x,
            end_y,
            ..
        } => {
            let original_start_x = *start_x;
            let original_start_y = *start_y;
            let original_end_x = *end_x;
            let original_end_y = *end_y;
            let (start_x, start_y) =
                n_sliced_node::runtime_deform_local_gradient_point_with_nsliced_node(
                    original_start_x,
                    original_start_y,
                    &context,
                    shape_world,
                    inverse_shape_world,
                );
            let (end_x, end_y) =
                n_sliced_node::runtime_deform_local_gradient_point_with_nsliced_node(
                    original_end_x,
                    original_end_y,
                    &context,
                    shape_world,
                    inverse_shape_world,
                );
            (start_x, start_y, end_x, end_y)
        }
        RuntimeShapePaintState::SolidColor { .. } => return Some(state),
    };

    Some(runtime_shape_paint_state_with_endpoints(
        state, start_x, start_y, end_x, end_y,
    ))
}

fn runtime_cached_gradient_shader<'a>(
    resources: &'a mut RuntimeGradientShaderResources<'_>,
    paint_global_id: u32,
    state: RuntimeShapePaintState,
    create: impl FnOnce(&mut dyn RenderFactory) -> Box<dyn RenderShader>,
) -> &'a dyn RenderShader {
    let needs_shader = resources
        .shaders
        .get(&paint_global_id)
        .is_none_or(|entry| entry.state != state);
    if needs_shader {
        let shader = create(resources.factory);
        resources.shaders.insert(
            paint_global_id,
            RuntimeGradientShaderCacheEntry { state, shader },
        );
    }
    resources
        .shaders
        .get(&paint_global_id)
        .expect("gradient shader cache entry was inserted")
        .shader
        .as_ref()
}

pub(crate) fn runtime_fill_rule_for_value(value: u64) -> RenderFillRule {
    crate::shapes::paint::fill::fill_rule(value)
}

// C++ reads the live fillRule property on every draw
// (shape_paint.cpp:176-180); the value baked into the import-time graph
// snapshot goes stale after a runtime Fill.fillRule write, exactly like
// stroke thickness/cap/join. Non-Fill paints have no fillRule property and
// keep the imported value.
fn runtime_live_shape_paint_fill_rule(
    instance: &ArtboardInstance,
    paint: &ShapePaintNode,
) -> RenderFillRule {
    let live_value = runtime_draw_property_key_for_name("Fill", "fillRule")
        .and_then(|key| instance.uint_property(paint.local_id, key))
        .unwrap_or(paint.fill_rule);
    runtime_fill_rule_for_value(live_value)
}

fn runtime_make_path_from_raw_path(
    factory: &mut dyn RenderFactory,
    raw_path: &RawPath,
    fill_rule: RenderFillRule,
) -> Box<dyn RenderPath> {
    let mut path = factory.make_empty_render_path();
    // C++ `ShapePaintPath::renderPath` materializes in this exact order:
    // makeEmptyRenderPath, addRawPath, then apply the path's fill rule
    // (`src/shapes/paint/shape_paint_path.cpp:61-66`). Rewind belongs only to
    // the dirty retained-path branch (`shape_paint_path.cpp:68-72`).
    path.add_raw_path(raw_path);
    path.fill_rule(fill_rule);
    path
}

fn runtime_cached_retained_render_path<'a>(
    slot: &'a mut Option<RuntimeRetainedRenderPath>,
    key: RuntimeRetainedRenderPathCacheKey,
    factory: &mut dyn RenderFactory,
    commands: &[RuntimePathCommand],
) -> &'a mut Box<dyn RenderPath> {
    let cached = slot.get_or_insert_with(|| {
        let raw_path = runtime_raw_path_from_commands(commands);
        RuntimeRetainedRenderPath {
            path: runtime_make_path_from_raw_path(factory, &raw_path, key.fill_rule),
            raw_path,
            key,
        }
    });
    if cached.key != key {
        runtime_rebuild_raw_path_from_commands(&mut cached.raw_path, commands);
        runtime_rebuild_path_from_raw_path(cached.path.as_mut(), &cached.raw_path, key.fill_rule);
        cached.key = key;
    }
    &mut cached.path
}

fn runtime_cached_retained_render_path_with_commands<'a>(
    slot: &'a mut Option<RuntimeRetainedRenderPath>,
    key: RuntimeRetainedRenderPathCacheKey,
    factory: &mut dyn RenderFactory,
    commands: impl FnOnce() -> Vec<RuntimePathCommand>,
) -> &'a mut Box<dyn RenderPath> {
    if slot.as_ref().is_none_or(|cached| cached.key != key) {
        let commands = commands();
        match slot {
            Some(cached) => {
                runtime_rebuild_raw_path_from_commands(&mut cached.raw_path, &commands);
                runtime_rebuild_path_from_raw_path(
                    cached.path.as_mut(),
                    &cached.raw_path,
                    key.fill_rule,
                );
                cached.key = key;
            }
            None => {
                let raw_path = runtime_raw_path_from_commands(&commands);
                *slot = Some(RuntimeRetainedRenderPath {
                    path: runtime_make_path_from_raw_path(factory, &raw_path, key.fill_rule),
                    raw_path,
                    key,
                });
            }
        }
    }
    &mut slot
        .as_mut()
        .expect("retained render path was just populated")
        .path
}

fn runtime_rebuild_path_from_raw_path(
    path: &mut dyn RenderPath,
    raw_path: &RawPath,
    fill_rule: RenderFillRule,
) {
    path.rewind();
    path.reserve(raw_path.verbs().len(), raw_path.points().len());
    path.fill_rule(fill_rule);
    path.add_raw_path(raw_path);
}

// Contract with host renderers: RenderPath::rewind clears geometry but
// preserves the previously applied fill rule (C++ ShapePaintPath::renderPath
// likewise rewinds without re-applying it, shape_paint_path.cpp). The
// draw-time fill-rule replay skips redundant fill_rule() calls on that
// assumption.
fn runtime_rebuild_path_from_raw_path_preserving_fill_rule(
    path: &mut dyn RenderPath,
    raw_path: &RawPath,
) {
    path.rewind();
    path.reserve(raw_path.verbs().len(), raw_path.points().len());
    path.add_raw_path(raw_path);
}

#[inline]
fn record_runtime_draw_path_command_replay() {
    #[cfg(test)]
    RUNTIME_DRAW_PATH_COMMAND_REPLAYS.with(|calls| calls.set(calls.get() + 1));
}

#[cfg(test)]
std::thread_local! {
    static RUNTIME_DRAW_PATH_COMMAND_REPLAYS: std::cell::Cell<usize> = const {
        std::cell::Cell::new(0)
    };
}

#[cfg(test)]
fn reset_runtime_draw_path_command_replays() {
    RUNTIME_DRAW_PATH_COMMAND_REPLAYS.with(|calls| calls.set(0));
}

#[cfg(test)]
fn runtime_draw_path_command_replays() -> usize {
    RUNTIME_DRAW_PATH_COMMAND_REPLAYS.with(std::cell::Cell::get)
}

pub(crate) fn transform_path_commands(commands: &mut [RuntimePathCommand], transform: Mat2D) {
    if transform == Mat2D::IDENTITY {
        return;
    }
    let [a, b, c, d, e, f] = transform.0;
    if b == 0.0 && c == 0.0 {
        transform_path_commands_scale_translate(commands, a, d, e, f);
    } else {
        transform_path_commands_affine(commands, a, b, c, d, e, f);
    }
}

fn transform_path_commands_scale_translate(
    commands: &mut [RuntimePathCommand],
    a: f32,
    d: f32,
    e: f32,
    f: f32,
) {
    for command in commands {
        match command {
            RuntimePathCommand::Move { x, y } | RuntimePathCommand::Line { x, y } => {
                *x = a.mul_add(*x, e);
                *y = d.mul_add(*y, f);
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                *x1 = a.mul_add(*x1, e);
                *y1 = d.mul_add(*y1, f);
                *x2 = a.mul_add(*x2, e);
                *y2 = d.mul_add(*y2, f);
                *x3 = a.mul_add(*x3, e);
                *y3 = d.mul_add(*y3, f);
            }
            RuntimePathCommand::Close => {}
        }
    }
}

fn transform_path_commands_affine(
    commands: &mut [RuntimePathCommand],
    a: f32,
    b: f32,
    c: f32,
    d: f32,
    e: f32,
    f: f32,
) {
    for command in commands {
        match command {
            RuntimePathCommand::Move { x, y } | RuntimePathCommand::Line { x, y } => {
                let (next_x, next_y) = map_point_affine(*x, *y, a, b, c, d, e, f);
                *x = next_x;
                *y = next_y;
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                (*x1, *y1) = map_point_affine(*x1, *y1, a, b, c, d, e, f);
                (*x2, *y2) = map_point_affine(*x2, *y2, a, b, c, d, e, f);
                (*x3, *y3) = map_point_affine(*x3, *y3, a, b, c, d, e, f);
            }
            RuntimePathCommand::Close => {}
        }
    }
}

fn append_transformed_path_commands(
    destination: &mut Vec<RuntimePathCommand>,
    source: &[RuntimePathCommand],
    transform: Mat2D,
) {
    destination.reserve(source.len());
    if transform == Mat2D::IDENTITY {
        destination.extend_from_slice(source);
        return;
    }
    let [a, b, c, d, e, f] = transform.0;
    if b == 0.0 && c == 0.0 {
        append_scale_translate_path_commands(destination, source, a, d, e, f);
    } else {
        append_affine_path_commands(destination, source, a, b, c, d, e, f);
    }
}

fn append_scale_translate_path_commands(
    destination: &mut Vec<RuntimePathCommand>,
    source: &[RuntimePathCommand],
    a: f32,
    d: f32,
    e: f32,
    f: f32,
) {
    for command in source {
        destination.push(match *command {
            RuntimePathCommand::Move { x, y } => RuntimePathCommand::Move {
                x: a.mul_add(x, e),
                y: d.mul_add(y, f),
            },
            RuntimePathCommand::Line { x, y } => RuntimePathCommand::Line {
                x: a.mul_add(x, e),
                y: d.mul_add(y, f),
            },
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => RuntimePathCommand::Cubic {
                x1: a.mul_add(x1, e),
                y1: d.mul_add(y1, f),
                x2: a.mul_add(x2, e),
                y2: d.mul_add(y2, f),
                x3: a.mul_add(x3, e),
                y3: d.mul_add(y3, f),
            },
            RuntimePathCommand::Close => RuntimePathCommand::Close,
        });
    }
}

fn append_affine_path_commands(
    destination: &mut Vec<RuntimePathCommand>,
    source: &[RuntimePathCommand],
    a: f32,
    b: f32,
    c: f32,
    d: f32,
    e: f32,
    f: f32,
) {
    for command in source {
        destination.push(match *command {
            RuntimePathCommand::Move { x, y } => {
                let (x, y) = map_point_affine(x, y, a, b, c, d, e, f);
                RuntimePathCommand::Move { x, y }
            }
            RuntimePathCommand::Line { x, y } => {
                let (x, y) = map_point_affine(x, y, a, b, c, d, e, f);
                RuntimePathCommand::Line { x, y }
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                let (x1, y1) = map_point_affine(x1, y1, a, b, c, d, e, f);
                let (x2, y2) = map_point_affine(x2, y2, a, b, c, d, e, f);
                let (x3, y3) = map_point_affine(x3, y3, a, b, c, d, e, f);
                RuntimePathCommand::Cubic {
                    x1,
                    y1,
                    x2,
                    y2,
                    x3,
                    y3,
                }
            }
            RuntimePathCommand::Close => RuntimePathCommand::Close,
        });
    }
}

fn map_point_affine(x: f32, y: f32, a: f32, b: f32, c: f32, d: f32, e: f32, f: f32) -> (f32, f32) {
    (a.mul_add(x, c.mul_add(y, e)), d.mul_add(y, b.mul_add(x, f)))
}

fn runtime_rect_commands(left: f32, top: f32, right: f32, bottom: f32) -> Vec<RuntimePathCommand> {
    vec![
        RuntimePathCommand::Move { x: left, y: top },
        RuntimePathCommand::Line { x: right, y: top },
        RuntimePathCommand::Line {
            x: right,
            y: bottom,
        },
        RuntimePathCommand::Line { x: left, y: bottom },
        RuntimePathCommand::Close,
    ]
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_text_clip_path_commands(
    clip: StaticTextClipBounds,
    text_world: Mat2D,
) -> Vec<RuntimePathCommand> {
    let (left, top, width, height) = clip.bounds;
    let mut commands = runtime_rect_commands(left, top, left + width, top + height);
    transform_path_commands(&mut commands, text_world.multiply(clip.local_transform));
    commands
}

pub(crate) fn runtime_render_mat(mat: Mat2D) -> RenderMat2D {
    RenderMat2D(mat.0)
}

pub(crate) fn runtime_translation(x: f32, y: f32) -> RenderMat2D {
    RenderMat2D([1.0, 0.0, 0.0, 1.0, x, y])
}

pub(crate) fn runtime_feather_uses_world_space(feather: &RuntimeFeatherState) -> bool {
    feather.space_value == 0
}

pub(crate) fn runtime_feather_has_offset(feather: &RuntimeFeatherState) -> bool {
    feather.offset_x != 0.0 || feather.offset_y != 0.0
}

fn mat2d_linear_is_identity(mat: Mat2D) -> bool {
    mat.0[0] == 1.0 && mat.0[1] == 0.0 && mat.0[2] == 0.0 && mat.0[3] == 1.0
}

fn runtime_blend_mode(value: u32) -> Result<RenderBlendMode> {
    // C++ `Drawable::onAddedDirty` casts the generated CoreUint through
    // `BlendMode : unsigned char`; later property writes keep that narrowing.
    Ok(match value as u8 {
        3 => RenderBlendMode::SrcOver,
        14 => RenderBlendMode::Screen,
        15 => RenderBlendMode::Overlay,
        16 => RenderBlendMode::Darken,
        17 => RenderBlendMode::Lighten,
        18 => RenderBlendMode::ColorDodge,
        19 => RenderBlendMode::ColorBurn,
        20 => RenderBlendMode::HardLight,
        21 => RenderBlendMode::SoftLight,
        22 => RenderBlendMode::Difference,
        23 => RenderBlendMode::Exclusion,
        24 => RenderBlendMode::Multiply,
        25 => RenderBlendMode::Hue,
        26 => RenderBlendMode::Saturation,
        27 => RenderBlendMode::Color,
        28 => RenderBlendMode::Luminosity,
        _ => anyhow::bail!("unsupported blend mode {value}"),
    })
}

pub(crate) fn runtime_shape_paint_command(
    artboard: &ArtboardInstance,
    paint: &ShapePaintNode,
    container_blend_mode_value: u32,
    needs_save_operation: bool,
    render_opacity: f32,
    shape_world: Mat2D,
    path_commands: Vec<RuntimePathCommand>,
    require_effective_visible: bool,
    suppress_authored_transparent: bool,
    aliases_local_clockwise_path: bool,
) -> Option<RuntimeShapePaintCommand> {
    let mut path_commands = path_commands;
    prune_empty_path_segments(&mut path_commands);
    let effect_path_commands = runtime_effect_path_commands(artboard, paint, &path_commands);
    runtime_shape_paint_command_with_effect_path(
        artboard,
        paint,
        container_blend_mode_value,
        needs_save_operation,
        render_opacity,
        shape_world,
        path_commands,
        effect_path_commands,
        require_effective_visible,
        suppress_authored_transparent,
        aliases_local_clockwise_path,
    )
}

#[allow(clippy::too_many_arguments)]
fn runtime_shape_paint_command_with_effect_path(
    artboard: &ArtboardInstance,
    paint: &ShapePaintNode,
    container_blend_mode_value: u32,
    needs_save_operation: bool,
    render_opacity: f32,
    shape_world: Mat2D,
    path_commands: Vec<RuntimePathCommand>,
    effect_path_commands: Option<Vec<RuntimePathCommand>>,
    require_effective_visible: bool,
    suppress_authored_transparent: bool,
    aliases_local_clockwise_path: bool,
) -> Option<RuntimeShapePaintCommand> {
    if !runtime_shape_paint_is_visible(artboard, paint) {
        return None;
    }
    let paint_state = runtime_shape_paint_state(artboard, paint, render_opacity);
    if require_effective_visible && !runtime_shape_paint_state_is_effectively_visible(&paint_state)
    {
        return None;
    }
    if suppress_authored_transparent && !runtime_shape_paint_state_is_visible(&paint_state) {
        return None;
    }
    let has_effect_path = effect_path_commands.is_some();
    let mut effect_path_commands = effect_path_commands.unwrap_or_default();
    prune_empty_path_segments(&mut effect_path_commands);
    let feather_path_commands = if has_effect_path {
        effect_path_commands.as_slice()
    } else {
        path_commands.as_slice()
    };
    let mut feather_state = runtime_feather_state(
        artboard,
        paint.feather.as_ref(),
        feather_path_commands,
        shape_world,
        paint.paint_type == ShapePaintKind::Fill,
    );
    if let Some(feather_state) = feather_state.as_mut() {
        prune_empty_path_segments(&mut feather_state.inner_path_commands);
    }
    let path_kind = runtime_live_shape_paint_path_kind(artboard, paint)?;
    Some(RuntimeShapePaintCommand {
        paint_local: paint.local_id,
        paint_global_id: paint.global_id,
        mutator_local: paint.mutator_local,
        paint_type: runtime_shape_paint_kind(paint.paint_type),
        fill_rule: runtime_live_shape_paint_fill_rule(artboard, paint),
        path_kind,
        path_slot_index: 0,
        clip_path_slot_index: 0,
        blend_mode_value: paint.blend_mode_value,
        render_blend_mode_value: runtime_shape_paint_blend_mode_value(
            paint.blend_mode_value,
            container_blend_mode_value,
        ),
        render_opacity,
        paint_state,
        feather_state,
        paint_space_transform: runtime_shape_paint_space_transform(path_kind, shape_world),
        path_commands,
        effect_path_commands,
        has_effect_path,
        needs_save_operation,
        shape_world_override: None,
        aliases_local_clockwise_path,
        uses_temporary_paint: false,
        text_path_bucket_slot: None,
        text_path_bucket_opacity: None,
        text_paint_ref: None,
        text_paint_pool: None,
        ensure_text_paint_pool_after_draw: None,
    })
}

fn runtime_shape_paint_is_visible(artboard: &ArtboardInstance, paint: &ShapePaintNode) -> bool {
    let Some(property_key) = shape_paint_is_visible_property_key() else {
        return paint.is_visible;
    };
    match paint.paint_type {
        ShapePaintKind::Fill | ShapePaintKind::Unknown => artboard
            .bool_property(paint.local_id, property_key)
            .unwrap_or(paint.is_visible),
        ShapePaintKind::Stroke => {
            artboard
                .bool_property(paint.local_id, property_key)
                .unwrap_or(paint.is_visible)
                && runtime_stroke_thickness_for_local(artboard, paint.local_id).unwrap_or(1.0) > 0.0
        }
    }
}

pub(crate) fn runtime_owned_shape_paint_is_visible(
    artboard: &ArtboardInstance,
    paint: &RuntimeShapePaintOwner,
) -> bool {
    // Pinned C++ reaches the concrete generated Fill/Stroke members through
    // the retained ShapePaint pointer (`shape_paint.cpp:78-191`). The typed
    // arena accessor is that same owner read; no CoreRegistry redispatch.
    let visible = artboard
        .shape_paint_is_visible(paint.paint_local)
        .unwrap_or(true);
    visible
        && (paint.paint_type != RuntimeShapePaintKind::Stroke
            || artboard.stroke_thickness(paint.paint_local).unwrap_or(1.0) > 0.0)
}

fn runtime_shape_paint_state_is_visible(state: &Option<RuntimeShapePaintState>) -> bool {
    // C++ skips authored-transparent Backboard/background draws, while
    // render-opacity-transparent backgrounds can still appear in the stream.
    !matches!(
        state,
        Some(RuntimeShapePaintState::SolidColor { color, .. })
            if !crate::shapes::paint::solid_color::authored_color_is_visible(*color)
    )
}

fn runtime_shape_paint_state_is_effectively_visible(
    state: &Option<RuntimeShapePaintState>,
) -> bool {
    match state {
        Some(RuntimeShapePaintState::SolidColor { render_color, .. }) => (render_color >> 24) != 0,
        Some(RuntimeShapePaintState::LinearGradient { stops, .. })
        | Some(RuntimeShapePaintState::RadialGradient { stops, .. }) => {
            stops.iter().any(|stop| (stop.render_color >> 24) != 0)
        }
        None => true,
    }
}

impl ArtboardInstance {
    /// Direct counterpart of C++ `Artboard::isTranslucent`, consumed by
    /// `StaticScene::isTranslucent`.
    pub(crate) fn runtime_is_translucent(&self) -> bool {
        self.runtime_shapes
            .paint_owner_refs
            .iter()
            .all(|owner_ref| {
                let Some(owner) = self
                    .runtime_shapes
                    .get(owner_ref.shape_local)
                    .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
                else {
                    return true;
                };
                // ShapePaint::isTranslucent calls the concrete virtual
                // Fill/Stroke::isVisible implementation. In particular,
                // Stroke::isVisible also requires positive thickness.
                if !runtime_owned_shape_paint_is_visible(self, owner) {
                    return true;
                }
                match owner.paint_state.borrow().as_ref() {
                    // This deliberately preserves pinned SolidColor's `if` /
                    // `else if` flag update: every nonzero solid is classified as
                    // opaque, including a partially transparent one.
                    Some(RuntimeShapePaintState::SolidColor { render_color, .. }) => {
                        (render_color >> 24) == 0
                    }
                    Some(RuntimeShapePaintState::LinearGradient { stops, .. })
                    | Some(RuntimeShapePaintState::RadialGradient { stops, .. }) => {
                        let visible = stops.iter().any(|stop| (stop.render_color >> 24) != 0);
                        let translucent = stops
                            .iter()
                            .any(|stop| (stop.render_color >> 24) != u32::from(u8::MAX));
                        !visible || translucent
                    }
                    None => true,
                }
            })
    }
}

fn runtime_shape_paint_blend_mode_value(
    paint_blend_mode_value: u32,
    container_blend_mode_value: u32,
) -> u32 {
    crate::shapes::paint::shape_paint::blend_mode(
        paint_blend_mode_value,
        container_blend_mode_value,
    )
}

fn runtime_live_owned_shape_paint_blend_mode_value(
    instance: &ArtboardInstance,
    paint: &RuntimeShapePaintOwner,
) -> u32 {
    let paint_blend_mode_value = instance
        .shape_paint_blend_mode_value(paint.paint_local)
        .and_then(|value| u32::try_from(value).ok())
        .unwrap_or(paint.authored_blend_mode_value);
    // TextStylePaint::draw copies the concrete Text drawable's blend mode to
    // each child ShapePaint before drawing (`text_style_paint.cpp:51-55`).
    // Text-input paint containers follow the same split ownership: the
    // ShapePaint owns RenderPaint while the concrete text drawable owns the
    // inherited opacity/blend state.
    let blend_owner_local = instance
        .runtime_shapes
        .get(paint.container_local)
        .and_then(|container| container.opacity_owner_local)
        .unwrap_or(paint.container_local);
    let container_blend_mode_value =
        runtime_draw_property_key_for_name("Drawable", "blendModeValue")
            .and_then(|key| instance.uint_property(blend_owner_local, key))
            .and_then(|value| u32::try_from(value).ok())
            .unwrap_or(3);
    runtime_shape_paint_blend_mode_value(paint_blend_mode_value, container_blend_mode_value)
}

/// C++ `Feather::update(Paint)` writes the authored/live strength directly to
/// its parent ShapePaint's retained RenderPaint. That write is independent of
/// whether the concrete container owns Shape geometry: TextStylePaint and the
/// TextInput paint containers keep their paths elsewhere but still inherit the
/// same ShapePaint RenderPaint member.
fn runtime_live_owned_shape_paint_feather_strength(
    instance: &ArtboardInstance,
    paint: &RuntimeShapePaintOwner,
) -> f32 {
    instance
        .runtime_graph()
        .and_then(|graph| {
            let container_index = instance
                .runtime_shapes
                .get(paint.container_local)?
                .paint_container_index?;
            graph
                .shape_paint_containers
                .get(container_index)?
                .paints
                .get(paint.paint_index)?
                .feather
                .as_ref()
        })
        .map(|feather| {
            runtime_feather_double_property(instance, feather, "strength", feather.strength)
        })
        .unwrap_or(0.0)
}

fn runtime_shape_paint_kind(kind: ShapePaintKind) -> RuntimeShapePaintKind {
    match kind {
        ShapePaintKind::Fill => RuntimeShapePaintKind::Fill,
        ShapePaintKind::Stroke => RuntimeShapePaintKind::Stroke,
        ShapePaintKind::Unknown => RuntimeShapePaintKind::Unknown,
    }
}

fn runtime_shape_paint_path_kind(kind: ShapePaintPathKind) -> Option<RuntimeShapePaintPathKind> {
    match kind {
        ShapePaintPathKind::Local => Some(RuntimeShapePaintPathKind::Local),
        ShapePaintPathKind::LocalClockwise => Some(RuntimeShapePaintPathKind::LocalClockwise),
        ShapePaintPathKind::World => Some(RuntimeShapePaintPathKind::World),
    }
}

pub(crate) fn runtime_live_shape_paint_path_kind(
    artboard: &ArtboardInstance,
    paint: &ShapePaintNode,
) -> Option<RuntimeShapePaintPathKind> {
    match paint.paint_type {
        ShapePaintKind::Fill => Some(crate::shapes::paint::fill::pick_path(
            runtime_live_shape_paint_fill_rule(artboard, paint),
        )),
        ShapePaintKind::Stroke => {
            let transform_affects_stroke =
                runtime_draw_property_key_for_name("Stroke", "transformAffectsStroke")
                    .and_then(|key| artboard.bool_property(paint.local_id, key))
                    .unwrap_or(paint.path_kind == Some(ShapePaintPathKind::Local));
            Some(if transform_affects_stroke {
                RuntimeShapePaintPathKind::Local
            } else {
                RuntimeShapePaintPathKind::World
            })
        }
        ShapePaintKind::Unknown => paint.path_kind.and_then(runtime_shape_paint_path_kind),
    }
}

pub(crate) fn runtime_live_owned_shape_paint_path_kind(
    artboard: &ArtboardInstance,
    paint: &RuntimeShapePaintOwner,
) -> RuntimeShapePaintPathKind {
    match paint.paint_type {
        RuntimeShapePaintKind::Fill => {
            let fill_rule = artboard
                .fill_rule(paint.paint_local)
                .map(runtime_fill_rule_for_value)
                .unwrap_or(paint.authored_fill_rule);
            crate::shapes::paint::fill::pick_path(fill_rule)
        }
        RuntimeShapePaintKind::Stroke => {
            let transform_affects_stroke = artboard
                .stroke_transform_affects_stroke(paint.paint_local)
                .unwrap_or(matches!(
                    paint.authored_path_kind,
                    RuntimeShapePaintPathKind::Local | RuntimeShapePaintPathKind::LocalClockwise
                ));
            if transform_affects_stroke {
                RuntimeShapePaintPathKind::Local
            } else {
                RuntimeShapePaintPathKind::World
            }
        }
        RuntimeShapePaintKind::Unknown => paint.authored_path_kind,
    }
}

fn runtime_shape_paint_space_transform(
    path_kind: RuntimeShapePaintPathKind,
    shape_world: Mat2D,
) -> Option<Mat2D> {
    (path_kind == RuntimeShapePaintPathKind::World).then_some(shape_world)
}

fn runtime_shape_paint_state(
    artboard: &ArtboardInstance,
    paint: &ShapePaintNode,
    render_opacity: f32,
) -> Option<RuntimeShapePaintState> {
    match paint.paint_state.clone()? {
        ShapePaintStateNode::SolidColor { color } => {
            let color = paint
                .mutator_local
                .zip(solid_color_value_property_key())
                .and_then(|(local_id, property_key)| {
                    artboard.color_property(local_id, property_key)
                })
                .unwrap_or(color);
            Some(RuntimeShapePaintState::SolidColor {
                color,
                render_color: color_modulate_opacity(color, render_opacity),
            })
        }
        ShapePaintStateNode::LinearGradient {
            start_x,
            start_y,
            end_x,
            end_y,
            opacity,
            stops,
        } => {
            let opacity = paint
                .mutator_local
                .map(|mutator_local| {
                    runtime_gradient_double_property(
                        artboard,
                        mutator_local,
                        "LinearGradient",
                        "opacity",
                        opacity,
                    )
                })
                .unwrap_or(opacity);
            let (start_x, start_y, end_x, end_y) = runtime_gradient_endpoints(
                artboard,
                paint.mutator_local,
                "LinearGradient",
                start_x,
                start_y,
                end_x,
                end_y,
            );
            Some(RuntimeShapePaintState::LinearGradient {
                start_x,
                start_y,
                end_x,
                end_y,
                opacity,
                render_opacity,
                stops: runtime_gradient_stops(artboard, stops, opacity * render_opacity),
            })
        }
        ShapePaintStateNode::RadialGradient {
            start_x,
            start_y,
            end_x,
            end_y,
            opacity,
            stops,
        } => {
            let opacity = paint
                .mutator_local
                .map(|mutator_local| {
                    runtime_gradient_double_property(
                        artboard,
                        mutator_local,
                        "RadialGradient",
                        "opacity",
                        opacity,
                    )
                })
                .unwrap_or(opacity);
            let (start_x, start_y, end_x, end_y) = runtime_gradient_endpoints(
                artboard,
                paint.mutator_local,
                "RadialGradient",
                start_x,
                start_y,
                end_x,
                end_y,
            );
            Some(RuntimeShapePaintState::RadialGradient {
                start_x,
                start_y,
                end_x,
                end_y,
                opacity,
                render_opacity,
                stops: runtime_gradient_stops(artboard, stops, opacity * render_opacity),
            })
        }
    }
}

// C++ ShapePaintMutator owns its inherited opacity independently of the
// TransformComponent. A newly mounted zero-opacity artboard can leave a
// descendant's RenderOpacity dirt pending; until Shape::update propagates it,
// the gradient mutator retains its default opacity of 1. Preserve the last
// shader value in that state instead of eagerly reading the transform's
// not-yet-propagated value.
fn runtime_retained_gradient_render_opacity(
    instance: &ArtboardInstance,
    opacity_local: usize,
    paint_global_id: u32,
    render_cache: &RuntimeArtboardPathState,
) -> f32 {
    let Some(component) = instance.component(opacity_local) else {
        return 1.0;
    };
    if !component.dirt.contains(ComponentDirt::RENDER_OPACITY) {
        return component.transform.render_opacity;
    }
    render_cache
        .gradient_shaders
        .get(&paint_global_id)
        .and_then(|entry| match &entry.state {
            RuntimeShapePaintState::LinearGradient { render_opacity, .. }
            | RuntimeShapePaintState::RadialGradient { render_opacity, .. } => {
                Some(*render_opacity)
            }
            RuntimeShapePaintState::SolidColor { .. } => None,
        })
        .unwrap_or(1.0)
}

fn runtime_gradient_endpoints(
    artboard: &ArtboardInstance,
    mutator_local: Option<usize>,
    type_name: &str,
    start_x: f32,
    start_y: f32,
    end_x: f32,
    end_y: f32,
) -> (f32, f32, f32, f32) {
    let Some(mutator_local) = mutator_local else {
        return (start_x, start_y, end_x, end_y);
    };
    (
        runtime_gradient_double_property(artboard, mutator_local, type_name, "startX", start_x),
        runtime_gradient_double_property(artboard, mutator_local, type_name, "startY", start_y),
        runtime_gradient_double_property(artboard, mutator_local, type_name, "endX", end_x),
        runtime_gradient_double_property(artboard, mutator_local, type_name, "endY", end_y),
    )
}

fn runtime_gradient_space_endpoints(
    paint_space_transform: Option<Mat2D>,
    start_x: f32,
    start_y: f32,
    end_x: f32,
    end_y: f32,
) -> (f32, f32, f32, f32) {
    let Some(shape_world) = paint_space_transform else {
        return (start_x, start_y, end_x, end_y);
    };
    let (start_x, start_y) = shape_world.transform_point(start_x, start_y);
    let (end_x, end_y) = shape_world.transform_point(end_x, end_y);
    (start_x, start_y, end_x, end_y)
}

fn runtime_gradient_double_property(
    artboard: &ArtboardInstance,
    local_id: usize,
    type_name: &str,
    property_name: &str,
    fallback: f32,
) -> f32 {
    runtime_draw_property_key_for_name(type_name, property_name)
        .and_then(|property_key| artboard.double_property(local_id, property_key))
        .unwrap_or(fallback)
}

fn runtime_gradient_stops(
    artboard: &ArtboardInstance,
    mut stops: Vec<GradientStopNode>,
    opacity: f32,
) -> Vec<RuntimeGradientStop> {
    // Ported from C++ `src/shapes/paint/linear_gradient.cpp::applyTo` and
    // `radial_gradient.cpp`: stops read live object properties after animation.
    let color_key = runtime_draw_property_key_for_name("GradientStop", "colorValue");
    let position_key = runtime_draw_property_key_for_name("GradientStop", "position");
    stops.sort_by(|left, right| {
        let left_position = runtime_gradient_stop_position(artboard, left, position_key);
        let right_position = runtime_gradient_stop_position(artboard, right, position_key);
        left_position.total_cmp(&right_position)
    });
    stops
        .into_iter()
        .map(|stop| {
            let color = color_key
                .and_then(|key| artboard.color_property(stop.local_id, key))
                .unwrap_or(stop.color);
            RuntimeGradientStop {
                color,
                render_color: color_modulate_opacity(color, opacity),
                position: runtime_gradient_stop_position(artboard, &stop, position_key)
                    .clamp(0.0, 1.0),
            }
        })
        .collect()
}

fn runtime_gradient_stop_position(
    artboard: &ArtboardInstance,
    stop: &GradientStopNode,
    position_key: Option<u16>,
) -> f32 {
    position_key
        .and_then(|key| artboard.double_property(stop.local_id, key))
        .unwrap_or(stop.position)
}

fn runtime_feather_state(
    artboard: &ArtboardInstance,
    feather: Option<&FeatherNode>,
    path_commands: &[RuntimePathCommand],
    shape_world: Mat2D,
    parent_is_fill: bool,
) -> Option<RuntimeFeatherState> {
    let mut feather = feather?.clone();
    feather.space_value =
        runtime_feather_uint_property(artboard, &feather, "spaceValue", feather.space_value);
    feather.strength =
        runtime_feather_double_property(artboard, &feather, "strength", feather.strength);
    feather.offset_x =
        runtime_feather_double_property(artboard, &feather, "offsetX", feather.offset_x);
    feather.offset_y =
        runtime_feather_double_property(artboard, &feather, "offsetY", feather.offset_y);
    let authored_inner = runtime_feather_bool_property(artboard, &feather, "inner", feather.inner);
    feather.inner =
        crate::shapes::paint::feather::is_inner(authored_inner, parent_is_fill.then_some("Fill"));

    let inner_path_commands = inner_feather_path_commands(&feather, path_commands, shape_world);
    Some(RuntimeFeatherState {
        feather_local: feather.local_id,
        space_value: feather.space_value,
        strength: feather.strength,
        offset_x: feather.offset_x,
        offset_y: feather.offset_y,
        inner: feather.inner,
        inner_path_commands,
    })
}

fn inner_feather_path_commands(
    feather: &FeatherNode,
    source: &[RuntimePathCommand],
    shape_world: Mat2D,
) -> Vec<RuntimePathCommand> {
    if !feather.inner {
        return Vec::new();
    }
    let bounds = path_command_bounds(source).unwrap_or_else(|| PathBounds::from_point(0.0, 0.0));
    let pad = feather.strength * 1.5;
    let mut commands = rect_commands(bounds.pad(pad));
    let mut reversed_source = path_commands_backwards(source);
    let mut offset = (feather.offset_x, feather.offset_y);
    if feather.space_value == 0 {
        offset = shape_world
            .invert_or_identity()
            .transform_direction(offset.0, offset.1);
    }
    translate_path_commands(&mut reversed_source, offset);
    commands.extend(reversed_source);
    commands
}

fn runtime_feather_double_property(
    artboard: &ArtboardInstance,
    feather: &FeatherNode,
    property_name: &str,
    default: f32,
) -> f32 {
    runtime_draw_property_key_for_name(feather.type_name, property_name)
        .and_then(|key| artboard.double_property(feather.local_id, key))
        .unwrap_or(default)
}

fn runtime_feather_uint_property(
    artboard: &ArtboardInstance,
    feather: &FeatherNode,
    property_name: &str,
    default: u32,
) -> u32 {
    runtime_draw_property_key_for_name(feather.type_name, property_name)
        .and_then(|key| artboard.uint_property(feather.local_id, key))
        .and_then(|value| u32::try_from(value).ok())
        .unwrap_or(default)
}

fn runtime_feather_bool_property(
    artboard: &ArtboardInstance,
    feather: &FeatherNode,
    property_name: &str,
    default: bool,
) -> bool {
    runtime_draw_property_key_for_name(feather.type_name, property_name)
        .and_then(|key| artboard.bool_property(feather.local_id, key))
        .unwrap_or(default)
}

fn runtime_geometry_owned_shape_paint_contains(
    runtime: &RuntimeFile,
    instance: &ArtboardInstance,
    shape: &RuntimeShape,
    paint: &RuntimeShapePaintOwner,
    shape_world: Mat2D,
    world_point: RenderVec2D,
) -> bool {
    if !runtime_owned_shape_paint_is_visible(instance, paint)
        || !runtime_shape_paint_state_is_effectively_visible(&paint.paint_state.borrow())
    {
        return false;
    }

    let path_kind = runtime_live_owned_shape_paint_path_kind(instance, paint);
    let source_path = shape.paint_paths[runtime_shape_paint_path_kind_slot(path_kind)]
        .retained
        .borrow();
    let active_effect = paint.effect_paths.iter().rev().find(|effect| {
        effect
            .retained
            .borrow()
            .as_ref()
            .is_some_and(Option::is_some)
    });
    let effect_retained = active_effect.map(|effect| effect.retained.borrow());
    let selected_path = effect_retained
        .as_ref()
        .and_then(|retained| retained.as_ref())
        .and_then(|path| path.as_ref())
        .or_else(|| source_path.as_ref());
    let Some(selected_path) = selected_path else {
        return false;
    };
    let effect_or_shape_commands =
        runtime_path_commands_from_raw_path(selected_path.raw_path.as_ref());
    let inner_feather_path = paint.inner_feather_path.borrow();
    let inner_feather_commands = inner_feather_path
        .as_ref()
        .map(|path| runtime_path_commands_from_raw_path(path.raw_path.as_ref()));
    let draw_commands = inner_feather_commands
        .as_deref()
        .unwrap_or(&effect_or_shape_commands);
    if draw_commands.is_empty() {
        return false;
    }

    let mut point = (world_point.x, world_point.y);
    let feather_state = paint.feather_state.borrow();
    let outer_feather = feather_state
        .as_ref()
        .filter(|feather| !feather.inner && runtime_feather_has_offset(feather));
    if let Some(feather) = outer_feather.filter(|feather| runtime_feather_uses_world_space(feather))
    {
        point.0 -= feather.offset_x;
        point.1 -= feather.offset_y;
    }
    if matches!(
        path_kind,
        RuntimeShapePaintPathKind::Local | RuntimeShapePaintPathKind::LocalClockwise
    ) {
        let Some(inverse) = runtime_mat2d_invert(shape_world) else {
            return false;
        };
        point = inverse.map_point(point.0, point.1);
    }
    if let Some(feather) =
        outer_feather.filter(|feather| !runtime_feather_uses_world_space(feather))
    {
        point.0 -= feather.offset_x;
        point.1 -= feather.offset_y;
    }
    let point = RenderVec2D::new(point.0, point.1);

    if feather_state.as_ref().is_some_and(|feather| feather.inner)
        && !runtime_path_contains(
            &effect_or_shape_commands,
            point,
            RuntimeGeometryFillRule::Clockwise,
        )
    {
        return false;
    }

    match paint.paint_type {
        RuntimeShapePaintKind::Fill => runtime_path_contains(
            draw_commands,
            point,
            runtime_geometry_fill_rule_from_render(
                runtime_draw_property_key_for_name("Fill", "fillRule")
                    .and_then(|key| instance.uint_property(paint.paint_local, key))
                    .map(runtime_fill_rule_for_value)
                    .unwrap_or(paint.authored_fill_rule),
            ),
        ),
        RuntimeShapePaintKind::Stroke => {
            let Some(object) = runtime.object(paint.paint_global_id as usize) else {
                return false;
            };
            let thickness = runtime_stroke_thickness(instance, object, paint.paint_local);
            if !thickness.is_finite() || thickness <= 0.0 {
                return false;
            }
            let Ok(cap) = runtime_stroke_cap(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "cap",
                0,
            )) else {
                return false;
            };
            let Ok(join) = runtime_stroke_join(runtime_stroke_uint_property(
                instance,
                object,
                paint.paint_local,
                "join",
                0,
            )) else {
                return false;
            };
            runtime_stroked_path_contains(draw_commands, point, thickness, cap, join)
        }
        RuntimeShapePaintKind::Unknown => false,
    }
}

#[derive(Debug, Clone, Copy)]
enum RuntimeGeometryFillRule {
    NonZero,
    EvenOdd,
    Clockwise,
}

fn runtime_geometry_fill_rule_from_render(fill_rule: RenderFillRule) -> RuntimeGeometryFillRule {
    match fill_rule {
        RenderFillRule::EvenOdd => RuntimeGeometryFillRule::EvenOdd,
        RenderFillRule::Clockwise => RuntimeGeometryFillRule::Clockwise,
        RenderFillRule::NonZero => RuntimeGeometryFillRule::NonZero,
    }
}

#[derive(Debug)]
struct RuntimeGeometryStrokeContour {
    origin: (f64, f64),
    segments: Vec<RuntimeGeometryStrokeSegment>,
    closed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum RuntimeGeometryStrokeSegment {
    Line {
        start: (f64, f64),
        end: (f64, f64),
    },
    Cubic {
        start: (f64, f64),
        control1: (f64, f64),
        control2: (f64, f64),
        end: (f64, f64),
    },
}

impl RuntimeGeometryStrokeSegment {
    fn start(self) -> (f64, f64) {
        match self {
            Self::Line { start, .. } | Self::Cubic { start, .. } => start,
        }
    }

    fn end(self) -> (f64, f64) {
        match self {
            Self::Line { end, .. } | Self::Cubic { end, .. } => end,
        }
    }

    fn start_adjacent(self) -> (f64, f64) {
        match self {
            Self::Line { end, .. } => end,
            Self::Cubic {
                start,
                control1,
                control2,
                end,
            } => {
                if control1 != start {
                    control1
                } else if control2 != start {
                    control2
                } else {
                    end
                }
            }
        }
    }

    fn end_adjacent(self) -> (f64, f64) {
        match self {
            Self::Line { start, .. } => start,
            Self::Cubic {
                start,
                control1,
                control2,
                end,
            } => {
                if control2 != end {
                    control2
                } else if control1 != end {
                    control1
                } else {
                    start
                }
            }
        }
    }
}

const MAX_RUNTIME_GEOMETRY_CUBIC_STROKE_BISECTIONS: usize = 768;

#[derive(Debug, Default)]
struct RuntimeGeometryStrokeWork {
    cubic_candidates: usize,
    cubic_bisections: usize,
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_stroked_path_contains(
    commands: &[RuntimePathCommand],
    point: RenderVec2D,
    thickness: f32,
    cap: RenderStrokeCap,
    join: RenderStrokeJoin,
) -> bool {
    runtime_stroked_path_contains_with_work(
        commands,
        point,
        thickness,
        cap,
        join,
        &mut RuntimeGeometryStrokeWork::default(),
    )
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_stroked_path_contains_with_work(
    commands: &[RuntimePathCommand],
    point: RenderVec2D,
    thickness: f32,
    cap: RenderStrokeCap,
    join: RenderStrokeJoin,
    work: &mut RuntimeGeometryStrokeWork,
) -> bool {
    let point = (f64::from(point.x), f64::from(point.y));
    let half_thickness = f64::from(thickness) * 0.5;
    runtime_geometry_stroke_contours(commands)
        .iter()
        .any(|contour| {
            runtime_geometry_stroke_contour_contains(
                contour,
                point,
                half_thickness,
                cap,
                join,
                work,
            )
        })
}

fn runtime_geometry_stroke_contours(
    commands: &[RuntimePathCommand],
) -> Vec<RuntimeGeometryStrokeContour> {
    let mut contours = Vec::new();
    let mut segments = Vec::new();
    let mut current = None;
    let mut contour_start = None;

    let finish = |contours: &mut Vec<RuntimeGeometryStrokeContour>,
                  segments: &mut Vec<RuntimeGeometryStrokeSegment>,
                  origin: Option<(f64, f64)>,
                  closed| {
        if let Some(origin) = origin {
            contours.push(RuntimeGeometryStrokeContour {
                origin,
                segments: std::mem::take(segments),
                closed,
            });
        } else {
            segments.clear();
        }
    };

    for command in commands {
        match *command {
            RuntimePathCommand::Move { x, y } => {
                finish(&mut contours, &mut segments, contour_start, false);
                let point = (f64::from(x), f64::from(y));
                current = Some(point);
                contour_start = Some(point);
            }
            RuntimePathCommand::Line { x, y } => {
                let end = (f64::from(x), f64::from(y));
                let start = current.unwrap_or(end);
                contour_start.get_or_insert(start);
                if start != end {
                    segments.push(RuntimeGeometryStrokeSegment::Line { start, end });
                }
                current = Some(end);
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                let start = current.unwrap_or((0.0, 0.0));
                contour_start.get_or_insert(start);
                let control1 = (f64::from(x1), f64::from(y1));
                let control2 = (f64::from(x2), f64::from(y2));
                let end = (f64::from(x3), f64::from(y3));
                if start != control1 || control1 != control2 || control2 != end {
                    segments.push(RuntimeGeometryStrokeSegment::Cubic {
                        start,
                        control1,
                        control2,
                        end,
                    });
                }
                current = Some(end);
            }
            RuntimePathCommand::Close => {
                if let (Some(start), Some(end)) = (current, contour_start)
                    && start != end
                {
                    segments.push(RuntimeGeometryStrokeSegment::Line { start, end });
                }
                let closed_start = contour_start;
                finish(&mut contours, &mut segments, contour_start, true);
                current = closed_start;
                contour_start = None;
            }
        }
    }
    finish(&mut contours, &mut segments, contour_start, false);
    contours
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_cubic_stroke_body_contains(
    point: (f64, f64),
    p0: (f64, f64),
    p1: (f64, f64),
    p2: (f64, f64),
    p3: (f64, f64),
    half_thickness: f64,
    work: &mut RuntimeGeometryStrokeWork,
) -> bool {
    if !half_thickness.is_finite()
        || half_thickness < 0.0
        || ![point, p0, p1, p2, p3]
            .into_iter()
            .all(|candidate| candidate.0.is_finite() && candidate.1.is_finite())
    {
        return false;
    }

    let min_x = p0.0.min(p1.0).min(p2.0).min(p3.0) - half_thickness;
    let max_x = p0.0.max(p1.0).max(p2.0).max(p3.0) + half_thickness;
    let min_y = p0.1.min(p1.1).min(p2.1).min(p3.1) - half_thickness;
    let max_y = p0.1.max(p1.1).max(p2.1).max(p3.1) + half_thickness;
    if point.0 < min_x || point.0 > max_x || point.1 < min_y || point.1 > max_y {
        return false;
    }

    work.cubic_candidates = work.cubic_candidates.saturating_add(1);
    let a = (
        -p0.0 + 3.0 * p1.0 - 3.0 * p2.0 + p3.0,
        -p0.1 + 3.0 * p1.1 - 3.0 * p2.1 + p3.1,
    );
    let b = (
        3.0 * p0.0 - 6.0 * p1.0 + 3.0 * p2.0,
        3.0 * p0.1 - 6.0 * p1.1 + 3.0 * p2.1,
    );
    let c = (-3.0 * p0.0 + 3.0 * p1.0, -3.0 * p0.1 + 3.0 * p1.1);
    let d = (p0.0 - point.0, p0.1 - point.1);
    let coefficients = [
        runtime_geometry_dot(c, d),
        runtime_geometry_dot(c, c) + 2.0 * runtime_geometry_dot(b, d),
        3.0 * runtime_geometry_dot(b, c) + 3.0 * runtime_geometry_dot(a, d),
        4.0 * runtime_geometry_dot(a, c) + 2.0 * runtime_geometry_dot(b, b),
        5.0 * runtime_geometry_dot(a, b),
        3.0 * runtime_geometry_dot(a, a),
    ];
    let radius_squared = half_thickness * half_thickness;
    let mut roots = Vec::with_capacity(5);
    let bisections_before = work.cubic_bisections;
    runtime_geometry_polynomial_roots_unit_interval(&coefficients, &mut roots, work);
    debug_assert!(
        work.cubic_bisections.saturating_sub(bisections_before)
            <= MAX_RUNTIME_GEOMETRY_CUBIC_STROKE_BISECTIONS
    );
    if roots.into_iter().any(|parameter| {
        let candidate = (
            runtime_cubic_value_f64(p0.0, p1.0, p2.0, p3.0, parameter),
            runtime_cubic_value_f64(p0.1, p1.1, p2.1, p3.1, parameter),
        );
        runtime_geometry_distance_squared(point, candidate) <= radius_squared
    }) {
        return true;
    }

    let start_tangent = runtime_geometry_cubic_start_tangent(p0, p1, p2, p3);
    let start_relative = (point.0 - p0.0, point.1 - p0.1);
    if runtime_geometry_distance_squared(point, p0) <= radius_squared
        && runtime_geometry_dot(start_relative, start_tangent) >= 0.0
    {
        return true;
    }
    let end_tangent = runtime_geometry_cubic_end_tangent(p0, p1, p2, p3);
    let end_relative = (point.0 - p3.0, point.1 - p3.1);
    runtime_geometry_distance_squared(point, p3) <= radius_squared
        && runtime_geometry_dot(end_relative, end_tangent) <= 0.0
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_polynomial_roots_unit_interval(
    coefficients: &[f64],
    roots: &mut Vec<f64>,
    work: &mut RuntimeGeometryStrokeWork,
) {
    let Some(mut degree) = coefficients.len().checked_sub(1) else {
        return;
    };
    while degree > 0 && coefficients.get(degree).copied() == Some(0.0) {
        degree -= 1;
    }
    match degree {
        0 => return,
        1 => {
            let Some(linear) = coefficients.get(1).copied() else {
                return;
            };
            let Some(constant) = coefficients.first().copied() else {
                return;
            };
            runtime_geometry_push_unit_root(roots, -constant / linear);
            return;
        }
        2 => {
            let Some(quadratic) = coefficients.get(2).copied() else {
                return;
            };
            let Some(linear) = coefficients.get(1).copied() else {
                return;
            };
            let Some(constant) = coefficients.first().copied() else {
                return;
            };
            for root in runtime_quadratic_roots_f64(quadratic, linear, constant) {
                runtime_geometry_push_unit_root(roots, root);
            }
            runtime_geometry_sort_deduplicate_unit_roots(roots);
            return;
        }
        _ => {}
    }

    let derivative = coefficients
        .iter()
        .copied()
        .enumerate()
        .skip(1)
        .take(degree)
        .map(|(power, coefficient)| coefficient * power as f64)
        .collect::<Vec<_>>();
    let mut critical_points = Vec::with_capacity(degree.saturating_sub(1));
    runtime_geometry_polynomial_roots_unit_interval(&derivative, &mut critical_points, work);
    runtime_geometry_sort_deduplicate_unit_roots(&mut critical_points);

    let active_coefficients = coefficients.get(..=degree).unwrap_or(coefficients);
    let scale = active_coefficients
        .iter()
        .map(|coefficient| coefficient.abs())
        .sum::<f64>()
        .max(1.0);
    let zero_tolerance = 64.0 * f64::EPSILON * scale;
    for &critical_point in &critical_points {
        if runtime_geometry_polynomial_value(active_coefficients, critical_point).abs()
            <= zero_tolerance
        {
            runtime_geometry_push_unit_root(roots, critical_point);
        }
    }

    let mut boundaries = Vec::with_capacity(critical_points.len().saturating_add(2));
    boundaries.push(0.0);
    boundaries.extend(critical_points);
    boundaries.push(1.0);
    for interval in boundaries.windows(2) {
        let Some(&low) = interval.first() else {
            continue;
        };
        let Some(&high) = interval.last() else {
            continue;
        };
        let low_value = runtime_geometry_polynomial_value(active_coefficients, low);
        let high_value = runtime_geometry_polynomial_value(active_coefficients, high);
        if low_value == 0.0
            || high_value == 0.0
            || low_value.is_sign_positive() == high_value.is_sign_positive()
        {
            continue;
        }
        let root = runtime_geometry_bisect_polynomial_root(
            active_coefficients,
            low,
            high,
            low_value,
            work,
        );
        runtime_geometry_push_unit_root(roots, root);
    }
    runtime_geometry_sort_deduplicate_unit_roots(roots);
}

fn runtime_geometry_push_unit_root(roots: &mut Vec<f64>, root: f64) {
    if root.is_finite() && root > 0.0 && root < 1.0 {
        roots.push(root);
    }
}

fn runtime_geometry_sort_deduplicate_unit_roots(roots: &mut Vec<f64>) {
    roots.sort_by(f64::total_cmp);
    roots.dedup_by(|left, right| (*left - *right).abs() <= 1.0e-12);
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_polynomial_value(coefficients: &[f64], parameter: f64) -> f64 {
    coefficients
        .iter()
        .rev()
        .fold(0.0, |value, coefficient| value * parameter + coefficient)
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_bisect_polynomial_root(
    coefficients: &[f64],
    mut low: f64,
    mut high: f64,
    mut low_value: f64,
    work: &mut RuntimeGeometryStrokeWork,
) -> f64 {
    for _ in 0..64 {
        work.cubic_bisections = work.cubic_bisections.saturating_add(1);
        let middle = (low + high) * 0.5;
        let middle_value = runtime_geometry_polynomial_value(coefficients, middle);
        if middle_value == 0.0 {
            return middle;
        }
        if middle_value.is_sign_positive() == low_value.is_sign_positive() {
            low = middle;
            low_value = middle_value;
        } else {
            high = middle;
        }
    }
    (low + high) * 0.5
}

fn runtime_geometry_cubic_start_tangent(
    p0: (f64, f64),
    p1: (f64, f64),
    p2: (f64, f64),
    p3: (f64, f64),
) -> (f64, f64) {
    let adjacent = if p1 != p0 {
        p1
    } else if p2 != p0 {
        p2
    } else {
        p3
    };
    (adjacent.0 - p0.0, adjacent.1 - p0.1)
}

fn runtime_geometry_cubic_end_tangent(
    p0: (f64, f64),
    p1: (f64, f64),
    p2: (f64, f64),
    p3: (f64, f64),
) -> (f64, f64) {
    let adjacent = if p2 != p3 {
        p2
    } else if p1 != p3 {
        p1
    } else {
        p0
    };
    (p3.0 - adjacent.0, p3.1 - adjacent.1)
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_dot(left: (f64, f64), right: (f64, f64)) -> f64 {
    left.0.mul_add(right.0, left.1 * right.1)
}

// Every direct index below is guarded by a non-empty segment slice, a fixed-size
// `windows` iterator, or modulo that same non-zero length.
#[allow(clippy::arithmetic_side_effects, clippy::indexing_slicing)]
fn runtime_geometry_stroke_contour_contains(
    contour: &RuntimeGeometryStrokeContour,
    point: (f64, f64),
    half_thickness: f64,
    cap: RenderStrokeCap,
    join: RenderStrokeJoin,
    work: &mut RuntimeGeometryStrokeWork,
) -> bool {
    let segments = contour.segments.as_slice();
    if segments.is_empty() {
        return runtime_geometry_empty_stroke_cap(contour.closed, join, cap).is_some_and(
            |empty_cap| {
                runtime_geometry_stroke_cap_contains(
                    point,
                    contour.origin,
                    contour.origin,
                    half_thickness,
                    empty_cap,
                )
            },
        );
    }

    for segment in segments {
        let contains = match *segment {
            RuntimeGeometryStrokeSegment::Line { start, end } => {
                runtime_geometry_segment_strip_contains(point, start, end, half_thickness)
            }
            RuntimeGeometryStrokeSegment::Cubic {
                start,
                control1,
                control2,
                end,
            } => runtime_geometry_cubic_stroke_body_contains(
                point,
                start,
                control1,
                control2,
                end,
                half_thickness,
                work,
            ),
        };
        if contains {
            return true;
        }
    }

    if contour.closed {
        for index in 0..segments.len() {
            let previous = segments[(index + segments.len() - 1) % segments.len()];
            let next = segments[index];
            if runtime_geometry_stroke_join_contains(
                point,
                previous.end_adjacent(),
                next.start(),
                next.start_adjacent(),
                half_thickness,
                join,
            ) {
                return true;
            }
        }
        return false;
    }

    for pair in segments.windows(2) {
        if runtime_geometry_stroke_join_contains(
            point,
            pair[0].end_adjacent(),
            pair[0].end(),
            pair[1].start_adjacent(),
            half_thickness,
            join,
        ) {
            return true;
        }
    }
    let first = segments[0];
    let last = segments[segments.len() - 1];
    runtime_geometry_stroke_cap_contains(
        point,
        first.start(),
        first.start_adjacent(),
        half_thickness,
        cap,
    ) || runtime_geometry_stroke_cap_contains(
        point,
        last.end(),
        last.end_adjacent(),
        half_thickness,
        cap,
    )
}

fn runtime_geometry_empty_stroke_cap(
    closed: bool,
    join: RenderStrokeJoin,
    cap: RenderStrokeCap,
) -> Option<RenderStrokeCap> {
    if !closed {
        return Some(cap);
    }
    match join {
        RenderStrokeJoin::Round => Some(RenderStrokeCap::Round),
        RenderStrokeJoin::Miter => Some(RenderStrokeCap::Square),
        RenderStrokeJoin::Bevel => None,
    }
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_segment_strip_contains(
    point: (f64, f64),
    start: (f64, f64),
    end: (f64, f64),
    half_thickness: f64,
) -> bool {
    let direction = (end.0 - start.0, end.1 - start.1);
    let length_squared = direction.0.mul_add(direction.0, direction.1 * direction.1);
    if length_squared == 0.0 {
        return false;
    }
    let relative = (point.0 - start.0, point.1 - start.1);
    let projection = relative.0.mul_add(direction.0, relative.1 * direction.1);
    if projection < 0.0 || projection > length_squared {
        return false;
    }
    let cross = relative.0 * direction.1 - relative.1 * direction.0;
    cross * cross <= half_thickness * half_thickness * length_squared
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_stroke_cap_contains(
    point: (f64, f64),
    endpoint: (f64, f64),
    adjacent: (f64, f64),
    half_thickness: f64,
    cap: RenderStrokeCap,
) -> bool {
    match cap {
        RenderStrokeCap::Butt => false,
        RenderStrokeCap::Round => {
            runtime_geometry_distance_squared(point, endpoint) <= half_thickness * half_thickness
        }
        RenderStrokeCap::Square => {
            let direction = (endpoint.0 - adjacent.0, endpoint.1 - adjacent.1);
            let length = direction.0.hypot(direction.1);
            if length == 0.0 {
                return (point.0 - endpoint.0).abs() <= half_thickness
                    && (point.1 - endpoint.1).abs() <= half_thickness;
            }
            let extended = (
                endpoint.0 + direction.0 / length * half_thickness,
                endpoint.1 + direction.1 / length * half_thickness,
            );
            runtime_geometry_segment_strip_contains(point, endpoint, extended, half_thickness)
        }
    }
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_stroke_join_contains(
    point: (f64, f64),
    previous: (f64, f64),
    vertex: (f64, f64),
    next: (f64, f64),
    half_thickness: f64,
    join: RenderStrokeJoin,
) -> bool {
    let incoming = runtime_geometry_normalized((vertex.0 - previous.0, vertex.1 - previous.1));
    let outgoing = runtime_geometry_normalized((next.0 - vertex.0, next.1 - vertex.1));
    let (Some(incoming), Some(outgoing)) = (incoming, outgoing) else {
        return runtime_geometry_distance_squared(point, vertex) <= half_thickness * half_thickness;
    };
    let turn = runtime_geometry_cross(incoming, outgoing);
    let dot = incoming.0.mul_add(outgoing.0, incoming.1 * outgoing.1);
    if turn == 0.0 {
        return dot < 0.0
            && runtime_geometry_distance_squared(point, vertex) <= half_thickness * half_thickness;
    }
    if join == RenderStrokeJoin::Round {
        return runtime_geometry_distance_squared(point, vertex) <= half_thickness * half_thickness;
    }

    let side = if turn > 0.0 { -1.0 } else { 1.0 };
    let incoming_normal = (-incoming.1 * side, incoming.0 * side);
    let outgoing_normal = (-outgoing.1 * side, outgoing.0 * side);
    let outer_incoming = (
        vertex.0 + incoming_normal.0 * half_thickness,
        vertex.1 + incoming_normal.1 * half_thickness,
    );
    let outer_outgoing = (
        vertex.0 + outgoing_normal.0 * half_thickness,
        vertex.1 + outgoing_normal.1 * half_thickness,
    );
    if join == RenderStrokeJoin::Bevel {
        return runtime_geometry_triangle_contains(point, vertex, outer_incoming, outer_outgoing);
    }

    let offset = (
        outer_outgoing.0 - outer_incoming.0,
        outer_outgoing.1 - outer_incoming.1,
    );
    let parameter = runtime_geometry_cross(offset, outgoing) / turn;
    let miter = (
        outer_incoming.0 + incoming.0 * parameter,
        outer_incoming.1 + incoming.1 * parameter,
    );
    // Rive hard-codes a four-times-stroke-radius miter limit. A sharper
    // corner falls back to the bevel region.
    let within_miter_limit =
        runtime_geometry_distance_squared(miter, vertex) <= 16.0 * half_thickness * half_thickness;
    if !within_miter_limit {
        return runtime_geometry_triangle_contains(point, vertex, outer_incoming, outer_outgoing);
    }
    runtime_geometry_triangle_contains(point, outer_incoming, miter, outer_outgoing)
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_normalized(vector: (f64, f64)) -> Option<(f64, f64)> {
    let length = vector.0.hypot(vector.1);
    (length != 0.0).then_some((vector.0 / length, vector.1 / length))
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_triangle_contains(
    point: (f64, f64),
    first: (f64, f64),
    second: (f64, f64),
    third: (f64, f64),
) -> bool {
    let side1 = runtime_geometry_cross(
        (second.0 - first.0, second.1 - first.1),
        (point.0 - first.0, point.1 - first.1),
    );
    let side2 = runtime_geometry_cross(
        (third.0 - second.0, third.1 - second.1),
        (point.0 - second.0, point.1 - second.1),
    );
    let side3 = runtime_geometry_cross(
        (first.0 - third.0, first.1 - third.1),
        (point.0 - third.0, point.1 - third.1),
    );
    (side1 >= 0.0 && side2 >= 0.0 && side3 >= 0.0) || (side1 <= 0.0 && side2 <= 0.0 && side3 <= 0.0)
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_cross(left: (f64, f64), right: (f64, f64)) -> f64 {
    left.0 * right.1 - left.1 * right.0
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_distance_squared(left: (f64, f64), right: (f64, f64)) -> f64 {
    let dx = left.0 - right.0;
    let dy = left.1 - right.1;
    dx.mul_add(dx, dy * dy)
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_exact_path_bounds(commands: &[RuntimePathCommand]) -> Option<RenderAabb> {
    let mut bounds: Option<RenderAabb> = None;
    let mut current: Option<(f32, f32)> = None;
    let mut contour_start: Option<(f32, f32)> = None;
    for command in commands {
        match *command {
            RuntimePathCommand::Move { x, y } => {
                runtime_geometry_include_point(&mut bounds, (x, y));
                current = Some((x, y));
                contour_start = current;
            }
            RuntimePathCommand::Line { x, y } => {
                runtime_geometry_include_point(&mut bounds, (x, y));
                current = Some((x, y));
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                let start = current.unwrap_or((0.0, 0.0));
                runtime_geometry_include_point(&mut bounds, start);
                runtime_geometry_include_point(&mut bounds, (x3, y3));
                for t in runtime_cubic_extrema(start.0, x1, x2, x3)
                    .into_iter()
                    .chain(runtime_cubic_extrema(start.1, y1, y2, y3))
                {
                    let x = runtime_cubic_value(start.0, x1, x2, x3, t);
                    let y = runtime_cubic_value(start.1, y1, y2, y3, t);
                    runtime_geometry_include_point(&mut bounds, (x, y));
                }
                current = Some((x3, y3));
            }
            RuntimePathCommand::Close => {
                current = contour_start;
            }
        }
    }
    bounds
}

fn runtime_geometry_include_point(bounds: &mut Option<RenderAabb>, point: (f32, f32)) {
    match bounds {
        Some(bounds) => {
            bounds.min_x = bounds.min_x.min(point.0);
            bounds.min_y = bounds.min_y.min(point.1);
            bounds.max_x = bounds.max_x.max(point.0);
            bounds.max_y = bounds.max_y.max(point.1);
        }
        None => *bounds = Some(RenderAabb::new(point.0, point.1, point.0, point.1)),
    }
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_rect_contains(bounds: (f32, f32, f32, f32), point: RenderVec2D) -> bool {
    let (x, y, width, height) = bounds;
    let max_x = x + width;
    let max_y = y + height;
    RenderAabb::new(x.min(max_x), y.min(max_y), x.max(max_x), y.max(max_y)).contains(point)
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_transformed_rect_bounds(bounds: (f32, f32, f32, f32), world: Mat2D) -> RenderAabb {
    let (x, y, width, height) = bounds;
    let mut transformed = None;
    for point in [
        world.transform_point(x, y),
        world.transform_point(x + width, y),
        world.transform_point(x + width, y + height),
        world.transform_point(x, y + height),
    ] {
        runtime_geometry_include_point(&mut transformed, point);
    }
    transformed.unwrap_or(RenderAabb::new(0.0, 0.0, 0.0, 0.0))
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_cubic_extrema(p0: f32, p1: f32, p2: f32, p3: f32) -> Vec<f32> {
    // The derivative divided by three is `a*t^2 + b*t + c`.
    let a = -p0 + 3.0 * p1 - 3.0 * p2 + p3;
    let b = 2.0 * (p0 - 2.0 * p1 + p2);
    let c = p1 - p0;
    runtime_quadratic_roots(a, b, c)
        .into_iter()
        .filter(|t| *t > 0.0 && *t < 1.0)
        .collect()
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_quadratic_roots(a: f32, b: f32, c: f32) -> Vec<f32> {
    if a == 0.0 {
        return if b == 0.0 { Vec::new() } else { vec![-c / b] };
    }
    let discriminant = b.mul_add(b, -4.0 * a * c);
    if discriminant < 0.0 {
        return Vec::new();
    }
    if discriminant == 0.0 {
        return vec![-b / (2.0 * a)];
    }
    let root = discriminant.sqrt();
    vec![(-b - root) / (2.0 * a), (-b + root) / (2.0 * a)]
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_cubic_value(p0: f32, p1: f32, p2: f32, p3: f32, t: f32) -> f32 {
    let one_minus_t = 1.0 - t;
    one_minus_t.powi(3) * p0
        + 3.0 * one_minus_t.powi(2) * t * p1
        + 3.0 * one_minus_t * t * t * p2
        + t.powi(3) * p3
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_path_contains(
    commands: &[RuntimePathCommand],
    point: RenderVec2D,
    fill_rule: RuntimeGeometryFillRule,
) -> bool {
    let point = (f64::from(point.x), f64::from(point.y));
    let mut winding = 0i32;
    let contours = runtime_path_net_contours(commands, fill_rule);
    for contour in &contours {
        if runtime_path_contour_crossing(contour, point, &mut winding) {
            return true;
        }
    }
    match fill_rule {
        RuntimeGeometryFillRule::EvenOdd | RuntimeGeometryFillRule::Clockwise => {
            winding.unsigned_abs() % 2 == 1
        }
        RuntimeGeometryFillRule::NonZero => winding != 0,
    }
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_path_segments_have_area(
    segments: impl IntoIterator<Item = RuntimeGeometryContourSegment>,
) -> bool {
    let mut origin = None;
    let mut direction = None;
    for segment in segments {
        let points: &[(f64, f64)] = match segment {
            RuntimeGeometryContourSegment::Line { start, end } => &[start, end],
            RuntimeGeometryContourSegment::Cubic {
                start,
                control1,
                control2,
                end,
            } => &[start, control1, control2, end],
        };
        for &point in points {
            let Some(first) = origin else {
                origin = Some(point);
                continue;
            };
            let Some(second) = direction else {
                if point != first {
                    direction = Some(point);
                }
                continue;
            };
            let cross = (second.0 - first.0) * (point.1 - first.1)
                - (second.1 - first.1) * (point.0 - first.0);
            if cross != 0.0 {
                return true;
            }
        }
    }
    false
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum RuntimeGeometryContourSegment {
    Line {
        start: (f64, f64),
        end: (f64, f64),
    },
    Cubic {
        start: (f64, f64),
        control1: (f64, f64),
        control2: (f64, f64),
        end: (f64, f64),
    },
}

impl RuntimeGeometryContourSegment {
    fn is_point(self) -> bool {
        match self {
            Self::Line { start, end } => start == end,
            Self::Cubic {
                start,
                control1,
                control2,
                end,
            } => start == control1 && control1 == control2 && control2 == end,
        }
    }

    fn net_key(self) -> Option<(RuntimeGeometrySegmentKey, RuntimeGeometrySegmentDirection)> {
        match self {
            Self::Line { start, end } => {
                let forward = [
                    runtime_geometry_point_key(start)?,
                    runtime_geometry_point_key(end)?,
                ];
                let reverse = [forward[1], forward[0]];
                let key = RuntimeGeometrySegmentKey::Line(forward.min(reverse));
                Some((key, runtime_geometry_segment_direction(&forward, &reverse)))
            }
            Self::Cubic {
                start,
                control1,
                control2,
                end,
            } => {
                let forward = [
                    runtime_geometry_point_key(start)?,
                    runtime_geometry_point_key(control1)?,
                    runtime_geometry_point_key(control2)?,
                    runtime_geometry_point_key(end)?,
                ];
                let reverse = [forward[3], forward[2], forward[1], forward[0]];
                let key = RuntimeGeometrySegmentKey::Cubic(forward.min(reverse));
                Some((key, runtime_geometry_segment_direction(&forward, &reverse)))
            }
        }
    }
}

fn runtime_geometry_segment_direction<T: Ord>(
    forward: &[T],
    reverse: &[T],
) -> RuntimeGeometrySegmentDirection {
    match forward.cmp(reverse) {
        std::cmp::Ordering::Less => RuntimeGeometrySegmentDirection::Forward,
        std::cmp::Ordering::Greater => RuntimeGeometrySegmentDirection::Reverse,
        std::cmp::Ordering::Equal => RuntimeGeometrySegmentDirection::Neutral,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct RuntimeGeometryPointKey(u64, u64);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum RuntimeGeometrySegmentKey {
    Line([RuntimeGeometryPointKey; 2]),
    Cubic([RuntimeGeometryPointKey; 4]),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RuntimeGeometrySegmentDirection {
    Forward,
    Reverse,
    Neutral,
}

#[derive(Default)]
struct RuntimeGeometrySegmentNetBucket {
    direction: Option<RuntimeGeometrySegmentDirection>,
    locations: Vec<RuntimeGeometrySegmentLocation>,
}

#[derive(Debug, Clone, Copy)]
struct RuntimeGeometrySegmentLocation {
    contour: usize,
    segment: usize,
}

fn runtime_geometry_point_key(point: (f64, f64)) -> Option<RuntimeGeometryPointKey> {
    fn coordinate(value: f64) -> Option<u64> {
        value
            .is_finite()
            .then_some(if value == 0.0 { 0 } else { value.to_bits() })
    }
    Some(RuntimeGeometryPointKey(
        coordinate(point.0)?,
        coordinate(point.1)?,
    ))
}

fn runtime_path_net_contours(
    commands: &[RuntimePathCommand],
    fill_rule: RuntimeGeometryFillRule,
) -> Vec<Vec<RuntimeGeometryContourSegment>> {
    let mut contours = Vec::new();
    let mut contour_start = 0;
    for (index, command) in commands.iter().enumerate().skip(1) {
        if matches!(command, RuntimePathCommand::Move { .. }) {
            let Some(contour_commands) = commands.get(contour_start..index) else {
                return Vec::new();
            };
            contours.push(runtime_path_contour_segments(contour_commands));
            contour_start = index;
        }
    }
    let Some(contour_commands) = commands.get(contour_start..) else {
        return Vec::new();
    };
    contours.push(runtime_path_contour_segments(contour_commands));
    for contour in &mut contours {
        if !runtime_path_segments_have_area(contour.iter().flatten().copied()) {
            contour.fill(None);
        }
    }
    runtime_path_net_segments(&mut contours, fill_rule);
    contours
        .into_iter()
        .map(|contour| contour.into_iter().flatten().collect())
        .collect()
}

fn runtime_path_contour_segments(
    commands: &[RuntimePathCommand],
) -> Vec<Option<RuntimeGeometryContourSegment>> {
    let mut segments = Vec::<Option<RuntimeGeometryContourSegment>>::new();
    let mut current = None;
    let mut contour_start = None;
    for command in commands {
        match *command {
            RuntimePathCommand::Move { x, y } => {
                let point = (f64::from(x), f64::from(y));
                current = Some(point);
                contour_start = Some(point);
            }
            RuntimePathCommand::Line { x, y } => {
                let end = (f64::from(x), f64::from(y));
                let start = current.unwrap_or(end);
                segments.push(Some(RuntimeGeometryContourSegment::Line { start, end }));
                current = Some(end);
                contour_start.get_or_insert(start);
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                let start = current.unwrap_or((0.0, 0.0));
                let control1 = (f64::from(x1), f64::from(y1));
                let control2 = (f64::from(x2), f64::from(y2));
                let end = (f64::from(x3), f64::from(y3));
                segments.push(Some(RuntimeGeometryContourSegment::Cubic {
                    start,
                    control1,
                    control2,
                    end,
                }));
                current = Some(end);
                contour_start.get_or_insert(start);
            }
            RuntimePathCommand::Close => {
                if let (Some(start), Some(end)) = (current, contour_start) {
                    segments.push(Some(RuntimeGeometryContourSegment::Line { start, end }));
                }
                current = contour_start;
                contour_start = None;
            }
        }
    }
    if let (Some(start), Some(end)) = (current, contour_start) {
        segments.push(Some(RuntimeGeometryContourSegment::Line { start, end }));
    }
    segments
}

fn runtime_path_net_segments(
    contours: &mut [Vec<Option<RuntimeGeometryContourSegment>>],
    fill_rule: RuntimeGeometryFillRule,
) {
    let mut buckets = BTreeMap::<RuntimeGeometrySegmentKey, RuntimeGeometrySegmentNetBucket>::new();
    for contour in 0..contours.len() {
        let Some(segment_count) = contours.get(contour).map(Vec::len) else {
            continue;
        };
        for segment in 0..segment_count {
            let location = RuntimeGeometrySegmentLocation { contour, segment };
            let Some(candidate) = runtime_path_segment_at(contours, location) else {
                continue;
            };
            if candidate.is_point() {
                runtime_path_remove_segment(contours, location);
                continue;
            }
            let Some((key, direction)) = candidate.net_key() else {
                continue;
            };
            if direction == RuntimeGeometrySegmentDirection::Neutral {
                runtime_path_remove_segment(contours, location);
                continue;
            }
            let bucket = buckets.entry(key).or_default();
            if matches!(
                fill_rule,
                RuntimeGeometryFillRule::EvenOdd | RuntimeGeometryFillRule::Clockwise
            ) {
                if let Some(previous) = bucket.locations.pop() {
                    runtime_path_remove_segment(contours, previous);
                    runtime_path_remove_segment(contours, location);
                } else {
                    bucket.locations.push(location);
                }
                continue;
            }
            match bucket.direction {
                Some(existing) if existing != direction => {
                    let Some(previous) = bucket.locations.pop() else {
                        bucket.direction = Some(direction);
                        bucket.locations.push(location);
                        continue;
                    };
                    runtime_path_remove_segment(contours, previous);
                    runtime_path_remove_segment(contours, location);
                    if bucket.locations.is_empty() {
                        bucket.direction = None;
                    }
                }
                Some(_) => bucket.locations.push(location),
                None => {
                    bucket.direction = Some(direction);
                    bucket.locations.push(location);
                }
            }
        }
    }
}

fn runtime_path_segment_at(
    contours: &[Vec<Option<RuntimeGeometryContourSegment>>],
    location: RuntimeGeometrySegmentLocation,
) -> Option<RuntimeGeometryContourSegment> {
    contours
        .get(location.contour)
        .and_then(|contour| contour.get(location.segment))
        .copied()
        .flatten()
}

fn runtime_path_remove_segment(
    contours: &mut [Vec<Option<RuntimeGeometryContourSegment>>],
    location: RuntimeGeometrySegmentLocation,
) {
    if let Some(slot) = contours
        .get_mut(location.contour)
        .and_then(|contour| contour.get_mut(location.segment))
    {
        *slot = None;
    }
}

fn runtime_path_contour_crossing(
    segments: &[RuntimeGeometryContourSegment],
    point: (f64, f64),
    winding: &mut i32,
) -> bool {
    for segment in segments {
        let contains = match *segment {
            RuntimeGeometryContourSegment::Line { start, end } => {
                runtime_geometry_line_crossing(point, start, end, winding)
            }
            RuntimeGeometryContourSegment::Cubic {
                start,
                control1,
                control2,
                end,
            } => runtime_geometry_cubic_crossing(point, start, control1, control2, end, winding),
        };
        if contains {
            return true;
        }
    }
    false
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_line_crossing(
    point: (f64, f64),
    start: (f64, f64),
    end: (f64, f64),
    winding: &mut i32,
) -> bool {
    if runtime_geometry_point_on_line(point, start, end) {
        return true;
    }
    let crosses_up = start.1 <= point.1 && end.1 > point.1;
    let crosses_down = start.1 > point.1 && end.1 <= point.1;
    if crosses_up || crosses_down {
        let crossing_x = start.0 + (point.1 - start.1) * (end.0 - start.0) / (end.1 - start.1);
        if crossing_x > point.0 {
            *winding += if crosses_up { 1 } else { -1 };
        }
    }
    false
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_cubic_crossing(
    point: (f64, f64),
    p0: (f64, f64),
    p1: (f64, f64),
    p2: (f64, f64),
    p3: (f64, f64),
    winding: &mut i32,
) -> bool {
    if runtime_geometry_point_on_cubic(point, p0, p1, p2, p3) {
        return true;
    }
    let mut knots = vec![0.0];
    knots.extend(runtime_cubic_extrema_f64(p0.1, p1.1, p2.1, p3.1));
    knots.push(1.0);
    knots.sort_by(f64::total_cmp);
    for interval in knots.windows(2) {
        let Some(&start_t) = interval.first() else {
            continue;
        };
        let Some(&end_t) = interval.last() else {
            continue;
        };
        let start_y = runtime_cubic_value_f64(p0.1, p1.1, p2.1, p3.1, start_t);
        let end_y = runtime_cubic_value_f64(p0.1, p1.1, p2.1, p3.1, end_t);
        let crosses_up = start_y <= point.1 && point.1 < end_y;
        let crosses_down = end_y <= point.1 && point.1 < start_y;
        if !crosses_up && !crosses_down {
            continue;
        }
        let t = runtime_monotonic_cubic_parameter(p0.1, p1.1, p2.1, p3.1, point.1, start_t, end_t);
        let crossing_x = runtime_cubic_value_f64(p0.0, p1.0, p2.0, p3.0, t);
        if crossing_x > point.0 {
            *winding += if crosses_up { 1 } else { -1 };
        }
    }
    false
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_point_on_line(point: (f64, f64), start: (f64, f64), end: (f64, f64)) -> bool {
    const EPSILON: f64 = 1.0e-5;
    let dx = end.0 - start.0;
    let dy = end.1 - start.1;
    let length_squared = dx.mul_add(dx, dy * dy);
    if length_squared == 0.0 {
        let point_dx = point.0 - start.0;
        let point_dy = point.1 - start.1;
        return point_dx.mul_add(point_dx, point_dy * point_dy) <= EPSILON * EPSILON;
    }
    let cross = (point.0 - start.0) * dy - (point.1 - start.1) * dx;
    if cross * cross > EPSILON * EPSILON * length_squared {
        return false;
    }
    let dot = (point.0 - start.0) * (point.0 - end.0) + (point.1 - start.1) * (point.1 - end.1);
    dot <= EPSILON * EPSILON
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_geometry_point_on_cubic(
    point: (f64, f64),
    p0: (f64, f64),
    p1: (f64, f64),
    p2: (f64, f64),
    p3: (f64, f64),
) -> bool {
    const EPSILON: f64 = 1.0e-5;
    let min_x = p0.0.min(p1.0).min(p2.0).min(p3.0) - EPSILON;
    let max_x = p0.0.max(p1.0).max(p2.0).max(p3.0) + EPSILON;
    let min_y = p0.1.min(p1.1).min(p2.1).min(p3.1) - EPSILON;
    let max_y = p0.1.max(p1.1).max(p2.1).max(p3.1) + EPSILON;
    if point.0 < min_x || point.0 > max_x || point.1 < min_y || point.1 > max_y {
        return false;
    }
    let mut candidates = runtime_cubic_coordinate_parameters(p0.0, p1.0, p2.0, p3.0, point.0);
    candidates.extend(runtime_cubic_coordinate_parameters(
        p0.1, p1.1, p2.1, p3.1, point.1,
    ));
    candidates.into_iter().any(|t| {
        let x = runtime_cubic_value_f64(p0.0, p1.0, p2.0, p3.0, t);
        let y = runtime_cubic_value_f64(p0.1, p1.1, p2.1, p3.1, t);
        (x - point.0).abs() <= EPSILON && (y - point.1).abs() <= EPSILON
    })
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_cubic_coordinate_parameters(
    p0: f64,
    p1: f64,
    p2: f64,
    p3: f64,
    target: f64,
) -> Vec<f64> {
    const EPSILON: f64 = 1.0e-5;
    let mut knots = vec![0.0];
    knots.extend(runtime_cubic_extrema_f64(p0, p1, p2, p3));
    knots.push(1.0);
    knots.sort_by(f64::total_cmp);
    let mut parameters = Vec::new();
    for interval in knots.windows(2) {
        let Some(&start_t) = interval.first() else {
            continue;
        };
        let Some(&end_t) = interval.last() else {
            continue;
        };
        let start = runtime_cubic_value_f64(p0, p1, p2, p3, start_t);
        let end = runtime_cubic_value_f64(p0, p1, p2, p3, end_t);
        if target < start.min(end) - EPSILON || target > start.max(end) + EPSILON {
            continue;
        }
        if (end - start).abs() <= EPSILON {
            if (target - start).abs() <= EPSILON {
                parameters.push(start_t);
                parameters.push(end_t);
            }
            continue;
        }
        parameters.push(runtime_monotonic_cubic_parameter(
            p0, p1, p2, p3, target, start_t, end_t,
        ));
    }
    parameters
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_monotonic_cubic_parameter(
    p0: f64,
    p1: f64,
    p2: f64,
    p3: f64,
    target: f64,
    mut low: f64,
    mut high: f64,
) -> f64 {
    let increasing = runtime_cubic_value_f64(p0, p1, p2, p3, high)
        >= runtime_cubic_value_f64(p0, p1, p2, p3, low);
    for _ in 0..64 {
        let middle = (low + high) * 0.5;
        let value = runtime_cubic_value_f64(p0, p1, p2, p3, middle);
        if (value < target) == increasing {
            low = middle;
        } else {
            high = middle;
        }
    }
    (low + high) * 0.5
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_cubic_extrema_f64(p0: f64, p1: f64, p2: f64, p3: f64) -> Vec<f64> {
    let a = -p0 + 3.0 * p1 - 3.0 * p2 + p3;
    let b = 2.0 * (p0 - 2.0 * p1 + p2);
    let c = p1 - p0;
    runtime_quadratic_roots_f64(a, b, c)
        .into_iter()
        .filter(|t| *t > 0.0 && *t < 1.0)
        .collect()
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_quadratic_roots_f64(a: f64, b: f64, c: f64) -> Vec<f64> {
    if a == 0.0 {
        return if b == 0.0 { Vec::new() } else { vec![-c / b] };
    }
    let discriminant = b.mul_add(b, -4.0 * a * c);
    if discriminant < 0.0 {
        return Vec::new();
    }
    if discriminant == 0.0 {
        return vec![-b / (2.0 * a)];
    }
    let root = discriminant.sqrt();
    vec![(-b - root) / (2.0 * a), (-b + root) / (2.0 * a)]
}

#[allow(clippy::arithmetic_side_effects)]
fn runtime_cubic_value_f64(p0: f64, p1: f64, p2: f64, p3: f64, t: f64) -> f64 {
    let one_minus_t = 1.0 - t;
    one_minus_t.powi(3) * p0
        + 3.0 * one_minus_t.powi(2) * t * p1
        + 3.0 * one_minus_t * t * t * p2
        + t.powi(3) * p3
}

#[derive(Debug, Clone, Copy)]
struct PathBounds {
    min_x: f32,
    min_y: f32,
    max_x: f32,
    max_y: f32,
}

impl PathBounds {
    fn from_point(x: f32, y: f32) -> Self {
        Self {
            min_x: x,
            min_y: y,
            max_x: x,
            max_y: y,
        }
    }

    fn include(&mut self, x: f32, y: f32) {
        self.min_x = self.min_x.min(x);
        self.min_y = self.min_y.min(y);
        self.max_x = self.max_x.max(x);
        self.max_y = self.max_y.max(y);
    }

    fn pad(self, amount: f32) -> Self {
        Self {
            min_x: self.min_x - amount,
            min_y: self.min_y - amount,
            max_x: self.max_x + amount,
            max_y: self.max_y + amount,
        }
    }
}

fn path_command_bounds(commands: &[RuntimePathCommand]) -> Option<PathBounds> {
    let mut bounds: Option<PathBounds> = None;
    for command in commands {
        for (x, y) in command_points(command) {
            match &mut bounds {
                Some(bounds) => bounds.include(x, y),
                None => bounds = Some(PathBounds::from_point(x, y)),
            }
        }
    }
    bounds
}

fn rect_commands(bounds: PathBounds) -> Vec<RuntimePathCommand> {
    vec![
        RuntimePathCommand::Move {
            x: bounds.min_x,
            y: bounds.min_y,
        },
        RuntimePathCommand::Line {
            x: bounds.max_x,
            y: bounds.min_y,
        },
        RuntimePathCommand::Line {
            x: bounds.max_x,
            y: bounds.max_y,
        },
        RuntimePathCommand::Line {
            x: bounds.min_x,
            y: bounds.max_y,
        },
        RuntimePathCommand::Close,
    ]
}

fn translate_path_commands(commands: &mut [RuntimePathCommand], offset: (f32, f32)) {
    for command in commands {
        match command {
            RuntimePathCommand::Move { x, y } | RuntimePathCommand::Line { x, y } => {
                *x += offset.0;
                *y += offset.1;
            }
            RuntimePathCommand::Cubic {
                x1,
                y1,
                x2,
                y2,
                x3,
                y3,
            } => {
                *x1 += offset.0;
                *y1 += offset.1;
                *x2 += offset.0;
                *y2 += offset.1;
                *x3 += offset.0;
                *y3 += offset.1;
            }
            RuntimePathCommand::Close => {}
        }
    }
}

fn command_points(command: &RuntimePathCommand) -> Vec<(f32, f32)> {
    match *command {
        RuntimePathCommand::Move { x, y } | RuntimePathCommand::Line { x, y } => {
            vec![(x, y)]
        }
        RuntimePathCommand::Cubic {
            x1,
            y1,
            x2,
            y2,
            x3,
            y3,
        } => vec![(x1, y1), (x2, y2), (x3, y3)],
        RuntimePathCommand::Close => Vec::new(),
    }
}

fn runtime_effect_path_commands(
    artboard: &ArtboardInstance,
    paint: &ShapePaintNode,
    source: &[RuntimePathCommand],
) -> Option<Vec<RuntimePathCommand>> {
    if paint.effects.is_empty() {
        return None;
    }

    crate::shapes::paint::group_effect::update_effects(
        &source.to_vec(),
        &paint.effects,
        |effect, current| {
            crate::shapes::paint::stroke_effect::runtime_stroke_effect_path_commands(
                artboard, effect, paint, current,
            )
        },
    )
}

// Coarsely translated from:
// /Users/levi/dev/oss/rive-runtime/src/shapes/paint/dash_path.cpp DashPath::updateEffect
// and PathDasher::applyDash.
pub(crate) fn runtime_dash_path_effect_commands(
    artboard: &ArtboardInstance,
    effect: &StrokeEffectNode,
    paint: &ShapePaintNode,
    source: &[RuntimePathCommand],
) -> Option<Vec<RuntimePathCommand>> {
    record_runtime_dash_path_effect_rebuild();
    let offset = runtime_dash_path_double_property(artboard, effect, "offset", effect.dash_offset)?;
    let offset_is_percentage = runtime_dash_path_bool_property(
        artboard,
        effect,
        "offsetIsPercentage",
        effect.dash_offset_is_percentage,
    )?;
    if paint.paint_type == ShapePaintKind::Fill {
        return Some(source.to_vec());
    }

    Some(dash_path_apply_dash(
        artboard,
        source,
        offset,
        offset_is_percentage,
        &effect.dashes,
    ))
}

#[inline]
fn record_runtime_dash_path_effect_rebuild() {
    #[cfg(test)]
    RUNTIME_DASH_PATH_EFFECT_REBUILDS.with(|calls| calls.set(calls.get() + 1));
}

#[cfg(test)]
std::thread_local! {
    static RUNTIME_DASH_PATH_EFFECT_REBUILDS: std::cell::Cell<usize> = const {
        std::cell::Cell::new(0)
    };
}

#[cfg(test)]
fn reset_runtime_dash_path_effect_rebuilds() {
    RUNTIME_DASH_PATH_EFFECT_REBUILDS.with(|calls| calls.set(0));
}

#[cfg(test)]
fn runtime_dash_path_effect_rebuilds() -> usize {
    RUNTIME_DASH_PATH_EFFECT_REBUILDS.with(std::cell::Cell::get)
}

fn runtime_dash_path_double_property(
    artboard: &ArtboardInstance,
    effect: &StrokeEffectNode,
    property_name: &str,
    fallback: Option<f32>,
) -> Option<f32> {
    runtime_draw_property_key_for_name("DashPath", property_name)
        .and_then(|key| artboard.double_property(effect.local_id, key))
        .or(fallback)
}

fn runtime_dash_path_bool_property(
    artboard: &ArtboardInstance,
    effect: &StrokeEffectNode,
    property_name: &str,
    fallback: Option<bool>,
) -> Option<bool> {
    runtime_draw_property_key_for_name("DashPath", property_name)
        .and_then(|key| artboard.bool_property(effect.local_id, key))
        .or(fallback)
}

fn dash_path_apply_dash(
    artboard: &ArtboardInstance,
    source: &[RuntimePathCommand],
    offset: f32,
    offset_is_percentage: bool,
    dashes: &[DashNode],
) -> Vec<RuntimePathCommand> {
    let path_measure = RuntimePathMeasure::from_commands(source);
    if path_measure.length <= 0.0
        || !dashes.iter().any(|dash| {
            dash_normalized_length(
                runtime_dash_length(artboard, dash),
                runtime_dash_length_is_percentage(artboard, dash),
                path_measure.length,
                false,
            ) > 0.0
        })
    {
        return Vec::new();
    }

    let mut commands = Vec::new();
    let mut dash_index = 0usize;
    let mut dashed = 0.0;
    let mut distance =
        dash_normalized_length(offset, offset_is_percentage, path_measure.length, true);
    let mut draw = true;

    while dashed < path_measure.length {
        let dash = &dashes[dash_index % dashes.len()];
        dash_index += 1;

        let mut dash_length = dash_normalized_length(
            runtime_dash_length(artboard, dash),
            runtime_dash_length_is_percentage(artboard, dash),
            path_measure.length,
            false,
        );
        if dash_length > path_measure.length {
            dash_length = path_measure.length;
        }

        let mut end_length = distance + dash_length;
        if end_length > path_measure.length {
            end_length -= path_measure.length;
            if draw {
                if distance < path_measure.length {
                    path_measure.get_segment(distance, path_measure.length, &mut commands, true);
                    path_measure.get_segment(
                        0.0,
                        end_length,
                        &mut commands,
                        !path_measure.is_closed(),
                    );
                } else {
                    path_measure.get_segment(0.0, end_length, &mut commands, true);
                }
            }

            distance = end_length - dash_length;
        } else if draw {
            path_measure.get_segment(distance, end_length, &mut commands, true);
        }

        distance += dash_length;
        dashed += dash_length;
        draw = !draw;
    }

    commands
}

fn runtime_dash_length(artboard: &ArtboardInstance, dash: &DashNode) -> f32 {
    runtime_draw_property_key_for_name("Dash", "length")
        .and_then(|key| artboard.double_property(dash.local_id, key))
        .unwrap_or(dash.length)
}

fn runtime_dash_length_is_percentage(artboard: &ArtboardInstance, dash: &DashNode) -> bool {
    runtime_draw_property_key_for_name("Dash", "lengthIsPercentage")
        .and_then(|key| artboard.bool_property(dash.local_id, key))
        .unwrap_or(dash.length_is_percentage)
}

fn dash_normalized_length(
    value: f32,
    is_percentage: bool,
    contour_length: f32,
    wraps: bool,
) -> f32 {
    crate::shapes::paint::dash::normalized_length(value, is_percentage, contour_length, wraps)
}

#[derive(Debug, Clone)]
pub(crate) struct TrimContour {
    segments: Vec<TrimMeasuredSegment>,
    pub(crate) length: f32,
    pub(crate) is_closed: bool,
}

#[derive(Debug, Clone)]
pub struct RuntimePathMeasure {
    contours: Vec<TrimContour>,
    length: f32,
    raw_is_closed: bool,
}

#[derive(Debug, Clone, Copy, Default)]
pub struct RuntimePathSample {
    pub pos: (f32, f32),
    pub tan: (f32, f32),
}

#[derive(Debug, Clone)]
pub struct RuntimeContourMeasure {
    contour: TrimContour,
}

#[derive(Debug, Clone)]
struct TrimMeasuredSegment {
    original_index: usize,
    kind: TrimSegmentKind,
    distance: f32,
    t: f32,
}

#[derive(Debug, Clone, Copy)]
enum TrimSegmentKind {
    Line {
        from: (f32, f32),
        to: (f32, f32),
    },
    Cubic {
        p0: (f32, f32),
        p1: (f32, f32),
        p2: (f32, f32),
        p3: (f32, f32),
    },
}

impl TrimContour {
    pub(crate) fn from_commands(commands: &[RuntimePathCommand]) -> Vec<Self> {
        Self::from_commands_with_inv_tolerance(commands, TRIM_CONTOUR_DEFAULT_INV_TOLERANCE)
    }

    fn from_commands_with_inv_tolerance(
        commands: &[RuntimePathCommand],
        inv_tolerance: f32,
    ) -> Vec<Self> {
        let mut contours = Vec::new();
        let mut raw_segments = Vec::<TrimSegmentKind>::new();
        let mut start = None::<(f32, f32)>;
        let mut current = None::<(f32, f32)>;
        let mut is_closed = false;

        let finish_contour = |contours: &mut Vec<Self>,
                              raw_segments: &mut Vec<TrimSegmentKind>,
                              is_closed: &mut bool| {
            if let Some(contour) = Self::from_raw_segments(raw_segments, *is_closed, inv_tolerance)
            {
                contours.push(contour);
            }
            raw_segments.clear();
            *is_closed = false;
        };

        for command in commands {
            match *command {
                RuntimePathCommand::Move { x, y } => {
                    if !raw_segments.is_empty() {
                        finish_contour(&mut contours, &mut raw_segments, &mut is_closed);
                    }
                    start = Some((x, y));
                    current = Some((x, y));
                }
                RuntimePathCommand::Line { x, y } => {
                    let Some(from) = current else {
                        continue;
                    };
                    let to = (x, y);
                    if distance_squared(from, to) > 0.0 {
                        raw_segments.push(TrimSegmentKind::Line { from, to });
                    }
                    current = Some(to);
                }
                RuntimePathCommand::Cubic {
                    x1,
                    y1,
                    x2,
                    y2,
                    x3,
                    y3,
                } => {
                    let Some(p0) = current else {
                        continue;
                    };
                    let p1 = (x1, y1);
                    let p2 = (x2, y2);
                    let p3 = (x3, y3);
                    raw_segments.push(TrimSegmentKind::Cubic { p0, p1, p2, p3 });
                    current = Some(p3);
                }
                RuntimePathCommand::Close => {
                    if let (Some(from), Some(to)) = (current, start) {
                        if distance_squared(from, to) > 0.0 {
                            raw_segments.push(TrimSegmentKind::Line { from, to });
                        }
                        current = Some(to);
                    }
                    is_closed = true;
                }
            }
        }

        if !raw_segments.is_empty() {
            finish_contour(&mut contours, &mut raw_segments, &mut is_closed);
        }
        contours
    }

    fn from_raw_path_with_inv_tolerance(path: &RawPath, inv_tolerance: f32) -> Vec<Self> {
        let mut contours = Vec::new();
        let mut raw_segments = Vec::<TrimSegmentKind>::new();
        let mut start = None::<(f32, f32)>;
        let mut current = None::<(f32, f32)>;
        let mut is_closed = false;
        let mut point_index = 0usize;

        let finish_contour = |contours: &mut Vec<Self>,
                              raw_segments: &mut Vec<TrimSegmentKind>,
                              is_closed: &mut bool| {
            if let Some(contour) = Self::from_raw_segments(raw_segments, *is_closed, inv_tolerance)
            {
                contours.push(contour);
            }
            raw_segments.clear();
            *is_closed = false;
        };

        for verb in path.verbs() {
            match verb {
                RenderPathVerb::Move => {
                    let Some(point) = path.points().get(point_index) else {
                        break;
                    };
                    point_index += 1;
                    if !raw_segments.is_empty() {
                        finish_contour(&mut contours, &mut raw_segments, &mut is_closed);
                    }
                    start = Some((point.x, point.y));
                    current = start;
                }
                RenderPathVerb::Line => {
                    let Some(point) = path.points().get(point_index) else {
                        break;
                    };
                    point_index += 1;
                    let Some(from) = current else {
                        continue;
                    };
                    let to = (point.x, point.y);
                    if distance_squared(from, to) > 0.0 {
                        raw_segments.push(TrimSegmentKind::Line { from, to });
                    }
                    current = Some(to);
                }
                RenderPathVerb::Quad => {
                    let (Some(control), Some(point), Some(p0)) = (
                        path.points().get(point_index),
                        path.points().get(point_index + 1),
                        current,
                    ) else {
                        break;
                    };
                    point_index += 2;
                    let p3 = (point.x, point.y);
                    let p1 = (
                        p0.0 + (control.x - p0.0) * (2.0 / 3.0),
                        p0.1 + (control.y - p0.1) * (2.0 / 3.0),
                    );
                    let p2 = (
                        p3.0 + (control.x - p3.0) * (2.0 / 3.0),
                        p3.1 + (control.y - p3.1) * (2.0 / 3.0),
                    );
                    raw_segments.push(TrimSegmentKind::Cubic { p0, p1, p2, p3 });
                    current = Some(p3);
                }
                RenderPathVerb::Cubic => {
                    let (Some(control_out), Some(control_in), Some(point), Some(p0)) = (
                        path.points().get(point_index),
                        path.points().get(point_index + 1),
                        path.points().get(point_index + 2),
                        current,
                    ) else {
                        break;
                    };
                    point_index += 3;
                    let p1 = (control_out.x, control_out.y);
                    let p2 = (control_in.x, control_in.y);
                    let p3 = (point.x, point.y);
                    raw_segments.push(TrimSegmentKind::Cubic { p0, p1, p2, p3 });
                    current = Some(p3);
                }
                RenderPathVerb::Close => {
                    if let (Some(from), Some(to)) = (current, start) {
                        if distance_squared(from, to) > 0.0 {
                            raw_segments.push(TrimSegmentKind::Line { from, to });
                        }
                        current = Some(to);
                    }
                    is_closed = true;
                }
            }
        }

        if !raw_segments.is_empty() {
            finish_contour(&mut contours, &mut raw_segments, &mut is_closed);
        }
        contours
    }

    fn from_raw_segments(
        raw_segments: &[TrimSegmentKind],
        is_closed: bool,
        inv_tolerance: f32,
    ) -> Option<Self> {
        let mut segments = Vec::new();
        let mut distance_so_far = 0.0;

        for (original_index, segment) in raw_segments.iter().copied().enumerate() {
            match segment {
                TrimSegmentKind::Line { from, to } => {
                    let length = distance(from, to);
                    if length == 0.0 {
                        continue;
                    }
                    distance_so_far += length;
                    segments.push(TrimMeasuredSegment {
                        original_index,
                        kind: segment,
                        distance: distance_so_far,
                        t: 1.0,
                    });
                }
                TrimSegmentKind::Cubic { p0, p1, p2, p3 } => {
                    let segment_count =
                        cubic_measure_segment_count([p0, p1, p2, p3], inv_tolerance);
                    if segment_count == 0 {
                        continue;
                    }
                    let dt = 1.0 / segment_count as f32;
                    let mut t = dt;
                    let mut previous = p0;
                    for _ in 1..segment_count {
                        let next = eval_cubic([p0, p1, p2, p3], t);
                        distance_so_far += distance(previous, next);
                        segments.push(TrimMeasuredSegment {
                            original_index,
                            kind: segment,
                            distance: distance_so_far,
                            t: trim_contour_dot30_t(t),
                        });
                        previous = next;
                        t += dt;
                    }
                    distance_so_far += distance(previous, p3);
                    segments.push(TrimMeasuredSegment {
                        original_index,
                        kind: segment,
                        distance: distance_so_far,
                        t: 1.0,
                    });
                }
            }
        }

        (distance_so_far > 0.0 && !segments.is_empty()).then_some(Self {
            segments,
            length: distance_so_far,
            is_closed,
        })
    }

    pub(crate) fn get_segment(
        &self,
        mut start_distance: f32,
        mut end_distance: f32,
        commands: &mut Vec<RuntimePathCommand>,
        start_with_move: bool,
    ) {
        start_distance = start_distance.max(0.0);
        end_distance = end_distance.min(self.length);
        if start_distance >= end_distance {
            return;
        }

        let mut start_index = self.find_segment(start_distance);
        let end_index = self.find_segment(end_distance);
        let mut start_t = self.compute_t(start_index, start_distance);
        let end_t = self.compute_t(end_index, end_distance);

        if 1.0 - start_t < TRIM_CONTOUR_EPSILON && start_index < end_index {
            start_index += 1;
            start_t = 0.0;
        }

        let start = &self.segments[start_index];
        let end = &self.segments[end_index];
        if start.original_index == end.original_index {
            start
                .kind
                .extract(commands, start_t, end_t, start_with_move);
            return;
        }

        start.kind.extract(commands, start_t, 1.0, start_with_move);

        let mut original_index = start.original_index + 1;
        while original_index < end.original_index {
            if let Some(segment) = self.first_segment_for_original(original_index) {
                segment.kind.extract_full(commands);
            }
            original_index += 1;
        }

        end.kind.extract(commands, 0.0, end_t, false);
    }

    fn find_segment(&self, distance: f32) -> usize {
        self.segments
            .iter()
            .position(|segment| segment.distance >= distance)
            .unwrap_or_else(|| self.segments.len() - 1)
    }

    fn compute_t(&self, index: usize, distance: f32) -> f32 {
        let segment = &self.segments[index];
        let mut previous_distance = 0.0;
        let mut previous_t = 0.0;
        if index > 0 {
            let previous = &self.segments[index - 1];
            previous_distance = previous.distance;
            if previous.original_index == segment.original_index {
                previous_t = previous.t;
            }
        }

        let denominator = segment.distance - previous_distance;
        if denominator == 0.0 {
            return previous_t;
        }
        let ratio = (distance - previous_distance) / denominator;
        previous_t
            .mul_add(1.0 - ratio, segment.t * ratio)
            .clamp(previous_t, segment.t)
    }

    fn first_segment_for_original(&self, original_index: usize) -> Option<&TrimMeasuredSegment> {
        self.segments
            .iter()
            .find(|segment| segment.original_index == original_index)
    }

    fn position_tangent_at_distance(&self, distance: f32) -> ((f32, f32), (f32, f32)) {
        let distance = distance.clamp(0.0, self.length);
        let index = self.find_segment(distance);
        let segment = &self.segments[index];

        match segment.kind {
            TrimSegmentKind::Line { from, to } => {
                let mut previous_distance = 0.0;
                if index > 0 {
                    previous_distance = self.segments[index - 1].distance;
                }
                let denominator = segment.distance - previous_distance;
                let rel_d = if denominator == 0.0 {
                    0.0
                } else {
                    (distance - previous_distance) / denominator
                };
                let tan = normalized_vector((to.0 - from.0, to.1 - from.1));
                (lerp_point(from, to, rel_d), tan)
            }
            TrimSegmentKind::Cubic { p0, p1, p2, p3 } => {
                cubic_position_tangent([p0, p1, p2, p3], self.compute_t(index, distance))
            }
        }
    }
}

impl RuntimePathMeasure {
    pub fn from_commands(commands: &[RuntimePathCommand]) -> Self {
        Self::from_commands_with_inv_tolerance(commands, TRIM_CONTOUR_DEFAULT_INV_TOLERANCE)
    }

    pub(crate) fn from_raw_path(path: &RawPath) -> Self {
        let contours =
            TrimContour::from_raw_path_with_inv_tolerance(path, TRIM_CONTOUR_DEFAULT_INV_TOLERANCE);
        let length = contours.iter().map(|contour| contour.length).sum();
        let raw_is_closed = matches!(path.verbs().last(), Some(RenderPathVerb::Close));
        Self {
            contours,
            length,
            raw_is_closed,
        }
    }

    pub(crate) fn from_commands_with_tolerance(
        commands: &[RuntimePathCommand],
        tolerance: f32,
    ) -> Self {
        let min_tolerance = 1.0 / 16.0;
        let tolerance = if tolerance.is_finite() {
            tolerance.max(min_tolerance)
        } else {
            TRIM_CONTOUR_DEFAULT_TOLERANCE
        };
        Self::from_commands_with_inv_tolerance(commands, 1.0 / tolerance)
    }

    fn from_commands_with_inv_tolerance(
        commands: &[RuntimePathCommand],
        inv_tolerance: f32,
    ) -> Self {
        let contours = TrimContour::from_commands_with_inv_tolerance(commands, inv_tolerance);
        let length = contours.iter().map(|contour| contour.length).sum();
        let raw_is_closed = matches!(commands.last(), Some(RuntimePathCommand::Close));
        Self {
            contours,
            length,
            raw_is_closed,
        }
    }

    pub fn length(&self) -> f32 {
        self.length
    }

    pub(crate) fn at_percentage(&self, percentage_distance: f32) -> RuntimePathSample {
        let mut in_range_percentage = percentage_distance % 1.0;
        if in_range_percentage < 0.0 {
            in_range_percentage += 1.0;
        }
        if percentage_distance != 0.0 && in_range_percentage == 0.0 {
            in_range_percentage = 1.0;
        }
        self.at_distance(self.length * in_range_percentage)
    }

    pub fn at_distance(&self, distance: f32) -> RuntimePathSample {
        let mut current_distance = distance;
        for contour in &self.contours {
            let contour_length = contour.length;
            if current_distance - contour_length <= 0.0 {
                let (pos, tan) = contour.position_tangent_at_distance(current_distance);
                return RuntimePathSample { pos, tan };
            }
            current_distance -= contour_length;
        }
        RuntimePathSample::default()
    }

    fn get_segment(
        &self,
        start_distance: f32,
        end_distance: f32,
        commands: &mut Vec<RuntimePathCommand>,
        start_with_move: bool,
    ) {
        if self.contours.is_empty() {
            return;
        }

        let start_distance = start_distance.clamp(0.0, self.length);
        let end_distance = end_distance.clamp(0.0, self.length);
        if start_distance >= end_distance {
            return;
        }

        let mut current_distance = 0.0;
        let mut is_first_segment = true;
        for contour in &self.contours {
            let contour_length = contour.length;
            let contour_start = current_distance;
            let contour_end = current_distance + contour_length;

            if contour_end > start_distance && contour_start < end_distance {
                let local_start = (start_distance - contour_start).max(0.0);
                let local_end = (end_distance - contour_start).min(contour_length);
                contour.get_segment(
                    local_start,
                    local_end,
                    commands,
                    !is_first_segment || start_with_move,
                );
                is_first_segment = false;
            }

            current_distance += contour_length;
            if current_distance >= end_distance {
                break;
            }
        }
    }

    pub fn is_closed(&self) -> bool {
        self.contours.len() == 1 && self.contours[0].is_closed
    }

    pub(crate) fn raw_is_closed(&self) -> bool {
        self.raw_is_closed
    }
}

impl RuntimeContourMeasure {
    pub fn from_commands(commands: &[RuntimePathCommand]) -> Vec<Self> {
        TrimContour::from_commands(commands)
            .into_iter()
            .map(|contour| Self { contour })
            .collect()
    }

    pub fn length(&self) -> f32 {
        self.contour.length
    }

    pub fn is_closed(&self) -> bool {
        self.contour.is_closed
    }

    pub fn at_distance(&self, distance: f32) -> RuntimePathSample {
        let (pos, tan) = self.contour.position_tangent_at_distance(distance);
        RuntimePathSample { pos, tan }
    }

    pub fn segment(&self, start: f32, end: f32, start_with_move: bool) -> RawPath {
        let mut commands = Vec::new();
        self.contour
            .get_segment(start, end, &mut commands, start_with_move);
        runtime_raw_path_from_commands(&commands)
    }
}

impl RuntimePathMeasure {
    pub fn segment(&self, start: f32, end: f32, start_with_move: bool) -> RawPath {
        let mut commands = Vec::new();
        self.get_segment(start, end, &mut commands, start_with_move);
        runtime_raw_path_from_commands(&commands)
    }
}

impl TrimSegmentKind {
    fn extract(
        self,
        commands: &mut Vec<RuntimePathCommand>,
        start_t: f32,
        end_t: f32,
        move_to: bool,
    ) {
        match self {
            Self::Line { from, to } => {
                let start = weighted_lerp_point(from, to, start_t);
                let end = weighted_lerp_point(from, to, end_t);
                if move_to {
                    commands.push(RuntimePathCommand::Move {
                        x: start.0,
                        y: start.1,
                    });
                }
                commands.push(RuntimePathCommand::Line { x: end.0, y: end.1 });
            }
            Self::Cubic { p0, p1, p2, p3 } => {
                let [start, control_1, control_2, end] =
                    cubic_extract([p0, p1, p2, p3], start_t, end_t);
                if move_to {
                    commands.push(RuntimePathCommand::Move {
                        x: start.0,
                        y: start.1,
                    });
                }
                commands.push(RuntimePathCommand::Cubic {
                    x1: control_1.0,
                    y1: control_1.1,
                    x2: control_2.0,
                    y2: control_2.1,
                    x3: end.0,
                    y3: end.1,
                });
            }
        }
    }

    fn extract_full(self, commands: &mut Vec<RuntimePathCommand>) {
        match self {
            Self::Line { to, .. } => commands.push(RuntimePathCommand::Line { x: to.0, y: to.1 }),
            Self::Cubic { p1, p2, p3, .. } => commands.push(RuntimePathCommand::Cubic {
                x1: p1.0,
                y1: p1.1,
                x2: p2.0,
                y2: p2.1,
                x3: p3.0,
                y3: p3.1,
            }),
        }
    }
}

const TRIM_CONTOUR_EPSILON: f32 = 1.0 / 4096.0;
const TRIM_CONTOUR_DEFAULT_TOLERANCE: f32 = 0.5;
const TRIM_CONTOUR_DEFAULT_INV_TOLERANCE: f32 = 1.0 / TRIM_CONTOUR_DEFAULT_TOLERANCE;
const TRIM_CONTOUR_MAX_SEGMENTS: u32 = 100;
const TRIM_CONTOUR_DOT30_SCALE: f32 = (1u32 << 30) as f32;
const TRIM_CONTOUR_MAX_DOT30: u32 = (1u32 << 30) - 1;
const TRIM_CONTOUR_INV_MAX_DOT30: f32 = 1.0 / TRIM_CONTOUR_MAX_DOT30 as f32;

fn trim_contour_dot30_t(t: f32) -> f32 {
    ((t * TRIM_CONTOUR_DOT30_SCALE) as u32) as f32 * TRIM_CONTOUR_INV_MAX_DOT30
}

fn cubic_measure_segment_count(points: [(f32, f32); 4], inv_tolerance: f32) -> u32 {
    wangs_cubic(points, inv_tolerance)
        .ceil()
        .ceil()
        .min(TRIM_CONTOUR_MAX_SEGMENTS as f32) as u32
}

fn wangs_cubic(points: [(f32, f32); 4], precision: f32) -> f32 {
    let first = vector_length_squared((
        points[0].0 - 2.0 * points[1].0 + points[2].0,
        points[0].1 - 2.0 * points[1].1 + points[2].1,
    ));
    let second = vector_length_squared((
        points[1].0 - 2.0 * points[2].0 + points[3].0,
        points[1].1 - 2.0 * points[2].1 + points[3].1,
    ));
    let length_term_pow2 = 9.0 * 4.0 / 64.0 * precision * precision;
    (first.max(second) * length_term_pow2).sqrt().sqrt()
}

fn eval_cubic(points: [(f32, f32); 4], t: f32) -> (f32, f32) {
    let a = (
        points[3].0 + 3.0 * (points[1].0 - points[2].0) - points[0].0,
        points[3].1 + 3.0 * (points[1].1 - points[2].1) - points[0].1,
    );
    let b = (
        3.0 * (points[2].0 - 2.0 * points[1].0 + points[0].0),
        3.0 * (points[2].1 - 2.0 * points[1].1 + points[0].1),
    );
    let c = (
        3.0 * (points[1].0 - points[0].0),
        3.0 * (points[1].1 - points[0].1),
    );
    (
        ((a.0 * t + b.0) * t + c.0) * t + points[0].0,
        ((a.1 * t + b.1) * t + c.1) * t + points[0].1,
    )
}

fn cubic_position_tangent(points: [(f32, f32); 4], t: f32) -> ((f32, f32), (f32, f32)) {
    if t == 0.0 {
        let tangent_to = if points[0] != points[1] {
            points[1]
        } else if points[1] != points[2] {
            points[2]
        } else {
            points[3]
        };
        return (
            points[0],
            (tangent_to.0 - points[0].0, tangent_to.1 - points[0].1),
        );
    }
    if t == 1.0 {
        let tangent_from = if points[3] != points[2] {
            points[2]
        } else if points[2] != points[1] {
            points[1]
        } else {
            points[0]
        };
        return (
            points[3],
            (points[3].0 - tangent_from.0, points[3].1 - tangent_from.1),
        );
    }

    let a = (
        points[3].0 + 3.0 * (points[1].0 - points[2].0) - points[0].0,
        points[3].1 + 3.0 * (points[1].1 - points[2].1) - points[0].1,
    );
    let b = (
        3.0 * (points[2].0 - 2.0 * points[1].0 + points[0].0),
        3.0 * (points[2].1 - 2.0 * points[1].1 + points[0].1),
    );
    let c = (
        3.0 * (points[1].0 - points[0].0),
        3.0 * (points[1].1 - points[0].1),
    );
    let tan = normalized_vector((
        (3.0 * a.0 * t + 2.0 * b.0) * t + c.0,
        (3.0 * a.1 * t + 2.0 * b.1) * t + c.1,
    ));
    (eval_cubic(points, t), tan)
}

fn cubic_extract(points: [(f32, f32); 4], start_t: f32, end_t: f32) -> [(f32, f32); 4] {
    if start_t == 0.0 && end_t == 1.0 {
        points
    } else if start_t == 0.0 {
        let chopped = cubic_subdivide(points, end_t);
        [chopped[0], chopped[1], chopped[2], chopped[3]]
    } else if end_t == 1.0 {
        let chopped = cubic_subdivide(points, start_t);
        [chopped[3], chopped[4], chopped[5], chopped[6]]
    } else {
        let chopped = cubic_subdivide(points, end_t);
        let chopped_again = cubic_subdivide(
            [chopped[0], chopped[1], chopped[2], chopped[3]],
            start_t / end_t,
        );
        [
            chopped_again[3],
            chopped_again[4],
            chopped_again[5],
            chopped_again[6],
        ]
    }
}

fn cubic_subdivide(points: [(f32, f32); 4], t: f32) -> [(f32, f32); 7] {
    let ab = weighted_lerp_point(points[0], points[1], t);
    let bc = weighted_lerp_point(points[1], points[2], t);
    let cd = weighted_lerp_point(points[2], points[3], t);
    let abc = weighted_lerp_point(ab, bc, t);
    let bcd = weighted_lerp_point(bc, cd, t);
    [
        points[0],
        ab,
        abc,
        weighted_lerp_point(abc, bcd, t),
        bcd,
        cd,
        points[3],
    ]
}

fn distance(from: (f32, f32), to: (f32, f32)) -> f32 {
    let x = to.0 - from.0;
    let y = to.1 - from.1;
    x.mul_add(x, y * y).sqrt()
}

fn distance_squared(from: (f32, f32), to: (f32, f32)) -> f32 {
    vector_length_squared((to.0 - from.0, to.1 - from.1))
}

fn vector_length_squared(vector: (f32, f32)) -> f32 {
    vector.0.mul_add(vector.0, vector.1 * vector.1)
}

fn lerp_point(from: (f32, f32), to: (f32, f32), t: f32) -> (f32, f32) {
    (from.0 + (to.0 - from.0) * t, from.1 + (to.1 - from.1) * t)
}

fn weighted_lerp_point(from: (f32, f32), to: (f32, f32), t: f32) -> (f32, f32) {
    let inverse_t = 1.0 - t;
    (from.0 * inverse_t + to.0 * t, from.1 * inverse_t + to.1 * t)
}

fn color_modulate_opacity(color: u32, opacity: f32) -> u32 {
    crate::shapes::paint::color::modulate_opacity(color, opacity)
}

pub(crate) fn color_lerp(from: u32, to: u32, mix: f32) -> u32 {
    crate::shapes::paint::color::lerp(from, to, mix)
}

pub(crate) fn path_commands(
    path: &PathGeometryNode,
    path_kind: ShapePaintPathKind,
    transform: Mat2D,
    weighted_context: Option<&WeightedPathContext<'_>>,
) -> Vec<RuntimePathCommand> {
    match path.type_name {
        "Ellipse" => ellipse_path_commands(path, path_kind, transform),
        "PointsPath" | "ListPath" => {
            points_path_commands(path, path_kind, transform, weighted_context)
        }
        "Polygon" => polygon_path_commands(path, path_kind, transform),
        "Rectangle" => rectangle_path_commands(path, path_kind, transform),
        "Star" => star_path_commands(path, path_kind, transform),
        "Triangle" => triangle_path_commands(path, path_kind, transform),
        _ => Vec::new(),
    }
}

pub(crate) fn runtime_path_geometry_commands(
    artboard: &ArtboardInstance,
    path: &PathGeometryNode,
    transform: Mat2D,
) -> Vec<RuntimePathCommand> {
    let path = runtime_path_geometry(artboard, path);
    // RF-32 query scratch may enter through an authored local id, but once
    // resolved it reads the same retained Skinnable owner as Path::update.
    let weighted_context = artboard
        .component_handle(path.local_id)
        .filter(|handle| artboard.runtime_skinnable_handle_has_skin(*handle))
        .map(|_| WeightedPathContext { instance: artboard });
    let path_transform =
        crate::shapes::points_path::path_transform(weighted_context.is_some(), transform);
    let mut commands = path_commands(
        &path,
        ShapePaintPathKind::World,
        path_transform,
        weighted_context.as_ref(),
    );
    prune_empty_path_segments(&mut commands);
    commands
}

/// C++ `Shape::hitTestHiFi` equivalent for one authored path.
///
/// The pinned implementation feeds the path into a `HitTestCommandPath` with
/// a two-pixel query radius and tests the resulting integer-cell windings.
pub(crate) fn runtime_path_geometry_hit_test(
    artboard: &ArtboardInstance,
    path: &PathGeometryNode,
    transform: Mat2D,
    point: (f32, f32),
) -> bool {
    let commands = runtime_path_geometry_commands(artboard, path, transform);
    let mut tester =
        crate::HitTestCommandPath::new(crate::HitTestArea::around(point.0, point.1, 2.0));
    tester.add_runtime_commands(&commands);
    tester.was_hit()
}

pub(crate) fn runtime_text_value_run_hit_test(
    artboard: &ArtboardInstance,
    run_local: usize,
    point: (f32, f32),
) -> bool {
    let Some(runtime) = artboard.runtime_file() else {
        return false;
    };
    let Some(graph) = artboard.runtime_graph() else {
        return false;
    };
    let Some(text_local) = artboard.component_parent_local(run_local) else {
        return false;
    };
    if artboard
        .component(text_local)
        .is_none_or(|component| component.type_name != "Text")
    {
        return false;
    }
    let layout_constraint = artboard.runtime_text_layout_constraint(text_local, None);
    let text_world = artboard.runtime_component_world_transform(text_local, graph);
    static_text_value_run_hit(
        runtime,
        graph,
        artboard,
        text_local,
        run_local,
        layout_constraint,
        text_world,
        RenderVec2D::new(point.0, point.1),
        2.0,
    )
}

pub(crate) fn runtime_path_geometry(
    artboard: &ArtboardInstance,
    path: &PathGeometryNode,
) -> PathGeometryNode {
    let mut path = path.clone();
    path.is_closed = runtime_path_bool_property(
        artboard,
        path.local_id,
        path.type_name,
        "isClosed",
        path.is_closed,
    );
    path.is_hole = runtime_path_bool_property(
        artboard,
        path.local_id,
        path.type_name,
        "isHole",
        path.is_hole,
    );
    path.is_clockwise = runtime_path_is_clockwise(artboard, path.local_id, path.is_clockwise);
    path.parametric = runtime_parametric_path(artboard, &path);

    if let Some(vertices) = runtime_retained_path_vertices(artboard, path.local_id) {
        path.vertices = vertices;
    }
    for vertex in &mut path.vertices {
        vertex.x = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "x",
            vertex.x,
        );
        vertex.y = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "y",
            vertex.y,
        );
        vertex.radius = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "radius",
            vertex.radius,
        );
        vertex.rotation = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "rotation",
            vertex.rotation,
        );
        vertex.distance = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "distance",
            vertex.distance,
        );
        vertex.in_rotation = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "inRotation",
            vertex.in_rotation,
        );
        vertex.in_distance = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "inDistance",
            vertex.in_distance,
        );
        vertex.out_rotation = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "outRotation",
            vertex.out_rotation,
        );
        vertex.out_distance = runtime_path_double_property(
            artboard,
            vertex.local_id,
            vertex.type_name,
            "outDistance",
            vertex.out_distance,
        );
    }

    path
}

fn runtime_retained_path_vertices(
    artboard: &ArtboardInstance,
    path_local: usize,
) -> Option<Vec<PathVertexNode>> {
    if let Some(vertices) = artboard.runtime_list_path_vertices(path_local) {
        return Some(vertices);
    }
    let vertices = &artboard
        .component(path_local)?
        .concrete
        .skinnable
        .as_ref()?
        .vertices;
    Some(
        vertices
            .iter()
            .filter_map(|handle| {
                let vertex = artboard.objects.component(*handle)?;
                let local_id = vertex.local_id;
                let type_name = vertex.type_name;
                let weight = vertex
                    .concrete
                    .vertex
                    .as_ref()
                    .and_then(|vertex| vertex.weight)
                    .and_then(|weight| artboard.objects.component(weight));
                let weight_local = weight.map(|weight| weight.local_id);
                let weight_global = weight.map(|weight| weight.global_id);
                let weight_type_name = weight.map(|weight| weight.type_name);
                let weight_uint = |owner, property| {
                    let local = weight_local?;
                    runtime_draw_property_key_for_name(owner, property)
                        .and_then(|key| artboard.uint_property(local, key))
                        .and_then(|value| u32::try_from(value).ok())
                };
                Some(PathVertexNode {
                    local_id,
                    global_id: vertex.global_id,
                    type_name,
                    x: runtime_path_double_property(artboard, local_id, type_name, "x", 0.0),
                    y: runtime_path_double_property(artboard, local_id, type_name, "y", 0.0),
                    radius: runtime_path_double_property(
                        artboard, local_id, type_name, "radius", 0.0,
                    ),
                    rotation: runtime_path_double_property(
                        artboard, local_id, type_name, "rotation", 0.0,
                    ),
                    distance: runtime_path_double_property(
                        artboard, local_id, type_name, "distance", 0.0,
                    ),
                    in_rotation: runtime_path_double_property(
                        artboard,
                        local_id,
                        type_name,
                        "inRotation",
                        0.0,
                    ),
                    in_distance: runtime_path_double_property(
                        artboard,
                        local_id,
                        type_name,
                        "inDistance",
                        0.0,
                    ),
                    out_rotation: runtime_path_double_property(
                        artboard,
                        local_id,
                        type_name,
                        "outRotation",
                        0.0,
                    ),
                    out_distance: runtime_path_double_property(
                        artboard,
                        local_id,
                        type_name,
                        "outDistance",
                        0.0,
                    ),
                    weight_local,
                    weight_global,
                    weight_type_name,
                    weight_values: weight_uint("Weight", "values"),
                    weight_indices: weight_uint("Weight", "indices"),
                    weight_in_values: weight_uint("CubicWeight", "inValues"),
                    weight_in_indices: weight_uint("CubicWeight", "inIndices"),
                    weight_out_values: weight_uint("CubicWeight", "outValues"),
                    weight_out_indices: weight_uint("CubicWeight", "outIndices"),
                })
            })
            .collect(),
    )
}

fn runtime_mesh_geometry(artboard: &ArtboardInstance, mesh: &MeshGeometryNode) -> MeshGeometryNode {
    let Some(skinnable) = artboard
        .component(mesh.local_id)
        .and_then(|component| component.concrete.skinnable.as_ref())
    else {
        return mesh.clone();
    };
    let vertices = skinnable
        .vertices
        .iter()
        .filter_map(|handle| {
            let vertex = artboard.objects.component(*handle)?;
            let weight = vertex
                .concrete
                .vertex
                .as_ref()
                .and_then(|vertex| vertex.weight)
                .and_then(|weight| artboard.objects.component(weight));
            Some(nuxie_graph::MeshVertexNode {
                local_id: vertex.local_id,
                global_id: vertex.global_id,
                type_name: vertex.type_name,
                weight_local: weight.map(|weight| weight.local_id),
                weight_global: weight.map(|weight| weight.global_id),
                weight_type_name: weight.map(|weight| weight.type_name),
            })
        })
        .collect();
    MeshGeometryNode {
        local_id: mesh.local_id,
        global_id: mesh.global_id,
        type_name: mesh.type_name,
        vertices,
    }
}

fn runtime_parametric_path(
    artboard: &ArtboardInstance,
    path: &PathGeometryNode,
) -> Option<ParametricPathNode> {
    match path.parametric.as_ref()? {
        ParametricPathNode::Ellipse {
            width,
            height,
            origin_x,
            origin_y,
        } => Some(ParametricPathNode::Ellipse {
            width: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "width",
                *width,
            ),
            height: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "height",
                *height,
            ),
            origin_x: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originX",
                *origin_x,
            ),
            origin_y: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originY",
                *origin_y,
            ),
        }),
        ParametricPathNode::Polygon {
            width,
            height,
            origin_x,
            origin_y,
            points,
            corner_radius,
        } => Some(ParametricPathNode::Polygon {
            width: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "width",
                *width,
            ),
            height: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "height",
                *height,
            ),
            origin_x: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originX",
                *origin_x,
            ),
            origin_y: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originY",
                *origin_y,
            ),
            points: runtime_path_uint_property(
                artboard,
                path.local_id,
                path.type_name,
                "points",
                *points as u64,
            ) as u32,
            corner_radius: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "cornerRadius",
                *corner_radius,
            ),
        }),
        ParametricPathNode::Star {
            width,
            height,
            origin_x,
            origin_y,
            points,
            corner_radius,
            inner_radius,
        } => Some(ParametricPathNode::Star {
            width: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "width",
                *width,
            ),
            height: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "height",
                *height,
            ),
            origin_x: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originX",
                *origin_x,
            ),
            origin_y: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originY",
                *origin_y,
            ),
            points: runtime_path_uint_property(
                artboard,
                path.local_id,
                path.type_name,
                "points",
                *points as u64,
            ) as u32,
            corner_radius: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "cornerRadius",
                *corner_radius,
            ),
            inner_radius: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "innerRadius",
                *inner_radius,
            ),
        }),
        ParametricPathNode::Rectangle {
            width,
            height,
            origin_x,
            origin_y,
            link_corner_radius,
            corner_radius_tl,
            corner_radius_tr,
            corner_radius_bl,
            corner_radius_br,
        } => Some(ParametricPathNode::Rectangle {
            width: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "width",
                *width,
            ),
            height: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "height",
                *height,
            ),
            origin_x: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originX",
                *origin_x,
            ),
            origin_y: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originY",
                *origin_y,
            ),
            link_corner_radius: runtime_path_bool_property(
                artboard,
                path.local_id,
                path.type_name,
                "linkCornerRadius",
                *link_corner_radius,
            ),
            corner_radius_tl: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "cornerRadiusTL",
                *corner_radius_tl,
            ),
            corner_radius_tr: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "cornerRadiusTR",
                *corner_radius_tr,
            ),
            corner_radius_bl: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "cornerRadiusBL",
                *corner_radius_bl,
            ),
            corner_radius_br: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "cornerRadiusBR",
                *corner_radius_br,
            ),
        }),
        ParametricPathNode::Triangle {
            width,
            height,
            origin_x,
            origin_y,
        } => Some(ParametricPathNode::Triangle {
            width: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "width",
                *width,
            ),
            height: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "height",
                *height,
            ),
            origin_x: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originX",
                *origin_x,
            ),
            origin_y: runtime_path_double_property(
                artboard,
                path.local_id,
                path.type_name,
                "originY",
                *origin_y,
            ),
        }),
    }
}

fn measure_parametric_path_layout(
    path: &PathGeometryNode,
    max_width: f32,
    max_height: f32,
) -> Option<(f32, f32)> {
    let (width, height) = match path.parametric.as_ref()? {
        ParametricPathNode::Ellipse { width, height, .. }
        | ParametricPathNode::Polygon { width, height, .. }
        | ParametricPathNode::Rectangle { width, height, .. }
        | ParametricPathNode::Star { width, height, .. }
        | ParametricPathNode::Triangle { width, height, .. } => (*width, *height),
    };
    Some((max_width.min(width), max_height.min(height)))
}

pub(crate) fn parametric_path_with_control_size(
    parametric: ParametricPathNode,
    width: f32,
    height: f32,
) -> ParametricPathNode {
    match parametric {
        ParametricPathNode::Ellipse {
            origin_x, origin_y, ..
        } => ParametricPathNode::Ellipse {
            width,
            height,
            origin_x,
            origin_y,
        },
        ParametricPathNode::Polygon {
            origin_x,
            origin_y,
            points,
            corner_radius,
            ..
        } => ParametricPathNode::Polygon {
            width,
            height,
            origin_x,
            origin_y,
            points,
            corner_radius,
        },
        ParametricPathNode::Star {
            origin_x,
            origin_y,
            points,
            corner_radius,
            inner_radius,
            ..
        } => ParametricPathNode::Star {
            width,
            height,
            origin_x,
            origin_y,
            points,
            corner_radius,
            inner_radius,
        },
        ParametricPathNode::Triangle {
            origin_x, origin_y, ..
        } => ParametricPathNode::Triangle {
            width,
            height,
            origin_x,
            origin_y,
        },
        ParametricPathNode::Rectangle {
            origin_x,
            origin_y,
            link_corner_radius,
            corner_radius_tl,
            corner_radius_tr,
            corner_radius_bl,
            corner_radius_br,
            ..
        } => ParametricPathNode::Rectangle {
            width,
            height,
            origin_x,
            origin_y,
            link_corner_radius,
            corner_radius_tl,
            corner_radius_tr,
            corner_radius_bl,
            corner_radius_br,
        },
    }
}

