    #[test]
    fn unresolved_draw_target_is_an_inert_graph_diagnostic_adaptation() {
        let bytes = include_bytes!("../../../fixtures/graph/clipping_and_draw_order.riv");
        let file = read_runtime_file(bytes).expect("fixture imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("fixture graphs");
        let mut graph = graphs
            .artboards
            .first()
            .expect("fixture has an artboard")
            .clone();
        let target = graph
            .draw_targets
            .first_mut()
            .expect("fixture has a draw target");
        let target_local = target.local_id;
        target.drawable_local = Some(usize::MAX);

        let instance = ArtboardInstance::from_graph(&file, &graph)
            .expect("Rust retains unresolved graph references as diagnostics");
        let retained = instance
            .runtime_drawables
            .draw_targets
            .iter()
            .find(|target| target.local_id == target_local)
            .expect("unresolved target remains inspectable");

        assert_eq!(retained.drawable_index, None);
        assert!(
            instance
                .runtime_drawables
                .drawables
                .iter()
                .take(instance.runtime_drawables.imported_count)
                .all(|drawable| drawable.draw_target_local != Some(target_local)),
            "the diagnostic target must not splice a drawable group"
        );
    }

    #[test]
    fn draw_order_dirt_relinks_retained_drawable_objects() {
        // Mirrors C++ `DrawTarget::placementValueChanged` ->
        // `ComponentDirt::DrawOrder` -> `Artboard::sortDrawOrder`
        // (`draw_target.cpp:28-31`, `artboard.cpp:574-746,1159-1165`).
        let bytes = include_bytes!("../../../fixtures/graph/clipping_and_draw_order.riv");
        let file = read_runtime_file(bytes).expect("fixture imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("fixture graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_pass();
        let active_target_local = instance
            .runtime_drawables
            .drawables
            .iter()
            .take(instance.runtime_drawables.imported_count)
            .find_map(|drawable| drawable.draw_target_local)
            .expect("fixture has a drawable group attached to a draw target");
        let target = graph
            .draw_targets
            .iter()
            .find(|target| target.local_id == active_target_local)
            .expect("active draw target is retained");
        let (active_drawable_local, active_rules_local) = instance
            .runtime_drawables
            .drawables
            .iter()
            .take(instance.runtime_drawables.imported_count)
            .find(|drawable| drawable.draw_target_local == Some(active_target_local))
            .and_then(|drawable| Some((drawable.local_id?, drawable.flattened_draw_rules_local?)))
            .expect("targeted drawable retains its flattened draw rules");

        let identities_before = instance
            .runtime_drawables
            .drawables
            .iter()
            .take(instance.runtime_drawables.imported_count)
            .filter_map(|drawable| {
                drawable
                    .local_id
                    .map(|local| (local, drawable.as_ref() as *const RuntimeDrawable as usize))
            })
            .collect::<BTreeMap<_, _>>();
        let order_before = instance
            .runtime_drawables
            .iter()
            .filter_map(|drawable| drawable.local_id)
            .collect::<Vec<_>>();
        let placement_key =
            property_key_for_name("DrawTarget", "placementValue").expect("placement key");
        let replacement = u64::from(target.placement_value == 0);
        instance
            .runtime_drawables
            .reset_artboard_maintenance_call_counts();
        assert!(instance.set_uint_property(target.local_id, placement_key, replacement));
        assert_eq!(
            instance.uint_property(target.local_id, placement_key),
            Some(replacement)
        );
        assert!(instance.update_pass());
        assert_eq!(
            instance
                .runtime_drawables
                .artboard_maintenance_call_counts(),
            (1, 1),
            "the generated DrawTarget callback publishes DrawOrder to the root Artboard"
        );

        let identities_after = instance
            .runtime_drawables
            .drawables
            .iter()
            .take(instance.runtime_drawables.imported_count)
            .filter_map(|drawable| {
                drawable
                    .local_id
                    .map(|local| (local, drawable.as_ref() as *const RuntimeDrawable as usize))
            })
            .collect::<BTreeMap<_, _>>();
        let order_after = instance
            .runtime_drawables
            .iter()
            .filter_map(|drawable| drawable.local_id)
            .collect::<Vec<_>>();

        assert_eq!(identities_after, identities_before);
        assert_ne!(
            order_after, order_before,
            "target={target:?} active={active_target_local} replacement={replacement}"
        );

        let drawable_flags_key =
            property_key_for_name("Drawable", "drawableFlags").expect("drawable flags key");
        let original_flags = instance
            .uint_property(active_drawable_local, drawable_flags_key)
            .expect("drawable flags are live instance state");
        assert!(instance.set_uint_property(
            active_drawable_local,
            drawable_flags_key,
            original_flags | 1,
        ));
        let active_drawable = instance
            .runtime_drawables
            .drawables
            .iter()
            .take(instance.runtime_drawables.imported_count)
            .find(|drawable| drawable.local_id == Some(active_drawable_local))
            .expect("active drawable remains retained");
        assert!(!instance.runtime_will_draw(active_drawable, false));
        assert!(instance.set_uint_property(
            active_drawable_local,
            drawable_flags_key,
            original_flags,
        ));

        let allocation_after_reorder = instance.runtime_drawables.drawables.len();
        let draw_target_id_key =
            property_key_for_name("DrawRules", "drawTargetId").expect("draw target id key");
        assert!(instance.set_uint_property(active_rules_local, draw_target_id_key, u64::MAX));
        assert!(instance.update_pass());
        let order_without_target = instance
            .runtime_drawables
            .iter()
            .filter_map(|drawable| drawable.local_id)
            .collect::<Vec<_>>();
        assert_ne!(order_without_target, order_after);
        assert!(instance.set_uint_property(
            active_rules_local,
            draw_target_id_key,
            active_target_local as u64,
        ));
        assert!(instance.update_pass());
        assert_eq!(
            instance
                .runtime_drawables
                .iter()
                .filter_map(|drawable| drawable.local_id)
                .collect::<Vec<_>>(),
            order_after
        );
        assert!(instance.set_uint_property(target.local_id, placement_key, target.placement_value));
        assert!(instance.update_pass());
        assert!(instance.set_uint_property(target.local_id, placement_key, replacement));
        assert!(instance.update_pass());
        assert_eq!(
            instance.runtime_drawables.drawables.len(),
            allocation_after_reorder,
            "ClippingShape proxy objects must return to their owner pool and be reused"
        );
    }

    #[test]
    fn draw_order_sort_uses_the_retained_draw_rules_owner() {
        // `DrawRules::onAddedDirty` resolves `m_ActiveTarget` once and the
        // generated setter refreshes that retained pointer before publishing
        // DrawOrder dirt. `Artboard::sortDrawOrder` never resolves the local
        // id again (`draw_rules.cpp:8-39`, `artboard.cpp:574-651`).
        let bytes = include_bytes!("../../../fixtures/graph/clipping_and_draw_order.riv");
        let file = read_runtime_file(bytes).expect("fixture imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("fixture graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_pass();

        let rules_local = instance
            .runtime_drawables
            .drawables
            .iter()
            .take(instance.runtime_drawables.imported_count)
            .find_map(|drawable| drawable.flattened_draw_rules_local)
            .expect("fixture has retained DrawRules");
        let order_before = instance
            .runtime_drawables
            .iter()
            .filter_map(|drawable| drawable.local_id)
            .collect::<Vec<_>>();
        let draw_target_id_key =
            property_key_for_name("DrawRules", "drawTargetId").expect("draw target id key");
        instance
            .runtime_drawables
            .reset_artboard_maintenance_call_counts();

        // This deliberately bypasses the generated DrawRules callback. It is
        // the Rust equivalent of changing deserialized backing storage after
        // onAddedDirty: the retained active target must remain authoritative.
        assert!(
            instance
                .objects
                .set_uint_property(rules_local, draw_target_id_key, u64::MAX)
        );
        assert!(instance.add_dirt(0, ComponentDirt::DRAW_ORDER, false));
        assert!(instance.update_pass());

        assert_eq!(
            instance
                .runtime_drawables
                .artboard_maintenance_call_counts(),
            (1, 1),
            "root DrawOrder dirt runs Artboard sorting once, including its clipping cleanup"
        );

        assert_eq!(
            instance
                .runtime_drawables
                .iter()
                .filter_map(|drawable| drawable.local_id)
                .collect::<Vec<_>>(),
            order_before,
            "DrawOrder sorting rediscovered DrawRules through its local id"
        );
    }

    #[test]
    fn draw_order_sort_uses_the_retained_draw_target_placement() {
        // `DrawTarget::onAddedDirty` retains its resolved Drawable and the
        // generated placement setter updates the retained target before
        // publishing DrawOrder dirt. Sorting must not re-read either backing
        // property (`draw_target.cpp:8-31`, `artboard.cpp:652-700`).
        let bytes = include_bytes!("../../../fixtures/graph/clipping_and_draw_order.riv");
        let file = read_runtime_file(bytes).expect("fixture imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("fixture graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_pass();

        let target = graph
            .draw_targets
            .iter()
            .find(|target| matches!(target.placement_value, 0 | 1))
            .expect("fixture has a placed draw target");
        let order_before = instance
            .runtime_drawables
            .iter()
            .filter_map(|drawable| drawable.local_id)
            .collect::<Vec<_>>();
        let placement_key =
            property_key_for_name("DrawTarget", "placementValue").expect("placement key");
        let drawable_id_key =
            property_key_for_name("DrawTarget", "drawableId").expect("drawable id key");
        let bypass_value = u64::from(target.placement_value == 0);

        assert!(
            instance
                .objects
                .set_uint_property(target.local_id, drawable_id_key, u64::MAX,)
        );
        assert!(
            instance
                .objects
                .set_uint_property(target.local_id, placement_key, bypass_value,)
        );
        assert!(instance.add_dirt(0, ComponentDirt::DRAW_ORDER, false));
        assert!(instance.update_pass());

        assert_eq!(
            instance
                .runtime_drawables
                .iter()
                .filter_map(|drawable| drawable.local_id)
                .collect::<Vec<_>>(),
            order_before,
            "DrawOrder sorting re-read the serialized DrawTarget placement"
        );
    }

    #[test]
    fn scripted_file_assets_displace_pending_image_importers() {
        let file = RuntimeFile::from_fixture_records(vec![
            fixture_record("Backboard", Vec::new()),
            fixture_record(
                "ImageAsset",
                vec![fixture_property(
                    "ImageAsset",
                    "assetId",
                    FixtureValue::Uint(10),
                )],
            ),
            fixture_record(
                "FileAssetContents",
                vec![fixture_property(
                    "FileAssetContents",
                    "bytes",
                    FixtureValue::Bytes(vec![1]),
                )],
            ),
            fixture_record(
                "ImageAsset",
                vec![fixture_property(
                    "ImageAsset",
                    "assetId",
                    FixtureValue::Uint(11),
                )],
            ),
            fixture_record(
                "FileAssetContents",
                vec![fixture_property(
                    "FileAssetContents",
                    "bytes",
                    FixtureValue::Bytes(vec![2]),
                )],
            ),
            fixture_record("ScriptAsset", Vec::new()),
            fixture_record(
                "FileAssetContents",
                vec![fixture_property(
                    "FileAssetContents",
                    "bytes",
                    FixtureValue::Bytes(vec![3]),
                )],
            ),
            fixture_record("Artboard", Vec::new()),
        ])
        .expect("file-asset import-order fixture imports");
        let image_globals = file
            .file_assets()
            .into_iter()
            .filter(|asset| asset.type_name == "ImageAsset")
            .map(|asset| asset.id)
            .collect::<Vec<_>>();
        let image_assets = RuntimeImageAssetCatalog::from_runtime(&file);

        assert_eq!(image_globals.len(), 2);
        assert_eq!(
            import_stack_pre_source_image_asset_globals(&file, &image_assets, false),
            vec![image_globals[0]],
            "a non-scripting importer leaves the final image pending"
        );
        assert_eq!(
            import_stack_pre_source_image_asset_globals(&file, &image_assets, true),
            image_globals,
            "WITH_RIVE_SCRIPTING treats ScriptAsset as the next FileAsset importer"
        );
    }

    #[test]
    fn large_image_catalog_scans_entries_once_and_serves_all_embedded_lookups() {
        const IMAGE_COUNT: usize = 4_096;

        let mut records = Vec::with_capacity(IMAGE_COUNT * 2 + 2);
        records.push(fixture_record("Backboard", Vec::new()));
        for ordinal in 0..IMAGE_COUNT {
            records.push(fixture_record(
                "ImageAsset",
                vec![fixture_property(
                    "ImageAsset",
                    "assetId",
                    FixtureValue::Uint(ordinal as u64),
                )],
            ));
            records.push(fixture_record(
                "FileAssetContents",
                vec![fixture_property(
                    "FileAssetContents",
                    "bytes",
                    FixtureValue::Bytes(vec![(ordinal & 0xff) as u8]),
                )],
            ));
        }
        records.push(fixture_record("Artboard", Vec::new()));
        let file = RuntimeFile::from_fixture_records(records)
            .expect("large image catalog fixture imports");
        let mut visited_entries = 0;

        let catalog = RuntimeImageAssetCatalog::from_entries(
            file.imported_file_assets_with_contents()
                .into_iter()
                .inspect(|_| visited_entries += 1),
        );

        assert_eq!(visited_entries, IMAGE_COUNT);
        assert_eq!(catalog.globals.len(), IMAGE_COUNT);
        for (ordinal, asset_global) in catalog.globals.iter().copied().enumerate() {
            assert_eq!(
                catalog.embedded_bytes(asset_global),
                Some(&[(ordinal & 0xff) as u8][..])
            );
        }
        assert_eq!(
            visited_entries, IMAGE_COUNT,
            "catalog lookups must not revisit the imported asset stream"
        );
    }

    #[test]
    fn text_draw_owner_rebuilds_only_after_object_local_dirt() {
        let owner = RuntimeTextDrawOwner::default();
        let builds = Cell::new(0usize);
        let build = || {
            builds.set(builds.get() + 1);
            Ok(RuntimeCachedTextShapePaints {
                commands: Arc::new(Vec::new()),
                replay: Arc::new(Vec::new()),
                paths: Arc::new(BTreeMap::new()),
                clip_path: None,
                clip_bounds: None,
                color: None,
                shape_local_transform: Mat2D::IDENTITY,
                publishes_layout_dirty: true,
            })
        };

        owner
            .retained_or_build(build)
            .expect("initial build succeeds");
        owner
            .retained_or_build(build)
            .expect("clean reuse succeeds");
        assert_eq!(builds.get(), 1);

        owner.mark_dirty();
        owner
            .retained_or_build(build)
            .expect("dirty rebuild succeeds");
        assert_eq!(builds.get(), 2);
    }

