    #[test]
    fn cloned_shape_occurrence_rebuilds_derived_paths_and_paint_state() {
        let bytes = synthetic_even_odd_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic riv graphs");
        let graph = graphs
            .artboards
            .first()
            .expect("synthetic riv has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_components();

        let mut cloned = instance.clone();
        let cloned_shape = cloned.runtime_shapes.get(1).expect("cloned Shape");
        assert!(
            cloned
                .runtime_shapes
                .paths_by_local
                .iter()
                .flatten()
                .all(|path| path.retained.borrow().is_none())
                && cloned_shape
                    .paint_paths
                    .iter()
                    .all(|path| path.retained.borrow().is_none())
                && cloned_shape
                    .paint_owners
                    .iter()
                    .all(|paint| paint.paint_state.borrow().is_none()),
            "Core clone copies current properties, then C++ reconstructs \
             PathComposer/ShapePaint derived state and renderer resources"
        );

        let report = cloned.update_components();
        assert!(report.did_update, "clone construction settlement must run");
        let cloned_shape = cloned.runtime_shapes.get(1).expect("settled cloned Shape");
        assert!(
            cloned_shape
                .paint_paths
                .iter()
                .any(|path| path.retained.borrow().is_some())
                && cloned_shape
                    .paint_owners
                    .iter()
                    .all(|paint| paint.paint_state.borrow().is_some()),
            "the clone-owned C++ lifecycle must repopulate paths and paint mutator state"
        );
    }

    #[test]
    fn inherited_shape_paint_blend_reads_the_live_container_property() {
        let bytes = synthetic_even_odd_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic riv graphs");
        let graph = graphs
            .artboards
            .first()
            .expect("synthetic riv has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        let paint_local = instance
            .runtime_shapes
            .get(1)
            .and_then(|shape| shape.paint_owners.first())
            .expect("ShapePaint owner")
            .paint_local;
        let paint_blend =
            property_key_for_name("ShapePaint", "blendModeValue").expect("ShapePaint blend key");
        let container_blend =
            property_key_for_name("Drawable", "blendModeValue").expect("Drawable blend key");
        if instance.uint_property(paint_local, paint_blend) != Some(127) {
            assert!(instance.set_uint_property(paint_local, paint_blend, 127));
        }
        assert!(instance.set_uint_property(1, container_blend, 14));
        instance.update_components();

        let paint = instance
            .runtime_shapes
            .get(1)
            .and_then(|shape| shape.paint_owners.first())
            .expect("settled ShapePaint owner");
        crate::shapes::shape_paint_container::reset_opacity_owner_resolution_count();
        assert_eq!(
            runtime_live_owned_shape_paint_blend_mode_value(&instance, paint),
            14,
            "ShapePaint::blendMode reads the live parent value when its own generated value is 127"
        );
        assert_eq!(
            crate::shapes::shape_paint_container::opacity_owner_resolution_count(),
            0,
            "a live paint query follows the retained C++ parent owner instead of re-walking the static graph"
        );
    }

    #[test]
    fn world_shape_paint_render_path_cache_follows_transform_writes() {
        use crate::TransformProperty;

        let bytes = synthetic_world_space_gradient_stroke_riv();
        let file = read_runtime_file(&bytes).expect("synthetic riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic riv graphs");
        let graph = graphs
            .artboards
            .first()
            .expect("synthetic riv has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_components();

        let stats = Rc::new(CountingStats::default());
        let mut factory = CountingFactory {
            stats,
            next_path_id: 0,
        };
        let mut paint_cache = preallocate_render_paint_cache_for_artboard_instance(
            &file,
            &instance,
            graph,
            &graphs.artboards,
            &mut factory,
        );
        let mut path_cache = RuntimeArtboardPathState::default();
        let mut renderer = PathGeometryRecordingRenderer::default();
        let mut geometry_cache = RuntimeGeometryState::default();

        instance
            .update_artboard_backend_tree(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("first prepare succeeds");
        instance
            .draw_artboard_internal_with_render_cache(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut renderer,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("first draw succeeds");
        let baseline = renderer
            .draw_paths
            .last()
            .cloned()
            .expect("world-space stroke draws a path");
        assert_eq!(
            instance.geometry_hit_test_with_context(
                &file,
                graph,
                RenderVec2D::new(5.0, 0.0),
                &mut geometry_cache,
            ),
            vec![1]
        );

        assert!(instance.set_transform_property(1, TransformProperty::X, 25.0));
        instance.update_components();
        instance
            .update_artboard_backend_tree(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("second prepare succeeds");
        instance
            .draw_artboard_internal_with_render_cache(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut renderer,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("second draw succeeds");
        let moved = renderer
            .draw_paths
            .last()
            .expect("moved world-space stroke draws a path");

        assert_path_points_translated(&baseline, moved, 25.0, 0.0);
        assert!(
            instance
                .geometry_hit_test_with_context(
                    &file,
                    graph,
                    RenderVec2D::new(5.0, 0.0),
                    &mut geometry_cache,
                )
                .is_empty(),
            "hit-test must leave the stale rendered position"
        );
        assert_eq!(
            instance.geometry_hit_test_with_context(
                &file,
                graph,
                RenderVec2D::new(30.0, 0.0),
                &mut geometry_cache,
            ),
            vec![1],
            "render and hit-test must move in lockstep"
        );
    }

