    #[test]
    fn artboard_background_path_is_retained_until_artboard_path_dirt() {
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"RIVE");
        push_var_uint(&mut bytes, 7);
        push_var_uint(&mut bytes, 0);
        push_var_uint(&mut bytes, 9662);
        push_var_uint(&mut bytes, 0);
        push_object(&mut bytes, "Backboard", |_| {});
        push_object(&mut bytes, "Artboard", |bytes| {
            push_f32(bytes, "LayoutComponent", "width", 100.0);
            push_f32(bytes, "LayoutComponent", "height", 50.0);
        });
        push_object(&mut bytes, "Fill", |bytes| {
            push_uint(bytes, "Component", "parentId", 0);
        });
        push_object(&mut bytes, "SolidColor", |bytes| {
            push_uint(bytes, "Component", "parentId", 1);
            push_color(bytes, "SolidColor", "colorValue", 0xff33_66aa);
        });

        let file = read_runtime_file(&bytes).expect("synthetic background imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic background graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_components();
        fn retained_background(instance: &ArtboardInstance) -> RuntimeShapePathState {
            instance
                .runtime_shapes
                .paint_path_owner(0, RuntimeShapePaintPathKind::Local)
                .and_then(|owner| owner.retained.borrow().clone())
                .expect("Artboard owns its settled local background path")
        }
        let before = retained_background(&instance);

        let mut factory = CountingFactory {
            stats: Rc::new(CountingStats::default()),
            next_path_id: 0,
        };
        let mut paint_cache = preallocate_render_paint_cache_for_artboard_instance(
            &file,
            &instance,
            graph,
            &graphs.artboards,
            &mut factory,
        );
        let mut path_cache = RuntimeArtboardPathState::default();
        let mut renderer = RecordingRenderer {
            ops: Rc::new(RefCell::new(Vec::new())),
        };
        for _ in 0..2 {
            instance
                .draw_artboard_internal_with_render_cache(
                    &file,
                    graph,
                    &graphs.artboards,
                    &mut factory,
                    &mut renderer,
                    &mut paint_cache,
                    &mut path_cache,
                )
                .expect("unchanged background draw succeeds");
        }
        let after_clean_draws = retained_background(&instance);
        assert!(
            Arc::ptr_eq(&before.raw_path, &after_clean_draws.raw_path),
            "Artboard::drawInternal reads m_ShapePaints and m_localPath; only \
             LayoutComponent::update calls Artboard::updateRenderPath \
             (artboard.cpp:1138-1157,1630-1650; layout_component.cpp:91-120)"
        );

        let origin_x = property_key_for_name("Artboard", "originX").expect("Artboard.originX key");
        assert!(instance.set_double_property(0, origin_x, 0.25));
        instance.update_components();
        let after_path_dirt = retained_background(&instance);
        assert!(
            !Arc::ptr_eq(&before.raw_path, &after_path_dirt.raw_path),
            "Artboard::originXChanged adds Path dirt before updateRenderPath \
             rebuilds the owner-local rectangle (artboard.cpp:1755-1768)"
        );

        let width =
            property_key_for_name("LayoutComponent", "width").expect("LayoutComponent.width key");
        assert!(instance.set_double_property(0, width, 150.0));
        instance.update_components();
        let after_width_dirt = retained_background(&instance);
        assert!(
            !Arc::ptr_eq(&after_path_dirt.raw_path, &after_width_dirt.raw_path),
            "LayoutComponent widthChanged dirties layout; a changed solved \
             width adds Path dirt before Artboard::updateRenderPath \
             (layout_component.cpp:1116-1124,1564-1565; \
             artboard.cpp:1138-1157)"
        );

        renderer.ops.borrow_mut().clear();
        instance.clip = true;
        assert!(instance.set_transform_property(
            0,
            TransformProperty::Rotation,
            std::f32::consts::FRAC_PI_2,
        ));
        instance.update_components();
        instance
            .draw_artboard_internal_with_render_cache(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut renderer,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("transformed, clipped background draw succeeds");
        let transformed_ops = renderer.ops.borrow();
        assert_eq!(transformed_ops.first().map(String::as_str), Some("save"));
        let clip_index = transformed_ops
            .iter()
            .position(|op| op == "clip_path")
            .expect("the clipped artboard emits its local clip");
        let transform_indices = transformed_ops
            .iter()
            .enumerate()
            .filter_map(|(index, op)| op.starts_with("transform:").then_some(index))
            .collect::<Vec<_>>();
        assert!(
            transform_indices
                .iter()
                .filter(|index| **index < clip_index)
                .count()
                >= 2,
            "the frame-origin and artboard self transforms both precede the local clip: {transformed_ops:?}"
        );
        drop(transformed_ops);

        renderer.ops.borrow_mut().clear();
        assert!(instance.set_host_opacity(0.0));
        instance
            .draw_artboard_internal_with_render_cache(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut renderer,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("host-transparent background draw succeeds");
        assert!(
            renderer.ops.borrow().is_empty(),
            "childOpacity, not the artboard's authored opacity alone, controls the draw early return"
        );
    }

    #[test]
    fn path_collapse_rebuilds_the_owned_shape_paint_path_in_the_same_update() {
        let bytes = synthetic_even_odd_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic local-paint riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic local-paint graphs");
        let graph = graphs
            .artboards
            .first()
            .expect("synthetic riv has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.update_components();

        let owned_local_path = |instance: &ArtboardInstance| {
            instance
                .runtime_shapes
                .paint_path_owner(1, RuntimeShapePaintPathKind::Local)
                .and_then(|owner| owner.retained.borrow().clone())
                .expect("the settled PathComposer owns its local path")
        };
        let before = owned_local_path(&instance);
        let before_commands = runtime_path_commands_from_raw_path(before.raw_path.as_ref());

        // Pinned C++ does not treat collapse as a scene-cache epoch. It calls
        // Path::collapse -> Shape::pathCollapseChanged ->
        // PathComposer::pathCollapseChanged and forcibly adds Path dirt to
        // the composer and its dependents (path.cpp:384-390,
        // shape.cpp:330, path_composer.cpp:119-133).
        assert!(instance.collapse_component(5, true));
        assert!(instance.update_components().did_update);
        let collapsed = owned_local_path(&instance);
        let collapsed_commands = runtime_path_commands_from_raw_path(collapsed.raw_path.as_ref());
        assert!(
            !Arc::ptr_eq(&before.raw_path, &collapsed.raw_path)
                && collapsed_commands.len() < before_commands.len(),
            "collapsing the inner Rectangle must recompose the owner without its contour"
        );
        assert!(
            !instance.update_components().did_update,
            "C++ updateComponents leaves collapsed component dirt parked and \
             clears Artboard::Components after the dependency pass; the \
             retained Path owner must not re-arm an unchanged frame \
             (artboard.cpp:1214-1230)"
        );
        assert!(
            Arc::ptr_eq(&collapsed.raw_path, &owned_local_path(&instance).raw_path),
            "a clean frame retains the ShapePaintPath owner"
        );

        assert!(instance.collapse_component(5, false));
        assert!(instance.update_components().did_update);
        let restored = owned_local_path(&instance);
        assert!(
            !Arc::ptr_eq(&collapsed.raw_path, &restored.raw_path)
                && runtime_path_commands_from_raw_path(restored.raw_path.as_ref())
                    == before_commands,
            "uncollapsing the Path must restore its contour in that same update"
        );
    }

