    #[test]
    fn cyclic_parametric_path_parent_chain_falls_back_without_layout_control() {
        let bytes = synthetic_layout_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic layout riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic layout riv graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        let local_for_type = |type_name| {
            instance
                .components()
                .iter()
                .find(|component| component.type_name == type_name)
                .unwrap_or_else(|| panic!("fixture has a {type_name}"))
                .local_id
        };
        let rectangle_local = local_for_type("Rectangle");
        let fill_local = local_for_type("Fill");
        let solid_color_local = local_for_type("SolidColor");

        let fill = instance.component_handle(fill_local).unwrap();
        let solid_color = instance.component_handle(solid_color_local).unwrap();
        instance.component_mut(rectangle_local).unwrap().parent = Some(fill);
        instance.component_mut(fill_local).unwrap().parent = Some(solid_color);
        instance.component_mut(solid_color_local).unwrap().parent = Some(fill);

        assert_eq!(
            instance.runtime_layout_control_size_for_path(rectangle_local, &BTreeMap::new()),
            None,
            "a cyclic non-layout parent chain must use the authored path size fallback"
        );
    }

    #[test]
    fn refreshed_layout_control_rebuilds_retained_parametric_path() {
        let bytes = synthetic_layout_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic layout riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic layout riv graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        let rectangle_local = instance
            .components()
            .iter()
            .find(|component| component.type_name == "Rectangle")
            .expect("fixture has a rectangle")
            .local_id;
        let layout_local = instance
            .component_parent_local(rectangle_local)
            .and_then(|shape_local| instance.component_parent_local(shape_local))
            .expect("rectangle is controlled by a layout");
        instance
            .component(layout_local)
            .and_then(|component| component.concrete.layout.as_ref())
            .expect("fixture has retained layout state")
            .set_animation_style(0, 0, 0.0, None);

        instance.enable_layout_constraint_bounds();
        instance.update_components();
        let width_key =
            property_key_for_name("LayoutComponent", "width").expect("LayoutComponent.width key");
        assert!(instance.set_double_property(layout_local, width_key, 140.0));
        instance.refresh_layout_constraint_bounds();
        assert_eq!(
            instance.runtime_parametric_path_layout_control_size(rectangle_local, graph),
            Some((140.0, 100.0))
        );

        instance.update_components();
        let retained = instance.runtime_shapes.paths_by_local[rectangle_local]
            .as_ref()
            .expect("rectangle owns a retained path")
            .retained
            .borrow();
        let points = retained
            .as_ref()
            .expect("rectangle path was built")
            .raw_path
            .points();
        let (minimum_x, maximum_x) = points.iter().fold(
            (f32::INFINITY, f32::NEG_INFINITY),
            |(minimum, maximum), point| (minimum.min(point.x), maximum.max(point.x)),
        );
        assert_eq!(
            maximum_x - minimum_x,
            140.0,
            "LayoutComponent::propagateSize must rebuild the ParametricPath at its new control \
             size, got {points:?}"
        );
    }

    #[test]
    fn parametric_layout_control_uses_the_live_animated_frame() {
        let bytes = synthetic_layout_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic layout riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic layout riv graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        let rectangle_local = instance
            .components()
            .iter()
            .find(|component| component.type_name == "Rectangle")
            .expect("fixture has a rectangle")
            .local_id;
        let layout_local = instance
            .component_parent_local(rectangle_local)
            .and_then(|shape_local| instance.component_parent_local(shape_local))
            .expect("rectangle is controlled by a layout");
        let layout = instance
            .component(layout_local)
            .and_then(|component| component.concrete.layout.as_ref())
            .expect("fixture has retained layout state");
        layout.set_animation_style(2, 1, 1.0, None);
        layout.retain_bounds(0.0, 0.0, 90.0, 60.0);
        layout.retain_bounds(0.0, 0.0, 140.0, 100.0);
        let solved_bounds = BTreeMap::from([(
            layout_local,
            RuntimeLayoutBounds {
                x: 30.0,
                y: 40.0,
                width: 140.0,
                height: 100.0,
            },
        )]);

        assert_eq!(
            instance.runtime_layout_control_size_for_path(rectangle_local, &solved_bounds),
            Some(RuntimeLayoutBounds {
                x: 30.0,
                y: 40.0,
                width: 90.0,
                height: 60.0,
            }),
            "LayoutComponent::propagateSize reads the interpolating m_layout frame, not its newer Yoga target"
        );
        assert_eq!(
            instance.runtime_layout_component_draw_bounds(
                layout_local,
                graph,
                Some(&solved_bounds),
            ),
            RuntimeLayoutBounds {
                x: 30.0,
                y: 40.0,
                width: 90.0,
                height: 60.0,
            },
            "LayoutComponent::updateRenderPath keeps the solved artboard-space position while reading the live m_layout size"
        );
    }

    #[test]
    fn interpolating_layout_world_transform_reads_the_animated_position() {
        let bytes = synthetic_layout_geometry_riv();
        let file = read_runtime_file(&bytes).expect("synthetic layout riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic layout riv graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        let layout_locals = instance
            .components()
            .iter()
            .filter(|component| component.type_name == "LayoutComponent")
            .map(|component| component.local_id)
            .collect::<Vec<_>>();
        let [parent_local, child_local] = layout_locals.as_slice() else {
            panic!("fixture has two child layouts");
        };
        let parent_local = *parent_local;
        let child_local = *child_local;
        let parent = instance
            .component_handle(parent_local)
            .expect("parent layout has a component handle");
        instance
            .component_mut(child_local)
            .expect("child layout remains live")
            .parent = Some(parent);

        let child = instance
            .component(child_local)
            .and_then(|component| component.concrete.layout.as_ref())
            .expect("child has retained layout state");
        child.set_animation_style(2, 1, 1.0, None);
        child.retain_bounds(10.0, 20.0, 90.0, 60.0);
        child.retain_bounds(40.0, 50.0, 90.0, 60.0);
        let solved_bounds = BTreeMap::from([
            (
                parent_local,
                RuntimeLayoutBounds {
                    x: 100.0,
                    y: 200.0,
                    width: 100.0,
                    height: 100.0,
                },
            ),
            (
                child_local,
                RuntimeLayoutBounds {
                    x: 140.0,
                    y: 250.0,
                    width: 90.0,
                    height: 60.0,
                },
            ),
        ]);
        assert_mat2d_near(
            instance
                .runtime_layout_component_world_transform_with_bounds(
                    child_local,
                    graph,
                    Some(&solved_bounds),
                )
                .0,
            [1.0, 0.0, 0.0, 1.0, 110.0, 220.0],
        );

        child.advance_interpolation(2.0, true);
        // Runtime layout interpolation intentionally applies the prior elapsed
        // value before adding the current delta. The following zero-delta
        // frame observes the elapsed 2s and takes the completion branch.
        child.advance_interpolation(0.0, true);
        assert_mat2d_near(
            instance
                .runtime_layout_component_world_transform_with_bounds(
                    child_local,
                    graph,
                    Some(&solved_bounds),
                )
                .0,
            [1.0, 0.0, 0.0, 1.0, 140.0, 250.0],
        );
    }

