    struct TestRenderPaint {
        stats: Rc<CountingStats>,
        has_shader: bool,
    }

    impl RenderPaint for TestRenderPaint {
        fn as_any(&self) -> &dyn Any {
            self
        }

        fn style(&mut self, _style: RenderPaintStyle) {
            self.stats.paint_ops.borrow_mut().push("style");
        }
        fn color(&mut self, _value: ColorInt) {
            self.stats.paint_ops.borrow_mut().push("color");
        }
        fn thickness(&mut self, _value: f32) {
            self.stats.paint_ops.borrow_mut().push("thickness");
        }
        fn join(&mut self, _value: RenderStrokeJoin) {
            self.stats.paint_ops.borrow_mut().push("join");
        }
        fn cap(&mut self, _value: RenderStrokeCap) {
            self.stats.paint_ops.borrow_mut().push("cap");
        }
        fn feather(&mut self, _value: f32) {
            self.stats.paint_ops.borrow_mut().push("feather");
        }
        fn blend_mode(&mut self, _value: RenderBlendMode) {
            self.stats.paint_ops.borrow_mut().push("blend_mode");
        }
        fn shader(&mut self, shader: Option<&dyn RenderShader>) {
            self.stats.paint_ops.borrow_mut().push("shader");
            self.has_shader = shader.is_some();
        }
        fn invalidate_stroke(&mut self) {
            self.stats.paint_ops.borrow_mut().push("invalidate_stroke");
        }
    }

    impl RenderFactory for CountingFactory {
        fn make_render_buffer(
            &mut self,
            buffer_type: RenderBufferType,
            flags: RenderBufferFlags,
            size_in_bytes: usize,
        ) -> Box<dyn RenderBuffer> {
            Box::new(TestRenderBuffer {
                buffer_type,
                flags,
                bytes: vec![0; size_in_bytes],
            })
        }

        fn make_linear_gradient(
            &mut self,
            sx: f32,
            sy: f32,
            ex: f32,
            ey: f32,
            colors: &[ColorInt],
            _stops: &[f32],
        ) -> Box<dyn RenderShader> {
            self.stats
                .linear_gradients
                .borrow_mut()
                .push([sx, sy, ex, ey]);
            self.stats
                .linear_gradient_colors
                .borrow_mut()
                .push(colors.to_vec());
            Box::new(TestRenderShader)
        }

        fn make_radial_gradient(
            &mut self,
            _cx: f32,
            _cy: f32,
            _radius: f32,
            _colors: &[ColorInt],
            _stops: &[f32],
        ) -> Box<dyn RenderShader> {
            Box::new(TestRenderShader)
        }

        fn make_render_path(
            &mut self,
            raw_path: RawPath,
            fill_rule: RenderFillRule,
        ) -> Box<dyn RenderPath> {
            let id = self.next_path_id;
            self.next_path_id += 1;
            Box::new(CountingRenderPath {
                stats: Rc::clone(&self.stats),
                id,
                raw_path,
                fill_rule,
            })
        }

        fn make_empty_render_path(&mut self) -> Box<dyn RenderPath> {
            self.stats
                .make_empty_paths
                .set(self.stats.make_empty_paths.get() + 1);
            self.stats.path_ops.borrow_mut().push(PathOp::MakeEmpty);
            self.make_render_path(RawPath::new(), RenderFillRule::NonZero)
        }

        fn make_render_paint(&mut self) -> Box<dyn RenderPaint> {
            self.stats.paint_ops.borrow_mut().push("make");
            Box::new(TestRenderPaint {
                stats: Rc::clone(&self.stats),
                has_shader: false,
            })
        }

        fn decode_image(
            &mut self,
            _data: &[u8],
        ) -> std::result::Result<Box<dyn RenderImage>, ImageDecodeError> {
            self.stats
                .image_decode_attempts
                .set(self.stats.image_decode_attempts.get() + 1);
            let failures_remaining = self.stats.image_decode_failures_remaining.get();
            if failures_remaining != 0 {
                self.stats
                    .image_decode_failures_remaining
                    .set(failures_remaining - 1);
                return Err(ImageDecodeError);
            }
            Ok(Box::new(TestRenderImage))
        }
    }

    fn compressed_rgba_png(width: u32, height: u32) -> Vec<u8> {
        let decoded_byte_length = decoded_rgba_len(width, height).expect("test image is bounded");
        let mut encoded = Vec::new();
        {
            let mut encoder = png::Encoder::new(&mut encoded, width, height);
            encoder.set_color(png::ColorType::Rgba);
            encoder.set_depth(png::BitDepth::Eight);
            let mut writer = encoder.write_header().expect("PNG header encodes");
            writer
                .write_image_data(&vec![0; decoded_byte_length])
                .expect("PNG pixels encode");
        }
        encoded
    }

    // The bounded host import policy exercised by these admission tests; the
    // high-level `nuxie::File` default in `FileImportLimits`.
    const HOST_BOUNDED_DECODED_IMAGE_BYTES: usize = 64 * 1024 * 1024;

    #[test]
    fn artboard_clone_shares_file_image_and_mesh_source_but_not_occurrence_buffers() {
        let bytes = include_bytes!("../../../fixtures/graph/dependency_test.riv");
        let file = read_runtime_file(bytes).expect("fixture imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("fixture graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        let image_assets = Arc::new(RuntimeImageAssetOwners::default());
        image_assets.insert(7, Box::new(TestRenderImage));
        instance
            .runtime_image_assets
            .replace(Some(Arc::clone(&image_assets)));

        let shared = Rc::new(RefCell::new(RuntimeMeshSharedRenderBuffers::default()));
        let mesh = RuntimeMeshOwner {
            local_id: 1,
            vertex_locals: Vec::new(),
            shared: RefCell::new(Rc::clone(&shared)),
            vertices: RefCell::new(Some((
                image_assets.backend_context_id(),
                nuxie_render_api::NullFactory::new().make_render_buffer(
                    RenderBufferType::Vertex,
                    RenderBufferFlags::None,
                    16,
                ),
            ))),
            vertex_render_buffer_dirty: Cell::new(false),
            settled_vertex_bytes: RefCell::new(Some(vec![0; 16])),
        };
        instance.runtime_meshes = RuntimeMeshList {
            meshes_by_local: vec![None, Some(mesh)],
            slices_by_local: vec![None, Some(RefCell::new(RuntimeSliceMeshOwner::new(1)))],
            details_by_local: Vec::new(),
        };

        let cloned = instance.clone();
        let original_assets = instance
            .runtime_image_assets
            .borrow()
            .as_ref()
            .map(Arc::clone)
            .expect("source occurrence retains the file owner list");
        let cloned_assets = cloned
            .runtime_image_assets
            .borrow()
            .as_ref()
            .map(Arc::clone)
            .expect("clone retains the same file owner list");
        assert!(Arc::ptr_eq(&original_assets, &cloned_assets));
        assert!(Rc::ptr_eq(
            &instance
                .runtime_meshes
                .mesh(1)
                .expect("source mesh")
                .shared
                .borrow(),
            &cloned
                .runtime_meshes
                .mesh(1)
                .expect("cloned mesh")
                .shared
                .borrow(),
        ));
        assert!(
            instance
                .runtime_meshes
                .mesh(1)
                .expect("source mesh")
                .vertices
                .borrow()
                .is_some()
        );
        assert!(
            cloned
                .runtime_meshes
                .mesh(1)
                .expect("cloned mesh")
                .vertices
                .borrow()
                .is_none(),
            "Mesh::clone creates a fresh dynamic vertex-buffer member",
        );
        assert!(
            cloned
                .runtime_meshes
                .mesh(1)
                .expect("cloned mesh")
                .vertex_render_buffer_dirty
                .get()
        );
        assert!(
            cloned
                .runtime_meshes
                .slice(1)
                .expect("cloned slicer")
                .borrow()
                .dirty,
            "NSlicer clone constructs a fresh unique SliceMesh",
        );
    }

    #[test]
    fn image_asset_replacement_notifies_each_image_referencer() {
        let bytes = synthetic_image_nslicer_riv();
        let file = read_runtime_file(&bytes).expect("fixture imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("fixture graphs");
        let graph = graphs.artboards.first().expect("fixture has an artboard");
        let mut instance = ArtboardInstance::from_graph(&file, graph).expect("instance builds");
        instance.image_asset_overrides.insert(1, Some(7));
        let image_assets = Arc::new(RuntimeImageAssetOwners::default());
        image_assets.insert(
            7,
            Box::new(SizedTestRenderImage {
                width: 10,
                height: 10,
            }),
        );
        instance.attach_runtime_image_assets_tree(Arc::clone(&image_assets));
        instance.runtime_images.control_size(1, 40.0, 50.0);
        instance.update_pass();

        let image_locals = instance
            .runtime_drawables
            .drawables
            .iter()
            .filter(|drawable| drawable.type_name == "Image")
            .filter_map(|drawable| drawable.local_id)
            .collect::<Vec<_>>();
        assert!(
            !image_locals.is_empty(),
            "fixture must retain an Image referencer"
        );

        image_assets.insert(
            7,
            Box::new(SizedTestRenderImage {
                width: 20,
                height: 30,
            }),
        );
        assert!(
            instance.runtime_image_asset_referencer.is_pending(),
            "ImageAsset::renderImage publishes to registered referencers synchronously",
        );
        let settled =
            image::runtime_image_layout_local_transform(&instance, 1, Mat2D::IDENTITY, true)
                .expect("replacement settles the direct Image owner inline");
        assert_eq!(settled.render_scale_x, 2.0);
        assert!((settled.render_scale_y - (50.0 / 30.0)).abs() <= f32::EPSILON);
        assert!(instance.settle_runtime_image_asset_updates());
        for local_id in image_locals {
            assert!(
                instance
                    .component(local_id)
                    .expect("Image occurrence")
                    .dirt
                    .contains(ComponentDirt::WORLD_TRANSFORM),
                "Image::assetUpdated marks the referencer's world transform dirty"
            );
        }
    }

    #[test]
    fn retained_images_reserve_one_aggregate_decoded_budget_before_decode() {
        const WIDTH: u32 = 4_096;
        const HEIGHT: u32 = 2_048;

        let encoded = compressed_rgba_png(WIDTH, HEIGHT);
        assert_eq!(
            nuxie_image_codec::validate_encoded_image(&encoded),
            Some(nuxie_image_codec::DecodedImageDimensions {
                width: WIDTH,
                height: HEIGHT,
            }),
            "the compressed regression payload must be fully valid"
        );
        let file = RuntimeFile::from_fixture_records(vec![
            fixture_record("Backboard", Vec::new()),
            fixture_record(
                "ImageAsset",
                vec![fixture_property(
                    "ImageAsset",
                    "assetId",
                    FixtureValue::Uint(10),
                )],
            ),
            fixture_record(
                "FileAssetContents",
                vec![fixture_property(
                    "FileAssetContents",
                    "bytes",
                    FixtureValue::Bytes(encoded.clone()),
                )],
            ),
            fixture_record(
                "ImageAsset",
                vec![fixture_property(
                    "ImageAsset",
                    "assetId",
                    FixtureValue::Uint(11),
                )],
            ),
            fixture_record(
                "ImageAsset",
                vec![fixture_property(
                    "ImageAsset",
                    "assetId",
                    FixtureValue::Uint(12),
                )],
            ),
            fixture_record("Artboard", Vec::new()),
        ])
        .expect("mixed embedded/external image fixture imports");
        let image_globals = file
            .file_assets()
            .into_iter()
            .filter(|asset| asset.type_name == "ImageAsset")
            .map(|asset| asset.id)
            .collect::<Vec<_>>();
        let image_assets = RuntimeImageAssetCatalog::from_runtime(&file);
        assert_eq!(image_globals.len(), 3);
        let external_images = BTreeMap::from([
            (11, Arc::<[u8]>::from(encoded.clone())),
            (12, Arc::<[u8]>::from(encoded)),
        ]);
        let stats = Rc::new(CountingStats::default());
        stats.image_decode_failures_remaining.set(1);
        let mut factory = CountingFactory {
            stats: Rc::clone(&stats),
            next_path_id: 0,
        };
        let images = RuntimeImageAssetOwners::with_max_retained_decoded_bytes(Some(
            HOST_BOUNDED_DECODED_IMAGE_BYTES,
        ));

        assert_eq!(
            predecode_render_image(
                &file,
                &image_assets,
                image_globals[0],
                Some(&external_images),
                &mut factory,
                &images,
            ),
            Err(ImageDecodeError),
            "a codec failure propagates"
        );
        assert_eq!(
            images.retained_decoded_bytes(),
            0,
            "failed decode rolls back"
        );
        predecode_render_image(
            &file,
            &image_assets,
            image_globals[0],
            Some(&external_images),
            &mut factory,
            &images,
        )
        .expect("embedded image retry decodes");
        predecode_render_image(
            &file,
            &image_assets,
            image_globals[1],
            Some(&external_images),
            &mut factory,
            &images,
        )
        .expect("external image fills the remaining budget");
        assert_eq!(
            images.retained_decoded_bytes(),
            HOST_BOUNDED_DECODED_IMAGE_BYTES
        );
        assert_eq!(
            predecode_render_image(
                &file,
                &image_assets,
                image_globals[2],
                Some(&external_images),
                &mut factory,
                &images,
            ),
            Err(ImageDecodeError),
            "the third individually valid compressed image exceeds the aggregate budget"
        );
        assert_eq!(
            stats.image_decode_attempts.get(),
            3,
            "aggregate admission rejects before invoking the decoder"
        );
        assert!(images.get(image_globals[0]).is_some());
        assert!(images.get(image_globals[1]).is_some());
        assert!(images.get(image_globals[2]).is_none());
    }

    #[test]
    fn retained_image_replacement_admits_net_size_and_rejects_atomically() {
        const HALF_BUDGET_WIDTH: u32 = 4_096;
        const HALF_BUDGET_HEIGHT: u32 = 2_048;

        let images = RuntimeImageAssetOwners::with_max_retained_decoded_bytes(Some(
            HOST_BOUNDED_DECODED_IMAGE_BYTES,
        ));
        for global_id in [7, 8] {
            images.insert(
                global_id,
                Box::new(SizedTestRenderImage {
                    width: HALF_BUDGET_WIDTH,
                    height: HALF_BUDGET_HEIGHT,
                }),
            );
        }
        assert_eq!(
            images.retained_decoded_bytes(),
            HOST_BOUNDED_DECODED_IMAGE_BYTES,
            "two half-budget images fill the aggregate exactly",
        );

        images.insert(
            7,
            Box::new(SizedTestRenderImage {
                width: 1,
                height: 1,
            }),
        );
        let replacement = images.get(7).expect("smaller replacement is retained");
        assert_eq!((replacement.width(), replacement.height()), (1, 1));
        let retained_after_replacement = decoded_rgba_len(HALF_BUDGET_WIDTH, HALF_BUDGET_HEIGHT)
            .expect("half-budget dimensions are valid")
            .checked_add(decoded_rgba_len(1, 1).expect("one pixel is valid"))
            .expect("test dimensions fit usize");
        assert_eq!(images.retained_decoded_bytes(), retained_after_replacement);

        images.insert(
            7,
            Box::new(SizedTestRenderImage {
                width: 4_096,
                height: 3_072,
            }),
        );
        let retained = images
            .get(7)
            .expect("a rejected replacement preserves the current image");
        assert_eq!(
            (retained.width(), retained.height()),
            (1, 1),
            "the other half-budget image plus a 48 MiB replacement exceeds the aggregate",
        );
        assert_eq!(
            images.retained_decoded_bytes(),
            retained_after_replacement,
            "a rejected replacement must not mutate aggregate accounting",
        );
    }

    #[test]
    fn retained_images_without_budget_admit_past_the_bounded_host_policy() {
        const HALF_BUDGET_WIDTH: u32 = 4_096;
        const HALF_BUDGET_HEIGHT: u32 = 2_048;

        let images = RuntimeImageAssetOwners::default();
        for global_id in [7, 8, 9] {
            images.insert(
                global_id,
                Box::new(SizedTestRenderImage {
                    width: HALF_BUDGET_WIDTH,
                    height: HALF_BUDGET_HEIGHT,
                }),
            );
        }
        for global_id in [7, 8, 9] {
            assert!(
                images.get(global_id).is_some(),
                "the unbounded compatibility path retains every image, like C++",
            );
        }
        assert!(images.retained_decoded_bytes() > HOST_BOUNDED_DECODED_IMAGE_BYTES);
    }

