    fn synthetic_nested_layout_gradient_chain_riv() -> Vec<u8> {
        fn push_gradient_artboard(
            bytes: &mut Vec<u8>,
            end_x: f32,
            nested_artboard_id: Option<u64>,
        ) {
            push_object(bytes, "Artboard", |bytes| {
                push_f32(bytes, "LayoutComponent", "width", 100.0);
                push_f32(bytes, "LayoutComponent", "height", 100.0);
            });
            push_object(bytes, "Shape", |bytes| {
                push_uint(bytes, "Node", "parentId", 0);
            });
            push_object(bytes, "Fill", |bytes| {
                push_uint(bytes, "Component", "parentId", 1);
            });
            push_object(bytes, "LinearGradient", |bytes| {
                push_uint(bytes, "Component", "parentId", 2);
                push_f32(bytes, "LinearGradient", "endX", end_x);
            });
            push_object(bytes, "GradientStop", |bytes| {
                push_uint(bytes, "Component", "parentId", 3);
                push_color(bytes, "GradientStop", "colorValue", 0xffff_0000);
                push_f32(bytes, "GradientStop", "position", 0.0);
            });
            push_object(bytes, "GradientStop", |bytes| {
                push_uint(bytes, "Component", "parentId", 3);
                push_color(bytes, "GradientStop", "colorValue", 0xff00_00ff);
                push_f32(bytes, "GradientStop", "position", 1.0);
            });
            push_object(bytes, "Rectangle", |bytes| {
                push_uint(bytes, "Node", "parentId", 1);
                push_f32(bytes, "ParametricPath", "width", 10.0);
                push_f32(bytes, "ParametricPath", "height", 10.0);
            });
            if let Some(artboard_id) = nested_artboard_id {
                push_object(bytes, "NestedArtboardLayout", |bytes| {
                    push_uint(bytes, "Node", "parentId", 0);
                    push_uint(bytes, "NestedArtboard", "artboardId", artboard_id);
                });
            }
        }

        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"RIVE");
        push_var_uint(&mut bytes, 7);
        push_var_uint(&mut bytes, 0);
        push_var_uint(&mut bytes, 9632);
        push_var_uint(&mut bytes, 0);
        push_object(&mut bytes, "Backboard", |_| {});
        push_object(&mut bytes, "Artboard", |bytes| {
            push_f32(bytes, "LayoutComponent", "width", 100.0);
            push_f32(bytes, "LayoutComponent", "height", 100.0);
        });
        push_object(&mut bytes, "NestedArtboardLayout", |bytes| {
            push_uint(bytes, "Node", "parentId", 0);
            push_uint(bytes, "NestedArtboard", "artboardId", 1);
        });
        push_gradient_artboard(&mut bytes, 10.0, Some(2));
        push_gradient_artboard(&mut bytes, 20.0, None);
        bytes
    }

    #[test]
    fn pending_initial_nested_layout_frames_drain_authoritative_descendants_once() {
        let bytes = synthetic_nested_layout_gradient_chain_riv();
        let file = read_runtime_file(&bytes).expect("nested layout chain imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("nested layout chain graphs");
        let graph = graphs.artboards.first().expect("parent graph");
        let instance = ArtboardInstance::from_graph_with_artboards(&file, graph, &graphs.artboards)
            .expect("nested layout chain instance");

        let parent_nested = instance
            .nested_artboards
            .values()
            .next()
            .expect("parent nested layout host");
        let parent_frame = parent_nested
            .child
            .capture_initial_nested_layout_paint_frame();
        assert_eq!(
            parent_frame.gradients.len(),
            1,
            "the frame records the intermediate Shape-owned shader event \
             created by NestedArtboard::update(Filthy) before ownership \
             returns to the live occurrence (nested_artboard.cpp:626-652)"
        );
        assert!(
            parent_frame.gradients[0].is_owned_shape,
            "the frame must retain ShapePaint ownership provenance"
        );
        parent_nested
            .child
            .transfer_owned_shape_gradient_events_to_initial_frame(&parent_frame);
        let child_nested = parent_nested
            .child
            .nested_artboards
            .values()
            .next()
            .expect("child nested layout host");
        let child_frame = child_nested
            .child
            .capture_initial_nested_layout_paint_frame();
        assert_eq!(
            child_frame.gradients.len(),
            1,
            "each mounted layout level owns its own intermediate shader event"
        );
        assert!(
            child_frame.gradients[0].is_owned_shape,
            "the descendant frame must retain ShapePaint ownership provenance"
        );
        child_nested
            .child
            .transfer_owned_shape_gradient_events_to_initial_frame(&child_frame);
        parent_nested
            .initial_layout_paint_frame
            .replace(Some(parent_frame));
        child_nested
            .initial_layout_paint_frame
            .replace(Some(child_frame));

        let stats = Rc::new(CountingStats::default());
        let mut factory = CountingFactory {
            stats: Rc::clone(&stats),
            next_path_id: 0,
        };
        let mut paint_cache = preallocate_render_paint_cache_for_artboard_instance(
            &file,
            &instance,
            graph,
            &graphs.artboards,
            &mut factory,
        );
        let mut render_cache = RuntimeArtboardPathState::default();
        let nested_ancestors = [graph.global_id];

        instance
            .drain_pending_initial_nested_layout_paint_frames(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut paint_cache.paints,
                Some(&mut paint_cache.paint_configurations),
                Some(&mut paint_cache.nested_artboards),
                &mut render_cache,
                &nested_ancestors,
            )
            .expect("initial frames drain");
        assert!(parent_nested.initial_layout_paint_frame.borrow().is_none());
        assert!(child_nested.initial_layout_paint_frame.borrow().is_none());
        let first_shader_count = stats.linear_gradients.borrow().len();
        assert_eq!(
            first_shader_count, 2,
            "each frame realizes its occurrence-owned gradient exactly once \
             at the dependency update (linear_gradient.cpp:86-126)"
        );
        for child in [parent_nested.child.as_ref(), child_nested.child.as_ref()] {
            let owner_ref = child
                .runtime_shapes
                .paint_owner_refs
                .first()
                .expect("synthetic child has one ShapePaint owner");
            let owner = child
                .runtime_shapes
                .get(owner_ref.shape_local)
                .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
                .expect("ShapePaint owner resolves");
            let backend = owner.backend.value.borrow();
            let paint = backend.paint.as_ref().expect("owner has a RenderPaint");
            assert!(
                paint
                    .as_any()
                    .downcast_ref::<TestRenderPaint>()
                    .expect("counting factory paint")
                    .has_shader,
                "construction ownership transfer must preserve the shader \
                 already attached by the initial layout frame"
            );
        }

        instance
            .drain_pending_initial_nested_layout_paint_frames(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut paint_cache.paints,
                Some(&mut paint_cache.paint_configurations),
                Some(&mut paint_cache.nested_artboards),
                &mut render_cache,
                &nested_ancestors,
            )
            .expect("second drain is a no-op");
        assert_eq!(stats.linear_gradients.borrow().len(), first_shader_count);
    }

    #[test]
    fn mounted_layout_solve_replaces_the_provisional_post_frame_gradient() {
        let bytes = synthetic_nested_layout_gradient_chain_riv();
        let file = read_runtime_file(&bytes).expect("nested layout chain imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("nested layout chain graphs");
        let graph = graphs.artboards.first().expect("parent graph");
        let instance = ArtboardInstance::from_graph_with_artboards(&file, graph, &graphs.artboards)
            .expect("nested layout chain instance");
        let child = instance
            .nested_artboards
            .values()
            .next()
            .expect("mounted layout child")
            .child
            .as_ref();
        let frame = child.capture_initial_nested_layout_paint_frame();
        let frame_state = frame.gradients[0].paint_state.clone();
        let provisional =
            runtime_shape_paint_state_with_endpoints(frame_state.clone(), 0.0, 0.0, 20.0, 0.0);
        let solved =
            runtime_shape_paint_state_with_endpoints(frame_state.clone(), 0.0, 0.0, 80.0, 0.0);
        let owner_ref = child
            .runtime_shapes
            .paint_owner_refs
            .first()
            .expect("child has one ShapePaint owner");
        let owner = child
            .runtime_shapes
            .get(owner_ref.shape_local)
            .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
            .expect("ShapePaint owner resolves");
        owner
            .pending_gradient_states
            .replace(vec![frame_state, provisional.clone()]);

        child.transfer_owned_shape_gradient_events_to_initial_frame(&frame);
        assert_eq!(
            owner.pending_gradient_states.borrow().as_slice(),
            std::slice::from_ref(&provisional),
            "the pre-transfer host update is provisionally retained"
        );

        owner.paint_state.replace(Some(solved.clone()));
        owner.record_gradient_update();
        assert_eq!(
            owner.pending_gradient_states.borrow().as_slice(),
            std::slice::from_ref(&solved),
            "the parent-owned solve is the sole post-frame shader event observed when the backend attaches"
        );
    }

    #[test]
    fn ordinary_nested_initial_update_retains_only_post_host_gradient_state() {
        let bytes = synthetic_zero_opacity_nested_gradient_riv();
        let file = read_runtime_file(&bytes).expect("synthetic nested riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic nested riv graphs");
        let graph = graphs.artboards.first().expect("parent graph");
        let mut instance =
            ArtboardInstance::from_graph_with_artboards(&file, graph, &graphs.artboards)
                .expect("parent instance builds");
        instance.update_components();

        let child = instance
            .nested_artboards
            .values()
            .next()
            .expect("ordinary nested host")
            .child
            .as_ref();
        let owner_ref = child
            .runtime_shapes
            .paint_owner_refs
            .first()
            .expect("child has one ShapePaint owner");
        let owner = child
            .runtime_shapes
            .get(owner_ref.shape_local)
            .and_then(|shape| shape.paint_owners.get(owner_ref.owner_index))
            .expect("ShapePaint owner resolves");
        let first = owner
            .paint_state
            .borrow()
            .clone()
            .expect("gradient state settled");
        let latest = runtime_shape_paint_state_with_endpoints(first.clone(), 1.0, 2.0, 30.0, 40.0);
        owner
            .pending_gradient_states
            .replace(vec![first, latest.clone()]);

        child.retain_latest_unrealized_shape_gradient_state();

        assert_eq!(
            owner.pending_gradient_states.borrow().as_slice(),
            std::slice::from_ref(&latest),
            "the late renderer attachment observes only the retained state \
             after NestedArtboard::update(Filthy), matching C++ \
             nested_artboard.cpp:626-652"
        );

        owner.pending_gradient_states.borrow_mut().push(latest);
        child.runtime_shapes.backend_context_id.set(Some(7));
        child.retain_latest_unrealized_shape_gradient_state();
        assert_eq!(
            owner.pending_gradient_states.borrow().len(),
            2,
            "live-backend updates remain distinct C++ shader events"
        );
    }

    #[test]
    fn zero_opacity_nested_host_prepares_child_paints_and_replays_only_host_envelope() {
        let bytes = synthetic_zero_opacity_nested_gradient_riv();
        let file = read_runtime_file(&bytes).expect("synthetic nested riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic nested riv graphs");
        let graph = graphs
            .artboards
            .first()
            .expect("synthetic nested riv has a parent artboard");
        let mut instance =
            ArtboardInstance::from_graph_with_artboards(&file, graph, &graphs.artboards)
                .expect("parent artboard instance builds");
        instance.update_components();

        let stats = Rc::new(CountingStats::default());
        let mut factory = CountingFactory {
            stats: Rc::clone(&stats),
            next_path_id: 0,
        };
        let mut paint_cache = preallocate_render_paint_cache_for_artboard_instance(
            &file,
            &instance,
            graph,
            &graphs.artboards,
            &mut factory,
        );
        let mut path_cache = RuntimeArtboardPathState::default();

        let prepared = path_cache.live_traversal_frame(&instance, graph, Some(&file));
        assert_eq!(
            prepared
                .commands
                .iter()
                .filter(|command| runtime_drawable_dispatch_is_nested_artboard(command))
                .count(),
            1,
            "NestedArtboard::willDraw() depends on visibility and reference, not opacity"
        );
        assert!(stats.linear_gradients.borrow().is_empty());

        instance
            .update_artboard_backend_tree(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("nested paint preparation succeeds");
        assert!(
            !stats.linear_gradients.borrow().is_empty(),
            "paint-allocation lifecycle must configure the nested child gradient"
        );
        assert_eq!(
            stats
                .linear_gradient_colors
                .borrow()
                .last()
                .map(|colors| colors.as_slice()),
            Some([0xffff_0000, 0xff00_00ff].as_slice()),
            "NestedArtboard::nest transfers zero opacity to the child \
             Artboard (nested_artboard.cpp:110-122), whose draw then returns \
             before child traversal (artboard.cpp:1613-1620); the untouched \
             child ShapePaintMutator therefore retains its constructed 1.0 \
             render opacity"
        );

        let ops = Rc::new(RefCell::new(Vec::new()));
        let mut renderer = RecordingRenderer {
            ops: Rc::clone(&ops),
        };
        instance
            .draw_artboard_internal_with_render_cache(
                &file,
                graph,
                &graphs.artboards,
                &mut factory,
                &mut renderer,
                &mut paint_cache,
                &mut path_cache,
            )
            .expect("zero-opacity parent draw succeeds");
        assert!(
            !ops.borrow().iter().any(|op| op == "draw_path"),
            "the zero-opacity referenced artboard must not draw child content"
        );
        assert!(
            ops.borrow().iter().any(|op| op.starts_with("transform:")),
            "the nested host envelope must still replay its transform"
        );
    }

    #[test]
    fn nested_will_draw_distinguishes_command_compatibility_from_live_mounts() {
        let bytes = synthetic_zero_opacity_nested_gradient_riv();
        let file = read_runtime_file(&bytes).expect("synthetic nested riv imports");
        let graphs = GraphFile::from_runtime_file(&file).expect("synthetic nested riv graphs");
        let graph = graphs.artboards.first().expect("parent artboard");
        let unmounted = ArtboardInstance::from_graph(&file, graph).expect("unmounted instance");
        let mounted = ArtboardInstance::from_graph_with_artboards(&file, graph, &graphs.artboards)
            .expect("mounted instance");
        let unmounted_drawable = unmounted
            .runtime_drawables
            .iter()
            .find(|drawable| drawable.family == RuntimeDrawableFamily::NestedArtboard)
            .expect("nested drawable");
        let mounted_drawable = mounted
            .runtime_drawables
            .iter()
            .find(|drawable| drawable.family == RuntimeDrawableFamily::NestedArtboard)
            .expect("nested drawable");

        assert!(
            unmounted.runtime_will_draw(unmounted_drawable, false),
            "the command-stream compatibility surface retains the resolved initial C++ pointer"
        );
        assert!(
            !unmounted.runtime_will_draw_live_traversal(unmounted_drawable),
            "live traversal requires the mounted child occurrence"
        );
        assert!(
            mounted.runtime_will_draw_live_traversal(mounted_drawable),
            "the mounted child occurrence is the live reference"
        );
    }

    struct FillRuleRecordingRenderer {
        fill_rules: Rc<RefCell<Vec<RenderFillRule>>>,
    }

    impl Renderer for FillRuleRecordingRenderer {
        fn save(&mut self) {}
        fn restore(&mut self) {}
        fn transform(&mut self, _transform: RenderMat2D) {}

        fn draw_path(&mut self, path: &dyn RenderPath, _paint: &dyn RenderPaint) {
            if let Some(path) = path.as_any().downcast_ref::<CountingRenderPath>() {
                self.fill_rules.borrow_mut().push(path.fill_rule);
            }
        }

        fn clip_path(&mut self, _path: &dyn RenderPath) {}

        fn draw_image(
            &mut self,
            _image: Option<&dyn RenderImage>,
            _sampler: RenderImageSampler,
            _blend_mode: RenderBlendMode,
            _opacity: f32,
        ) {
        }

        #[allow(clippy::too_many_arguments)]
        fn draw_image_mesh(
            &mut self,
            _image: Option<&dyn RenderImage>,
            _sampler: RenderImageSampler,
            _vertices: Option<&dyn RenderBuffer>,
            _uv_coords: Option<&dyn RenderBuffer>,
            _indices: Option<&dyn RenderBuffer>,
            _vertex_count: u32,
            _index_count: u32,
            _blend_mode: RenderBlendMode,
            _opacity: f32,
        ) {
        }

        fn modulate_opacity(&mut self, _opacity: f32) {}
    }

